INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130012, 'ذ', '<span class=\"hlight\">ذ.</span> (حرف ) حرف نهم است از حروف الفبای عرب و یازدهم از الفبای فارسی و بیست و پنجم از حروف ابجد و در حساب جمّل آن را به هفتصد دارند. و نام آن ذال است و گاه برای استواری ضبط ذال معجمة گویند و آن از حروف روادف و شمسیّة و ارضیة یا ترابیة و مصمته و نیز از حروف مجزوم است .<br />ابدالها:<br /> <font color=\"Red\">حرف «ذ» در فارسی :</font><br />> بدل به «د» شود:<br />گذار = گدار.<br />> و به «گ » بدل گردد:<br />آذر = آگر (آتش ).<br />> و بدل ِ «همزه » آید:<br />پاذیز = پائیز <span class=\"hlight\">:</span> از سر دولاب برخاست و به دارالملک همدان آمد، فصل پاذیز بود. (راحةالصدور راوندی ). در سنه ٔ ست و اربعین و خمسمائة به فصل پاذیز قصد بغداد کرد. (راحةالصدور راوندی ).<br /> <font color=\"Red\">حرف «ذ» در تعریب :</font><br />> بدل ِ دال آید:<br />بیجاذق = بیجاده .<br />شوذر = چادر.<br />فالوذج = پالوده .<br />ساذج = ساده .<br />انموذج = نموده .<br />سنباذج = سنباده .<br />> وبدل ِ «ز» آید:<br />ذقن = زنخ .<br />حرف «ذ» در عربی :<br />> بدل به «ش » شود:<br />ذرف = شرف .<br />> و بدل به «ث » شود:<br />مرذ = مرث <br />ذَروَت = ثَروَت <br />> و بدل به «ط» شود:<br />ذلاقت = طلاقت .<br />> و بدل به «ز» شود:<br />بَذَع = فَزَع .<br />و صوت آن زاء است آنگاه که زبان میان دو رده ٔ دندانهای پیشین (ضواحک ) درآرند. و در تقاویم و جز آن صورت «ذ» رمز ذوالحجة و با ازدیاد الف «ذا» رمز ذوالقعده باشد و برای فرق میان دال و ذال در فارسی، خواجه نصیرالدین محمد طوسی قاعده ٔ ذیل را بنظم گفته است :<br />آنانکه بپارسی سخن میرانند<br />در معرض دال ذال را ننشانند<br />ماقبل وی ار ساکن جز وای بود<br />دال است و گرنه ذال معجم خوانند.<br />و شرف الدین علی یزدی گوید:<br />در زبان فارسی فرق میان دال و ذال <br />با تو گویم ز آنکه نزدیک افاضل مبهم است <br />پیش از او در لفظ مفرد گر صحیح ساکن است <br />دال باشد ور نه باقی جمله ذال معجم است .<br />و در بودن این حرف در فارسی اختلاف کرده اند، بعضی گویند که اصلاً این حرف در فارسی نباشد و حتّی کلمه ٔ آذر و گذر و گذشت فصیح آن بدال مهمله است و شرف الدین علی یزدی گوید که ذال معجمة در زبان اهل فارس هست و در لهجه ٔ ماوراءالنهر آن ذالها را دال تلفظ کنند و حکیم سنائی علیه الرحمة ذال تعویذ را با دال قافیه کرده است :<br />درین زمانه که دیو از ضعیفی مردم <br />همی سلاح ز لا حول سازد و تعویذ<br />کسی که عزت عزلت نیافت هیچ نیافت <br />کسی که روی قناعت ندید هیچ ندید.<br />و امیرخسرو دهلوی لفظ نفاذ را با شادو یاد و امثال آن قافیه کرده است :<br />بسم اﷲ آنچه خواهی پیش تو خسرو، اینک <br />فرمان دوستان را بر جان نفاذ باشد.<br />..........<br />و شمس قیس رازی صاحب المعجم فی معاییر اشعار العجم در ذیل حرف دال گوید: حرف دال، و زواید آن دو بیش نیست . حرف نعت : و آن میم و نون و دالی است که در اواخر صفات به معنی نعت باشد چنانکه دانشمند و حاجتمند و هنرمند و دردمند و نزدیک بدین معنی خداوند و خویشاوند و باوندیعنی بند که بر پای نهند و آوند خنور آب را گویند وهمانا در اصل آب وند بوده است .<br />حرف رابطه و جمع: و آن نون و دالی است که در آخر صفات فایده ٔ ربط (صفت ) بجماعت دهد چنانکه عالمند و توانگرند و در جمع گویند می آیند و می روند و رفتند و آمدند و در قوافی دالی خداوند و خویشاوند بهم شاید از بهر آنکه مشهورالترکیب نیست و به کثرت استعمال و قلت امثال و اخوات از کلمات مفرده می نماید و خردمند و هنرمند بهم نشاید، و مستمندو دردمند بهم نشاید از بهر ظهور ترکیب، و دانشمند وحاجتمند بهم شاید اگر چه وجه ترکیب در حاجتمند ظاهرتر است . اما چون دانشمند اسم علم گشته است عالمان رابه اسمی مفرد ماننده شده است و از این جهت هر دو باهم قافیت میسازند چنانکه انوری گفته است :<br />آدمیزاده بی گنه نبود<br />ز آن بکفارتست حاجتمند<br />شخص و دینت ودیعت ایزد<br />بی نیاز از طبیب و دانشمند.<br />حرف ذال : زواید آن سه است :<br />حرف مضارع : و آن ذالی (مفرد) است که در اواخر کلمات فعل راصیغت مضارع گرداند چنانکه آیذ و روذ و میگویذ و میشنوذ.<br />حرف ضمیر: و آن یاء و ذالی است که در آخر کلمه فایده ٔ ضمیر جماعت حاضران دهد چنانکه می آییذ و میرویذ وربط را نیز باشد چنانکه عالمیذ و توانگریذ.<br />حرف دعا: و آن الف و ذالی است که در اواخر افعال معنی دعا دهد چنانکه برساذ و بدهاذ و صیغت خاصه ٔ دعا باذ و مباذ است و در اصل بواذ ومبواذ بوده است، واو تخفیف را حذف کرده اند و در قوافی ذالی هفتاذ و هشتاذ بهم شاید، افتاذ و بدافتاذ بهم نشاید، و گشاذ و نگشاذ بهم نشاید، اما داذ و بیداذبهم شاید از بهر آنکه لفظ بیداذ اسم علم است ظلم رانه چنانکه لفظ بی اسب و بیمال و مانند آن که ترکیب این کلمات مشهور و معلوم است و سوذ و نمکسوذ بهم شاید، و بدیذ و نابدیذ بهم شاید، و جمله ٔ الفاظ ماضی چون رفت و گفت و آمذ و شذ و دیذ و شنیذ و کرد و آزرد وغیر آن شاید که قافیه سازند بخلاف الفاظ مضارع که صیغ ماضی کلمات مفرده اند و صیغ مستقبل مرکب اند و بدانکه در صحیح لغت دری ماقبل دال مهمله الا راء ساکن چنانکه درد و مرد یا زاء ساکن چنانکه دزد و مزد و یا نون ساکن چنانکه کمند و گزند نباشد و هر دال که ماقبل آن یکی از حروف مد و لین است چنانکه باذ و شاذ و سوذ و شنوذ و دیذ و کلیذ یا یکی از حروف صحیح متحرک است چنانکه نمذ و سبذ و دذ و آمذ همه ذال معجمه اند و در زبان اهل غزنین و بلخ و ماوراءالنهر ذال معجمه نیست و جمله دالات مهمله در لفظ آرند چنانکه گفته اند. شعر:<br />از دور چو بینی مرا بداری <br />پیش رخ رخشنده دست عمدا<br />چون رنگ شراب از پیاله گردد<br />رنگ رخت از پشت دست پیدا.<br />و دال و ذال بهم قافیت کرده از بهر آنکه ایشان همه دالات مهمله در لفظ آرند. (المعجم چ طهران صص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> - <span class=\"hlight\" dir=\"rtl\">١٦٦</span>) .<br /></font></div>'),
(130013, 'ذآبت', '<span class=\"hlight\">ذآبت .</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ع مص ) مانند گرگ شدن در خبث و دها. رجوع به ذآبة شود.<br /></font></div>'),
(130014, 'ذآف', '<span class=\"hlight\">ذآف .</span><font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ذأف . سرعت موت . <BR><font color=\"Blue\">◄</font> موت ذُآف ؛ موت شتاب و زود کشنده . <BR><font color=\"Blue\">◄</font> زهر هلاهل .<br /></font></div>'),
(130015, 'ذآلیل', '<span class=\"hlight\">ذآلیل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذُئلان و ذؤلان .<br /></font></div>'),
(130016, 'ذآلین', '<span class=\"hlight\">ذآلین .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذَئلان و ذؤلان .<br /></font></div>'),
(130017, 'ذآنین', '<span class=\"hlight\">ذآنین .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذٔنون .<br /></font></div>'),
(130018, 'ذا', '<span class=\"hlight\">ذا.</span> (ع اِ) از اسماء اشارت است برای مفرد و مذکر قریب . این مرد. ذو. هذا. و تثنیه ٔ آن ذان و ذین و جمع آن از غیر صیغه، اولاء باشد.<br /></font></div>'),
(130019, 'ذا', '<span class=\"hlight\">ذا.</span> (ع اِ) صاحب . مالک . دارا، در حال نصب . ذو در حال رفع و ذی در حال جَرّ. رأیت رجلاً ذا مال ...<br /></font></div>'),
(130020, 'ذاب', '<span class=\"hlight\">ذاب .</span> <font color=\"DarkGreen\"><b>[ ذاب ب ]</font></b> (ع ص ) نعت فاعلی از ذب . بعیرٌ ذاب ؛ لا یتقارّ فی مکان واحد. شتر که در یک جای قرار نگیرد.<br /></font></div>'),
(130021, 'ذاب', '<span class=\"hlight\">ذاب .</span> (ع اِ) عیب . (مهذب الاسماء). ذام . ذَیم . ذان . ذین : آهو. <BR><font color=\"Blue\">◄</font> (ص ) سخت تشنه چنانکه لبها خشک شده باشد از تشنگی . (مهذب الاسماء).<br /></font></div>'),
(130022, 'ذابح', '<span class=\"hlight\">ذابح .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ذبح . سربرنده . ذامط. ذبح کننده ٔ حیوان مأکول اللحم . بسمل کننده . گلوبرنده . <BR><font color=\"Blue\">◄</font> (اِ) داغ گلوی ستور. یا آهن داغی است که بدان بر جانب گردن ستور داغ کنند. <BR><font color=\"Blue\">◄</font> موی که میان بند سر و گردن و جای ذبح رُسته باشد. <BR><font color=\"Blue\">◄</font> (اِخ ) سعد ذابح ؛ یکی از منازل قمر است و آن دو ستاره است روشن که میان آن دو مسافتی بمقدار یک گز است و در جای ذبح یکی از آن دو ستاره ستاره ای است خرد که گوئی آن ستاره ٔ روشن ستاره ٔ خرد را ذبح کردن خواهد <span class=\"hlight\">:</span> <br />سعد ذابح سر بریدی هر شکاری را که شاه <br />سوی او محور ز خط استوا کردی رها.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> در یکی از لغت نامه های مترجم عربی به فارسی آمده است : گیاهی سرخ است که آن را شترمرغ خورد.<br /></font></div>'),
(130023, 'ذابر', '<span class=\"hlight\">ذابر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) نعت فاعلی از ذَبر، استواردانش . استوار در علم .<br /></font></div>'),
(130024, 'ذابل', '<span class=\"hlight\">ذابل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) ذَوی ّ. پژمرده . ترنجیده . پلاسیده . <BR><font color=\"Blue\">◄</font> لاغر. نزار. مَهزول . <BR><font color=\"Blue\">◄</font> خشک شده از عطش مانند لب . <BR><font color=\"Blue\">◄</font> قنّا ذابِل ؛ دقیق لاصق باللیط. و فی المحکم ؛ لاصق اللیط. (تاج العروس ). نیزه ٔ باریک چسبیده پوست . ج، ذُبُل، ذُبّل، ذَوابِل . و در نسخه ای از مهذب الاسماء آمده است : ذابل زره نرم و در نسخه ای دیگر نیزه ٔ نرم و اﷲ اعلم .<br /></font></div>'),
(130025, 'ذابل', '<span class=\"hlight\">ذابل .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن طفیل السدوسی، صحابی است . و جمیعة دختر او از وی یک حدیث روایت کرده است .<br /></font></div>'),
(130026, 'ذابلة', '<span class=\"hlight\">ذابلة.</span> <font color=\"DarkGreen\"><b>[ ب ِ ل َ ]</font></b> (ع ص ) تأنیث ذابِل . عین ٌ ذابلة. فاترةالجفون، سست پلک .<br /></font></div>'),
(130027, 'ذات', '<span class=\"hlight\">ذات .</span> (ع اِ) تأنیث ذو. صاحب . مالک . دارا. خداوند. و تثنیه ٔ آن ذواتا. و ج، ذوات : امراءة ذات مال . <BR><font color=\"Blue\">◄</font> مؤلف آنندراج آرد: ذات : بالفتح، بمعنی صاحب و خداوند و به معنی هستی و حقیقت هر چیز و نفس هر شی ٔ و مؤنث ذو. و در اصطلاح سالکان ذات را به اعتبار جمیع صفات واحد گویند و هستی حق تبارک و تعالی پیداتر از هستیها است که او بخود پیداست و پیدائی هستیها بدوست که : اﷲ نور السموات و الارض . حقیقت دلیل هستی او بحقیقت جز او نیست که هیچگونه کثرت را به هستی او راه نیست و دلیل او ناگزیر بود. او لم یکف بربک انه علی کل ّ شی ٔ شهید. (قرآن <span class=\"hlight\" dir=\"rtl\">٥٣/٤١</span>). حقیقت هستی او تبارک و تعالی نماینده ٔ خود است که نمایندگی حقیقی جز از هستی نیاید. به معنی طرف و جانب . و لفظ ذات عربی است و در حقیقت اسم اشارت است که های وقف داخل آن شده است و اصل او، ذاه بود چون ها جزو کلمه گردید بتا مبدل گشت و ذات گفتند ومعنی لفظ ذات مشارالیه است چون هستی هر شی ٔ مشارالیه میباشد لهذا به معنی خداوند و هستی هرچیز مستعمل (است ). (از شرح نصاب که از مولانا یوسف بن مانع است و کنز). و خان آرزو در چراغ هدایت نوشته که لفظ ذات به معنی قوم که در عرف مستعمل است غلط است زیرا که بدین معنی لفظ جات است بجیم و آن لفظ هندی الاصل است و سبب غلط بودنش آن باشد که ذال معجمه در هندی نمی آید پس طغرا در دو شعر خود لفظ جات را ذات به ذال معجمه فهمیده، و آورده است خطا کرد. تم کلامه . و بخاطر مؤلف میرسد که لفظ ذات بمعنی قوم بذال معجمه نوشتن خطا باشد مگر بهتر آن است که ذات به زای معجمه نویسند چرا که ذات مفرس جات باشد که به هندی قوم است به ابدال جیم عربی به زای معجمه و قطع نظر از نیت تفریس جیم جات را به جهت فصاحت به زای معجمه بدل کرده ذات خوانده شود تا اینجا عین عبارت غیاث است . و سپس صاحب آنندراج گوید: و آن هر دو شعر ملاطغرا این است <span class=\"hlight\">:</span> <br />گر بساید از قدح نوشی بط می را دهن <br />ذات مرغابی است خواهد صاحب منقار شد<br />شوخ سوسن را بگو دل میرباید قشقه ات <br />ذات رجپوت است ترسم دست بر جمدر کند.<br />و سبب غلط آن است که ذال و زای معجمه درزبان هندی نیست پس طغرا لفظ جات را ذات به ذال فهمیده و خطا کرده اگرچه در شعر دوم تدارک آن میشود که نظر بر لفظ رجپوت لفظ هندی آورده لیکن در شعر اول علاج پذیر نیست مگر آنکه گویند که طغرا عمداً الفاظ هندیه را در اشعار خود می آرد چنانکه بر متتبع کلام او ظاهراست و چون این وضع به تکلف اختیار نموده تبدیل جیم به ذال از جهت تصرف باشد که بر صاحبان قدرت جایز است و توافق لسانین نیز احتمال دارد لیکن در جای دیگر بدین معنی دیده نشده - انتهی . <BR><font color=\"Blue\">◄</font> وجود. هستی . (مهذب الاسماء) (دستوراللغه ٔ ادیب نظنزی ) <span class=\"hlight\">:</span> <br />مجوی از وحدت محضش برون از ذات او چیزی <br />که او عام است و ماهیات خاص اندر همه اشیا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />این عالم مرده سوی من نام است <br />و آن عالم زنده ذات بس والا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای ذات تو شمس و ذاتها انجم <br />وی ملک تو کّل و ملکها اجزا.<br /> <font color=\"Red\">مسعودسعد.</font><br />هر که در میدان عشق نیکوان گامی نهاد<br />چار تکبیری کند بر ذات او لیل و نهار.<br /> <font color=\"Red\">سنائی .</font><br />ذات او هم بدو توان دانست .<br /> <font color=\"Red\">سنائی .</font><br />و ذات خویش را فدای آن داشته آید. (کلیله و دمنه ). بقاء ذات تو بدوام تناسل ما متعلق است . (کلیله و دمنه ).<br />حق ذات پاک اﷲ الصمد<br />که بود به مار بد از یار بد.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> ذات واجب . ذات باری . هویت حق <span class=\"hlight\">:</span> <br />ذات حق سلطان سلطانان و کعبه دار ملک <br />مصطفی را شحنه و منشور قرآن دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />پیشت آرم ذات یزدان را شفیع<br />کش عطابخش و توانا دیده ام .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> کنه . حقیقت . مقابل صفت . و منه الحدیث <span class=\"hlight\">:</span> <br />تفکروا فی آلأاﷲ و لاتفکروا فی ذاته .<br />صفات و ذات او هر دو قدیم است <br />شدن واقف در او سیر عظیم است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />اما سخن درست این باشد<br />کز ذات و صفات خود فنا گردد.<br /> <font color=\"Red\">عطار.</font><br /> <BR><font color=\"Blue\">◄</font> جسم <span class=\"hlight\">:</span> <br />سایه با ذات آشنا باشد<br />سایه از ذات کی جداباشد.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> پیش . عِند. رای <span class=\"hlight\">:</span> از ذات خویش نص ّ تنزیل را تأویلی چند می نهند که موجب هدم قواعد دین و دفع معاقد یقین است . (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٣٩٨</span>). <BR><font color=\"Blue\">◄</font> معنی . حقیقت <span class=\"hlight\">:</span> <br />ذات ایمان نعمت ولوتی است هول <br />ای قناعت کرده از ایمان بقول .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> ماهیت . هویّت <span class=\"hlight\">:</span> <br />اسلام بذات خود ندارد عیبی <br />عیبی که در اوست از مسلمانی ماست .<br /> <font color=\"Red\">؟ (از امثال و حکم ).</font><br /> <BR><font color=\"Blue\">◄</font> جِبِلَّت، فطرت : بدذات . خوش ذات : ما بالذّات لایتغیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذات نایافته از هستی بخش </span> ؛ ماهیت معدوم <span class=\"hlight\">:</span> <br />ذات نایافته از هستی بخش <br />کی تواند که شودهستی بخش .<br /> <font color=\"Red\">جامی .</font><br />و صاحب کشاف اصطلاحات الفنون گوید: الذات هو یطلق علی معان : منها الماهیّة. بمعنی ما به الشی ٔ هوهو. و قد سبق تحقیقه فی لفظالحقیقة و علی هذا قال فی الانسان الکامل ان ّ مطلق الذّات هو الامر الذی تستند الیه الاسماء و الصّفات فی عینها لا فی وجودها فکل ّ اسم او صفة استند الی شی ٔ فذلک الشی ٔ هو الذّات سواء کان معدوماً کالعنقاء، او موجوداً. و الموجود نوعان : نوع هو موجود محض و هو ذات الباری سبحانه . و نوع هو موجود ملحق بالعدم و هو ذات المخلوقات . و اعلم ان ّ ذات اﷲ تعالی عبارة عن نفسه التی هو بها موجود لانّه قائم بنفسه . و هو الشی ٔ الّذی استحق َّ الاسماء و الصفات بهُویّته، فیتصوّر بکُل ّ صورة تقتضیها منه کُل ّ معنی فیه، اعنی اتّصف بکُل صفة تطلبها بکُل ّ نعت و استحق ّ بوجوده کُل ّ اسم دَل ّ علی مفهوم یقتضیه الکمال . و من جملةالکمالات عدم الانتهاء و نفی الادراک فحکم بانها لاتدرک و انّها مدرکة له لاستحالة الجهل علیه تعالی، فذاته غیب الاحدیة التی کُل ّالعبارات واقعة علیها من کُل ّ وجه غیر مستوفیة لمعناهامن وجوه کثیرة، فهی لاتدرک بمفهوم عبارة و لاتفهم بمعلوم اشارة، لان ّ الشی ٔ انّما یعرف بما یناسبه فیطابقه و بما ینافیه فیضادّه و لیس لذاته فی الوجود مناسب و لامناف و لامضاد فارتفع من حیث الاصطلاح اذا معناه فی الکلام و انتفی لذلک ان یدرک للانام - انتهی . و فی شرح المواقف : للمتکلمین هیهنا مقامان : الاوّل الوقوع، فذهب جمهورالمحقّقین من الفرق الاسلامیّة و غیرهم الی ان ّ حقیقة اﷲ تعالی غیر معلوم للبشر و قد خالف فیه کثیر من المتکلّمین من اصحاب الاشعری و المعتزلة. و الثّانی الجواز. و فیه خلاف . فمنعه الفلاسفة و بعض اصحابنا کالغزّالی و امام الحرمین . و منهم من توقف کالقاضی ابی بکر و ضراربن عمرو. و کلام الصوفیّة فی الاکثر مُشعرٌ بالامتناع . اعلم انّهم اختلفوا فی ان ّ ذاته تعالی مخالفة لسائرالذّوات . فذهب نفاةالاحوال الی التخالف و هومذهب الاشعری و ابی الحسین البصری فهو منزّه عن المثل و الندّ. و قال قدماءالمتکلمین ذاته مماثلة لسائر الذوات فی الذاتیة و الحقیقة و انّما یمتاز عن سائرالذوات باحوال اربعة: الوجوب . و الحیاة. و العلم التّام و القدرة التّامة. ای الواجبیة و الحییة و العالمیّة و القادریّة التامّتین . هذا عندالجبّائی . و امّا عند ابی هاشم فانّه یمتاز بحالة خامسة، هی موجبة لهذه الاربعة. و هی المسماة بالالهیة. و المذهب الحق ّ هو الاوّل - انتهی . و منها الماهیّة باعتبارالوجود. و اطلاق لفظ الذّات علی هذا المعنی اغلب من الاطلاق الاوّل و قدسبق ایضاً فی لفظ الحقیقة. و منها ما صدق علیه الماهیة من الافراد کما وقع فی شرح التجرید فی لفظالماهیة. و بهذا المعنی یقول المنطقیون ذات الموضوع ما یصدق علیه ذلک الموضوع من الافراد ثم المعتبر عندهم فی ذات الموضوع فی القضیة المحصورة لیس افراده مطلقاً بل الافراد الشخصیة ان کان الموضوع نوعاً او ما یساویه من الخاصة و الفصل و الافراد الشخصیة و النوعیة ان کان جنساً؛ او ما یساویه من العَرَض العام و بعضهم خص ّ ذلک مطلقاً بالافراد الشخصیة و هو قریب الی التحقیق . و تفصیله یطلب من شرح الشمسیة و شرح المطالع فی تحقیق المحصورات . و هذه المعانی الثلاثة تشتمل الجوهر و العرض . و منها ما یقوم بنفسه و هذا لا یشتمل العرض . و تقابله الصفة به معنی ما لایقوم بنفسه . و معنی القیام بالذّات یجیی ٔ فی محله . هکذا ذکر احمدُ جند فی حاشیة شرح الشمسیة فی بحث التصور و التصدیق . و السیّد السند فی حاشیة المطول فی بحث هل، فی باب الانشاء. و منها مایقوم به غیره سواء کان قائماً بنفسه کزید فی قولنا زیدٌ العالم قائم او لایکون قائماً بنفسه کالسواد فی قولنا رأیت السواد الشدید. و بهذا المعنی وقع فی تعریف النعت بانّه تابع یدل علی ذات . کذا فی چلپی المطوّل فی باب القصر و منها الجسم کما فی الاطول و حاشیةالمطول للسید السند فی بحث الاستفهامیة. و منها المستقل ّ بالمفهومیة ای المفهوم الملحوظ بالذّات . و هذا معنی ما قالوا: الذّات ما یصح ان یعلم و یخبر عنه و تقابله الصّفة بمعنی ما لایستقل ّ بالمفهومیةای مایکون آلة لملاحظة مفهوم آخر فالنسب الحکمیة صفات بهذا المعنی و اطرافها من المحکوم علیه و المحکوم به ذوات لاستقلالهما بالمفهومیة. هکذا ذکر السید الشریف ایضاً فی بحث هل . قال فی الاطول : هذا المعنی للذّات و الصفة الذی ادّعاه السید الشریف لم یثبت فی السنة مشاهیرالانام - انتهی . و قد ذکر الچلبی ایضاً هذاالمعنی فی حاشیةالمطول فی بحث الاستعارة الاصلیة. و منها الموضوع سمی به لانه ملحوظ علی وجه ثبت له الغیر کما هو شأن الذّوات و تقابله الصفة بمعنی المحمول . سمیت به لانها ملحوظ علی وجه الثبوت للغیر. هکذا فی الاطول فی بحث هل . و هکذا فی العضدی حیث قال فی المبادی : المفردان من القضیة التی جعلت جزءالقیاس الاقترانی یسمیها المنطقیون موضوعاً و محمولاً، و المتکلمون ذاتاً و صفةً و الفقهاء محکوماً علیه و محکوماً به و النّحویون مسندالیه و مسنداً - انتهی . قیل ما ذکره من اصطلاح المتکلمین انّما یصح ّ فیما هو موضوع و محمول بالطبع کقولنا الانسان کاتب لا فی عکسه ای الکاتب انسان . واجیب بان ّ المحکوم علیه یراد به ما صدق علیه و هو الذات و المحکوم به یراد به المفهوم و هو الصفة. و ماقیل ان ّ المسندالیه عند النحاة قدیکون سوراً عندالمنطقیین کقولک کل انسان حیوان فجوابه ان ّ المحکوم علیه بحسب المعنی هو الانسان . هکذا ذکر السید الشریف فی حاشیته . و بقی ان ّ ما ذکره من اصطلاح الفقهاء مخالف لما مرّ فی محله فلینظر ثمة. منها الاسم الجامد و تقابله الصفة بمعنی الاسم المشتق . و منها الجزء الدّاخل بان یکون مخفف الذاتی و تقابله الصفة بمعنی الامر الخارج . هکذا ذکر احمد جند فی حاشیة شرح الشمسیة فی بحث التصور والتصدیق و یجیی ٔ ما یتعلق بهذا المقام فی لفظ الذاتی . و باز گوید: ذات، عبارت از نفس است . و آن اسمی است ناقص که تمام آن ذوات است . نبینی در تثنیه ذواتان میگویند. مانند نواة و نواتان چنین است در بحر الجواهر. و برای همین نکته ما ذات را با لفظ ذاتی و ذات الجنب و غیرآنها در همین باب ضمن اسامی معتل اللام واوی ذکر کرده ایم . - انتهی . در تعریف آن گفته اند: آنچه سزای دانستن و خبردادن از وی باشد. و گفته اند ذات شی ٔ نفس او وعین اوست . جناح . <BR><font color=\"Blue\">◄</font> گوهر. گهر. نهاد. جوهر. جنس <span class=\"hlight\">:</span> <br />آنکه خلقش بحسن مشتهر است <br />و آنکه ذاتش به لطف مذکوراست .<br /> <font color=\"Red\">مسعودسعد.</font><br />گر پخته ای بعقل می خام خواه ازآنک <br />رامش نخیزدت مگر از ذات خام می .<br /> <font color=\"Red\">مسعودسعد.</font><br />ذات تو را زمانه هم بازشناسد از کسان <br />عقل دَم مسیح را فرق کند ز دُم ّ خر.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />ذات زرّش داد ربانیت است <br />نقش بت بر نقد زر عاریت است .<br /> <font color=\"Red\">مولوی .</font><br />ما بالذّات لایتغیّر.<br /> <BR><font color=\"Blue\">◄</font> اَصل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اسم ذات </span> ؛ مقابل اسماء صفات اﷲ است و ابن اثیر گوید:و غیرذلک (ای غیر کلمةاﷲ من اسمائه تعالی ) من صفات الربوبیة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اسم ذات </span> ؛ عین، مقابل اسم معنی، حدث . اسم ذات در تداول ادباء کلمه ای است که معنی آن در خارج موجود باشد. لیکن معنی و مفهوم اسم معنی تنها در ذهن بود.<br /> <BR><font color=\"Blue\">◄</font> نفس . تن . شخص <span class=\"hlight\">:</span> <br />مرد را اول بزرگی نفس باید پس نسب <br />هست اندر ذات او این هر دو معنی آشکار.<br /> <font color=\"Red\">فرخی .</font><br />فضائل و هنر ذات او بحیله وجهد<br />شماره کرد نداند همی ستاره شمر.<br /> <font color=\"Red\">فرخی .</font><br />چنین گفته اند که از وحی قدیم که ایزد تعالی فرستاد به پیغمبر روزگار آن است که مردم را گفت ذات خویش را بدان چون ذات خویش را بدانستی چیزها را دریافتی . (تاریخ بیهقی ) .<br />بفکرت حاضر اوقات خود باش <br />چه باشی با کسان، با ذات خود باش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نه چون ذاتش بود کوشنده هر ذات <br />نه چون عود اوفتد بوینده هر عود.<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />بذات خویش ندارم درین قصیده سخن <br />بگفتم آنچه شنیدم ز دولت پدرام .<br /> <font color=\"Red\">مسعودسعد.</font><br />هنگام حمله خواست که ناگه بذات خویش <br />بیدست تو برآید تیغ از نیام تو.<br /> <font color=\"Red\">مسعودسعد.</font><br />با خود گفت اگر نقل این بذات خویش تکفل کنم عمری دراز در آن بشود. (کلیله و دمنه ). وعقل مرد را به هشت خصلت بتوان شناخت ... دوم خویشتن شناسی و صیانت ذات . (کلیله و دمنه ). اگر بذات خویش مقاومت نتواند کرد یاران گیرد. (کلیله و دمنه ). این کافر نعمت ... بذات خویش تکفل کند. (کلیله و دمنه ). و ذات بیهمال خویش را بر نصرت دین اسلام و مراعات مصالح خلق وقف کرد. (کلیله و دمنه ). راحت ما بصحت ذات ملک متعلق است . (کلیله و دمنه ). تن و جان من ... فدای ذات شریف ملک باد. (کلیله و دمنه ). هیچکس بمردم از ذات او نزدیکتر نیست . (کلیله و دمنه ). حالی ذات او از مشقت فاقه ... مسلم گردد. (کلیله و دمنه ). ممکن است که خصم را در قوّت ذات از من بیشتر یابد. (کلیله و دمنه ). و الاّ نفاذ کار و ادراک مطلوب جز بسعادت ذات و مساعدت بخت ملک نتواند بود. (کلیله و دمنه ). بناء کارها بقوت ذات و استیلاء اعوان نیست . (کلیله و دمنه ). و فایده در تعلم حرمت ذات و عزّت نفس است . (کلیله و دمنه ). و هرگاه که متقی در کار این جهان گذرنده تاملی کند مقابح آن را بنظر بصیرت بیند... و پاکیزگی ذات حاصل آید. (کلیله و دمنه ). با آنچه ملک عادل انوشیروان کسری بن قباد را سعادت ذات ... حاصل است می بینم که کارهای زمانه میل بادبار دارد. (کلیله و دمنه ).<br />دریا هبتی و کوه هیبت <br />کز ذات تو این و آن ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />کمال ذات شریفش ز شرح مستغنی است <br />بماهتاب چه حاجت شب تجلی را.<br /> <font color=\"Red\">ظهیر فاریابی .</font><br />و بذات خویش بحفظ خزانه ٔ جواهر قیام نمود. (ترجمه ٔ تاریخ یمینی خطی کتابخانه ٔ مؤلف صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>). جان را وقایه ٔ ذات و فدای نفس شریف او میساخت . (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٤٤٠</span>).<br />آنچه در علم بیش میباید<br />دانش ذات خویش میباید.<br /> <font color=\"Red\">اوحدی .</font><br />مرکز دائره ٔ دولت و دین ذات تو باد<br />که از آن دائره ٔ دولت و دین گشت پدید.<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذات الشی ٔ</span> ؛ قال ابن بری حقیقته و خاصیته . حقیقت چیزی . و نیز گفته اند ذات شی ٔ نفس او و عین اوست .<br /> <BR><font color=\"Blue\">◄</font> هستی هر چیزی . (دهار) (دستوراللغة ادیب نظنزی ).هستی . (محمودبن عمر ربنجنی ). ج، ذوات . <BR><font color=\"Blue\">◄</font> خود: الجوهر القائم بالذّات ؛ یعنی آنچه بخود پاید. (مهذّب الاسماء) <span class=\"hlight\">:</span> <br />زیرنشین علمت کائنات <br />ما بتو قائم چو تو قائم بذات .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> سریره ٔ مضمره <span class=\"hlight\">:</span> ان ّ اﷲ عَلیم ٌ بذات ِالصدور (قرآن <span class=\"hlight\" dir=\"rtl\">١١٩/٣</span>). <BR><font color=\"Blue\">◄</font> جهت . جانب . سمت . سوی . (دهار):ذات الیمین . ذات الشمال .<br /></font></div>'),
(130028, 'ذات آرام', '<span class=\"hlight\">ذات آرام .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) نام کوهی است به دیار ضُباب . (منتهی الارب ). اَکیمةُ دون الحوأب . (المزهر سیوطی ). اَکمةُ دون الحوأب لبنی ابی بکر. (المرصع). و یاقوت در معجم البلدان گوید: کانّه جمع أرم و هو حجارة تنصب کالعلم . اسم جبل بین مکة والمدینة. قال ابومحمد الغندجانی فی شرح قول جامع:<br />أرقت بذی الاَّرام و هناً و عادنی <br />عدادالهوی بین العناب و حثیل .<br />قال ذوالاَّرام حزن ُ به آرام ُ جمعتها عاد علی عهدها. و قال ابوزیاد: و من جبال الضباب ذات آرام، قُنَّة سوداءُ فیها یقول القائل :<br />خلت ذات آرام و لم تخل عن عصر<br />و اقفرها من حلّها سالف الدهر<br />و فاض اللّئآم و الکرام تَغیضوا<br />فذلک حال الدهر ان کنت لاتدری .<br /></font></div>'),
(130029, 'ذات ابواب', '<span class=\"hlight\">ذات ابواب .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَب ْ ]</font></b> (اِخ ) موضعی است در باب القریتین براه مکه و آن قریه ای است طسم و جدیس را. یاقوت ازاصمعی و او از ابوعمروبن العلاء روایت کند که گفت، در ذات ابواب درمهائی یافت شد هر یک بوزن شش درهم و دو دانگ از دراهم ما. و من به یابندگان آن دراهم گفتم آنها را بمن دهید و بوزن آن درهم ستانید. گفتند ما بیم داریم چه ما باید این یافته ها را بسلطان دهیم .<br /></font></div>'),
(130030, 'ذات اجدال', '<span class=\"hlight\">ذات اجدال .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) موضعی است نزدیکی بدر که رسول اکرم صلوات اﷲ علیه هنگام رفتن بدر بدانجا نماز گزارد و عبیدبن حرث بن عبدالمطلب یکی از شهدای بدر نیز بدانجا مدفون است . (از المرصع).<br /></font></div>'),
(130031, 'ذات احدال', '<span class=\"hlight\">ذات احدال .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) موضعی است براه مکه در وادی موسوم به صفرا. و در سیر، ذات اجدال آمده است با جیم معجمة.<br /></font></div>'),
(130032, 'ذات احفار', '<span class=\"hlight\">ذات احفار.</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) موضعی است در شعر. و شاعر در وصف ابر گوید <span class=\"hlight\">:</span> <br />القی علی ذات احفار کلاکله <br />و شب ّ نیرانه و انجاب یأتلق .<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130033, 'ذات اسلام', '<span class=\"hlight\">ذات اسلام .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (ع ص مرکب ) زمین که سلم رویاند. زمین سلم ناک . <BR><font color=\"Blue\">◄</font> (اِخ ) نام زمینی است .<br /></font></div>'),
(130034, 'ذات اسمین', '<span class=\"hlight\">ذات اسمین .</span> <font color=\"DarkGreen\"><b>[ ت ُ اِ م َ ]</font></b> (ع اِ مرکب ) انوق . رخمة. و آن یکی از جوارح طیور است <span class=\"hlight\">:</span> <br />و ذات اسمین و الالوان شتی <br />تحمّق و هی کیّسةالحویل .<br /><font color=\"Red\">(المرصع) (المزهر ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).</font><br /></font></div>'),
(130035, 'ذات اشاجع', '<span class=\"hlight\">ذات اشاجع.</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ج ِ ]</font></b>(ع ص مرکب ) یا غدد ذات الاشاجع. این کلمه در نصاب الصبیان چ برلین در قطعه ٔ ذیل که محرّمات گوسفند را گردکرده، آمده است و در جای دیگر نیافتیم <span class=\"hlight\">:</span> <br />غدد ذات اشاجعحدق و فرج و قضیب <br />انثیان و دم و عِلبا و نخاعست و طحال .<br />پس مثانه است و مراره است و مشیمه خرزه <br />یاد گیر این که ترا بازرهاندز وبال .<br /></font></div>'),
(130036, 'ذات اطلاح', '<span class=\"hlight\">ذات اطلاح .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) موضعی است به شام و از آنجا تا بلقاء یکشبه راه است و گویند جائی است بدان سوی وادی القری . (المرصع). و مقریزی در امتاع الاسماع در سوانح صفر سال هشتم هجری گوید: ثم ّ کانت سریّة کعب بن عمیرالغفاری الی ذات اطلاح من ارض الشام وراء وادی القری فی خمسة عشر رجلاً فقاتلهم حتی قتلوا.<br /></font></div>'),
(130037, 'ذات اغیال', '<span class=\"hlight\">ذات اغیال .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَغ ْ ]</font></b> (اِخ ) رودباری است به یمامة. (منتهی الارب ).<br /></font></div>'),
(130038, 'ذات الاثل', '<span class=\"hlight\">ذات الاثل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (اِخ ) اثل نوعی گز است و صاحب نصاب گوید شوره گز. و ذات الاثل موضعی است در بلاد تیم اﷲبن ثعلبة و در این مکان میان طائفة تیم اﷲبن ثعلبه با بنی اسد جنگی روی داده است . و صخربن عمرو برادر خنساء بدانجا کشته شده است و کلمه ٔذات الاثل در اشعار عرب بسیار آمده است . (المرصّع).<br /></font></div>'),
(130039, 'ذات الاخصاص', '<span class=\"hlight\">ذات الاخصاص .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (اِخ ) نام دیگر تنیس (جزیره ای به مصر) است .<br /></font></div>'),
(130040, 'ذات الارانب', '<span class=\"hlight\">ذات الارانب .</span> <font color=\"DarkGreen\"><b>[ تُل ْاَ ن ِ ]</font></b> (اِخ ) نام موضعی است، عدی بن الرقاع راست :<br />فذر ذا ولکن هل تری ضوء بارق <br />و میضاً تری منه علی بعده لمعا<br />تصعد فی ذات الارانب موهناً<br />اذا هز رعداً خلت فی ودقه شفعاً.<br /><font color=\"Red\">(معجم البلدان ).</font><br /></font></div>'),
(130041, 'ذات الاساود', '<span class=\"hlight\">ذات الاساود.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ وِ ]</font></b> (اِخ ) موضعی است . (المرصع).<br /></font></div>'),
(130042, 'ذات الاسم', '<span class=\"hlight\">ذات الاسم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اِ ]</font></b> (اِخ ) قریه ای به شرقیه ٔ مصر.<br /></font></div>'),
(130043, 'ذات الاشظاظ', '<span class=\"hlight\">ذات الاشظاظ.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (اِخ ) مقریزی در امتاع الاسماع در حوادث سال هشتم از هجرت آرد: فخرج بسربن سفیان علی صدقات بنی کعب ... فجاء و قد حل ّ بنواحیهم من بنی تمیم بنوعمروبن جندب بن العنبربن عمروبن تمیم . فهم یشربون علی غدیرلهم بذات الاشظاظ. و یقال عسفان . (امتاع الاسماع جزء اول صفحه ٔ <span class=\"hlight\" dir=\"rtl\">٤٣٤</span>).<br /></font></div>'),
(130044, 'ذات الاصابع', '<span class=\"hlight\">ذات الاصابع.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ب ِ ]</font></b> (اِخ ) موضعی است . حسان بن ثابت انصاری گوید <span class=\"hlight\">:</span> <br />عفت ذات الاصابع فالجواء<br />الی عذراء منزلها خلاء<br />دیارٌ من بنی الحسحاس قفر<br />تعفیها الروامس و السماء.<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130045, 'ذات الاصاد', '<span class=\"hlight\">ذات الاصاد.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اِ ]</font></b> (اِخ ) موضعی است از سرزمین شَرّبة، ردهه و قلتی یعنی مغاکی در کوه که آب در وی گرد آید، به دیار عبس میان هضب القلیب . و سباق میان داحس (اسب قیس بن زهیرالعبسی ) و غبراء (اسب حذیفةبن بدر الفزاری ) بدین جای بود و چون اسب قیس را بدغاو دغل از پیش رفتن مانع آمدند جنگی میان دو قبیله که چهل سال بکشید روی داد. و قیس در این معنی گوید:<br />و ما لاقیت من حل بن بدر<br />واخوته علی ذات الاصاد<br />هم فخروا علی ّ بغیر فخر<br />و ردوّا دون غایته جوادی .<br /> <font color=\"Red\">(المرصع).</font><br />و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span> شود.<br /></font></div>'),
(130046, 'ذات الاصبع', '<span class=\"hlight\">ذات الاصبع.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اِ ب َ ]</font></b> (اِخ ) رضیمه ای است یعنی سنگهای برهم چیده ای است به دیار عرب . (المرصع). و صاحب تاج العروس گوید: رضیمه ای است بنی ابی بکربن کلاب را و این قول اصمعی است و برخی گفته اند که در دیار غطفان است .<br /></font></div>'),
(130047, 'ذات الاطباق', '<span class=\"hlight\">ذات الاطباق .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (ع اِ مرکب ) قسمتی از احشاء گوسفند و امثال آن که با شکمبه است و آن را قبه نیز نامند و فارسی زبانان آن را هزارخانه گویند و در تداول عوام نام آن توپی است و ابن الاثیر در المرصع گوید: هی التی تکون مع الکرش و هی القبّة. رمّانة. توپی . قطنه . هزارلا.<br /></font></div>'),
(130048, 'ذات الاعین', '<span class=\"hlight\">ذات الاعین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ی ُ ]</font></b> (ع اِ مرکب ) رجوع به باریکلومانن شود.<br /></font></div>'),
(130049, 'ذات الاقبر', '<span class=\"hlight\">ذات الاقبر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ب َ ]</font></b> (اِخ ) هی جبل ٌ به نعمان . (المرصع).<br /></font></div>'),
(130050, 'ذات الاماحل', '<span class=\"hlight\">ذات الاماحل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ح ِ ]</font></b> (اِخ ) یاقوت گوید گمان برم موضعی بنزدیک مکة است . یکی از حضریون گوید <span class=\"hlight\">:</span> <br />جاب َ التنائف من وادی السکاک الی <br />ذات الأماحل من بطحاء أجیاد.<br /></font></div>'),
(130051, 'ذات الامر', '<span class=\"hlight\">ذات الامر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ م َ ]</font></b> (اِخ ) یکی از غزوات پیغامبر صلوات اﷲ علیه . بلعمی در ترجمه ٔ طبری آرد: درذکر خبر غزو ذات الامر و کشتن کعب بن الاشرف - پس بنزدیک پیغمبر صلی اﷲ علیه و سلم خبر آوردند که گروهی از عرب از بنی سلیم و بنی غطفان گرد آمده اند بجایگاهی که ذی امر خوانند پس آن حضرت ترسید که ایشان بر مدینه شبیخون کنند و بر پنج روزه راه بودند از مدینه . پیغمبر صلی اﷲ علیه و سلم اول ماه صفر بر ایشان تاختن کرد و ایشان چون خبر آمدن او بشنیدند بگریختند پس چون پیغمبر صلی اﷲ علیه و سلم آنجا رسید کس را نیافت و آخر ماه صفر به مدینه بازآمد و بماه ربیعالاول در مدینه ببودو بدین ماه اندر، دختر خود را نام او ام کلثوم بزنی به عثمان داد که رقیه نمانده بود و این دختر دیگر بدو داد و عثمان بدو دختر داماد آن حضرت بود پس بماه ربیعالاول کس فرستاد که کعب بن الاشرف را بکشتند که از وی بسیار آزارها داشت و بیحرمتیها کرده بود و گفته بود و این کعب بن اشرف مردی بود از جهودان بنی النضیر ومهتر و سخن روا بود و بر آن حصار بنی النضیر حکم داشتی و خرماستانی داشت و او را هر سال گندم بسیار آمدی و خرمای بسیار و مردمان را بسلف دادی و خواسته بسیاراز این معاملت کرده بود و مردی بود فصیح شاعر که پدرش از قبیله ٔ بنی طی بود و مادرش از بنی النضیر و آن روز که زیدبن حارثه بدر مدینه آمد ببشارت کعب بن اشرف بدر مدینه بود و زید همی گفتی که از قریش فلان و فلان را بکشتند و مهتران را نام میبرد کعب بن اشرف گفت این نشاید بودن و این همه خویشان وی بودند چون خبر درست شد او به مکه شد و مردمان را تعزیت کرد و شعر و مرثیه گفت . پیغمبر صلی اﷲ علیه و سلم و مسلمانان را هجو کرد و باز بمدینه آمد و پیغمبر را صلی اﷲ علیه و سلم خبر آمد که او بشعر اندر هجو گفته است و هر که بمدینه آمدی گفتی بگرئید (؟) تا مردمان پندارند که محمد نمانده است و تا دین او را بقا نبود و این سخن به آن حضرت همی رسید و یک روز اندر میان انصار نشسته بود وحدیث کعب بن اشرف همی کردند پیغمبر علیه السلام از وی بنالید و گفت کیست که تن خود بخدای بخشد و او را بکشد مردی از انصار نام او محمدبن مسلمه برخاست و گفت یا رسول اﷲ من بروم و او را بکشم پیغمبر صلی اﷲ علیه و سلم برو دعا کرد و سه روز برآمد و آن حضرت چشم همی داشت که برود و چون نرفت او را گفت چرا نرفتی گفت یا رسول اﷲ سه روز است تا نان نخورده ام از این غم گفت چرا گفت زیرا که زبان گروگان کرده ام با تو و ترسم که آن را وفا نتوانم کردن که این کعب مردی بزرگ است و وی را تبع بسیار و بحصاری استوار اندر است فرمود که توجهد بکن اگر بتوانی مبارک و اگر نتوانی معذوری گفت یا رسول اﷲ مرا اندر این کار یاران بایند. مردی بود از انصار نام وی سلکان و کنیت او ابونایله و با محمدبن مسلمه دوست بود و با کعب شیر خورده بود و هرگه که کعب به مدینه آمدی بخانه ٔ وی فرودآمدی و وی را دوست داشتی و بر وی ایمن بودی و محمدبن مسلمه سوی وی شد ووی را از این کار آگاه کرد و گفت اگر تو با من یار باشی این کار بتوانم کردن و دل پیغمبر خدای را خوش کردن . ابونایله اجابت کرد و گفت دیگر یاران باید پس هفت تن از انصار یار شدند و بنشستند و تدبیر کار کردن که چگونه کنند چون تدبیر راست شد به نیت رفتن بیامدند و وقت نماز خفتن رسول خدای صلی اﷲ علیه و سلم را آگاه کردند که ما میرویم و ما را سخنانی چند باید گفتن بغیبت تو (؟) پیغمبر صلی اﷲ علیه و سلم تا بقیع با ایشان برفت پس گفت بسم اﷲ بروید و زود بازگردید ایشان برفتند تا بحصار کعب شدند چون به نیم فرسنگی رسیدندپیش حصار خرماستانی بود و حصار بنی نضیر برابر بود وگرداگرد حصار اندر جهودان بودند و ایشان برفتند و بشب اندر حصار کعب شدند و کعب به نو زنی کرده بود و با زن بر بام حصار خفته بود ابونایله یاران را براه بنشاند و خود با سلاح بدر حصار آمد و کعب را بانگ کرد کعب بیدار شد و وی را بشناخت و پاسخ داد و سر فروکردابونایله گفت سخنی با تو دارم گفت بدین وقت ترا با من چه سخن است گفت آمده ام تا با تو مشورت کنم به کاری اندر، اگر توانی فرودآی و اگر نتوانی بازگردم کعب برخاست که فرودآید زن دامن وی بگرفت و گفت مشو کعب گفت این برادر من است شیرخورده و در او شب و روز بر من گشاده است و اگر من در خویش بر وی ببندم زشت بود ومن هرگز از در وی بازنگشتم زن گفت مرو که شب است و ندانی که چه شود گفت بر وی ایمن ترم که بر تن خویش . زن دست از دامن او بازداشت کعب گفت «لو دعی الفتی بطعنه فقد اجاب » و این مثل عرب است که اگر جوانمرد را بکشتن خوانند اجابت کند و این مثل کعب از گستاخی و دلیری گفت و ندانست که آن خود حقیقت است و آنچه به زبانش رفت راست خواهد بود پس چون از حصار بیرون شد ابونایله گفت آگاه باش ای برادر که آمدن من از مدینه بدان بود که این محمّد شوم است و در همه زمین ما قحط و تنگی افتاد و طعام نیست شد. کعب دست بریش فرودآورد وگفت من پسر پدر خویشم شما را گفتم که این خیری نیست و این کار وی را اصلی نیست ابونایله گفت مردمان را همه پدید آید سخن تو و من خاصه گرسنه شده ام و بدر توآمده ام بدان که تا مرا لختی گندم دهی یا خرما تا من بسر عیالان روم و هرچه خواهی گروگان دهم دیگر یاران با منند بدین خرماستان نشسته و شرم داشتند بر تو آمدن که من فرازآمدم تا بگویم که مرا اجابت کنی کعب گفت مرا بسی طعام نمانده است ولیکن نتوانم ترا بیازردن ابونایله گفت ما شب بدان آمدیم تا اگر اجابت کنی کسی این حال نداند کعب گفت اجابت کردم ولیکن خواهم که فرزندان بمن گروگان کنی ابونایله گفت ما را رسوا خواهی کردن میان مردمان ما گروگان سلاحها آورده ایم تا پیش تو گروگان کنیم و سلاح ترا بهتر بود کعب گفت روا باشد ابونایله یاران را بخواند محمدبن مسلمه با یاران فرازآمدند با سلاحها پیش او بنشستند و حدیث همی کردند و در جمله کعب با ایشان گفت من شما را گفتم که این مرد شوم است و این کار او بسی نپاید گفتند هرچه تو گفتی ما را پدید آمد کعب موی داشت تا گردن و آن موی برمشک و عود کرده بود و ابونایله هر ساعت سر او فروکشیدی و همی بوئیدی و همی گفتی خوش عطری است چون از شب لختی بگذشت کعب گفت از این سلاحها برکشید و بنهید و ابونایله گفت ساعتی در این خرماستان تماشا کنیم مگر این غم کمتر شود پس آن سلاحها ترا دهیم تا بخانه بری و فردا چهارپایان بیاریم و طعام ببریم کعب برخاست و با ایشان برفت و حدیث همی کردند ابونایله هر زمان دست به موی فروآوردی و بر دماغ خویش مینهادی و آن عطر را می ستودی چون به میان خرماستان درشدند ابونایله هردو موی او محکم بگرفت و گفت مدد دهید محمدبن مسلمه او را نیز استوار بگرفت و حارث بن اوس نیز یاری کرد و هر سه او را بر جای داشتند دیگران دست بشمشیر بردند و همی زدند و یک از حصار آگاه شد و بانگ کرد و چراغ برافروختند و زنش از بام بخروشید و ایشان او را بکشتند و برفتند و یکی شمشیر بغلط بر سر حارث بن اوس فرودآمده بود و خون از وی می آمد و ایشان چون دانستند که او کشته شد دست بازداشتند و بدویدند و سوی مدینه راه برگرفتند از بیم آنکه مردمان ایشان را طلب کنند و حارث نتوانست دویدن بر اثر ایشان نرم نرم برفت و از جهودان کس از دنبال ایشان نیارست رفتن و چون بنزدیک مدینه شدند ایمن گشتند و ایستادند تا حارث برسید. سپیده دم بود به مدینه اندر آمدند پیغمبر صلی اﷲ علیه و سلم را دیدند که نماز همی کرد او را خبر دادند شاد شدو خدای را شکر کرد و ایشان را دعا گفت و باد بر سر حارث دمید و آن جراحت و زخم هم در وقت به شد و این در ماه ربیعالاول بود - انتهی . و رجوع به ذوامر شود.<br /></font></div>'),
(130052, 'ذات الامراد', '<span class=\"hlight\">ذات الامراد.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130053, 'ذات الامرار', '<span class=\"hlight\">ذات الامرار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130054, 'ذات الاوتار', '<span class=\"hlight\">ذات الاوتار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ ]</font></b> (ع ص مرکب، اِ مرکب ) رودجامه . آلت زهی . هر آلت موسیقی که آن را زه و وتر باشد.<br /></font></div>'),
(130055, 'ذات الاکارع', '<span class=\"hlight\">ذات الاکارع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اَ رِ ]</font></b> (اِخ ) نام قصیده ٔ رائیه از فرزدق شاعر معروف است و این یکی از قصائد خوب اوست و مطلع آن این است :<br />عرفت با علی رأس الفا و بعد ما<br />مضت سنة ایامها و شهورها.<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130056, 'ذات الاکیراح', '<span class=\"hlight\">ذات الاکیراح .</span> <font color=\"DarkGreen\"><b>[ تُل ْ اُ ک َ ]</font></b> (اِخ ) موضعی است به عراق و بدانجا دیری بنام دیر حنة. ابونواس گوید <span class=\"hlight\">:</span> <br />یا دیر حنة من ذات الاکیراح <br />من یصح عنک فانی لست بالصاحی .<br /> <font color=\"Red\">(المرصع).</font><br />و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> شود.<br /></font></div>'),
(130057, 'ذات البان', '<span class=\"hlight\">ذات البان .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) قال الطویق بن عاصم النمیری <span class=\"hlight\">:</span> <br />عرفت لحبی بین منعرج اللوی <br />و اسفل ذات البان مَبداً و محضراً<br />الی حیث فاض المذنبان و واجها<br />من الرمل ذی الارطی قواعد عُقّرا<br />بهاکن اسباب الهوی مطمئنة<br />ومات الهوی ذاک الزمان و اقصرا.<br />قال - المذنبان - وادیان بذات البان . و بان من قری مصر و بان من قری نیسابور، ثم من قری ارغیان . (معجم البلدان یاقوت حموی ). ابن الاثیر در المرصع گوید: نام موضعی است و در اشعار عرب بسیار یاد شده است و بان درختی است مشهور که میوه ٔ خوشبوی دارد شاعر گوید <span class=\"hlight\">:</span> <br />و یوم بذات البان قصر طوله <br />حدیث یکادالروح تشبهه لطفا.<br /></font></div>'),
(130058, 'ذات البروج', '<span class=\"hlight\">ذات البروج .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب ُ ]</font></b> (اِخ ) یا سماء ذات البروج، فلک هشتم است که بروج دوازده گانه را قدما در آن توهم کرده اند و آفتاب در هر ماهی از ماههای شمسی در یکی از این بروج جای دارد و بروج دوازده گانه اینها است : حمل، ثور، جوزا، سرطان، اسد، سنبله، میزان، عقرب، قوس، جدی، دلو، حوت . و سال شمسی یکدور سیر آفتاب در این دوازده برج است و در شرع سماء ذات البروج را کرسی نامند.<br /></font></div>'),
(130059, 'ذات البشام', '<span class=\"hlight\">ذات البشام .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب َ ]</font></b> (اِخ ) وادیئی است از بلاد هذیل <span class=\"hlight\">:</span> <br />و حاولت النکوس بهم فضاقت <br />علی ابراجها ذات البشام <br /><font color=\"Red\">(از المرصع) (معجم البلدان یاقوت ).</font><br /></font></div>'),
(130060, 'ذات البطن', '<span class=\"hlight\">ذات البطن .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب َ ]</font></b> (ع اِ مرکب ) آنچه در شکم بود از فضول .<br /></font></div>'),
(130061, 'ذات البعل', '<span class=\"hlight\">ذات البعل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب َ ]</font></b> (ع ص مرکب ) زن شوهردار.<br /></font></div>'),
(130062, 'ذات البهق', '<span class=\"hlight\">ذات البهق .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب َ ]</font></b> (اِخ ) موضعی است و رؤبة گوید: شذب اخراهن عن ذات البهق . (الموشح ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>).<br /></font></div>'),
(130063, 'ذات البین', '<span class=\"hlight\">ذات البین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ب َ ]</font></b> (ع اِ مرکب ) مشترک میان دوتن یا دو قوم . میان دو کس یا دو جماعت، دوجانبه . دوجانبی، دوطرفی . که شامل هر دو جانب بود، اصلاح ذات البین . افساد ذات البین <span class=\"hlight\">:</span> رسول فرستادیم نزدیک برادر... و پیغامها دادیم رسول را که اندر آن صلاح ذات البین بود. (تاریخ بیهقی ). مشایخ بخارا به اصلاح ذات البین برخاستند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span>). ملک نوح بعد از حصول رضاء جانبین و حدوث صفاء ذات البین بر اثر وزیر روانه شد. (ترجمه ٔ تاریخ یمینی همان نسخه ). و او را <font color=\"DarkGreen\"><b>[ ابوعلی سیمجور فایق را ]</font></b> به موافقت و مرافقت خویش و اتحاد ذات البین بفریفت و او را در این دعوت سمح القیاد یافت . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>). فایق ... ابوعلی را گفت مقصود از ارسال تو بخطه ٔ جرجانیه و التفاتی که بجانب تو کرده اند، تفریق ذات البین است و آنکه سلسله ٔ اتحاد و موافقت ما از هم فروگشایند... (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>). بخفض جناح ذلت پیش آئی و به استمالت خاطر و استقالت از فساد ذات البینی که در جانبین حاصل است مشغول شوی . (مرزبان نامه ).<br /></font></div>'),
(130064, 'ذات التلافیف', '<span class=\"hlight\">ذات التلافیف .</span> <font color=\"DarkGreen\"><b>[ تُت ْت َ ]</font></b> (ع اِ مرکب ) روده های باریکی است در شکم . (منتهی الارب ).<br /></font></div>'),
(130065, 'ذات التنانیر', '<span class=\"hlight\">ذات التنانیر.</span> <font color=\"DarkGreen\"><b>[ تُت ْ ت َ ]</font></b> (اِخ ) عقبه ای است محاذی زباله و آن منزلی از منازل بربریة است . راعی گوید <span class=\"hlight\">:</span> <br />فلمّا علا ذات التنانیر صوته <br />تکشف من برق قلیل صواعقه .<br /><font color=\"Red\">(المرصع) (معجم البلدان ).</font><br /></font></div>'),
(130066, 'ذات الثری', '<span class=\"hlight\">ذات الثری .</span> <font color=\"DarkGreen\"><b>[ تُث ْ ث ِ ]</font></b> (اِخ ) جایگاهی است منسوب به ثری .<br /></font></div>'),
(130067, 'ذات الثقبتین', '<span class=\"hlight\">ذات الثقبتین .</span> <font color=\"DarkGreen\"><b>[ تُث ْ ث ُ ب َ ت َ ]</font></b> (ع اِ مرکب ) یکی از آلات فلکی که از او اختلاف منظر گیرند.<br /></font></div>'),
(130068, 'ذات الجرف', '<span class=\"hlight\">ذات الجرف .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج ُ رُ ]</font></b> (اِخ ) موضعی است و در آنجا جنگی عبس و یربوع را بوده است و جایگاهی است در نزدیکی مدینه . (المرصّع).<br /></font></div>'),
(130069, 'ذات الجزع', '<span class=\"hlight\">ذات الجزع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج ِ ]</font></b> (اِخ ) موضعی است . (المرصّع).<br /></font></div>'),
(130070, 'ذات الجفوف', '<span class=\"hlight\">ذات الجفوف .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج ُ ]</font></b> (اِخ ) لقب زنی معاصر رسول اکرم صلوات اﷲ علیه که بزائید و خون نفاس ندید و ازین رو بدو لقب ذات الجفوف دادند. (المرصّع).<br /></font></div>'),
(130071, 'ذات الجلال', '<span class=\"hlight\">ذات الجلال .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج ِ ]</font></b> (اِخ ) نام اسپ هلال بن قیس اسدی .<br /></font></div>'),
(130072, 'ذات الجلامید', '<span class=\"hlight\">ذات الجلامید.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج َ ]</font></b> (اِخ ) موضعی است در نزدیکی بصره و بدان جا عرب را حرب ها بوده است . <BR><font color=\"Blue\">◄</font> ونام حربی از حروب عرب است و آن را یوم القُبیبات نیزنامند و قبیبات موضعی است نزدیک بصرة. (المرصّع).<br /></font></div>'),
(130073, 'ذات الجنادع', '<span class=\"hlight\">ذات الجنادع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج َ دِ ]</font></b> (ع اِ مرکب ) بلا. سختی . داهیة.<br /></font></div>'),
(130074, 'ذات الجنب', '<span class=\"hlight\">ذات الجنب .</span> <font color=\"DarkGreen\"><b>[ تُل ْ جَم ْ ]</font></b> (ع اِ مرکب ) درد پهلو. (مهذب الاسماء). برسام . جُناب . نوعی بیماری پهلو. درد و آماس پهلو. ورم حارّ مولم در نواحی صدر. وَرم ِ حجاب مستبطن . دردی است به دنده ها با سرفه و تب . سینه پهلو. ورم حارّ مولم که در نواحی سینه پیدا شود که قسمتی از آن را شوصة و قسمی را برساما و قسمی را ذات الجنب ساده گویند. ورمی است حارّ که در حوالی سینه پدید آید. (منتهی الارب ). و صاحب آنندراج گوید:ورمی باشد در حجاب که آن پرده ای است میان قلب و معده و این ورم گاه در یمین بود و گاهی در یسار و علامات آن درد پهلو با تب و ضیق النفس بود و داود ضریر انطاکی گوید: شوصة و ذات الجنب، مرضان اتحدا مادة و علاجا و هما عبارة عن تحیز ما فسد من الاخلاط بین الاغشیة فان کان فی أحدالجانبین فذات الجنب . و علامته الحمی و منشاریةالنبض و السعال مطلقا و ضیق النفس غالباً و أسلمه البلغمی و اردؤه السوداوی و قد ینفجر و لو من خارج فی النادر و الابان استبطن الخلط غیر ما ذکر فهی الشوصة و یقال لما بین الکتفین منها ذات العرض و مقابلهاذات الصدر و منها البرسام و تقدم و تکون فی العضل و فی المنتصب و أی جهة حلتها منعت المیل الیها و النوم علیها و قد تعم فتمنع من الکون علی سائرالاشکال و علامتها یبس العصب و العضل و عدم الحرکة و علامات الخلط الغالب - انتهی . صاحب کشاف اصطلاحات الفنون گوید: ذات الجنب نزد پزشکان ورمی است حار و دردناک که در اطراف سینه یا در عضلات باطن یا در پرده ٔ اندرون، یا در پرده ٔ حاجز بین آلات غذاء و آلات تنفس یا در عضلات خارج یا در پرده ٔ بیرون بمشارکت پوست یا بغیر مشارکت پوست عارض میشود. و بیمناک ترین انواع این بیماری آن است که پرده ٔ حاجز حادث شود که آن را ذات الجنب خالص نامند بنا بر تعریفی که شیخ کرده است، چه شیخ بین این بیماری و بیماری شوصه فرقی ننهاده . و این بیماری را با بیماریهای برسام و شوصه الفاظ مترادف یکدیگر شناخته است . سمرقندی گوید: برسام عبارت از ورمی است که عارض میشود پرده ای را که بین جگر و معده واقع شده باشد. و آن پرده ای است که حائل بین معده و پیوسته به حجاب حاجز است . و شوصه عبارت است از ورمی که عارض میشود در دنده های پشت و ذات الجنب خالص ورمی است که عارض میگردد غشاء مستبطن مر اضلاع و حجاب حاجز را که در یکی از دو طرف پهلو واقع است . چنانکه در اقسرائی گفته و در بحر الجواهر گوید: ذات الجنب ورمی است حار و دردناک که در اطراف سینه حادث میشود. پس اگر این بیماری در عضله ٔ سینه عارض شود و خصوصاً در عضله ٔ داخل یا در حجاب اضلاع از داخل آن را شوصه نامند. و اگر در غشاء مستبطن سینه حادث گردد آن را برسام خوانند. و اگر در حجاب حاجز ایجاد شود ذات الجنب به اسم عام گویند. و صاحب ذخیره ٔ خوارزمشاهی گوید: آماسی است گرم و دردناک اندر نواحی سینه . اما اگر آماس اندر عضله های سینه باشد خاصة اندر عضله های زندرونین آن را شوصه گویند و اگر اندر غشاء باشد که زندرون سینه بدان پوشیده است و سینه را همچون بطانه است یعنی آستری، آن را برسام گویند یعنی آماس سینه . (سام آماس است و بر، سینه ) و اگر اندر حجاب باشد که میان احشاء برسوئین و فروسوئین ایستاده است آن را ذات الجنب گویند و بسیار باشد که اندر جگر آماسی گرم افتد و معالیق او کشیده میشود و درد آن بحجاب بازمیدهد و نفس تنگ میشود و بیمار و طبیب هر دو پندارند ذات الجنب است و... آن ذات الکبد باشد. (ذخیره ٔ خوارزمشاهی ) <span class=\"hlight\">:</span> و اندر همه ٔ انواع ذات الریه و ذات الصدر وذات الجنب جهد باید کرد تا سینه از رطوبتها پاک گردد. (ذخیره ٔ خوارزمشاهی ) .<br /></font></div>'),
(130075, 'ذات الجنب کاذب', '<span class=\"hlight\">ذات الجنب کاذب .</span> <font color=\"DarkGreen\"><b>[ تُل ْ جَم ْ ب ِ ذِ ]</font></b> (ترکیب وصفی، اِ مرکب ) ذات الجنب خفیف .<br /></font></div>'),
(130076, 'ذات الجنبی', '<span class=\"hlight\">ذات الجنبی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ جَم ْ بی ی ]</font></b> (ع ص نسبی ) منسوب بذات الجنب .<br /></font></div>'),
(130077, 'ذات الجواشن', '<span class=\"hlight\">ذات الجواشن .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ج َ ش ِ ]</font></b> (اِخ ) نام زره قیس بن زهیر است که از احیحةبن جلاح بستده بود و ربیعبن زیاد آن را به غصب ببرد. (المرصع).<br /></font></div>'),
(130078, 'ذات الجیش', '<span class=\"hlight\">ذات الجیش .</span><font color=\"DarkGreen\"><b>[ تُل ْ ج َ ]</font></b> (اِخ ) نام وادیئی است در یک منزلی مدینه ٔ طیبة میان ذوالحلیفة و برثان و در این ذات الجیش گلوبند ام المؤمنین عایشه بنت ابی بکر رضی اﷲ عنها بگسیخت و برای تجسس دانه های آن رسول اکرم صلوات اﷲ علیه امر بتوقف جیش فرمود و آیه ٔ تیمم نازل گردید. عروةبن اُذینة گوید: کاد الهوی یوم ذات الجیش یقتلنی لمنزل لم یهج لاشوق من صقب . (از المرصع) (معجم البلدان ). و آن را اولات الجیش نیز نامند. رجوع به جزء <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130079, 'ذات الحاذ', '<span class=\"hlight\">ذات الحاذ.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) نام موضعی است و در شعر حجاج آمده است : امسی بذات الحاذ و الحذور. (المرصع) (معجم البلدان ).<br /></font></div>'),
(130080, 'ذات الحبک', '<span class=\"hlight\">ذات الحبک .</span> <font color=\"DarkGreen\"><b>[ تُل ْح ُ ب ُ ]</font></b> (ع ص مرکب، اِ مرکب ) آسمان . (آنندراج ). و ابن الأثیر در المرصع آرد: گویند بمعنی صاحب خلقت نیکوست و از این جاست که بافنده ٔ جامه ٔ خوب را گویند: مااحسن حبکه، و نیز گفته اند ذات الحبک بمعنی زینت است و برخی گفته اند که معنی آن راههاست . ج، ذوات الحبک .<br /></font></div>'),
(130081, 'ذات الحجب والنخاع', '<span class=\"hlight\">ذات الحجب والنخاع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح ُ ج ُ ب ِ وَن ْ ن ُ ]</font></b> (ع اِ مرکب ) بیماری التهاب حجاب ریه و قلب با نخاع .<br /></font></div>'),
(130082, 'ذات الحرمل', '<span class=\"hlight\">ذات الحرمل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َم َ ]</font></b> (اِخ ) نام موضعی است در شعر حجاج . (المرصع).<br /></font></div>'),
(130083, 'ذات الحلق', '<span class=\"hlight\">ذات الحلق .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح ِ ل َ ]</font></b> (ع اِ مرکب ) حلقه های متداخله ای است که علمای هیئات کواکب را بدان رصد کنند. (مفاتیح العلوم خوارزمی ). مجموع حلقه های بسیاری است فلزین یا چوبین یا از مُقوا که آسمان و حرکات کواکب را نماید و در مرکز حلقه ها کره ای خرد که نماینده ٔ زمین است . اصطرلاب الکری <span class=\"hlight\">:</span> ج، ذوات الحِلق . و هی خمس دوائر متخذة من نحاس، الاولی دائرة نصف النهار و هی مرکوزة علی الارض و دائرة معدل النهار و دائرةالعرض و دائرة المیل و فیه دائرةالسمتیة یعرف بها سمت الکواکب : و آلات رصد از کراسی و ذات الحلق و اسطرلابهای تام و نصفی و الشعاع (؟) دیگر که موجود بود برگرفتم . (جهانگشای جوینی ). و هر آلتی که رصد را بکار آید بساختند از دیوار و ذات الحلق و مانند این (نوروزنامه ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>) <br /></font></div>'),
(130084, 'ذات الحمات', '<span class=\"hlight\">ذات الحمات .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> یاقوت در شرح کلمه الحُنَبِطلة گوید: ماء لبنی سلول، یردها حاج الیمامة و ایاها عنی ابن ابی حفصة و کان نعت ماکان بین الیمامة و مکة، ماءالسلولیین ذات الحمات .<br /></font></div>'),
(130085, 'ذات الحماط', '<span class=\"hlight\">ذات الحماط.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َ ]</font></b> (اِخ ) یا روضة ذات الحماط، موضعی است، بنواحی مدینة <span class=\"hlight\">:</span> <br />و حلت بروضة ذات الحماط<br />و غدر انها فائضات الجهام .<br /></font></div>'),
(130086, 'ذات الحمام', '<span class=\"hlight\">ذات الحمام .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َم ْ ما ]</font></b> (اِخ ) موضعی است میان اسکندریة و افریقیة. رجوع به افریقیه شود.در چهل فرسنگی مغرب مصر. (المرصع). و یاقوت گوید درفتوح ذکر آن آمده است . و به افریقیة نزدیکتر است .<br /></font></div>'),
(130087, 'ذات الحمام', '<span class=\"hlight\">ذات الحمام .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح ُ ]</font></b> (اِخ ) موضعی است میان مکه و مدینه . <BR><font color=\"Blue\">◄</font> نام آبی بدیار قُشیر، نزدیک یمامة. <BR><font color=\"Blue\">◄</font> نام آبی جاهلی . به ضریّة.<br /></font></div>'),
(130088, 'ذات الحنزاب', '<span class=\"hlight\">ذات الحنزاب .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح ِ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ).<br /></font></div>'),
(130089, 'ذات الحنظل', '<span class=\"hlight\">ذات الحنظل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َظَ ]</font></b> (اِخ ) عقبه ای است میان مکه و جده . (المرصع).<br /></font></div>'),
(130090, 'ذات الحنظل', '<span class=\"hlight\">ذات الحنظل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َ ظَ ]</font></b> (اِخ ) رجوع به ثنیة ذات الحنظل در همین لغت نامه شود.<br /></font></div>'),
(130091, 'ذات الحومل', '<span class=\"hlight\">ذات الحومل .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ح َ م َ ]</font></b> (اِخ ) نام موضعی است در شعر حجاج . (المرصّع).<br /></font></div>'),
(130092, 'ذات الخال', '<span class=\"hlight\">ذات الخال .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) نام موضعی است .<br /></font></div>'),
(130093, 'ذات الخال', '<span class=\"hlight\">ذات الخال .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) لقب معشوقه ٔ هارون الرشید خلیفه ٔ عباسی است که بحسن و هنر و دانش و دهاء مشهور است . و نام او خنث است و لقب ذات الخال ازآنرو بوی داده اند که خجگی دلکش بر لب زبرین داشت .<br /></font></div>'),
(130094, 'ذات الخطمی', '<span class=\"hlight\">ذات الخطمی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ خ ِ ]</font></b> (اِخ ) موضعی است بر راه تبوک و بدانجاست یکی از مساجد رسول صلوات اﷲ علیه که گاه عزیمت به تبوک در آن نماز گزارده است .<br /></font></div>'),
(130095, 'ذات الخف', '<span class=\"hlight\">ذات الخف .</span> <font color=\"DarkGreen\"><b>[ تُل ْ خ ُف ف ]</font></b> (ع ص مرکب ) دارنده ٔ سپل . نرم پای . ج، ذوات الاخفاف . یا ذوات الخف ّ. سپل داران . نرم پایان، مانند اشتر.<br /></font></div>'),
(130096, 'ذات الخمار', '<span class=\"hlight\">ذات الخمار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ خ ِ ]</font></b> (اِخ ) موضعی است به تهامة. (منتهی الارب ). حمیدبن ثور گوید <span class=\"hlight\">:</span> <br />و قد قالتا هذا جمیعی و ان یری <br />بعلیاء او ذات الخمار عجیب .<br /><font color=\"Red\">(از المرصع) (معجم البلدان ).</font><br /></font></div>'),
(130097, 'ذات الخمار', '<span class=\"hlight\">ذات الخمار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ خ ِ ]</font></b> (اِخ ) لقب هنیدة عمّه ٔ فرزدق است . و از آنرو وی را ذات الخمار گویند که وی چانه بندخویش را برگرفت آنگاه که پدر او صعصعةبن ناجیه و برادر وی غالب بن صعصعة و خال او اقرع بن حابس و شوهرش زبرقان بن بدر در خیمه ٔ او بودند و گفت کیست از زنان عرب که چهار محرم بزرگوار چون محارم من داشته باشد.<br /></font></div>'),
(130098, 'ذات الخنادع', '<span class=\"hlight\">ذات الخنادع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ خ َ دِ ]</font></b> (ع اِ مرکب ) داهیة.<br /></font></div>'),
(130099, 'ذات الخیار', '<span class=\"hlight\">ذات الخیار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) موضعی است و آن را عین اباغ نیز نامند.<br /></font></div>'),
(130100, 'ذات الخیم', '<span class=\"hlight\">ذات الخیم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ خی ی َ ]</font></b>(اِخ ) از بلاد مهره به اقصای یمن . (معجم البلدان ).<br /></font></div>'),
(130101, 'ذات الدبر', '<span class=\"hlight\">ذات الدبر.</span> <font color=\"DarkGreen\"><b>[ تُدْ دَ ]</font></b> (اِخ ) عقبه ای است به کوهی و گویند نام موضعی است و دَبرجماعت نحل است .<br /></font></div>'),
(130102, 'ذات الدخول', '<span class=\"hlight\">ذات الدخول .</span> <font color=\"DarkGreen\"><b>[ تُدْ دَ ]</font></b> (اِخ ) پشته و زمین فرازی به دیار بنی سلیم <span class=\"hlight\">:</span> <br />قعدت له ذات العشاء و دونه <br />شماریخ من ذات الدخول و منکب .<br /><font color=\"Red\">(از المرصع).</font><br /></font></div>'),
(130103, 'ذات الدیر', '<span class=\"hlight\">ذات الدیر.</span> <font color=\"DarkGreen\"><b>[ تُدْ دَ ]</font></b> (اِخ ) عقبه ای است به بلاد هذیل و اصمعی ذات الطیور روایت کرده است . (المرصع).<br /></font></div>'),
(130104, 'ذات الذخایر', '<span class=\"hlight\">ذات الذخایر.</span> <font color=\"DarkGreen\"><b>[ تُذْ ذَ ی ِ ]</font></b> (اِخ ) ناحیه ای است میان حمص و دمشق . رجوع به کلمه ٔ نبک در معجم البلدان یاقوت شود.<br /></font></div>'),
(130105, 'ذات الذرات', '<span class=\"hlight\">ذات الذرات .</span> <font color=\"DarkGreen\"><b>[ تُذْ ذَرْ <span class=\"hlight\" dir=\"rtl\">/</span> را ]</font></b> (اِخ ) نام موضعی براه تبوک از مدینه و بدانجا یکی از مساجد رسول اکرم صلوات اﷲ علیه است . (المرصع).<br /></font></div>'),
(130106, 'ذات الذراع', '<span class=\"hlight\">ذات الذراع .</span> <font color=\"DarkGreen\"><b>[ تُذْ ذِ ]</font></b> (اِخ ) نام جایگاهی بر طریق تبوک و بدانجا یکی از مساجد رسول صلوات اﷲ علیه باشد یعنی حضرت او بدانجا نماز گزارده است . (المرصع).<br /></font></div>'),
(130107, 'ذات الرایات', '<span class=\"hlight\">ذات الرایات .</span> <font color=\"DarkGreen\"><b>[ تُرْ را ]</font></b> (اِخ ) رجوع به ذات الرایه شود.<br /></font></div>'),
(130108, 'ذات الربا', '<span class=\"hlight\">ذات الربا.</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ]</font></b> (اِخ ) موضعی است بدانسوی جحفة. کثیر گوید <span class=\"hlight\">:</span> <br />الی ابن ابی العاصی بدوت ارقلت (؟)<br />و بالسفح من ذات الربا فوق مطعن .<br /><font color=\"Red\">(از المرصع).</font><br /></font></div>'),
(130109, 'ذات الرجع', '<span class=\"hlight\">ذات الرجع.</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ]</font></b> (ع ص مرکب ) صفت آسمان <span class=\"hlight\">:</span> و السماء ذات الرجع. (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٨٦</span>). لانها ترجع الغیب و ارزاق العباد. (المرصع).<br /></font></div>'),
(130110, 'ذات الرحم و الصفاق', '<span class=\"hlight\">ذات الرحم و الصفاق .</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ح ِ م ِ وَص ْ ص ِ ]</font></b> (ع اِ مرکب ) بیماری التهاب رحم و صفاق . <br /></font></div>'),
(130111, 'ذات الرحم و الورید', '<span class=\"hlight\">ذات الرحم و الورید.</span> <font color=\"DarkGreen\"><b>[ ت ُ رْ رَ ح ِ م ِ وَل ْ وَ ]</font></b> (ع اِ مرکب ) بیماری التهاب رحم و اورده .<br /></font></div>'),
(130112, 'ذات الرضم', '<span class=\"hlight\">ذات الرضم .</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ]</font></b>(اِخ ) موضعی بنواحی وادی القری و تیماء. (المرصع).<br /></font></div>'),
(130113, 'ذات الرعد', '<span class=\"hlight\">ذات الرعد.</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ]</font></b> (ع اِ مرکب ) جنگ . حرب . شر و شدّت . و در مثل است : جاءَ بذات الرعد و الصلیل، یعنی برپا کرد فتنه و شر را چنانکه ابر رعد و برق تولید کند. و صلیل صوت شدید باشد. (المرصع).<br /></font></div>'),
(130114, 'ذات الرقاع', '<span class=\"hlight\">ذات الرقاع .</span> <font color=\"DarkGreen\"><b>[ تُرْ رِ ]</font></b> (اِخ ) نام قریه ای به نخیل . (المرصع). و کوهی است و در آن کوه جای جای سرخی و سیاهی و سپیدی است یعنی رقعه ها به الوان مختلف .<br /></font></div>'),
(130115, 'ذات الرقاع', '<span class=\"hlight\">ذات الرقاع .</span> <font color=\"DarkGreen\"><b>[ تُرْ رِ ]</font></b>(اِخ ) (غزوه ٔ...) یکی از غزوات رسول اکرم صلوات اﷲ علیه در جبل ذات الرقاع . و این نام را به غزوه برای وقوع آن در این جبل داده اند و بعضی گویند هفت تن از صحابه را در این غزوه یک شتر برنشست بیش نبود و هر هفت تن پای برهنه داشتند و به نوبت بر آن می نشستند تا در آخر پایهای آنان بکفید و خون روان گردید ناچار رقعه ها یعنی ریته ها از جامه ٔ خویش برگرفته در پایها می بستند و غزوه را از آن روی ذات الرقاع نامیدند و جماعتی وجه تلقب این غزوه را گوناگونی اعلام افراشته ٔ جیش گفته اند و گروهی گویند بدین مکان درختی بوده است و آن درخت را ذات الرقاع میخوانده اند. و این غزوه به سال چهارم هجرت بود به ماه جمادی الاولی رجوع به امتاع الاسماع جزء <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">١٨٨</span> - <span class=\"hlight\" dir=\"rtl\">١٩٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٨٢</span> و طبقات ابن سعد، ص <span class=\"hlight\" dir=\"rtl\">٥٦٤</span> و مجمع الامثال میدانی در یوم ذات الرقاع شود. و صلوة خوف را بار اوّل مسلمانان با رسول اﷲ صلوات اﷲعلیه بدین غزوه گزاردند. و در ترجمه ٔ طبری بلعمی آمده است : فصل : در ذکر خبر غزو ذات الرقاع : چون پیغمبرصلی اﷲ علیه و سلم از بنی نضیر بپرداخت و هر دو ربیعبگذشت و از جمادی الاول نیمه ای برفت خبر آمد که عرب بسیار گرد آمده اند از بنی غطفان و بنی محارب و بنی ثعلبه و آهنگ مدینه خواهند کرد. پیغمبر صلی اﷲ علیه و سلم با سپاه بیرون آمد و عثمان را بر مدینه خلیفت کرد و خود برفت و به بادیه اندر شد بر هشت روزه راه، و جانبی فرودآمد که آن را ذات الرقاع خوانند و گروهی گویندکوهی بود آنجا بحدود نجد از او چند رقعه سیاه و چندرقعه زرد و کبود و سرخ و هرچه در جهان رنگی است بر آن رقعه بینند و گروهی گویند آنجا خرمابنان بود و درختان بسیار و جمعی از عرب آنجا گرد آمدند و بنزدیک پیغمبر صلی اﷲ علیه و سلم فرودآمدند و خدای عزّ و جل اندر دلشان افکند و از بیم حرب و زحمت بازنگشتند و سه روز بودند و از یکدیگر بترسیدند پس سپاه عرب بازگشتند و حرب نکردند و از هیبت پیغمبر صلی اﷲ علیه و سلم بهزیمت شدند و آنحضرت سه روز نماز خوف کرد و این آیه آمد: و اذا کنت فیهم فاَقمت لهم الصلوة. (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٢/٤</span>). و سپاه را بدو نیم کرد نیمی بفرمود که بر دشمن صف زنند و یک نیمه از پس او صف زدند و یک رکعت بکردندپس با ایشان برخاست و برکعتی دیگر آن صف که پیش دشمن بودند بیامدند و از پس پیغمبر علیه الصلوة والسلام ایستادند و تکبیر کردند و با او نماز کردند و باز بصف دشمن شدند و آن صف که با پیغمبر صلی اﷲ علیه و سلم رکعت ثانی کرده بودند آنجا بجای نماز آمدند بی آنکه سخن گفتند و رکعتی نماز کردند و سلام دادند تا هر صفی یک رکعت نماز با پیغمبر صلی اﷲ علیه و سلم کرده بودندو یک رکعت تنها و علماء بجماعت اندر خلاف کرده اند گروهی ایدون گویند که نماز جماعت فریضه است هر که بمزکت تواند شدن و نماز بجماعت تواند کردن و بدین آیة حجت کرده اند و گروهی گویند که فریضه نیست بجماعت، سنت است و اگر بجماعت کنند نیکوتر و مزد بیشتر و اگر بتنها کنند نیز روا باشد و نماز خوف بر همه واجب نیست واز فقها هست که گویند که با هیچ امام نشاید کردن .<br /></font></div>'),
(130116, 'ذات الرقاع', '<span class=\"hlight\">ذات الرقاع .</span> <font color=\"DarkGreen\"><b>[ تُرْ رِ ]</font></b> (ع ص مرکب، اِ مرکب ) (استخاره ٔ...) استخاره ای است که بر هریک از شش یا نه پاره کاغذ افعل و یا لاتفعل نویسند وبر زیر سجاده نهند و سپس نماز گزارند و بعد از نماز وادعیه و اوراد وارده یکی از آن شش یا نه رقعه را برگیرند اگر افعل باشد خوب و اگر لاتفعل باشد بد است .<br /></font></div>'),
(130117, 'ذات الرماح', '<span class=\"hlight\">ذات الرماح .</span> <font color=\"DarkGreen\"><b>[ تُرْ رِ ]</font></b> (اِخ ) موضعی نزدیک تبالة.<br /></font></div>'),
(130118, 'ذات الرماح', '<span class=\"hlight\">ذات الرماح .</span> <font color=\"DarkGreen\"><b>[ تُرْ رِ ]</font></b> (اِخ ) نام اسپی بنی ضبة را.<br /></font></div>'),
(130119, 'ذات الرمح ابرق', '<span class=\"hlight\">ذات الرمح ابرق .</span> <font color=\"DarkGreen\"><b>[ تُرْ رُ ح ِ اَ رَ ]</font></b> (اِخ ) موضعی بدیار بنی کلاب .<br /></font></div>'),
(130120, 'ذات الرمرم', '<span class=\"hlight\">ذات الرمرم .</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ رَ ]</font></b> (اِخ ) نام جایگاهی و بدانجا جنگی میان بنی عامر و بنوعبس رویداد و فیروزی بنوعامر را بود و رمرم منقوص و مخفف رمرام است و رمرام نوعی گیاه بهاری است . (المرصع). و رجوع به یوم ذات الرمرم در مجمع الامثال میدانی شود.<br /></font></div>'),
(130121, 'ذات الرواعد', '<span class=\"hlight\">ذات الرواعد.</span> <font color=\"DarkGreen\"><b>[ تُرْ رَ ع ِ ]</font></b> (ع اِ مرکب ) داهیة. جنگ . حرب .<br /></font></div>'),
(130122, 'ذات الریال', '<span class=\"hlight\">ذات الریال .</span> <font color=\"DarkGreen\"><b>[ تُرْ ر ی ]</font></b> (اِخ ) نام باغی باشد معروف . و ریال جمع رأل به معنی چوزه ٔ شترمرغ است . (المرصع).<br /></font></div>'),
(130123, 'ذات الریش', '<span class=\"hlight\">ذات الریش .</span> <font color=\"DarkGreen\"><b>[تُرْ ر ی ]</font></b> (ع اِ مرکب ) گیاهی است ماننده بقیصوم .<br /></font></div>'),
(130124, 'ذات الریوی', '<span class=\"hlight\">ذات الریوی .</span> <font color=\"DarkGreen\"><b>[ تُرْ ری ی َ وی ی ]</font></b> (ع ص نسبی ) منسوب بذات الریه .<br /></font></div>'),
(130125, 'ذات الزراب', '<span class=\"hlight\">ذات الزراب .</span> <font color=\"DarkGreen\"><b>[تُزْ زِ ]</font></b> (اِخ ) یکی از مساجد رسول صلوات اﷲ علیه است بر دو روزه راه از تبوک و آن را زراب نیز نامند.<br /></font></div>'),
(130126, 'ذات الزمین', '<span class=\"hlight\">ذات الزمین .</span> <font color=\"DarkGreen\"><b>[ تُزْ زُ م َ ]</font></b> (ع اِ مرکب ) میانه ٔ روزگار. (قاضیخان بدر محمد دهار). <BR><font color=\"Blue\">◄</font> در زمانی مقدّم .<br /></font></div>'),
(130127, 'ذات الساحل', '<span class=\"hlight\">ذات الساحل .</span> <font color=\"DarkGreen\"><b>[ تُس ْ سا ح ِ ]</font></b> (اِخ ) نام قریه ای به جیزه .<br /></font></div>'),
(130128, 'ذات الساق', '<span class=\"hlight\">ذات الساق .</span> <font color=\"DarkGreen\"><b>[ تُس ْ سا ]</font></b> (اِخ ) نام موضعی و نام درختی که رسول اکرم صلوات اﷲ علیه در یکی از غزوات در زیر آن نزول کرده و نماز گزارده است . (المرصّع).<br /></font></div>'),
(130129, 'ذات السباع', '<span class=\"hlight\">ذات السباع .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س ِ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130130, 'ذات الستار', '<span class=\"hlight\">ذات الستار.</span> <font color=\"DarkGreen\"><b>[ تُس ْ س ِ ]</font></b> (اِخ ) نام موضعی است و ابن اثیر در المرصع گوید: این نام در اشعار عرب بسیار یادشده است و آن راههای عقبه هاست به بر سوی حرم مکة.<br /></font></div>'),
(130131, 'ذات السعیر', '<span class=\"hlight\">ذات السعیر.</span> <font color=\"DarkGreen\"><b>[ تُس ْ س َ ]</font></b> (اِخ ) منزلی است نزدیک مدینه . و بلعمی در شرح غزوه ٔ انواط گوید: فصل در ذکر خبر غزو انواط: و این غزو را غزو انواطخوانند. پیغمبر صلی اﷲ علیه و سلم برفت و بر پایان کوهی شد و آن کوه را نام رضوی بود و همی رفت تا از حدّ یثرب بیرون شد و بحد تهامه درآمد و بمنزلی فرودآمدکه آن منزل را انواط گویند. خبر آمد که کاروان را بجهانیدند و کس را نیافتند و از آنجا به مدینه بازآمدند و چون ماه دیگر بود به جمادی الاولی برفت و ابوسلمةبن عبدالاشهل را بر مدینه خلیفه ساخت و علم بدست حمزه داد. و منزلی است بنزدیک مدینه آن را ذات السعیر خوانند پس پیغمبر را صلی اﷲ علیه و سلم خبر آمد که کاروان از این راه نیامد پس بر دست راست از این منزل برفتند و پیاده آمدند بمنزلی که آنجا نیز گذر کاروان بود، هم نیافتند و آنجا درختی بود بزرگ که آن را ذات النسا خوانند بسایه ٔ آن درخت فرودآمدند پس پیغمبر صلی اﷲعلیه و سلم زیر آن درخت نماز کرد و آنجا دیک پختند و شب آنجا بودند و آن مزگت زیر آن درخت که پیغمبر صلی اﷲ علیه و سلم نماز کرده است و جای آن دیک هست پس دیگر روز برفتند بطلب کاروان شدند بمنزلی دیگر و از آنجا بجائی شدند نامش مسرعه (؟) پس بمنزلی دیگر فرودآمدند نام آن صخرالرماد باز دیگر بجایی آمدند نامش شوب (؟) و از آنجا آب خوردند و باز بصحرا آمدند و اندرآن راه هیچ منزل و هیچ جای آب نماند که دانستند که کاروان گذر کند که نه همه گشتند و هیچ جای از کاروان اثر نیافتند پس براه راست بازآمدند و باز به ذات السعیر آمدند و آنجا مردمانی بودند از بنی لحم . پیغمبر صلی اﷲ علیه و سلم با ایشان صلح کرد و باز به مدینه آمد اندر ماه جمادی الاخر. و اندر این غزو ذات السعیر بودکه پیغمبر صلی اﷲ علیه و سلم علی مرتضی را طلب کرد ونیافت و از دیه بیرون شده بود و بزیر خرماستانی خفته و جامه از وی باز شده بود و روی او بخاک اندر رفته و پیغمبر علیه السلام او را بیدار کرد و گفت قم یا اباتراب این لقب بر علی علیه السلام بماند و او بدین فخرکردی و دوست داشتی که او را بدین کنیت خواندندی . عمار یاسر گفت من با علی خفته بودم هم بر آن خاک، چون آواز پیغمبر صلی اﷲ علیه و سلم شنیدم بیدار شدم آن حضرت را دیدم که علی را بیدار میکرد و علی برخاست و پیش پیغمبر صلی اﷲ علیه و سلم بایستاد و پیغمبر به ردای مبارک خویش سر و روی علی را پاک میکرد پس فرمود یا علی اندر این جهان بدبخت تر از آن کس نیست که ترا دشمن دارد و ترا بکشد و بر سرت زخم زند تا این محاسن تواز خون سرت تر شود و پیغمبر صلی اﷲ علیه و سلم پیش از آنکه بغزوها شود فاطمه را به علی علیه السلام داد و فاطمه هنوز سیزده ساله بود و به ماه صفر او را به خانه ٔ امیرالمؤمنین علی فرستاد پس از آن بغزوها بیرون شد به ربیعالاول و از این غزوها که آخر جمادی الاولی بازگشت پس چون از این غزوها بازگشت و روزی دو به مدینه بماند مردی بیامد از مکه نام او عمروبن جابر و به مدینه تاختن کرد و تا حدّ مدینه بیامد و ستوران مدینه براند از چراگاه چه گاو و گوسفند و خر هرچه یافتند ببردند و براه کج به بادیه اندر شدند و به مکه بردندو از مدینه بسه روز در راه بودند و پیغمبر صلی اﷲ علیه و سلم از پس سه روز خبر یافت پس برنشست با جماعتی از مهاجران و از پس ایشان بتاختند تا از حدّ مدینه بیرون آمدند و ایشان را درنیافتند و علم بدین غزو علی علیه السلام داشت پس برفتند تا بسر چاهی رسیدند آنجافرودآمدند و سه روز ببودند و باز به مدینه آمدند.<br /></font></div>'),
(130132, 'ذات السلاسل', '<span class=\"hlight\">ذات السلاسل .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س َ س ِ ]</font></b> (اِخ ) رجوع به ابوعون عبدالملک در همین لغت نامه شود.<br /></font></div>'),
(130133, 'ذات السلاسل', '<span class=\"hlight\">ذات السلاسل .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س َس ِ ]</font></b> (اِخ ) ابرق ذات السلاسل، موضعی است بدیار عرب .<br /></font></div>'),
(130134, 'ذات السلاسل', '<span class=\"hlight\">ذات السلاسل .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س َ س ِ ]</font></b> (اِخ ) نام موضعی به مشارق بزمین بلحا و عذره و بدانجا پس وادی قری بزمین جذام . و میدانی گوید نام آبی است بزمین بنوجذام شام که بسال هشتم از هجرت رسول اکرم صلوات اﷲ علیه جیشی برای تسخیر آن فرستاد و قائد این جیش عمروبن العاص بود. (المرصع). رجوع به حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> - <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> و امتاع الاسماع جزء اول صص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> شود. و این جنگ بنام غزوه ٔ ذات السلاسل و ذات السلسل نامیده شده است .<br /></font></div>'),
(130135, 'ذات السلسل', '<span class=\"hlight\">ذات السلسل .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س ُ س ُ ؟ ]</font></b> (اِخ ) رجوع به فقره ٔ فوق شود.<br /></font></div>'),
(130136, 'ذات السلیم', '<span class=\"hlight\">ذات السلیم .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س ُ ل َ ]</font></b> (اِخ ) نام جایگاهی است . ساعدةبن جؤیة گوید <span class=\"hlight\">:</span> <br />تَحَمَّلن من ذات السُلَیم کأنّها<br />سفائن یم یَنتحیها دبورها.<br /></font></div>'),
(130137, 'ذات السلیم', '<span class=\"hlight\">ذات السلیم .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س ُ ل َ ]</font></b> (اِخ ) نام موضعی است بنی ضبّة را بیمامة.<br /></font></div>'),
(130138, 'ذات السواسی', '<span class=\"hlight\">ذات السواسی .</span><font color=\"DarkGreen\"><b>[ تُس ْ س َ ]</font></b> (اِخ ) کوهی است بنی جعفربن کلاب را و اصمعی گوید: ذات السواسی شعبی است بنصیبین از ینوف یا آب راهه هاست که در ینوف میریزد. شاعر گوید <span class=\"hlight\">:</span> <br />و ابصر ناراً بذات السواسی .<br /><font color=\"Red\">(المرصع) (معجم البلدان ).</font><br /></font></div>'),
(130139, 'ذات السیب', '<span class=\"hlight\">ذات السیب .</span> <font color=\"DarkGreen\"><b>[ تُس ْ س َ ]</font></b> (اِخ ) رحبه ای است از رحاب اضم به حجاز. (المرصع) (معجم البلدان ).<br /></font></div>'),
(130140, 'ذات الشام', '<span class=\"hlight\">ذات الشام .</span> <font color=\"DarkGreen\"><b>[ تُش ْ شا]</font></b> (ع اِ مرکب ) ابن الاثیر در المرصع گوید: «ذات الشام »شقشقه ٔ شتر است از آنرو که بر آن نقطه های سیاه باشدچه شام جمع شامة است و شامة بمعنی خال و خجک است .<br /></font></div>'),
(130141, 'ذات الشبق', '<span class=\"hlight\">ذات الشبق .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ِ ]</font></b> (اِخ ) موضعی است در شعر <span class=\"hlight\">:</span> <br />کان ّ عجوزی لم تلد غیر واحد<br />و ماتت بذات الشبق غیر عقیم .<br /></font></div>'),
(130142, 'ذات الشر', '<span class=\"hlight\">ذات الشر.</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش َرر ]</font></b> (اِخ ) موضعی است . امروءالقیس گوید <span class=\"hlight\">:</span> <br />فلم تترک بذات الشر ظبیاً<br />و لم تترک بحبلها (؟) حمارا.<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130143, 'ذات الشری', '<span class=\"hlight\">ذات الشری .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ِ ]</font></b> (اِخ ) موضعی است معروف در قول بریق هذلی <span class=\"hlight\">:</span> <br />کأن ّ عجوزی لم تلد غیر واحد<br />و ماتت بذات الشری و هی عقیم . <br /></font></div>'),
(130144, 'ذات الشری', '<span class=\"hlight\">ذات الشری .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش َرْی ْ ]</font></b> (اِخ ) (بسکون الرّاء) نام موضعی است .<br /></font></div>'),
(130145, 'ذات الشعاع', '<span class=\"hlight\">ذات الشعاع .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ُ ]</font></b>(ع اِ مرکب ) یکی از آلات رصد است <span class=\"hlight\">:</span> و آلات رصد از کراسی و ذات الحلق و اسطرلابهای تام و نصفی و ذات الشعاع که موجود بود برگرفتم . (از نسخه ای از جهانگشای جوینی ). ذات المطرقین <br /></font></div>'),
(130146, 'ذات الشعبتین', '<span class=\"hlight\">ذات الشعبتین .</span> <font color=\"DarkGreen\"><b>[تُش ْ ش ُ ب َ ت َ ]</font></b> (ع اِ مرکب ) یکی از آلات رصد است و ابن الندیم در شرح حال ابن ابی عباد ابوالحسن محمدبن عیسی منجّم گوید: او راست کتاب العمل بذات الشعبتین .<br /></font></div>'),
(130147, 'ذات الشعبین', '<span class=\"hlight\">ذات الشعبین .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش َ ب َ ]</font></b> (اِخ ) یکی از وادیهای علاة به یمامه است و مخلافی است به یمن . (معجم البلدان ).<br /></font></div>'),
(130148, 'ذات الشعور', '<span class=\"hlight\">ذات الشعور.</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ُ ]</font></b> (اِخ ) صورتی از صور شمالی فلک میان صورت دب ّ اکبر و اسد و آن را حوض و ضفیرةالاسد و شعر بره نیس یا برنیکی و هلبة نیز نامند و مرکب است از نه کوکب مثنی و یک کوکب از قدر سیم .<br /></font></div>'),
(130149, 'ذات الشقوق', '<span class=\"hlight\">ذات الشقوق .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ُ ]</font></b> (اِخ ) منزلی است بطریق مکة. (المرصع). رجوع به ج <span class=\"hlight\" dir=\"rtl\">٦</span> عقدالفرید ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> شود. <BR><font color=\"Blue\">◄</font> یوم ذات الشقوق، یا حرب ذات الشقوق، نام یکی از جنگهای معروف عرب است . و شقوق موضعی است بطریق مکه بعد از واقصه ٔ کوفه .<br /></font></div>'),
(130150, 'ذات الشمال', '<span class=\"hlight\">ذات الشمال .</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ِ ]</font></b> (ع اِ مرکب ) دست چپ . سوی چپ . جهت چپ . طرف چپ . سوی دست چپ . (مهذب الاسماء). جانب چپ . (قاضی خان بدر محمد دهار). به چپ <span class=\"hlight\">:</span> <br />هم بتقلیب تو تا ذات الیمین <br />تا سوی ذات الشمال ای رب دین .<br /> <font color=\"Red\">مولوی .</font><br />و صاحب غیاث از لطائف نقل کند مراداز ذات الشمال گنه کاران و کافران باشند چرا که نامه ٔاعمال ایشان را بدست چپ آید، و صاحب آنندراج نیز عین آن را نقل کرده است .<br /></font></div>'),
(130151, 'ذات الشمیط', '<span class=\"hlight\">ذات الشمیط.</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش َ ]</font></b> (اِخ ) ریگی است بنی تمیم را و در آنجا گزنه و غضا روید. (المرصع).<br /></font></div>'),
(130152, 'ذات الشهور', '<span class=\"hlight\">ذات الشهور.</span> <font color=\"DarkGreen\"><b>[ تُش ْ ش ُ ]</font></b> (ع ص مرکب ) آن زن که بحد زنان رسیده لکن خون نمی بیند. عده ٔ طلاق او در صورت آرمیدگی با زوج سه ماه هلالی است .<br /></font></div>'),
(130153, 'ذات الشیح', '<span class=\"hlight\">ذات الشیح .</span> <font color=\"DarkGreen\"><b>[ تُش ْ شی ]</font></b> (اِخ ) صاحب المرصع گوید: موضعالحزن من دیار بنی تمیم . و در منتهی الارب آید: موضعی است در دیار بنی یربوع که در آن گیاه شیح بسیار روید.<br /></font></div>'),
(130154, 'ذات الصدر', '<span class=\"hlight\">ذات الصدر.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص َ ]</font></b> (ع اِ مرکب ) ورم حادث در حجاب قاسم صدر. یا گرد آمدن ریم در فضای سینه . (ذخیره ٔ خوارزمشاهی ). ورمی است در پرده ٔ سینه یا گرد آمدن ریم است در فضای سینه . (منتهی الارب ). و صاحب کشاف اصطلاحات الفنون گوید: نزد پزشکان ورمی است که حادث میشود در پرده ای که سینه رادو نیمه کند. و در طرفی که بر جانب شکم واقع شده باشد پس اگر در جانبی که بر پشت سر واقع شده باشد عارض شود آن را ذات العرض گویند. و داود ضریر انطاکی در تذکره در ذیل کلمه ٔ شوصة و ذات جنب گوید: و یقال لما بین الکتفین منها ذات العرض و مقابلها ذات الصدر. رجوع بکلمه ٔ ذات الجنب قسمت منقول از تذکره شود. <BR><font color=\"Blue\">◄</font> سرّ مرد. راز. و صاحب غیاث از لطائف نقل کند که ذات الصدر به معنی خداوند سینه یعنی دانای اسرار دل است و مراد از این اولیاء باشد. - انتهی <span class=\"hlight\">:</span> <br />سدّه و دیدان و استسقاء و سل <br />کسر و ذات الصدر و لدغ و درد دل .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ناخوشی ذات الصدر داشتن </span> ؛ به مزاح، حریص بنشستن صدر مجلس بودن است چنانکه عادت سوء بعض ارباب عمائم است .<br /></font></div>'),
(130155, 'ذات الصدع', '<span class=\"hlight\">ذات الصدع .</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص َ ]</font></b> (ع ص مرکب ) زمینی که روئیدن گیاه و تفجیر آب و جز آن آن را شکافته باشد. (المرصع).<br /></font></div>'),
(130156, 'ذات الصدور', '<span class=\"hlight\">ذات الصدور.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص ُ ]</font></b>(ع اِ مرکب ) افکار. اندیشه ها. حاجتها. (مهذب الاسماء). مضمرات قلب : انه علیم بذات الصدور. (قرآن <span class=\"hlight\" dir=\"rtl\">٥/١١</span>).<br /></font></div>'),
(130157, 'ذات الصفا', '<span class=\"hlight\">ذات الصفا.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص َ ]</font></b> (اِخ ) نام قریه ای به فیوم . <BR><font color=\"Blue\">◄</font> نام ماری یا قسمی مار که نابغه ذکر آن را در شعر آورده و قصه ای دارد.<br /></font></div>'),
(130158, 'ذات الصفاح', '<span class=\"hlight\">ذات الصفاح .</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص ِ ]</font></b> (اِخ ) موضعی است . (المرصع).<br /></font></div>'),
(130159, 'ذات الصمد', '<span class=\"hlight\">ذات الصمد.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص َ م َ ]</font></b> (اِخ ) موضعی است و گویند آبی است در شاکلةالحمی از ضریة و در آنجا جنگی بوده است بنی یربوع را و روز این جنگ را یوم ذی طلوح نامند بشار گوید <span class=\"hlight\">:</span> <br />یا طلل الحی ّ بذات الصمد<br />باﷲ خبر کیف کنت بعدی .<br />و رجوع به الموشح ص <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> شود.<br /></font></div>'),
(130160, 'ذات الصور', '<span class=\"hlight\">ذات الصور.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص ُ وَ ]</font></b> (اِخ ) غزو ذات الصور. بلعمی در ترجمه ٔ طبری گوید <span class=\"hlight\">:</span> چنین گویند که اندر دریاغزو کردن بر مسلمانان معاویه بگشاد و بروزگار عمر (؟) هر امیری که به شام بمردی ولایت آن امیر به معاویةدادی و چون همه ٔ شام معاویة را شد آهنگ روم کرد. ملک روم سپاهی را بساخت و روی به مصر نهاد با سپاهی که هرگز کس چنان سپاه بدریا اندر ندیده بود. امیر مصر عبداﷲبن ابی سرح بود و او نیز بیامد با چهل کشتی مقدار سی هزار مرد. چون کشتیها اندر دریا جایی رسید که آن را ذات الصور گویند مسلمانان کشتیهای رومیان بدیدندپانصد کشتی پر از خلق آکنده بترسیدند و باد برخاست سه شبان روز کشتیهای رومیان و مسلمانان در دریا بداشته بودند تا باد بنشست و کشتیها نزدیک یکدیگر آوردند و حربی ساختند به تیر و شمشیر و نیزه . حربی کردند سخت و تیری از مسلمانان بملک روم آمد و خسته شد و رومیان صفها بشکستند و کشتیها بگشادند و مسلمانان ندانستند که ایشان هزیمت خواهند شد عبداﷲبن سعد را گفتند ما نیز کشتیها بگشائیم و برویم از پس ایشان . محمدبن ابی بکرآنجا بود گفت ما را از پس ایشان نباید شدن عبداﷲ گفت خاموش باش که نه کار تو است تدبیر حرب کردن . محمدبن ابوبکر را اندوه آمد و گفت کار تو است که دی مرتد بودی و کار من نیست ! عبداﷲ او را بانگ برزد مردمان عبداﷲ را سرد گفتند و بحدیث عثمان شدند و گفتند این گناه عثمان است که چون تو کسی را بر مسلمانان مسلط کند و خون او حلال است ما را خود جهاد به مدینه باید کردن با عثمان . جهاد بدریا چکنیم . پس عبداﷲ بگذاشت تا رومیان بهزیمت برفتند و سپاه را به مصر آورد. درحبیب السیر در وقایع سال <span class=\"hlight\" dir=\"rtl\">٣١</span> از هجرت گوید: در این سال قسطنطین رومی بقصد تسخیر مصر و اسکندریه با پانصد کشتی مشحون بمردان جنگی در دریا نشست و معاویةبن ابی سفیان چهل کشتی به اتفاق عبداﷲبن سعدبن ابی سرح بدفع رومیان فرستاد و در موضع ذات الصور فریقین بهم رسیدندو بروی آب آتش قتال التهاب یافت مسلمانان بظفر و نصرت اختصاص یافتند... قسطنطین از معرکه ٔ ذات الصور در سفینه ٔ فرار نشسته بدارالملک خویش رفت ... - انتهی .<br /></font></div>'),
(130161, 'ذات الصور', '<span class=\"hlight\">ذات الصور.</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص ُ وَ ]</font></b> (اِخ ) (دز...) (قلعه ...) (معرکه ..) و در مثنوی مولوی در حکایت سه پادشاه زاده که به دستور پدر بسیاحت ممالک شدند و او آنان را از رفتن بقلعه ٔ ذات الصور منع فرمود با اینهمه آنها برخلاف وصیّت پدر بدان قلعه رفتند و عاشق صورتی که بر این قلعه نقش بود گردیدند فرماید <span class=\"hlight\">:</span> <br />هر کجا دلتان کشد عازم شوید<br />فی امان اﷲ دست افشان روید<br />غیر آن قلعه که نامش هشربا<br />تنگ آرد بر کله داران قبا<br />اﷲاﷲ زان دز ذات الصور<br />دور باشید و بترسید از خطر.<br />رجوع به مثنوی مولوی چ علاءالدوله ص <span class=\"hlight\" dir=\"rtl\">٦٣٨</span> و بعد آن شود.<br /></font></div>'),
(130162, 'ذات الصوی', '<span class=\"hlight\">ذات الصوی .</span> <font color=\"DarkGreen\"><b>[ تُص ْ ص ُ وا ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130163, 'ذات الضال', '<span class=\"hlight\">ذات الضال .</span> <font color=\"DarkGreen\"><b>[ تُض ْ ضا ]</font></b> (اِخ ) موضعی به نواحی مدینه ٔ رسول صلوات اﷲ علیه . (المرصع).<br /></font></div>'),
(130164, 'ذات الضریع', '<span class=\"hlight\">ذات الضریع.</span> <font color=\"DarkGreen\"><b>[ تُض ْ ض َ ]</font></b> (ع اِ مرکب ) التهاب ضریع. <br /></font></div>'),
(130165, 'ذات الطلوع', '<span class=\"hlight\">ذات الطلوع .</span> <font color=\"DarkGreen\"><b>[ تُطْ طُ]</font></b> (اِخ ) نام موضعی که رسول اکرم سریّه ای بدانجا گسیل داشت و همگی بدرجه ٔ شهادت فائز آمدند. (المرصع).<br /></font></div>'),
(130166, 'ذات الطواویس', '<span class=\"hlight\">ذات الطواویس .</span><font color=\"DarkGreen\"><b>[ تُطْ طَ ]</font></b> (اِخ ) محلی است نزدیک بخارا و آن را طواویس و ارقود نیز نامند. رجوع بتاریخ بخارای نرشخی چ مدرس رضوی ص <span class=\"hlight\" dir=\"rtl\">١٣</span> شود. طواویس قصبه ای نزه بود و بازاری داشت که هر سال یکروز دائر می شد. و دیواری داشت که اکنون ویران شده است و نیز مسجد جامعی که از میان رفته است ولی بازار آن بزرگتر شده است . (مقدسی <span class=\"hlight\" dir=\"rtl\">٢٨١</span>). وهر سال جمعی کثیر از مردم ماوراءالنهر هنگامی معین از سال در آن گرد می آمدند و از آن جامه های پنبه بشهرهای دیگر میبردند و آن قصبه را بستانهای بسیار بود وآب فراوان داشت . (اصطخری <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). این قصبه را نام دیگر «طواویسه » بود و نام دیگر «ارقود» و در آن مردمی بودند با نعمت و تجمل و از راه تجمل هر کسی در خانه ٔ خود یک یا دو طاوس داشت و چون تازیان به بخارا شدند و پیش از آن طاوس ندیده بودند و در آنجا بسیار دیدندآن دیه را «ذات الطواویس » نام کردند و نام اصلی آن برخاست و بعد از آن ذات را نیز بینداختند و طواویس گفتند و بازار آن هر سال در تیر ماه ده روز بود و رسم چنان بود که هر چه آخریان معیوب داشتند از برده و ستور همه بدان بازار می فروختند و باز رد کردن آن امکان نداشتی و نه خریدار و نه فروشنده هیچ شرط نپذیرفتی و هر سال بیش از ده هزار کس بدین بازار حاضر شدندی از بازرگان و اصحاب حوائج چنانکه از فرغانه و شاش و جایهای دیگر می آمدند و با سود بسیار بازمی گشتند و بدین سبب مردم دیه توانگر بوده اند، از راه سوداگری و نه ازراه کشاورزی و این دیه بر سر شاهراه سمرقند بود وتا شهر بخارا هفت فرسنگ بود. (تاریخ بخارا ص <span class=\"hlight\" dir=\"rtl\">١١</span>).<br /></font></div>'),
(130167, 'ذات الطیر', '<span class=\"hlight\">ذات الطیر.</span> <font color=\"DarkGreen\"><b>[ تُطْ طَ ]</font></b> (اِخ ) رجوع به ذات الدیر شود.<br /></font></div>'),
(130168, 'ذات الظبی', '<span class=\"hlight\">ذات الظبی .</span> <font color=\"DarkGreen\"><b>[ تُظْ ظَ ]</font></b> (اِخ ) یکی از بلاد بنی سلیم است .<br /></font></div>'),
(130169, 'ذات العجرم', '<span class=\"hlight\">ذات العجرم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُ رُ ]</font></b> (اِخ ) موضعی است به بطحاءنزدیک قوافر و حنو. (المرصّع). یا نزدیک ذوقار. رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span> و معرب جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٧٧</span> شود.<br /></font></div>'),
(130170, 'ذات العجم', '<span class=\"hlight\">ذات العجم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ]</font></b> (اِخ ) نام اسب حنظلةبن اوس سعدی . (منتهی الارب ).<br /></font></div>'),
(130171, 'ذات العرار', '<span class=\"hlight\">ذات العرار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (اِخ ) نام موضعی است در شعر و عَرار گیاهی است خوشبوی .<br /></font></div>'),
(130172, 'ذات العراس', '<span class=\"hlight\">ذات العراس .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ِ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130173, 'ذات العراقی', '<span class=\"hlight\">ذات العراقی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ِ قی ی ]</font></b> (ع اِ مرکب ) داهیة. آفت . بلا و سختی .<br /></font></div>'),
(130174, 'ذات العراقیب', '<span class=\"hlight\">ذات العراقیب .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ]</font></b> (اِخ ) صخره ای و بقولی رملی به بلاد عمروبن تمیم .<br /></font></div>'),
(130175, 'ذات العرض', '<span class=\"hlight\">ذات العرض .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (ع اِ مرکب ) داود ضریر انطاکی در تذکره ذیل کلمه ٔ شوصه و ذات جنب گوید: و یقال لما بین الکتفین منها ذات العرض و مقابلها ذات الصدر. رجوع بکلمه ٔ ذات الجنب قسمت منقول از تذکره شود. و رجوع به ذات الصدر، جزء منقول از کشاف اصطلاحات الفنون شود.<br /></font></div>'),
(130176, 'ذات العش', '<span class=\"hlight\">ذات العش .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُش ش ]</font></b> (اِخ ) گویند منزلی است بطریق مکه میان صنعا و مکه به أسفل طریق تهامة.<br /></font></div>'),
(130177, 'ذات العشر', '<span class=\"hlight\">ذات العشر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُ ش َ ]</font></b> (اِخ ) موضعی است به طریق حاجیان بصره نزدیک هجر. و موضعی نزدیک طنب و ماریة <BR><font color=\"Blue\">◄</font> ذات العشیرةَ. رجوع به ذات العشیرةَ شود.<br /></font></div>'),
(130178, 'ذات العضوم', '<span class=\"hlight\">ذات العضوم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ؟ ]</font></b> (اِخ ) نام موضعی است در شعر.<br /></font></div>'),
(130179, 'ذات العلندی', '<span class=\"hlight\">ذات العلندی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ل َ دا ]</font></b> (اِخ ) نام موضعی است . راعی گوید <span class=\"hlight\">:</span> <br />تحملن ّ حتی قلت لسن بوارحاً<br />بذات العلندی حیث نام المفاخر.<br /><font color=\"Red\">(معجم البلدان یاقوت ).</font><br /></font></div>'),
(130180, 'ذات العماد', '<span class=\"hlight\">ذات العماد.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ِ ]</font></b> (اِخ ) این کلمه در صفت ارم درقرآن کریم آمده است . ذات العماد یعنی صاحب ستونها یاصاحب بناهای بلند. (غیاث از منتخب ). و بعضی گفته اندذات العماد لقب دمشق است و صاحب المرصع گوید: ذات العماد دمشق است و نیز گفته اند، نام امتی از امم سالفه است که قبیله ٔ عاد نیز از آن امت است و ارم قبیله ای است از قوم عاد. و ارادوا بذات العماد ذات الطول و القوة و البطش . و نیز در معنی آن چیزهای دیگر گفته اند - انتهی . و رجوع به ارم ذات العماد شود. قوله <span class=\"hlight\">:</span> الم ترَکَیف َ فَعَل رَبﱡک بعاد اِرَم َ ذات ِالعماد. (قرآن <span class=\"hlight\" dir=\"rtl\">٦/٨٩</span> و <span class=\"hlight\" dir=\"rtl\">٧</span>)؛ ای البناء الرفیع. نقل انّهم کانوا ینحتون العمدَ من الجبال فیجعلون طول العمد مثل طول الجبل َ الذی یسلخون من اسفله الی اعلاه ثم یَنْقُلون تلک العمدَ فینصبونها ثم یبنون القصور فوقها فسمیّت ذات العماد و قیل اهل عمد لانّهم کانوا بدوییّن اهل خیام . قال الشیخ ابوعلی رحمه اﷲ اختلفوا فی ارم ذات العماد علی اقوال : احدها، انّه اسم قبیلة قال ابوعبیدة و هم عادان فالاولی هی ارم و هی التی قال اﷲ تعالی فیهم انّه هلک عاداً الاولی . و قیل هم جدّ عاد و هو عادبن عوض بن آدم بن سام بن نوح نسب عاد الیه و قیل ارم قبیلة من قوم عاد کان فیهم الملک . و ثانیها ان ّ ارم اسم بلد ثم ّ قیل هو دمشق و قیل هی المدینة الاسکندریة و قیل هی مدینة بناها عادبن شداد فلما اتمها و اراد ان یدخلها اهلکه اﷲ بصیحة نزلت من السماء. و ثالثها انّه لیس بقبیلة و لا بلد بل هو لقب لعاد و کان عاد یعرف به وروی عن الحسن انّه قراء بعاد ارم علی الاضافة و قال هو اسم ُ آخر لعاد و کان له اسمان - انتهی . رجوع به ارم ذات العماد شود.<br /></font></div>'),
(130181, 'ذات العنقر', '<span class=\"hlight\">ذات العنقر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُ ق ُ ]</font></b> (اِخ ) موضعی است بدیار بنی بکربن وائل .<br /></font></div>'),
(130182, 'ذات العنیق', '<span class=\"hlight\">ذات العنیق .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُ ن َ ]</font></b> (اِخ ) آبی است نزدیک حاجر بر طریق حاجیان کوفه به مکه بر یک میلی نُشناش . شاعر گوید <span class=\"hlight\">:</span> <br />الا تلکما ذات العنیق کأنّها<br />عجوز نفی عنها اقاربها الدهر.<br />واعرابی راست :<br />رایت و اصحابی بأظلم موهنا<br />سناالبرق یجلو مکفهرّاً یمانیا<br />قعدت له من بعد مانام صحبتی <br />تسح ّ علی ذات العنیق العزالیا.<br /><font color=\"Red\">(از معجم البلدان یاقوت ).</font><br /></font></div>'),
(130183, 'ذات العواسی', '<span class=\"hlight\">ذات العواسی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (اِخ ) کوهی است بنوجعفر را. (المرصع).<br /></font></div>'),
(130184, 'ذات العوایم', '<span class=\"hlight\">ذات العوایم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ی ِ ]</font></b> (ع اِ مرکب، ق مرکب ) ج ِ ذات العویم .<br /></font></div>'),
(130185, 'ذات العویم', '<span class=\"hlight\">ذات العویم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع ُ وَ ]</font></b> (ع اِ مرکب، ق مرکب ) سال گذشته و پیشین . لقیته ذات العویم ؛ ای لقیته بین الاعوام . (منتهی الارب ). و ابن الاثیر در المرصع گوید، عویم مصغر عام است . و لقیته ذات العویم، یعنی پس از سالیان دراز. و ذات بظرفیت منصوب شده است و کنایه از مدّت است . - انتهی . و «دهار»ذات العویم را میان سالگی، ترجمه کرده است و رایته ذات العویم ظاهراً معنی آن او را دیدم بفلان سال باشد.<br /></font></div>'),
(130186, 'ذات العیص', '<span class=\"hlight\">ذات العیص .</span> <font color=\"DarkGreen\"><b>[ تُل ْع ِ ]</font></b> (اِخ ) نام موضعی است . تغلبی گوید <span class=\"hlight\">:</span> <br />سألت عنهم و قد سدت اباعرهم <br />من ابین رحبة ذات العیص فالعدن .<br /><font color=\"Red\">(معجم البلدان ).</font><br /></font></div>'),
(130187, 'ذات العین', '<span class=\"hlight\">ذات العین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (ع اِ مرکب ) علت چشم . (آنندراج ).<br /></font></div>'),
(130188, 'ذات العین', '<span class=\"hlight\">ذات العین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (اِخ ) حمداﷲ مستوفی در نزهةالقلوب در ذیل عنوان و من واسط الی ثعلبیة گوید <span class=\"hlight\">:</span> از واسط تا شعشعة سی میل از او تا عیص سی و دو میل، از او تا ذات العین بیست و شش میل از او تا شابیة بیست و شش میل از او تااخادید سی میل ... (نزهةالقلوب چ بریل لیدن <span class=\"hlight\" dir=\"rtl\">١٣٣١</span>).<br /></font></div>'),
(130189, 'ذات العین', '<span class=\"hlight\">ذات العین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ع َ ]</font></b> (ع اِ مرکب ) سلفینون . صریمةالجدی . عنبیة. فلومانن .<br /></font></div>'),
(130190, 'ذات الغار', '<span class=\"hlight\">ذات الغار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) چاهی است با آب بسیار و خوش به سه فرسنگی سوارقیة.<br /></font></div>'),
(130191, 'ذات الغضا', '<span class=\"hlight\">ذات الغضا.</span> <font color=\"DarkGreen\"><b>[ تُل ْ غ َ ]</font></b> (اِخ ) موضعی است که نام آن در شعر عرب بسیار آمده است . و غضا نوعی از طرفا یعنی گز است . (المرصع).<br /></font></div>'),
(130192, 'ذات الغمر', '<span class=\"hlight\">ذات الغمر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ غ َ]</font></b> (اِخ ) نام موضعی است . قیس هذلی راست <span class=\"hlight\">:</span> <br />سقی اﷲ ذات الغمر و بلاً و دیمةً<br />و جادت علیها بارقات اللوامع.<br /><font color=\"Red\">(المرصع)</font><br /></font></div>'),
(130193, 'ذات الفضول', '<span class=\"hlight\">ذات الفضول .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ف ُ ]</font></b> (اِخ ) نام زرهی رسول اکرم صلوات اﷲ علیه را.<br /></font></div>'),
(130194, 'ذات الفلس', '<span class=\"hlight\">ذات الفلس .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ف ِ ]</font></b> (ع ص مرکب ) دشنامی است . جریر راست <span class=\"hlight\">:</span> <br />جزعت ابن ذات الفلس لما تداکأت <br />من الحرب انیاب علیک و کلکل .<br /></font></div>'),
(130195, 'ذات القتاد', '<span class=\"hlight\">ذات القتاد.</span> <font color=\"DarkGreen\"><b>[ تُل ْق ُ ]</font></b> (ع اِ مرکب ) نوعی از مار است . <BR><font color=\"Blue\">◄</font> (اِخ ) جایگاهی است به برسوی وادی به مدینة که میان دو کوه کوچک واقع است . (المرصع). <BR><font color=\"Blue\">◄</font> موضعی است بدانسوی فلج . (معجم البلدان در ذیل کلمه ٔ قتاد).<br /></font></div>'),
(130196, 'ذات القرطین', '<span class=\"hlight\">ذات القرطین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ق ُ طَ ]</font></b> (اِخ ) لقب ماریة، مادر حرث بن جبلة ابن الحرث و زوجه ٔ جبلةبن الحرث دو ملک از ملوک آل جفنه .<br /></font></div>'),
(130197, 'ذات القرنین', '<span class=\"hlight\">ذات القرنین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ق َ ن َ ]</font></b> (اِخ ) موضعی است قرب مدینةالرسول میان دو کوه خرد.<br /></font></div>'),
(130198, 'ذات القرون', '<span class=\"hlight\">ذات القرون .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ق ُ ]</font></b> (اِخ ) کنیت شام است . مرقش اکبر راست : و اهلی بالشام ذات القرون . (از المرصع).<br /></font></div>'),
(130199, 'ذات القصور', '<span class=\"hlight\">ذات القصور.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ق ُ ]</font></b> (اِخ ) نام قدیم شهر معرة است .<br /></font></div>'),
(130200, 'ذات القن', '<span class=\"hlight\">ذات القن .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ق ِن ن ]</font></b> (اِخ ) اکمه ای باشد بر کوهی از کوههای اجاء. (المرصع).<br /></font></div>'),
(130201, 'ذات اللظا', '<span class=\"hlight\">ذات اللظا.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ل َ ]</font></b> (اِخ ) موضعی است از حرةالنار. و حرةالنار در میان وادی القری و تیما از دیار غطفان است . (المرصع).<br /></font></div>'),
(130202, 'ذات المحمول', '<span class=\"hlight\">ذات المحمول .</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (ع اِ مرکب ) کبری . کبرای قیاس . مقابل ذات الموضوع که صغرای قیاس است .<br /></font></div>'),
(130203, 'ذات المداق', '<span class=\"hlight\">ذات المداق .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ؟ ]</font></b> (اِخ ) دشتی است ببلاد بنی اسد.<br /></font></div>'),
(130204, 'ذات المر', '<span class=\"hlight\">ذات المر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (ع ص مرکب، اِ مرکب ) سورتی از قرآن که به الف لام میم راء آغاز می شود.<br /></font></div>'),
(130205, 'ذات المزاهیر', '<span class=\"hlight\">ذات المزاهیر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (اِخ ) نام پشته هائی سرخ است به بلاد بنی بکر.<br /></font></div>'),
(130206, 'ذات المسطرتین', '<span class=\"hlight\">ذات المسطرتین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ طَ رَ ت َ ]</font></b> (ع اِ مرکب ) آلتی قدیم رصد را. ذات الشعاع .<br /></font></div>'),
(130207, 'ذات المطامیر', '<span class=\"hlight\">ذات المطامیر.</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (اِخ ) شهری است به ثغور شامیة.و در کتاب الفتوح در ایام مهدی و مأمون و معتصم نام او آمده است و نیز در فتوح ذکر آن بسیار کرده اند وآن را المطامیر نیز نامند. (معجم البلدان یاقوت ).<br /></font></div>'),
(130208, 'ذات الملح', '<span class=\"hlight\">ذات الملح .</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (اِخ ) نام موضعی است .<br /></font></div>'),
(130209, 'ذات المنار', '<span class=\"hlight\">ذات المنار.</span> <font color=\"DarkGreen\"><b>[ تُل ْ م ِ ]</font></b> (اِخ ) موضعی باشد به اول زمین شام از سوی حجاز و ابوعبیدة آنگاه که به شام میشد بدانجا نزول کرد.<br /></font></div>'),
(130210, 'ذات المواشی', '<span class=\"hlight\">ذات المواشی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (اِخ ) نام زرهی از رسول اﷲ صلوات اﷲ علیه .<br /></font></div>'),
(130211, 'ذات الموضوع', '<span class=\"hlight\">ذات الموضوع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ م َ ]</font></b> (ع اِ مرکب ) صغری . صغرای قیاس . مقابل ذات المحمول، کبری .<br /></font></div>'),
(130212, 'ذات النابت', '<span class=\"hlight\">ذات النابت .</span> <font color=\"DarkGreen\"><b>[ تُن ْ نا ب ِ ]</font></b> (اِخ )نام موضعی به عرفات .<br /></font></div>'),
(130213, 'ذات النحیین', '<span class=\"hlight\">ذات النحیین .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ِ ی َ ی ]</font></b> (اِخ ) لقب زنی است از تیم اﷲبن ثعلبة. وی در جاهلیت روغن فروختی . روزی خوات بن جبیر انصاری بروغن خریدن نزد وی شد و او را تنها یافت و در وی طمع کرد پس دهانه ٔ خیکی از روغن بگشود تا بیازماید و بدست زن داد و سپس در خیک دیگر بگشاد وهمچنان بدست زن سپرد و چون هر دو دست زن بند و مشغول شد خوات بقضاء حاجت خویش پرداخت و بگریخت و گفت :<br />و ذات عیال واثقین بعقلها<br />خلجت لها جاراستها خلجات ِ<br />شغلت یدیها اذا ردت خلاطها<br />بنحیین من سمن ذوی عجرات <br />فاخرجته ریان ینطف راسه ُ<br />من الرامک المذموم بالمقرات (او بالثغرات )<br />فکان لها الویلات من ترک سمنها<br />و رجعتها صفرا بغیر تبات ِ<br />فشدّت علی النحیین کفّا شحیحة<br />علی سمنها و الفتک من فعلات .<br />و سپس خوّات مسلمانی پذیرفت و درک غزوه ٔ بدر کرد و رسول اکرم صلوات اﷲ علیه بمزاح به او گفت یا خوات کیف شراوک و در بعض روایات شراؤک و تبسم فرمود و او گفت یا رسول اﷲ قد رزق اﷲ خیرا و اعوذ باﷲ من الحور بعد الکور و در روایت حمزه آمده است که نبی اکرم بدو فرمود: ما فعل بعیرک اشرد علیک و او گفت اما منذ اسلمت او منذ قیده الاسلام فلا. و انصار گویند که رسول صلوات اﷲ علیه دعا فرمود تاشدت و سورت شهوت وی فرونشست . مردی بنی تیم اﷲ را هجا گوید:<br />اناس ٌ ربةالنحیین منهم <br />فعدوها اذا عدّ الصمیم .<br />و این حکایت را بام ّ الوردعجلانیة نیز نسبت کرده اند و او پس از انجام عمل فریاد کرد یا ثار ذات النحیین . و نحی به معنی خیک روغن باشد و اشغل من ذات النحیین مثل است .<br /></font></div>'),
(130214, 'ذات النخاع', '<span class=\"hlight\">ذات النخاع .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ُ ]</font></b> (ع اِ مرکب ) بیماری التهاب نخاع .<br /></font></div>'),
(130215, 'ذات النسا', '<span class=\"hlight\">ذات النسا.</span> <font color=\"DarkGreen\"><b>[ تُن ْن ِ ]</font></b> (اِخ ) موضعی بدو منزلی مدینة و نام درختی بدانجا. رجوع به شرح غزوه ٔ انواط در ترجمه ٔ بلعمی شود.<br /></font></div>'),
(130216, 'ذات النسوع', '<span class=\"hlight\">ذات النسوع .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ُ ]</font></b>(اِخ ) نام اسبی است معروف، بسطام بن قیس شیبانی را. (المرصع). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و <span class=\"hlight\" dir=\"rtl\">٦٧</span> شود.<br /></font></div>'),
(130217, 'ذات النصب', '<span class=\"hlight\">ذات النصب .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ُ ]</font></b> (اِخ ) موضعی است به چهار میلی مدینةالرسول . و رسول اکرم بدانجا نماز قصر گزارده است .<br /></font></div>'),
(130218, 'ذات النطاق', '<span class=\"hlight\">ذات النطاق .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ِ ]</font></b> (ع اِ مرکب ) نام نوعی موش خالدار است . <BR><font color=\"Blue\">◄</font> (اِخ ) پشته ای است بنی کلاب را که خالهای سیاه وسپید دارد و یا بر کمر آن سپیدی باشد چون کمربند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130219, 'ذات النطاقین', '<span class=\"hlight\">ذات النطاقین .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ِ ق َ ]</font></b> (اِخ ) لقب اسماء بنت ابی بکر زوجه ٔ زبیربن عوام و مادر عبداﷲبن زبیر و عروةبن الزبیر. تاریخ بیهقی پس از شرح قتل حسنک وزیر که در آن داد سخن داده است گوید: چون عبداﷲ زبیر رضی اﷲ عنهما بخلافت بنشست به مکه، و حجاز و عراق او را صافی شد و مُصعب برادرش بخلیفتی وی بصره و کوفه و سواد بگرفت، عبدالملک مروان با لشکر بسیار از شام قصد مصعب کرد که مردم و آلت و عدت او داشت، و میان ایشان جنگی بزرگ افتاد و مصعب کشته شد، عبدالملک سوی شام بازگشت و حجاج یوسف را با لشکری انبوه و ساخته به مکه فرستاد، چنانکه آن اقاصیص بشرح در تواریخ مذکور است، حجاج با لشکر بیامد و با عبداﷲ جنگ پیوست، و مکه حصار شد، و عبداﷲ مسجد مکه را حصار گرفت، و جنگ سخت شد، و منجنیق سوی خانه روان شد، و سنگ می انداختند تا یک رکن را فرودآوردند، عبداﷲ چون کارش سخت تنگ شد از جنگ به ایستاد، و حجاج پیغام فرستاد سوی او که از تو تا گرفتار شدن یک دو روز مانده است، و دانم که بر امانی که من دهم بیرون نیایی، بر حکم عبدالملک بیرون آی تا ترا به شام فرستم بی بندعزیزاً و مکرماً آنگاه او داند که چه باید کرد، تا در حرم بیش ویرانی نیفتد و خونها ریخته نشود. عبداﷲ گفت تا در این بیندیشم . آن شب با قوم خویش که مانده بودند رای زد، بیشتر اشارت آن کردند که بیرون باید رفت تا فتنه بنشیند و المی بتو نرسد. وی نزدیک مادر آمد، اسماء - و دختر بوبکر صدیق بود رضی اﷲ عنه - و همه حالها با وی بگفت، اسماء زمانی اندیشید پس گفت : ای فرزند این خروج که تو بر بنی امیه کردی دین را بود یا دنیا را؟ گفت به خدای که از بهر دین را بود، و دلیل آنکه نگرفتم یک درم از دنیا، و این ترا معلوم است .گفت پس صبر کن بر مرگ و کشتن و مثله کردن چنانکه برادرت مصعب کرد، که پدرت زبیر عوام بوده است و جدت ازسوی من بوبکر صدیق رضی اﷲ عنه و نگاه کن که حسین علی رضی اﷲ عنهما چه کرد، او کریم بود و بر حکم پسر زیاد عبیداﷲ تن درنداد. گفت ای مادر من هم برینم که تو می گوئی، اما رأی و دل تو خواستم که بدانم در این کار، اکنون بدانستم و مرگ با شهادت پیش من خوش گشت، اما می اندیشم که چون کشته شوم مُثله کنند. مادرش گفت چون گوسپند را بکشند از مثله کردن و پوست بازکردن دردش نیاید. عبداﷲ همه شب نماز کرد و قرآن خواند، وقت سحر غسل کرد و نماز بامداد بجماعت بگزارد و سوره ٔ نون و القلم و سوره ٔ هل اتی علی الانسان در دو رکعت بخواند و زره بپوشید و سلاح ببست - و در عرب هیچ کس جنگ پیاده چون او نکرده است - و در وقت مادر را در کنار گرفت و بدرود کرد، و مادرش زره بر وی راست می کرد و بغلگاه می دوخت و می گفت «دندان افشار با این فاسقان » چنانکه گفتی او را بپالوده خوردن می فرستد، و البته جزعی نکرد چنانکه زنان کنند و عبداﷲ بیرون آمد لشکر خویش را بیافت پراکنده و برگشته و وی را فروگذاشته مگر قومی که از اهل و خویش اوبودند که با وی ثبات خواستند کرد در جوشن و زره و مغفر و سلاح غرق بودند، آواز داد که رویها بمن نمائید، همگان رویها بوی نمودند عبداﷲ این بیت بگفت، شعر:<br />اِنی اذا اعرف یومی اصبر<br />اذ بعضهم یعرف ثم ینکر.<br />چون بجنگ جای رسیدند بایستادند. روز سه شنبه بود هفدهم جمادی الاولی سنه ٔ ثلث و سبعین من الهجرة - و حجاج یوسف از آن روی درآمد با لشکر بسیار، و ایشان را مرتب کرد اهل حمص را برابر در کعبه بداشت و مردم دمشق را برابر در بنوشیبه و مردم اُردن را برابر در صفا و مروه و مردم فلسطین را برابر در بنوجمح و مردم قِنسرین را برابر در بنوسهم، و حجاج و طارق بن عمر و با معظم لشکر بر مروه بایستاد و علم بزرگ آنجا بداشتند. عبداﷲ زبیرچون دید لشکری بی اندازه از هر جانبی روی بدو نهادند، روی بقوم خویش کرد و گفت یا آل الزبیر لوطبتم لی نفسا عن انفسکم کنا اهل بیت من العرب اصطلمنا (<span class=\"hlight\" dir=\"rtl\">١</span>) عن آخرنا و ما صحبنا عاراً (<span class=\"hlight\" dir=\"rtl\">١</span>) اما بعد یا آل الزبیر فلایرعُکم وقعُ السیوف فانی لم احضر موطنا قط الا (<span class=\"hlight\" dir=\"rtl\">٢</span>) ارتثثت فیه بین القتلی (<span class=\"hlight\" dir=\"rtl\">٢</span>) و ما اجد (<span class=\"hlight\" dir=\"rtl\">٣</span>) من دواء جراحها (<span class=\"hlight\" dir=\"rtl\">٣</span>) اشدُ مما اجد من الم وقعها صونوا سیوفکم کما تصونون وجوهکم، لااعلم امرءَ منکم کسر سیفه و استبقی نفسه، فان الرجل اذا ذهب سلاحه فهو کالمراءة اعزل . غضوا ابصارکم و لیشغل کل امری قرنه و لایلهینکم السؤال عنی ولایقولن احد این عبداﷲبن الزبیر الا من کان سائلا عنی فانی فی الرعیل الاول، ثم قال، شعر:<br />ابی لابن سلمی انه غیر خالد<br />مُلاقی المنایا ای صرف تیمما <br />فلست بمبتاع الحیوة بسبة<br />و لامرتق من خشیةالموت سلما.<br />پس گفت بسم اﷲ، هان ای آزادمردان حمله برید، و درآمد چون شیری دمان بر هر جانب، و هیچ جانبی نبود که وی بیرون آمد با کم از ده تن که نه از پیش وی دررمیدند چنانکه روبهان از پیش شیران گریزند و جان را میزدند، و جنگ سخت شد، و دشمنان بسیار بودند عبداﷲ نیرو کرد تا جمله ٔ مردم برابر درها را پیش حجاج افکند، و نزدیک بودکه هزیمت شدندی حجاج فرمود تا علم پیشتر بردند، و مردم آسوده و مبارزان نامدار از قلب بیرون شدند و با یکدیگر درآویختند در این درآویختن عبداﷲ زبیر را سنگی سخت بر روی آمد و خون بر روی وی فرودوید. آواز دادو گفت :<br />فلسنا علی الاعقاب تدمی کلومُنا<br />ولکن علی اقدامنا تقطرُالدَما <br />وسنگی دیگر آمد قویتر بر سینه اش که دستهایش از آن بلرزید، یکی از موالی عبداﷲ چون دید بانگ کرد که «امیرالمؤمنین را بکشتند» و دشمنان وی را نمی شناختند که روی پوشیده داشت، چون از مولی بشنیدند و بجای آوردندکه او عبداﷲ است بسیار مردم بدو شتافت و بکشتندش، رضی اﷲ عنه، و سرش برداشتند و پیش حجاج بردند، او سجده کرد، و بانگ برآمد که عبداﷲ زبیر را بکشتند، زبیریان صبر کردند تا همه کشته شدند، و فتنه بیارامید و حجاج در مکه آمد و بفرمود تا آن رکن را که بسنگ منجنیق ویران کرده بودند نیکو کنند و عمارتهای دیگر کنند، و سر عبداﷲ زبیر رضی اﷲ عنهما را بنزدیک عبدالملک مروان فرستاد و فرمود تا جثه ٔ او را بر دار کردند. خبر کشتن بمادرش آوردند هیچ جزع نکرد و گفت انا ﷲ و انا الیه راجعون اگر پسرم نه چنین کردی نه پسر زبیر و نبسه ٔ بوبکر صدیق رضی اﷲ عنهما بودی . و مدتی برآمد، حجاج پرسید که این عجوزه چه میکند؟ گفتار و صبوری وی بازنمودند، گفت «سبحان اﷲ العظیم ! اگر عایشه ام المؤمنین و این خواهر دو مرد بودندی هرگز این خلافت به بنی امیه نرسیدی، این است جگر و صبر، حیلت باید کرد تا مگر وی را بر پسرش بتوانید گذرانید تا خود چه گوید»، پس گروهی زنان را بر این کار بگماشتند و ایشان درایستادند و حیلت ساختند تا اسماء را بر آن جانب بردند، چون دار بدید بجای آورد که پسرش <font color=\"DarkGreen\"><b>[ است ]</font></b>، روی بزنی کرد از شریف ترین زنان و گفت «گاه آن نیامد که این سوار را از این اسب فرودآورند؟» و بر این نیفزود و برفت و این خبر بحجاج بردند بشگفت بماند و فرمود تا عبداﷲ را فروگرفتند و دفن کردند. و این قصه هرچند دراز است در او فایده هاست، و دیگر دو حال را بیاوردم که تا مقرر گردد که حسنک را در جهان یاران بودند بزرگتر از وی، اگر به وی چیزی رسیدکه بدیشان رسیده بود پس شگفت داشته نیاید، و دیگر اگر مادرش جزع نکرد و چنان سخن بگفت طاعنی نگوید که این نتواند بود، که میان مردان و زنان تفاوت بسیار است و ربّک یخلق ما یشاء و یختار. (تاریخ بیهقی صص <span class=\"hlight\" dir=\"rtl\">١٨٩</span>-<span class=\"hlight\" dir=\"rtl\">١٩٣</span>).<br />ابن حجر در الاصابة گوید: اسماء، مادر عبداﷲبن الزبیربن العوام التیمیة. دختر ابی بکر الصدیق . مادر او قتلة یا قتیلة بنت عبدالعزی قرشیه است از بنی عامربن لوی . او قدیماً به مکه اسلام آورد. و ابن اسحاق گوید پس از هفده تن . و زبیر العوام او را بزنی گرفت و آنگاه که بعبداﷲ آبستن بود هجرت کرد و بقباء بزائید و تا آنگاه که پسرش را به خلافت برداشتند بزیست و تا گاه قتل پسر خویش ببود و کمی پس از قتل فرزند درگذشت . و او لقب ذات النطاقین داشت .<br />ابوعمر گوید این لقب رسول خدا صلوات اﷲ علیه به وی داد چه او درآن وقت که پیامبر صلی اﷲ علیه و آله و سلم عزیمت هجرت فرمود سفره ای تهیه کرد و چیزی بایست تا سفره در وی بندد وی خمار خویش بدو نیم کرد و به نیمی سفره را استوار کرد و نیمه دیگر را میان بند ساخت . و گوید ابن اسحاق و بعض دیگر این گفتند... و ابن سعد از ابواسامه و او از هشام عروة و او از پدر خویش و فاطمة بنت المنذر از اسماء ما را خبر دادند که گفت سفره ای برای رسول علیه السلام آنگاه که قصد هجرت به مدینه فرمود در خانه ٔ ابوبکر مهیا ساختم و چیزی برای بستن سفره و آویختن مشک نیافتم به ابی بکر گفتم چیزی جز میان بند خویش نمی یابم گفت بدو نیم کن و بیکی مشک آویز و با دیگری سفره را استوار ساز. و سند او صحیح است . و هم بدین سند از عروه و او از اسماء روایت کند که بدان هنگام که زبیر مرا بزنی کرد در روی زمین جز اسبی هیچ نداشت نه مالی و نه مملوکی و نه چیزی دیگر و من اسب او را علف میدادم و کارهای دیگر نیز بر عهده ٔ من بود و استخوان خرما نیز من از ارض زبیر می آوردم و برای شتر آبکش می کوفتم تا آنگاه که ابی بکر ما را خادمی فرستادو از آن پس خدمت اسب به او محول داشتیم . زبیربن بکار گوید: پیغامبر صلوات اﷲ علیه بدو فرمود ترا به بهشت بجای این میان بند دو میان بند دهم و از اینرو به او ذات النطاقین یعنی صاحب دو کمر گفتند. و او را از رسول اکرم صلوات اﷲ علیه احادیث چند است که در صحیحین و در سنن آمده است و از وی دو پسر او عبداﷲبن عروة و نبایر او عبادبن عبداﷲ و عبداﷲبن عروة و فاطمه ٔ بنت المنذربن الزبیر و عبادبن حمزةبن عبداﷲبن زبیر و غلام وی عبداﷲبن کیسان و ابن عباس و صفیه ٔ بنت شیبة و ابن ابی ملیکة و وهب ابن کیسان و غیر آنان روایت کنند و ابن السکن از طریق ابی الحیاة یحیی بن یعلی التیمی و اواز پدر خویش روایت کند که گفت : پس از قتل ابن الزبیربه مکه شدم و جسد ابن الزبیر هنوز بر دار بود و نزدحجاج رفتم و اسماء مادر زبیر پیرزالی بلندبالا و نابینا به مجلس حجاج درآمد و گفت آیا گاه آن نرسید که این سوار را پیاده سازند؟ حجاج گفت منافق را گوئی گفت سوگند با خدای که او منافق نبود بلکه روزها را بروزه و شب ها را بطاعت بسر میبرد. حجاج گفت بازگرد تو پیر و خرف شده ای گفت نه قسم بخدا من خرف نشده ام و از رسول خدا شنیدم که گفت از ثقیف کذابی و مردمخواره ای بیرون آیند اما کذاب را بدیدم و لکن آن مردمخواره تو باشی ... و هشام بن عروة از پدر خویش روایت کند که اسماء به صدسالگی رسید در حالی که نه یک دندان وی بیفتاد و نه در عقل وی خللی راه یافت . و ابونعیم اصفهانی گوید: اسماء بیست و هفت سال قبل از هجرت بزاد و تا اوائل سال بیست و چهار هجرت بزیست . و نیز گفته اند که وی بیست روز پس از قتل فرزند خویش درگذشت و ابن عبدالبر در استیعاب گوید وفات او به مکه بجمادی الاولی سال هفتاد و سه کمی پس از قتل پسرش عبداﷲ زبیر بود - انتهی . و ابن الأثیر در المرصع گوید: عبداﷲ زبیر را بنکوهش ابن ذات النطاقین خواندند و او چون بشنید گفت :<br />وعیرها الواشون انی احبها<br />و تلک شکاة ظاهر عنک عارها.<br />رجوع به حبیب السیر جزء <span class=\"hlight\" dir=\"rtl\">٢</span> از ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> س <span class=\"hlight\" dir=\"rtl\">٣</span> به بعد، و فهرست عقدالفرید و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠١</span> و <span class=\"hlight\" dir=\"rtl\">٣١٢</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠٤</span> و اسماء بنت ابی بکر در همین لغت نامه شود.<br /></font></div>'),
(130220, 'ذات النعال', '<span class=\"hlight\">ذات النعال .</span> <font color=\"DarkGreen\"><b>[ تُن ْ ن ِ ]</font></b> (اِخ ) نام اسب زبیر.<br /></font></div>'),
(130221, 'ذات الودع', '<span class=\"hlight\">ذات الودع .</span> <font color=\"DarkGreen\"><b>[ تُل ْ وَ دَ]</font></b> (اِخ ) سفینه ٔ نوح . کشتی نوح . <BR><font color=\"Blue\">◄</font> اوثان . بتها. یا بتی بعینه . <BR><font color=\"Blue\">◄</font> کعبة. خانه ٔ کعبه، از اینرو که بر پرده های وی ودَعه یعنی مورچه ها (مهره های بحری ) می آویختند.<br /></font></div>'),
(130222, 'ذات الوشاح', '<span class=\"hlight\">ذات الوشاح .</span> <font color=\"DarkGreen\"><b>[ تُل ْ وِ ]</font></b> (اِخ ) نام زرهی رسول اکرم صلوات اﷲ علیه را. (المرصع).<br /></font></div>'),
(130223, 'ذات الکبد', '<span class=\"hlight\">ذات الکبد.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ک َ ب ِ ]</font></b> (ع اِ مرکب ) آماس جگر. ورم کبد. نزد پزشکان ورمی است که در کبد عارض شود از مواد گرم یا سرد که به کبد ریزد و متورم سازد. (کشاف اصطلاحات الفنون ).<br />صاحب ذخیره ٔ خوارزمشاهی گوید: آماس جگر را ذات الکبد گویند. و نیز در موضعی دیگر از همان کتاب آرد: و بسیار باشد که اندر جگر آماسی گرم افتد و معالیق او کشیده میشود و درد آن بحجاب بازمیدهد و نفس تنگ می شود و بیمار و طبیب هر دو پندارند که ذات الجنب است از بهر آنکه همچنانکه اندر ذات الجنب، تب و سرفه و تنگی نفس باشد و آن ذات الجنب نباشد بلکه ذات الکبد است . (نقل به اختصاراز ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(130224, 'ذات الکرسی', '<span class=\"hlight\">ذات الکرسی .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ک ُ ]</font></b> (اِخ ) خداوند کرسی . صورتی از صور شمالی فلک مجاور قطب شمال که همیشه در طرف مقابل دب اکبر است بنسبت ستاره ٔ قطبی . و آن به صورت زنی بکرسی نشسته و هر دو پای فروهشته توهم شده است . سر و تنش بر کهکشان کشیده و آن را خداوند کرسی و خداوند عرش وخداوند منبر نیز نامند و مشتمل بر <span class=\"hlight\" dir=\"rtl\">٥٥</span> ستاره است از جمله صدر و کف الخضیب . و صاحب جهان دانش گوید: ذات الکرسی، خداوند کرسی . نام صورتی از صور فلکیه از ناحیه شمالی و آن را بر صورت زنی توهم کرده اند بر کرسی نشسته و پایها فروهشته و آن سیزده کوکب است و از کواکب او کوکبی روشن است از قدر ثالث و او را کف الخضیب خوانند - انتهی . و نامهای دیگر آن عرش و منبر و مراءة ذات الکرسی است . رجوع به ثوابت در همین لغت نامه شود.<br /></font></div>'),
(130225, 'ذات الکرش', '<span class=\"hlight\">ذات الکرش .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ک َ ]</font></b> (اِخ ) از زبیربن عوام آرند، که بروز بدر، عبیدةبن سعیدبن عاصی را دیدم بر اسبی و زرهی تمام در برکه تنها دو چشم وی پیدا بود و میگفت : اَنا ابوذات الکرش . و در دست وی نیزه ای کوتاه بود و پس از قتل وی نیزه در تسهیم غنائم، رسول اکرم صلوات اﷲ علیه و سلم را شد و در دیگر جنگها آن را پیشاپیش رسول میبردند.<br /></font></div>'),
(130226, 'ذات الکهف', '<span class=\"hlight\">ذات الکهف .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ک َ ]</font></b> (اِخ ) موضعی است در شعر عوف بن الأحوص <span class=\"hlight\">:</span> <br />یسوق صریم شأها من جلاجل <br />الی ّ و دونی ذات کهف و قورها.<br />و در شعربشربن ابی حازم :<br />یسومون الصلاح بذات کهف <br />و ما فیها لهم سلع وقار.<br /><font color=\"Red\">(از معجم البلدان یاقوت ).</font><br /></font></div>'),
(130227, 'ذات الکوم', '<span class=\"hlight\">ذات الکوم .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ]</font></b> (اِخ ) نام قریه ای به جیزه .<br /></font></div>'),
(130228, 'ذات الید', '<span class=\"hlight\">ذات الید.</span> <font color=\"DarkGreen\"><b>[ تُل ْ ی َ ]</font></b> (ع اِ مرکب ) ملک ید. مال . مملوک . ثروت . حریشه . دارائی <span class=\"hlight\">:</span> از ذات الید خویش آنچه مکنت داشت هریک را مراعات کرد تا همگان راضی شدند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). شکا یوماً الی ابی هارون خلیفة محمدبن یزداد، الوحدة و الغربة و قلة ذات الید. (معجم البلدان چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span> س <span class=\"hlight\" dir=\"rtl\">١٢</span>). <BR><font color=\"Blue\">◄</font> قدرت . توان . توانائی .<br /></font></div>'),
(130229, 'ذات الیمین', '<span class=\"hlight\">ذات الیمین .</span> <font color=\"DarkGreen\"><b>[ تُل ْ ی َ ]</font></b> (ع اِ مرکب ) سوی دست راست . (مهذب الاسماء). جانب راست . (دهار). دست راست . براست <span class=\"hlight\">:</span> <br />هم بتقلیب تو تا ذات الیمین <br />تا سوی ذات الشمال ای رب ّ دین .<br /> <font color=\"Red\">مولوی </font><br /><BR><font color=\"Blue\">◄</font> و صاحب غیاث گوید و کسانی که نامه ٔ اعمالشان بر دست راست آید و مراد از این مؤمنانند.<br /></font></div>'),
(130230, 'ذات انمار', '<span class=\"hlight\">ذات انمار.</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) در مجمل التواریخ والقصص چ بهار ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> آمده است : الأیهم بن جبلة، بیست و هفت سال و دو ماه پادشاه بود و خداوند تدمر و قصر برکة و ذات انمار بود و غزا کرد به بنی الفین بر خبر و غایله <font color=\"DarkGreen\"><b>[ آمد و نابغه ]</font></b> اندر آن گوید:<br />ضلت حلومهم عنهم و عزهم <br />سن ّالمعیدی فی رعی و تعزیب .<br /></font></div>'),
(130231, 'ذات انیار', '<span class=\"hlight\">ذات انیار.</span> <font color=\"DarkGreen\"><b>[ ت ُ اَن ْ ]</font></b> (ع ص مرکب ) ناقة ذات انیار، ناقة ذات نیرین . رجوع به ذات نیرین شود.<br /></font></div>'),
(130232, 'ذات اوشال', '<span class=\"hlight\">ذات اوشال .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) اوشال جمع وشل به معنی آب اندک است . و ذات اوشال نام موضعی است بر طریق شام . نصیب در مدیح سلیمان بن عبدالملک گوید <span class=\"hlight\">:</span> <br />اقول لرکب صادرین لقیتهم <br />قفا ذات اوشال و مولاک قارب <br />قفوا و اخبرونی عن سلیمان اننی <br />لمعروفه من اهل ودان طالب <br />فعاجوا فأثنوا بالذی انت اهله <br />ولو سکتوا اثنت علیک الحقائب .<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130233, 'ذات اوعال', '<span class=\"hlight\">ذات اوعال .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) نام هضبه ای است به نجد و بدانجا چاهی . امرءالقیس گوید <span class=\"hlight\">:</span> <br />و تحسب سلمی لاتزال کعهدنا<br />بوادی الخزامی او علی ذات اوعال .<br />و گویندکوهی است میان دو عَلَم به نجد. (المرصع).<br /></font></div>'),
(130234, 'ذات اوهام', '<span class=\"hlight\">ذات اوهام .</span> <font color=\"DarkGreen\"><b>[ ت ُ اَ ]</font></b> (اِخ ) نام موضعی نزدیک سرندیب که گرشاسب با مهراج آنگاه که بتسخیر سرندیب رفتند یکهفته بدانجا مقام کردند <span class=\"hlight\">:</span> <br />بیک هفته آنجاش آرام بود<br />کجا نام او ذات اوهام بود.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(130235, 'ذات اکلیل', '<span class=\"hlight\">ذات اکلیل .</span> <font color=\"DarkGreen\"><b>[ ت ُ اِ ]</font></b> (ع ص مرکب ) چتری . تاجدار. ذواکلیل (گیاه ) .<br /></font></div>'),
(130236, 'ذات ایله', '<span class=\"hlight\">ذات ایله .</span> <font color=\"DarkGreen\"><b>[ ت ُ ل َ ]</font></b> (ع اِ مرکب ) ماری خرافی که به آدمی حمله آرد.<br /></font></div>'),
(130237, 'ذات بطن', '<span class=\"hlight\">ذات بطن .</span> <font color=\"DarkGreen\"><b>[ ت ُ ب َ ]</font></b> (ع اِ مرکب ) آنچه در شکم باشد از فضول یا تخم یا جنین <span class=\"hlight\">:</span> القت الدجاجة ذات بطنها؛ ماکیان فضله افکند یا تخم کرد.<br /></font></div>'),
(130238, 'ذات بیض', '<span class=\"hlight\">ذات بیض .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) (روضة...) یاقوت در معجم این نام را بی هیچ شرحی آورده و تنها در عقیب آن گوید: قال منذربن درهم <span class=\"hlight\">:</span> <br />و روض من ریاض ذوات بیض <br />به دهنی مخالطها کثیب .<br /></font></div>'),
(130239, 'ذات جانبین', '<span class=\"hlight\">ذات جانبین .</span> <font color=\"DarkGreen\"><b>[ ت ُ ن ِ ب َ ]</font></b> (اِخ ) رجوع به کلمه ٔ اربعا در همین لغت نامه شود.<br /></font></div>'),
(130240, 'ذات حاج', '<span class=\"hlight\">ذات حاج .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) موضعی است میان شام و مدینه و حاج جمع حاجت است .<br /></font></div>'),
(130241, 'ذات حافر', '<span class=\"hlight\">ذات حافر.</span> <font color=\"DarkGreen\"><b>[ ت ُ ف ِ ]</font></b> (ع ص مرکب ) رجوع به ذوات الحافر شود.<br /></font></div>'),
(130242, 'ذات حبیس', '<span class=\"hlight\">ذات حبیس .</span> <font color=\"DarkGreen\"><b>[ ت ُ ح َ ]</font></b> (اِخ ) موضعی است به مکّه و بدانجاست کوه سیاه موسوم به اظلم . (المرصع).<br /></font></div>'),
(130243, 'ذات حج', '<span class=\"hlight\">ذات حج .</span> <font color=\"DarkGreen\"><b>[ ت ُ ح َج ج ]</font></b> (اِخ ) آبی است در طریق مکّه به شام و گویند از تبوک حفار است .<br /></font></div>'),
(130244, 'ذات حص', '<span class=\"hlight\">ذات حص .</span> <font color=\"DarkGreen\"><b>[ ت ُ ح َص ص ]</font></b> (ع ص مرکب ) رحم ذات حص ّ. رحم محصوصة. رَحِم حاصةَ، رحم مقطوعه . خویشی گسسته .<br /></font></div>'),
(130245, 'ذات خلفین', '<span class=\"hlight\">ذات خلفین .</span> <font color=\"DarkGreen\"><b>[ ت ُ خ ِ ف َ ]</font></b>(ع ص مرکب، اِ مرکب ) تَبَر دوسر. ج، ذوات الخلفین .<br /></font></div>'),
(130246, 'ذات خیم', '<span class=\"hlight\">ذات خیم .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) موضعی است میان مدینةو دیار غطفان . (معجم البلدان یاقوت ). جائی است به دیار غطفان . (المرصع). جایگاهی به مدینة. (المرصع).<br /></font></div>'),
(130247, 'ذات خیم', '<span class=\"hlight\">ذات خیم .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) از بلاد مهره است به یَمَن دور. (المرصع). رجوع به ذات الخیم شود.<br /></font></div>'),
(130248, 'ذات ذرو', '<span class=\"hlight\">ذات ذرو.</span> <font color=\"DarkGreen\"><b>[ ت ُ ذَ ]</font></b> (اِخ ) رجوع بذرو شود.<br /></font></div>'),
(130249, 'ذات رجل', '<span class=\"hlight\">ذات رجل .</span> <font color=\"DarkGreen\"><b>[ ت ُ رِ ]</font></b> (اِخ ) موضعی است به دیار عرب . مثقب عبدی گوید <span class=\"hlight\">:</span> <br />مررن علی شراف فذات رجل <br />و نکبن الذرانح بالیمین .<br /> <font color=\"Red\">(معجم البلدان ).</font><br />و ابن الأثیر در المرصع ذات رجل این شعر را گوید به دیار کلب در شام است . <BR><font color=\"Blue\">◄</font> و نیز جایگاهی است به زمین بکربن وائل . (المرصع). و یاقوت گوید: از ارض بکربن وائل از اسافل حزن . <BR><font color=\"Blue\">◄</font> و نیز محلی نزدیک یمامة. (المرصع).<br /></font></div>'),
(130250, 'ذات رفرف', '<span class=\"hlight\">ذات رفرف .</span> <font color=\"DarkGreen\"><b>[ ت ُ رَ رَ ]</font></b> (اِخ ) وادیئی است بنی سلیم را. (معجم البلدان یاقوت ).<br /></font></div>'),
(130251, 'ذات رمح', '<span class=\"hlight\">ذات رمح .</span> <font color=\"DarkGreen\"><b>[ ت ُ رُ ]</font></b> (اِخ ) قریه ای است به شام . (المرصع). <BR><font color=\"Blue\">◄</font> و ابرقی سپید بدیار بنی کلاب، بنوعمروبن ربیعة را. (المرصع) (معجم البلدان ).<br /></font></div>'),
(130252, 'ذات روقین', '<span class=\"hlight\">ذات روقین .</span> <font color=\"DarkGreen\"><b>[ ت ُ رَ ق َ ]</font></b> (ع ص مرکب ) حرب ذات روقین ؛جنگی سخت . داهیة ذات روقین، داهیة عظیمة. بلای بد.<br /></font></div>'),
(130253, 'ذات سوار', '<span class=\"hlight\">ذات سوار.</span> <font color=\"DarkGreen\"><b>[ ت ُ س ِ ]</font></b> (اِخ ) زنی مجلّله و صاحب مکانت : لو ذات سوار لطمتنی .<br /></font></div>'),
(130254, 'ذات شد', '<span class=\"hlight\">ذات شد.</span> <font color=\"DarkGreen\"><b>[ ت ُ ش َدد ]</font></b> (اِخ ) رجوع بذات شَل شود.<br /></font></div>'),
(130255, 'ذات شل', '<span class=\"hlight\">ذات شل .</span> <font color=\"DarkGreen\"><b>[ ت ُ ش َل ل ]</font></b> (اِخ ) پشته ای است به دیارغطفان . و بجای لام شل دال هم آمده است . یعنی شَدّ.<br /></font></div>'),
(130256, 'ذات شماص و ملاص', '<span class=\"hlight\">ذات شماص و ملاص .</span> <font color=\"DarkGreen\"><b>[ ت ُ ش ِ وَ م ِ ]</font></b> (ع ص مرکب ) دختر نرم اندام، شوخ بی باکانه پیش آینده . در فارسی، مثل عروس قلندرها گویند.<br /></font></div>'),
(130257, 'ذات شهر', '<span class=\"hlight\">ذات شهر.</span> <font color=\"DarkGreen\"><b>[ ت َ ش َ رِن ْ ]</font></b> (ع ق مرکب ) به ماهی . در ماهی .<br /></font></div>'),
(130258, 'ذات ضغن', '<span class=\"hlight\">ذات ضغن .</span> <font color=\"DarkGreen\"><b>[ ت ُ ض ِ ]</font></b> (ع ص مرکب ) ناقة ذات ضغن ؛ ماده اشتری دوستار وطن یعنی جایباش خویش . ای مائلةٌ الی وطنها؛ اشتر ماده که شوگاه خویش دوست گیرد.<br /></font></div>'),
(130259, 'ذات طس', '<span class=\"hlight\">ذات طس .</span> <font color=\"DarkGreen\"><b>[ ت ُ طَ ]</font></b> (ع ص مرکب، اِمرکب ) سورتی از قرآن که به طس آغازد.<br /></font></div>'),
(130260, 'ذات ظلف', '<span class=\"hlight\">ذات ظلف .</span> <font color=\"DarkGreen\"><b>[ ت ُ ظِ ]</font></b> رجوع به ذوات الاظلاف شود.<br /></font></div>'),
(130261, 'ذات عرش', '<span class=\"hlight\">ذات عرش .</span> <font color=\"DarkGreen\"><b>[ ت ُ ع َ ]</font></b> (اِخ ) یکی از صد و ده دارات عرب است . رجوع به کلمه ٔ دور در لغت نامه های عرب شود.<br /></font></div>'),
(130262, 'ذات عرق', '<span class=\"hlight\">ذات عرق .</span> <font color=\"DarkGreen\"><b>[ ت ُ ع ِ ]</font></b> (اِخ ) یاقوت گوید: ذات عرق مُهل یعنی میقات و احرام بستن گاه حاجیان عراق باشد و آن حدّ میان نجد و تهامة است . و بعضی گویند عرق کوهی است براه مکه و ذات عرق بدانجاست و اصمعی گوید قسمت مرتفع از بطن الرمّة تا خم های ذات عرق نجد باشد و عرق کوه مشرف بر ذات عرق بود و ساعدةبن جویة درشعر خود همانجا را اراده کرده است . آنجا که گوید:<br />لمّا رای عرقا و رجع صوته <br />هدراً کما هدرا لفنیق المصعب .<br />و دیگری گوید:<br />و نحن بشهب مشرف غیر منجد<br />و لا متهم فالعین بالدّمع تذرف .<br />و آن بدو منزلی مکه است .<br />و ابن عیینة گوید: سألت اهل ذات عرق امتهمون انتم ام منجدون فقالوا: ما نحن بمتهمین و لامنجدین . یعنی شمایان از ارض تهامه باشید یا نجد گفتند از هیچیک .و ابن شبیب گوید ذات عرق از غور است و غور از ذات عرق باشد تا اوطاس و اوطاس بر سر راه است و نجد از اوطاس است تا قریتین . و برخی گفته اند: اول تهامة از جانب نجد، مدارج ذات عرق باشد. و یکی از اهل عراق گفته است :<br />و نحن بسهب مشرف غیر منجد<br />و لامتهم فالعین بالدمع تذرف .<br /> <font color=\"Red\">- انتهی .</font><br />رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span> و امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> و معجم البلدان یاقوت ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span> و <span class=\"hlight\" dir=\"rtl\">١٨٣</span> س <span class=\"hlight\" dir=\"rtl\">١٤</span> والموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٥٠</span> و <span class=\"hlight\" dir=\"rtl\">١١٩</span> و <span class=\"hlight\" dir=\"rtl\">١٩٦</span> و عیون الأخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٠</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span> و <span class=\"hlight\" dir=\"rtl\">٢٨</span> شود.<br /></font></div>'),
(130263, 'ذات عروس', '<span class=\"hlight\">ذات عروس .</span> <font color=\"DarkGreen\"><b>[ت ُ ع َ ]</font></b> (ع اِ مرکب ) از جمله ٔ مثلی است که زبّاء پس از کشتن جذیمةالأبرش گفت : ذات عروس تری . (المرصع).<br /></font></div>'),
(130264, 'ذات عقد', '<span class=\"hlight\">ذات عقد.</span> <font color=\"DarkGreen\"><b>[ ت ُ ع ُ ق َ ]</font></b> (ع ص مرکب ) پرگره .<br /></font></div>'),
(130265, 'ذات عوار', '<span class=\"hlight\">ذات عوار.</span> <font color=\"DarkGreen\"><b>[ ت ُ ع ِ ]</font></b> (ع ص مرکب ) آهمند. معیوب . فاسد.<br /></font></div>'),
(130266, 'ذات غسل', '<span class=\"hlight\">ذات غسل .</span> <font color=\"DarkGreen\"><b>[ ت ُ غ ِ ]</font></b> (اِخ ) ابن موسی گوید موضعی است میان یمامه و نباج و میان آن و نباج دو منزل است و آن در اول بنی کلیب بن یربوع را بود و سپس به بنونمیر منتقل گردید. وعمرانی آورده است که ذوغسل (؟) قریه ای است بنوامری ٔالقیس را در شعر ذی الرمّة آنجا که گوید <span class=\"hlight\">:</span> <br />واظعان طلبت بذات لوث <br />یزید رسیمها سرعاًو لینا<br />انخن جمالهن ّ بذات غسل <br />سراةالیوم یمهدن الکدونا.<br />و ابوعبیداﷲ سکونی گوید آنکس که از نباج به یمامه رفتن خواهد باید از اشی ّ بذات غسل رود و آن نخست بنوکلیب بن یربوع رهط جریر را بود و اکنون نمیر راست . و از ذات غسل تا امرة قریه ای است . و حفصی راست :<br />بثرمداء شُعب ٌ من عقل <br />و ذات غسل ما بذات غسل ِ.<br />و بدانجا بستانی است که به ذات غسل معروف است .<br /></font></div>'),
(130267, 'ذات فرض', '<span class=\"hlight\">ذات فرض .</span> <font color=\"DarkGreen\"><b>[ ت ُ ف َ ]</font></b> (ع ص مرکب ) آنکه در ارث فریضه دارد، مقابل عاصب .<br /></font></div>'),
(130268, 'ذات فرق', '<span class=\"hlight\">ذات فرق .</span> <font color=\"DarkGreen\"><b>[ ت ُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> وذات فرقین . (اِخ ) موضعی است بنی سلیم را. (المرصع).<br /></font></div>'),
(130269, 'ذات فرقین', '<span class=\"hlight\">ذات فرقین .</span> <font color=\"DarkGreen\"><b>[ ت ُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (اِخ ) پشته ای است میان بصره و کوفه در بلاد تمیم .<br /></font></div>'),
(130270, 'ذات فلس', '<span class=\"hlight\">ذات فلس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> ( ) این صورت با شرحی در المرصع ابن الاثیر آمده است و این نسخه چون خطی و منحصر است تکمیل آن میسر نشد. رجوع به فلس در معجم یاقوت شود.<br /></font></div>'),
(130271, 'ذات قرب', '<span class=\"hlight\">ذات قرب .</span> <font color=\"DarkGreen\"><b>[ ت ُ ق َ ]</font></b> (اِخ ) موضعی است . و در آن جنگی بوده است عرب را.<br /></font></div>'),
(130272, 'ذات قرنین', '<span class=\"hlight\">ذات قرنین .</span> <font color=\"DarkGreen\"><b>[ ت ُ ق َ ن َ ]</font></b> (اِخ ) لقب مادر حرث اعرج غسانی است . (المرصع). و او را ذات القرطین نیز نامند.<br /></font></div>'),
(130273, 'ذات لظی', '<span class=\"hlight\">ذات لظی .</span> <font color=\"DarkGreen\"><b>[ ت ُ ل َ ظا ]</font></b> (اِخ ) موضعی است بحرةالنار و حرةالنار میان وادی القری و تیما از دیار غطفان . در عقدالفرید آمده است : و اقبل رجل ٌ الی عمربن الخطاب فقال له عمر ما اسمک ؟ فقال شهاب حرقة، قال ممن ؟ قال من اهل حرةالنار. قال و این مسکنک ؟ قال بذات لظی قال اذهب فان ّ اهلک قد احترقوا. (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span> در باب التفاؤل بالاسماء). و رجوع به ذات اللظا شود.<br /></font></div>'),
(130274, 'ذات لوث', '<span class=\"hlight\">ذات لوث .</span><font color=\"DarkGreen\"><b>[ ت ُ ل َ ]</font></b> (اِخ ) موضعی است . راعی راست <span class=\"hlight\">:</span> <br />و اظعان طلبت بذات لوث <br />یزید رسیمها سرعاً و لینا<br />انخن جِمالهن بذات غسل <br />سراةالیوم یمهدن الکدونا.<br /></font></div>'),
(130275, 'ذات ماسل', '<span class=\"hlight\">ذات ماسل .</span> <font color=\"DarkGreen\"><b>[ ت ُ س ِ ]</font></b> (اِخ ) (ابرق ...) قال الشمردل بن شریک الیربوعی و کان صاحب شراب <span class=\"hlight\">:</span> <br />شربت و نادمت الملوک فلم اجد<br />علی الکأس ندماناً لها مثل دیکل <br />اقل ّ مکاساً فی جزور و ان غلت <br />و اسرع ایضاحاً و انزال مِرجل <br />تری البازل الکوماء فوق خوانه <br />مفصّلة اعضأها لم تفصّل <br />سقیناه بعد الرّی حتی کأنما<br />تری حین امسی ابرقی ذات ماسل <br />عشیة انسینا قبیصة نعله <br />فراح الفتی البکری ّ غیر منعل .<br /></font></div>'),
(130276, 'ذات مال', '<span class=\"hlight\">ذات مال .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (ع ص مرکب ) خداوند مال (زن ). زن مالدار. زنی توانگر. زن باخواسته . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دارائی . توانگری .<br /></font></div>'),
(130277, 'ذات مخارم', '<span class=\"hlight\">ذات مخارم .</span> <font color=\"DarkGreen\"><b>[ ت ُ م َ رِ ]</font></b> (ع ص مرکب ) عین ذات مخارم ؛ ای ذات مخارج .<br /></font></div>'),
(130278, 'ذات مغول', '<span class=\"hlight\">ذات مغول .</span> <font color=\"DarkGreen\"><b>[ ت ُ م ِغ ْ وَ ]</font></b> (ع ص مرکب ) فرس ذات مغول ؛ اسپ پیشی گیرنده .<br /></font></div>'),
(130279, 'ذات منسم', '<span class=\"hlight\">ذات منسم .</span> <font color=\"DarkGreen\"><b>[ ت ُ م َ س ِ ]</font></b> (ع ص مرکب ) صاحب سَپل . نرم پای . ج، ذوات المنسم . چون شتر و فیل و شترمرغ .<br /></font></div>'),
(130280, 'ذات منور', '<span class=\"hlight\">ذات منور.</span> <font color=\"DarkGreen\"><b>[ ت ُ م َن ْ وَ ]</font></b> (ع ص مرکب ) یقال بغاه اﷲ ذات منور؛ ای ضربة او رمیةً تنیر فلاتخفی علی احد. (منتهی الارب ).<br /></font></div>'),
(130281, 'ذات میل', '<span class=\"hlight\">ذات میل .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) قریه ای به شرقیه ٔ مِصر.<br /></font></div>'),
(130282, 'ذات نوط', '<span class=\"hlight\">ذات نوط.</span> <font color=\"DarkGreen\"><b>[ ت ُ ن َ ]</font></b> (اِخ ) رجوع به ذات انواط شود.<br /></font></div>'),
(130283, 'ذات نکیف', '<span class=\"hlight\">ذات نکیف .</span><font color=\"DarkGreen\"><b>[ ت ُ ن َ ]</font></b> (اِخ ) موضعی به ناحیت یلملم . (المرصع).<br /></font></div>'),
(130284, 'ذات نیرین', '<span class=\"hlight\">ذات نیرین .</span> <font color=\"DarkGreen\"><b>[ ت ُ ن َ ]</font></b> (ع ص مرکب ) ناقه ٔ ذات نیرین، ناقه ٔ کلانسال که در آن بقیه ای باشد. (منتهی الارب ). ناقة ذات انیار. و ابن الاثیر در المرصع گوید:ذات نیرین، راه پهناور باشد. شاعر گوید <span class=\"hlight\">:</span> <br />و قد جاوزتها ذات نیرین سارق <br />محرمة فیها لوامع تخفق .<br /><font color=\"Red\">(المرصع).</font><br /></font></div>'),
(130285, 'ذات وبر', '<span class=\"hlight\">ذات وبر.</span> <font color=\"DarkGreen\"><b>[ ت ُ وَ ب َ ]</font></b> (ع ص مرکب ) یقال للرجل اذا تکلم بما ینکر علیه، جئت بها شعراء و ذات وَبر.<br /></font></div>'),
(130286, 'ذات ودقین', '<span class=\"hlight\">ذات ودقین .</span> <font color=\"DarkGreen\"><b>[ ت ُ وَ ق َ ]</font></b> (ع اِمرکب ) صاحب دو جهت . داهیة. درد و سختی . (مهذب الاسماء). ذات وجهین . (المرصع). که گوئی آن دو روی دارد.<br /></font></div>'),
(130287, 'ذات کهف', '<span class=\"hlight\">ذات کهف .</span> <font color=\"DarkGreen\"><b>[ ت ُ ک َ ]</font></b> (اِخ ) کوهی است نزدیک ضریّة و بدانجا بنویربوع را با جیش منذربن ماءالسماء جنگی روی داد و غلبه بنویربوع را بود. جریر گوید <span class=\"hlight\">:</span> <br />هم ملکوا الملوک بذات کهف <br />هم منعوا من الیمن الکلابا.<br /> <font color=\"Red\">(از المرصع).</font><br />و روضة ذات کهف نیز موضعی است و یاقوت گوید: روضة ذات کهف حجازیّةٌ بنواحی المدینة.<br />جبلةبن جریس حلاّبی راست <span class=\"hlight\">:</span> <br />و قلت لهم بروضة ذات کهف <br />اقیموا الیوم لیس اوان سیر.<br /></font></div>'),
(130288, 'ذات ید', '<span class=\"hlight\">ذات ید.</span> <font color=\"DarkGreen\"><b>[ ت ُ ی َ ]</font></b> (ع اِ مرکب ) دارائی . مال . ذات ید فلان ؛ مایملک او. قلت ذات یده ؛ تنگ دست گردید.<br /></font></div>'),
(130289, 'ذات یدین', '<span class=\"hlight\">ذات یدین .</span> <font color=\"DarkGreen\"><b>[ ت ُ ی َ دَ ]</font></b> (ع اِ مرکب ) قبل ذات یدین ؛ پیش از هر چیز. قبل از همه . به اول وَهلة: لقیته قبل ذات یدین . و قیل اول نفس ذات یدین . و نیز صاحب المرصع گوید کنایه از سرعت در کار است .<br /></font></div>'),
(130290, 'ذات یوم', '<span class=\"hlight\">ذات یوم .</span> <font color=\"DarkGreen\"><b>[ ت َ ی َ مِن ْ ]</font></b> (ع ق مرکب ) روزی . (دهار). در روزی . بروزی . روزی از روزها.<br /></font></div>'),
(130291, 'ذاتی', '<span class=\"hlight\">ذاتی .</span> <font color=\"DarkGreen\"><b>[ تی ی ]</font></b> (ع ص نسبی ) منسوب به ذات . گوهری، گهری . جبلی . غریزی . طبیعی . فطری . جوهری : مقابل عرضی . عارضی : حسن و قبح اشیاء ذاتی نیست . اصلی . ذاتی بیاءِ النّسبة عندالمنطقیین یطلق بالاشتراک علی معان : منها یقال الذّاتی لکل ّ شی ٔ ما یخصّه و یُمیزه عن جمیع ما عداه . و قیل ذات الشی ٔ نفسه و عینه و هو لایشتمل العرض والفرق بین الذّات و الشخص ان ّ الذّات اعم ّ من الشخص لان ّ الذّات یُطلق علی الجسم و غیره . و الشخص لایطلق الاّ علی الجسم . هکذا فی الجرجانی . منها فی کتاب ایساغوجی فانّه یطلق فی هذا المقام علی جزءِ الماهیّة و المقصود به الجزء المفرد المحمول علی الماهیّة و هو منحصر فی الجنس و الفصل و ربّما یطلق علی ما لیس بخارج و هذا اعم ّ من الاوّل لتناوله نفس الماهیة و جزئها. و التسمیة علی الاول ظاهرة و علی الثّانی اصطلاحیّة محضة. و الخارج عن الماهیّة یسمّی عَرَضیّاً. وربّما یطلق الذّاتی علی الجزء مطلقاً، سواء کان محمولاً علی الماهیة او لم یکن کالواحد للثلاثة ثم ّ انَهم ذکروا للذاتی خواصاً ثلاثاً. الاولی ان یمتنع رفعه عن الماهیّة بمعنی انّه اذا تصوّر الّذاتی و تصوّر معه الماهیّة امتنع الحکم بسلبه عنها بل لابدّ من ان یحکم بثبوته لها. الثّانیة ان یجب اثباته للماهیّة علی معنی انّه لایمکن تصوّرالماهیّة الاّ مع تصوّره موصوفةبه . ای مع التّصدیق بثبوته لها. و هی اخص ّ من الاولی . لانّه اذا کان تصورالماهیّة بکنهها مستلزماً لتصوّرالتّصدیق بثبوته لها کان تصوّرهما معاً مستلزماً لذلک التّصدیق کلیّاً بدون العکس . اذا لایلزم من کون التّصورین کافیین فی الحکم بالثبوت ان یکون احدهما کافیاً مع ذلک . و هاتان الخاصّتان لیستا خاصّتین مطلقتین لان ّ الاولی تشتمل اللّوازم البینة بالمعنی الاعم ّ و الثّانیة بالمعنی الاخص ّ. الثّالثة و هی خاصة مطلقة لایشارک الذّاتی فیها العرضی ّ اللاّزم . و هی ان یتقدّم علی الماهیّة فی الوجودین الخارجی ّ و الذّهنی ّ بمعنی ان الذاتی و الماهیة اذا وجدا باحدالوجودین، کان وجودالذاتی متقدّماً علیها بالذّات . ای العقل یحکم بانّه وجد الذّاتی اوّلاً فوجدت الماهیة و کذا فی العدمیّین . لکن ّ التقدّم فی الوجود بالنّسبة الی جمیعالاجزاء.و فی العدم بالقیاس الی جزء واحد. فان قیل هذه الخاصة تنافی ماحکموا به من ان ّ الذّاتی متّحد مع الماهیة فی الجعل و الوجود لاستحالة ان یکون المتقدّم فی الوجود متّحداً فیه مع المتأخر عنه و تنافی صحة حمل الذّاتی علی الماهیة لامتناع حمل احدالمتغایرین فی الوجود علی الاَّخر و یستلزم ان یکون کل مرکب فی العقل مرکباً فی الخارج مع انهم صرحوا بخلافها، قلنا ما ذکرناه خاصّة للجزء مطلقاً فانّه اینما کان جزء کان متقدّماً فی الوجود و العدم هناک، فالجزء العقلی متقدّم علی الماهیة فی العقل لا فی الوجود و لا فی الخارج . فلایلزم شی ٔ ممّا ذکرتموه . فاذا ارید تمیزه ایضاً عن الجزء الخارجی زید الحمل علی اعتبارالتقدم المذکور لیمتاز به عنه ایضاً. و هذه الخواص ّ انّما توجد للذاتی اذا خطر بالبال مع ما له الذّاتی . لا بمعنی انّه لاتکون ثابتة للذاتی الاّ عندالاخطار بالبال . فربّما لاتکون الماهیة و ذاتیاتها معلومة. و تلک الخاصیات ثابتة لها فضلاً عن اخطارها بالبال بل بمعنی انها انما یعلم ثبوتها للذاتیات اذا کانت مخطرة بالبال و الشی ٔ خاطر بالبال ایضاً. کذا قیل . و قد یعرف الذّاتی ای الجزء مطلقاً بما لایصح توهمه مرفوعاً مع بقاءِ الماهیة کالواحد للثلاثة اذ لایمکن ان یتوهّم ارتفاعه مع بقاءِ ماهیةالثلاثة بخلاف وصف الفردیة. اذ یمکن ان یتوهّم ارتفاعها عنها مع بقائها. نعم یمتنع ارتفاعها مع بقاء ماهیة الثلاثة موجودة. فالحال هیهنا المتصوّر فقط. و هناک التصوّر و المتصور معاً. و السرّ فی ذلک ان ّ ارتفاع الجزء هو بعینه ارتفاع الکل لا انّه ارتفاع آخر و من المستحیل ان یتصور انفکاک الشی ٔ عن نفسه . بخلاف ارتفاع اللوازم . فانّه مغایر لارتفاع الماهیة تابع له . فامکن تصورالانفکاک بینهما مع استحالته . و کذا ارتفاع الماهیة مغایر لارتفاعها مستتبع له فجاز ان یتصور انفکاک احدهما عن الاَّخر. و یقال ایضاً الذّاتی ما لایحتاج الی علة خارجة عن علّةالذّات بخلاف العرضی فانّه محتاج الی الذات و هی خارجة عن علتها. کالزوجیة للاربعة المحتاجه الی ذات الاربعة. و یقال ایضاً هو ما لاتحتاج الماهیة فی اتصافها به الی علة مغایرة لذاتها. فان السواد لون لذاته لابشی ٔ آخر یجعله لوناً. و هذه خاصة اضافیّة لان ّ لوازم الماهیة کذلک . فان ّ الثلاثة فردٌ فی حدّ ذاته لابشی ٔ آخر یجعلها متصفة بالفردیّة. هذا کله خلاصة ما فی شرح المطالع. و ما حققّه السیدالشریف فی حاشیته، و ذکر فی العضدی ان ّ الذّاتی ما لایتصور فهم الذّات قبل فهمه و قال السیدالشریف فی حاشیته مأخذه هو ما قیل من ان الجزء لایمکن توهم ارتفاعه مع بقاءِ الماهیة بخلاف اللازم . اذ قد یتصوّر ارتفاعه مع بقائها فمعناه ان ّ الذّاتی محمول لایمکن ان یتصوّر کون الذّات مفهوماً حاصلاً فی العقل بالکنه . و لایکون هو بعد حاصلاً فیه . و هذا التعریف یتناول نفس الماهیة. اذ یستحیل تصور ثبوتها عقلاً قبل ثبوتها فیه و الجزء المحمول، اذ یمتنع تصور ثبوت الذات فی العقل . و هو معنی کونه مفهوماً قبل ثبوته فیه ای مع ارتفاعه عنه . ثم قال صاحب العضدی : و قد یعرف الذّاتی بانه غیر معلّل . قال المحقّق التفتازانی ای ثبوته للذّات لایکون لعِلّة. لانّه امّا نفس الذّات او الجزء المتقدم بخلاف العرضی . فانّه ان کان عَرضاً ذاتیاً اوّلیاً یعلّل بالذّات لامحالة، کزوجیة الاربعة و الاّ فبالوسائط، کالضحک الانسان لتعجّبه . و ما یقال انّه ان کان لازماً بیناً یعلّل بالذّات و الاّ فبالوسائط، اّنما یصح لو ارید العلّة فی التصدیق . و لو ارید ذلک انتقض باللوازم البینة. فان ّ التصدیق بثبوتها للملزومات لایعلّل بشی ٔ اصلاً. نعم یشکل ما ذکر بما اطبق المنطقیون من ان ّ حمل الاجناس العالیة علی الانواع انّما هو بواسطة المتوسطات . و حمل المتوسطات بواسطة السوافل . حتّی صرّح ابن سینا ان ّ الجسمیة للانسان معلّلة بحیوانیته - انتهی . و مرجع هذا التعریف الی ما مرّ سابقاً من ان ّ الذاتی ما لایحتاج الی علّة خارجة عن علّةالذات . کما لایخفی . ثم قال صاحب العضدی ؛ و قد یعرف الذاتی بالترتّب العقلی . و هوالّذی یتقدّم علی الذات فی التعقل - انتهی . و ذلک لانّهما فی الوجود واحد لااثنینیة اصلاً فلاتقدّم . و هذاالتفسیر مختص بجزء الماهیة و الأولان یعمان نفس الماهیةایضاً و حقیقةالتعریفین الاخیرین یرجع الی الاول و هومالایتصور فهم الذات قبل فهمه . لان عدم تعلیل الذاتی مبنی علی انه لایمکن فهم الذات قبل فهمه بل بالعکس . والتقدم فی التعقل مستلزم لذلک و ان لم یکن مبنیاً علیه . کذا ذکر المحقق التفتازانی فی حاشیته و منها فی غیر کتاب ایساغوجی . قال شارح المطالع و السید الشریف ما حاصله ان ّ للذّاتی معان آخر فی غیر کتاب ایساغوجی یقال علیها بالاشتراک . و هی علی کثرتها ترجع الی اربعة اقسام . الاوّل ؛ ما یتعلّق بالمحمول و هو اربعة: الاوّل المحمول الذی یمتنع انفکاکه عن الشی ٔ و یندرج فیه الذاتیات و لوازم الماهیة بینة کانت او غیر بینة و لوازم الوجود کالسواد للحَبَشی . و الثانی الذی یمتنع انفکاکه عن ماهیة الشی ٔ. و یندرج فیه الثلاثة الاوّل فقط. فهو اخص من الاوّل . و الثالث ما یمتنع رفعه عن الماهیة بالمعنی المذکور سابقاً فی خواص الذاتیات . فهو یختص بالذاتیات و اللوازم البینة بالمعنی الاعم . فهو اخص من الثانی . فان من المعلوم ان ّ مایمتنع رفعه عن الماهیة فی الذهن بل یجب اثباته لها عند تصوّرهما کان الحکم بینهما من قبیل الاوّلیات فلابدّ ان یمتنع انفکاکه عنها فی نفس الامر. و الاّ ارتفع الوثوق عن البدیهیات و لیس کلما یمتنع انفکاکه عن ماهیةالشی ٔ یجب ان یمتنع رفعه عنها فی الذهن، لجواز ان لایکون ذلک الامتناع معلوماً لنا کما فی تساوی الزّوایا الثلاث لقائمتین فی المثلث . و الرابع مایجب اثباته للماهیة. و قد عرفت معناه ایضاً. فهو یختص ّ بالذاتیات و اللوازم البینة بالمعنی الاخص فکل ّ من هذه الثلاثة الاخیرة اخص مماقبله . و الثانی ما یتعلق بالحمل . و هو ثمانیة: الاوّل ان یکون الموضوع مستحقاً للموضوعیة. کقولنا الانسان کاتب . فیقال له حمل ذاتی . و لمقابله حمل عَرَضی . و الثانی ان یکون المحمول اعم من الموضوع . و بازائه الحمل العَرَضی . فالمحمول فی مثل قولنا الکاتب بالفعل انسان ذاتی بهذا المعنی <font color=\"DarkGreen\"><b>[ و ]</font></b> عَرَضی بالمعنی الاول لان الوصف و ان کان اخص ّ لیس مستحقاً ان یکون موضوعاً للذاتی . و الثالث ان یکون المحمول حاصلاً بالحقیقته، ای محمولاً علیه بالمواطاءة و الاشتقاق حمل عَرَضی . و منهم من فسّر الحاصل للموضوع بالحقیقة بما یکون قائماً به حقیقة. سواء کان حاصلاً له بمقتضی طبعه او لقاسر: کقولنا: لا الحجر متحرک الی تحت او الی فوق و ما لیس کذلک فحمله عَرَضی . کقولنا جالس السفینة متحرک . فان الحرکة لیست قائمة به حقیقة بل بالسفینة. و هذا اشهر استعمالاً حیث یقال للساکن فی السفینة المتحرّکة انّه متحرّک بالعَرَض لا بالذات . و الرابع ان یحصل لموضوعه باقتضاء. طبعه، کقولنا الحجر متحرک الی اسفل وما لیس باقتضاء طبعالموضوع عَرَضی . و الخامس ان یکون دائم الثبوت للموضوع . و ما لایدوم عَرَضی . و السادس ان یحصل لموضوعه بلاواسطة و فی مقابله العَرَضی . و السابع ان یکون مقوماً لموضوعه و عکسه عرضی . والثامن ان یلحق لا لامر اعم ّ او اخص ّ. و یسمّی فی کتاب البرهان عرضاً ذاتیاً سواء کان لاحقاً بلاواسطة او بواسطة امرُ مساو و مایلحق بالامر الاخص ّ او الاعم عَرَضی . اعلم ان ّ حمل الواحد قد یکون ذاتیاً باعتبار و عرضیاً باعتبار آخر. فتأمل فی الاقسام الثمانیة و کیفیة اجتماعها و افتراقها. و الثالث ما یتعلق بالسبب فیقال لایجاب السبب للمُسبب انّه ذاتی اذا ترتب علیه دائماً کالذبح للموت . او اکثریاً کشُرب السقمونیا للاسهال . و عَرَضی ان کان الترتُب اقلیاً کلمعان البرق للعثور علی المطر. و الرابع مایتعلّق بالوجود، فالموجود ان کان قائماً بذاته یقال انّه موجود بذاته کالجوهر و ان کان قائما بغیره، یقال انّه موجود بالعَرَض . کالعرض .<br />کلی را چنانکه گفته اند، شایستگی آن باشد که محمول باشد بر موضوعی، و چون نگاه کنند حال او به نسبت با آن موضوع از سه وجه خالی نتواند بود: یا تمامی ماهیت آن موضوع باشد، مانند انسان به نسبت با زید و عمرو و یا ضاحک به نسبت با این ضاحک و آن ضاحک . چه مفهوم این ضاحک و آن ضاحک را بیرون معنی ضاحک ماهیتی و حقیقتی نیست، و اختلاف میان هر دوکه لفظ این و آن دال ّ است بر آن، نه اختلافی است که بسبب آن در تصور حقیقت تفاوتی افتد و یا داخل بود درماهیت آن موضوع، مانند لون به نسبت با سواد، چه ماهیت سواد لون تنها نیست بل بیرون معنی لونیت که با دیگر رنگها در آن اشتراک دارد، خصوصیتی دیگر هست که باآن از دیگر رنگها ممتاز شده است . و سواد سواد به این دو معنی است که مقارن یکدیگرند، پس هر یک از این دو معنی داخل باشند در ماهیت سواد، و این قسم جز در موضوعاتی که در مفهوم آن ترکیب ذهنی باشد معقول نبود.و یا خارج بود از ماهیت آن موضوع مانند اسود به نسبت با ضاحک . چه آنجا که گوئی : این ضاحک اسود است، مفهوم از اسود نه تمام ماهیت ضاحک است، و نه داخل در آن ماهیت، بلکه خارج بود از آن ماهیت . و قسم اول و دوم در این اشتراک دارند که ماهیت موضوع را با آن دو قسم قوام تواند بود، پس مقوم موضوع باشند و به این اعتبار هر دو قسم را ذاتی خوانند. و ذاتی در این اصطلاح منسوب نیست با ذات، چه به یک وجه خود عین ذات است و عین ذات منسوب نتواند بود با خود. (اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). ذاتی یا تمامی ماهیت است، یا جزو ماهیت . و جزو ماهیت دوگونه بود. یا جزوی بود خاص بماهیت آن موضوع که ذاتی به اضافت با او ذاتی است، یا نبود، بلکه همان جزو جزو ماهیت موضوعی دیگر باشد. مثلاً سواد را لون ذاتی است و غیر او را با او در آن شرکت است، چه بیاض نیز هم لون است و هم سواد را بیرون لون خصوصیتی دیگراست داخل در مفهوم او که غیر او را نیست تا او به آن از دیگر الوان ممتاز شده است، و آن جزو خاص بود، واز حال لغات معلوم است که آنکس که چیزی را نشناسد، و طلب تصوّر حقیقت آن چیز کند، سؤال از آن بلفظ؛ چیست کند، و بتازی ما هو گویند، که ماهیت از این لفظ گرفته اند. و چون اصلی حقیقت متصور بود، و امتیاز از اشتباه حاصل نشده، سؤال از آن بلفظ؛ کدام است کنند، و بتازی ای ُ شی ٔ هُوَ گویند، و یا ای ّ ما هُوَ. و ظاهر شد که حقیقت سواد بی تصور لونیت تصور نتوان کرد و امتیاز او از دیگر الوان جز بتصور آن معنی خاص که گفتیم صورت نبندد، پس جزو ماهیت یا مقول در جواب ما هوبود یا مقول در جواب ای ّ شی ٌٔ هُوَ و تمام ماهیت خود عین جواب ما هو است . پس ذاتی به این اعتبار دو قسم شود: مقول در جواب ما هو و مقول در جواب ای ّ شی ٔ هو. (اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>).<br /></font></div>'),
(130292, 'ذاتی', '<span class=\"hlight\">ذاتی .</span> (اِخ ) یکی از مشاهیر شعرای عثمانی از مردم بالیکسر. نامش عوض . متولد <span class=\"hlight\" dir=\"rtl\">٨٧٦</span> او در اوایل عمر شغل کفشدوزی می ورزید و پس از آنکه به اسلامبول رفت قصائدی در مدح سلطان بایزیدخان ثانی و اکابر معاصر بگفت و جوائزی بوی دادند و از آنگاه ببعد با صلات شعر خود امرار معاش می کرد و گاهی نیز تولیت پاره ای اعمال دولتی بوی محول شد و سپس به سعایت خیالی شاعر معاصر او جوائز و صلات وی مقطوع گردید و دچار فقر وتنگدستی شد و در نزدیکی جامع سلطان بایزید دکانی گرفته به رمّالی اشتغال ورزید و بسال <span class=\"hlight\" dir=\"rtl\">٩٥٣</span> درگذشت . و بگفته ٔ خود او بیش از <span class=\"hlight\" dir=\"rtl\">١٦٠٠</span> غزل و زیاده بر چارصد قصیده دارد و دو منظومه بنام احمد و محمود و شمع و پروانه نیز داشته است و اشعار وی بر یک نسق نیست و پستی و بلندی و غث و سمین بسیار دارد. و بیت ذیل از اوست :<br />دو شدم نشان پای سگ دلبراوستنه <br />اول غنچه گلدی دیدی یوزن گلار اوستنه <br />بر روی نشانهای پای سگ دلبر بر وی درافتادم و آن غنچه آمد و گفت بر روی گلها دراز بکش .<br /></font></div>'),
(130293, 'ذاتی', '<span class=\"hlight\">ذاتی .</span> (اِخ ) (شیخ سلیمان ...) یکی از شعرا و از مشایخ طریقه ٔ خلوتیه از مردم کاشان قصبه ٔ بروم ایلی است ...<br />وی از جانشینان شیخ حقی افندی بروسه ای بود و در قصبه ٔ مزبوره در تکیه ٔ خلوتیه پوست تخت ارشاد گسترده داشت وبه سال <span class=\"hlight\" dir=\"rtl\">١١٥١</span> درگذشت . بیت ذیل از اوست :<br />بو مرده جسممک سان جانیدر فیض <br />بو درد سینه مک درمانی در فیض .<br />(ترجمه : فیض بی شک جان این جسم مرده ٔ من و درمان این سینه ٔ دردمند من است ).<br /></font></div>'),
(130294, 'ذاتیات', '<span class=\"hlight\">ذاتیات .</span> <font color=\"DarkGreen\"><b>[ تی یا ]</font></b> (ع اِ) ج ِ ذاتیة.<br /></font></div>'),
(130295, 'ذاتیة', '<span class=\"hlight\">ذاتیة.</span> <font color=\"DarkGreen\"><b>[ تی ی َ ]</font></b> (ع ص نسبی ) تأنیث ذاتی . ج، ذاتیات .<br /></font></div>'),
(130296, 'ذاج', '<span class=\"hlight\">ذاج .</span> <font color=\"DarkGreen\"><b>[ ذاج ج ]</font></b> (ع ص ) نعت فاعلی از ذج ّ. آینده ٔ از راه . قادم از سفر. <BR><font color=\"Blue\">◄</font> آشامنده ٔ آب .<br /></font></div>'),
(130297, 'ذاجل', '<span class=\"hlight\">ذاجل .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) ستمگر. ستمکار. ظالم . جائر.<br /></font></div>'),
(130298, 'ذاخر', '<span class=\"hlight\">ذاخر.</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع ص ) نعت فاعلی از ذخر. فربه . فربی .سمین . <BR><font color=\"Blue\">◄</font> ذخیره کننده . دست پس دارنده . پستائی کننده . یخنی نهنده . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی .<br /></font></div>'),
(130299, 'ذاذی', '<span class=\"hlight\">ذاذی .</span> <font color=\"DarkGreen\"><b>[ ذی ی ]</font></b> (ع اِ) نباتی است با خوشه ٔ دراز (جاء علی النسب، ای بیاء مشدّده و لیس بِنسب ). رجوع به دادی شود.<br /></font></div>'),
(130300, 'ذاذیخ', '<span class=\"hlight\">ذاذیخ .</span> (اِخ ) قریه ای است از اعمال حلب نزدیک سرمین . و بدانجا سیف الدوله را با یونس مؤنسی وقعه ای است .<br /></font></div>'),
(130301, 'ذار', '<span class=\"hlight\">ذار.</span> (پسوند) مانند دار، مزید مؤخر بعض امکنه است : وذار. ویذار. اسفیذار.<br /></font></div>'),
(130302, 'ذارع', '<span class=\"hlight\">ذارع .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) منسوب به ذرع یعنی ذرع ثیاب و ارض . (سمعانی ). <BR><font color=\"Blue\">◄</font> نعت فاعلی از ذرع . شفیع. شافع. خواهشگر. <BR><font color=\"Blue\">◄</font> گزکننده . پیماینده ٔ به گز. <BR><font color=\"Blue\">◄</font> (اِخ ) اولاد ذارع یا اولاد ذراع ؛ کلاب و حِمْیِر و بجای آن اولاد وازع نیز گویند با واو و زاء اخت الراء.<br /></font></div>'),
(130303, 'ذارع', '<span class=\"hlight\">ذارع .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع اِ) خیک خرد شراب . مشکولی . خیکچه ٔ شراب . مشکیزه ٔ شراب . ج، ذوارع .<br /></font></div>'),
(130304, 'ذاری', '<span class=\"hlight\">ذاری ٔ.</span> <font color=\"DarkGreen\"><b>[ رِءْ ]</font></b> (ع ص ) نعت فاعلی از ذرء. آفریننده . (مهذب الاسماء). خالق . نامی از نامهای خدای تعالی .<br /></font></div>'),
(130305, 'ذاریات', '<span class=\"hlight\">ذاریات .</span> (ع ص، اِ) ج ِ ذاریة. بادهای برافشاننده . بادهای افشاننده . بادها که چیزها را ببرد.<br /></font></div>'),
(130306, 'ذاریات', '<span class=\"hlight\">ذاریات .</span> (اِخ ) نام سوره ٔ پنجاه و یکمین از قرآن کریم . و آن مکیة و دارای شصت آیت است، پیش از سوره ٔ طور و پس از سوره ٔ ق .<br /></font></div>'),
(130307, 'ذاریة', '<span class=\"hlight\">ذاریة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) باد. باد برنده . باد برافشاننده . ج، ذاریات .<br /></font></div>'),
(130308, 'ذاصبوح', '<span class=\"hlight\">ذاصبوح .</span> <font color=\"DarkGreen\"><b>[ ص َ]</font></b> (ع اِ مرکب ) اسقنی ذاصبوح ؛ بیاشامان مرا صبوحی .<br /></font></div>'),
(130309, 'ذاعر', '<span class=\"hlight\">ذاعر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) نعت فاعلی از ذعر. خائف . ترسنده . <BR><font color=\"Blue\">◄</font> ترساننده . ترسناک .<br /></font></div>'),
(130310, 'ذاعط', '<span class=\"hlight\">ذاعط.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) نعت فاعلی از ذعط. موت ذاعِط؛ مرگ شتاب . موت ذعوط.<br /></font></div>'),
(130311, 'ذاغی', '<span class=\"hlight\">ذاغی .</span> (ع ص ) نعت فاعلی از ذغی .<br /></font></div>'),
(130312, 'ذاغیة', '<span class=\"hlight\">ذاغیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) تأنیث ذاغی . زن گول سُست خویشتن نما و خویشتن آرا. (منتهی الارب ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130313, 'ذافنبداس', '<span class=\"hlight\">ذافنبداس .</span> <font color=\"DarkGreen\"><b>[ ف ِ ن ُ]</font></b> (معرب، اِ) داود انطاکی در تذکره گوید: آن را به مغرب مازریون گویند و هم مازره نامند. و آن گیاهی است با برگهای پهن و گلی سپید و حبی خردتر از حب غار و ساق آن گوئی چیزی است میانه ٔ زیتون و غار (یعنی شباهت به این هر دو دارد) و پوستی سخت و سیاه بر روی شاخهای طری و لطیف الملمس کشیده با طعمی حادّ و زبان گز و در لبنان و بلاد مغرب بسیار روید و گاه چیدن و باز کردن (قطف ) ثمر آن بماه حزیران بود. و آن گرم و خشک است در آخر درجه ٔ سیم . و محلل و مقطع و مخرج کیموسات لزجه و مفتح سده هاست . و آن را چون از خارج استعمال کنند مسقط خشک ریشه های لزجه و ثآلیل باشد و آثار را از قبیل خالها و خجک ها بزداید و بیشتر طبیبان از استعمال داخلی آن پرهیز کنند، چه آن داروئی محرق و مقطع است و مصلح آن نشاسته و کتیرا باشد و شربت آن تا سه قیراط و بدل آن دو برابر آن مازریون است - انتهی . و صاحب برهان قاطع این نام را ذاقنوبداس بکسر قاف و نون بواو رسیده و کسر بای ابجد و دال بی نقطه به الف کشیده و بسین مهمله زده ضبطکرده است و گوید لغتی است یونانی یعنی مانند غار و آن داروئی است و گویند نوعی از مازریون است و برگ آن پهن میباشد. رجوع به ذافنی ویداس و ذافنوبداس شود.<br /></font></div>'),
(130314, 'ذافنوبداس', '<span class=\"hlight\">ذافنوبداس .</span>(معرب، اِ) و معناه بالیونانیة الشبیه بالغار یعنی فی ورقه خاصة و هذا النوع من النبات یعرفه شجار و الأندلس بالمازریون العریض الورق و بالمازر أیضا و منهم من یعرفه بالخضراء و بالبربریة ادرار و هو مشهور عندهم بما ذکرناه آنفا و هذا النبات کثیر بارض الشام و خاصة بجبلی لبنان و بیروت و یعرفونه بالبقلة و هو عندهم دواء ردی ءالکیفیة و یحذرون من استعماله . ذیسقوریدوس : فی الرابعة. و من الناس من یسمیه خاماذاقنی وأوفاطالن و هو تمنش طوله نحو من ذراع و له اغصان کثیرة دقاق فی نصفها الاعلی ورق و علی الاغصان قشر قوی لزج و ورق شبیه بورق ذاقنی الا انه الین منه و أقوی و لیس بهین الانکسار و یلذع اللسان و یحذو الفم و الحنک و له زهر ابیض و ثمر اذا نضج کان اسود و له أصل لاینتفع به فی الطب و ینبت فی أماکن جبلیة و ورق هذا النبات اذا شرب یابسا و رطبا أسهل الفضول البلغمیة وقد یهیج القی ٔ و یدر الطّمث و اذا مضغ حلب من الفم البلغم و هو أیضا معطس ّ و ان أخذ من حبه خمس عشرة حبة و شربه بشراب اسهلت البطن . جالینوس : فی السادسة. قوّته شبیهة بقوة ذاقنی الاسکندرانی . (ابن البیطار).<br /></font></div>'),
(130315, 'ذافنوبداس', '<span class=\"hlight\">ذافنوبداس .</span> (معرب، اِ) رجوع به ذافنبداس شود.<br /></font></div>'),
(130316, 'ذافنی', '<span class=\"hlight\">ذافنی .</span> (معرب، اِ) صاحب مخزن الادویة گوید به کسر قاف لغت یونانی است . بمعنی غار الاسکندرانی . گیاهی است برگ آن قریب بدرخت غار جبلی و شبیه ببرگ مورد واز آن بزرگتر و سفید و طولانی و شاخهای آن بقدر شبری . و از ساق مابین برگ آن ثمر میروید بقدر نخودی سبز و مدوّر و بیخ آن خوشبو و شبیه بعود و تندطعم و منبت آن کوهستانهاست . طبیعت آن در دوّم گرم و خشک . آشامیدن بیخ آن بقدر شش درم با طلا که نوعی از شراب است جهت ادرار بول و حیض و اخراج مشیمة و رفع تقطیرالبول وحبس آن نافع. مقدار شربت از بیخ و ثمر آن تا دو مثقال است - انتهی . و صاحب برهان قاطع گوید: ذاقی بر وزن ساقی به یونانی درخت غار را گویند و آن درختی است که برگش از برگ بید درازتر و از برگ مورد بزرگتر و نرمتر و سفیدتر میباشد و میوه ٔ آن از فندق کوچکتر و از نخود بزرگتر است . اسهال خونی را نافع بود و یکنوع از آن را ذاقی الاسکندری خوانند - انتهی . و صاحب تحفه گوید: ذاقنی الاسکندرانی، گیاهی است برگش قریب بدرخت غار جبلی شبیه ببرگ مورد و از آن بزرگتر و سفید و طول شاخها بقدر شبری و از ساق و مابین برگ ثمری رسته بقدر نخودی، سبز و مدوّر بیخش خوشبو و شبیه بعود و تندطعم و در دوّم گرم و خشک و مدور و مخرج جنین و جهت تقطیر و حبس البول و حیض نافع و قدر شربتش از بیخ و ثمر تا دو مثقال است . و صاحب اختیارات بدیعی گوید: ذاقی الاسکندرانی معنی آن به یونانی غارالأسکندرانی بود دیسقوریدس گوید ورق او از ورق مورد بزرگتر و نرم تر وبغایت سپیدتر بود و ثمر وی در میان ورق بود بمقدار نخودی و در کوهستانها روید و بیخ وی مانند بیخ مورد بود لیکن بزرگتر و خوشبوی تر بود و چون بیخ وی بگیرندمقدار شش درم و با طلا بیاشامند نافع بود جهت دشوار زادن و چکیدن کمیز و جهت کسی که بجای کمیز از وی خون آید و جالینوس گوید طبیعت وی بغایت گرم بود و در طعم وی تلخی بود و مجرب است با نمک بول و حیض براند.<br />اما خاماذاقی معنی آن غارالارض بود. دیسقریدوس گوید ورق وی مانند ورق غار بود و لون وی سبز بود و قضبان وی به اندازه ٔ یک گز بود و ثمر وی گرد بود و سرخ رنگ و پیوسته بورق . و ورق چون نیک کوبند و ضماد کنند صداع را ساکن گرداند و عصاره ٔ وی چون با شراب بیاشامند مغص ساکن گرداندو بول و حیض براند و چون زن فرزجه کند و بخود برگیرد همین فعل کند. جالینوس گوید قوت وی مانند قوت ذاقی الاسکندرانی بود و عبداﷲبن صالح گوید فرق میان ذاقی الاسکندرانی و خاماذاقی آن است که ورق ذاقی الأسکندرانی اول پهن بود و با قضبان بود و خاماذاقی و ورق وی کوچکتر بود و از قضبان جدا بود و باقی همه مانند یکدیگرند - انتهی . صورتهای مختلف که به این کلمه داده اند از قبیل ذاقی و ذاقنی و غیره همگی غلط و تصحیف است . اصل این کلمه ٔ دافنه یونانی است به معنی غار و رند و نزدیک سی نوع از این درختچه یا بُته در نزد گیاه شناسان معروف و مضبوط است .<br /></font></div>'),
(130317, 'ذافنی الاسکندرانی', '<span class=\"hlight\">ذافنی الاسکندرانی .</span> <font color=\"DarkGreen\"><b>[ نِل ْ اِ ک َ دَ ]</font></b> (ع اِ مرکب ) معناه بالیونانیة الغار الأسکندرانی و لذلک ذکره اکثرالمصنفین فی هذا الفن مع الغار. لا لانه من أنواعه الا من اجل اشتراکه مع الغار فی الاسمیة فقط. لان اسم الغار بالیونانیة ذاقنی و هذا النبات لم اتحققه انا بعد و لا وقفت علیه .<br />قال شیخنا و معلمنا أبوالعباس النباتی، هو نوع من الشقاقل ینبت عندنا ببعض جبال الاندلس کثیراً. دیسقوریدوس : فی الرابعة. هو نبات له ورق شبیه بورق الاس الا انه اکبر منه وألین و أشدّ بیاضا و له ثمر فیمابین الورق اخضر فی قدرالحمص و قضبان طولها نحو من شبر و اکثر. و اصل شبیه باصل الاَّس البری الا أنه ألین منه و أعظم و هو طیب الرائحة و ینبت فی مواضع جبلیة و اذا أخذ من أصله مقدار ستة درخمیات و شرب بالطلاء نفع النساء اللواتی تعسر ولادتهن و من تقطیرالبول و من یبول دماً. جالینوس : فی السابعة. مزاجه حارّ حرارة ظاهرة قویة و ذلک ان من یذوقه یجده حاداحریف الطعم و فیه مرارة و من جربه وجده یدر الطمث و البول . دیسقوریدس : فی الرابعة. و أما النبات اذا دق ناعما و تضمد به سکن الصداع و التهاب المعدة و أذاشرب بالشراب سکن المغص و عصارته اذا شربت بالشراب سکنت الغمص و أدرت البول و الطمث و اذا احتملتها المراءة فی فزجة فعلت ذلک . جالینوس : فی السادسة. و اما النبات المسمی خاما ذاقنی فقضبانه توء کل مادامت طریة و قوتة شبیهة بقوةالنبات المسمی ذاقنی الاسکندرانی . عبداﷲبن صالح : الفرق بین ذاقنی الاسکندرانی و بین خاما ذاقنی ان الاول اعرض ورقا و ورقه مع طول القضبان . و خاما ذاقنی أضیق ورقا و قضبانه عاریة من الورق و سائر أوصافها واحدة و یسمیان بالاندلس بینب لی : البینب أوله باء بواحدة مفتوحة ثم یاء باثنتین من تحتها مضمومة ثم نون ساکنة بعدها باء بواحدة من أسفلها ساکنة و یدبغ بها الجلود بغربی بلاد اندلس (ابن البیطار) .<br /></font></div>'),
(130318, 'ذافنی ویداس', '<span class=\"hlight\">ذافنی ویداس .</span> (معرب، اِ) صاحب تحفه، حکیم مؤمن گوید: کلمه ای یونانی است و بمعنی شبیه الغار و قسمی از مازریون و عریض الورق است و به مغربی مازره و در شام بقله نامندساقش بقدر ذرعی و شاخهای او بسیار و باریک و از نصف اعلی میروید و پوست شاخهای قوی و لزج و گلش سفید و ثمرش بعد از رسیدن سیاه و دانه ٔ او کوچکتر از حب الغار و در آخر سیم گرم و خشک و حاد و مسهل بلغم و اخلاط غلیظه و مقیی ٔ و مدرّ حیض و محلل و مفتح و جالی جلد و رافع آثار و استعمال او شرباً جایز نیست و قدر شربتش از برگ تا سه قیراط و از ثمر تا پنج عدد و مقطع ومحرق خلط و مصلحش نشاسته و کتیرا و بدلش دو وزن او مازریون است . و رجوع به ذافنبداس و ذافنوبداس شود.<br /></font></div>'),
(130319, 'ذاقن', '<span class=\"hlight\">ذاقن .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) نعت فاعلی مذکر از ذقن . <BR><font color=\"Blue\">◄</font> (اِ) زیر زنخ . <BR><font color=\"Blue\">◄</font> کرانه ٔ حلقوم .<br /></font></div>'),
(130320, 'ذاقن', '<span class=\"hlight\">ذاقن .</span> <font color=\"DarkGreen\"><b>[ق ِ ]</font></b> (اِخ ) نام قریه ای است به حلب . (منتهی الارب ).<br /></font></div>'),
(130321, 'ذاقنة', '<span class=\"hlight\">ذاقنة.</span> <font color=\"DarkGreen\"><b>[ ق ِ ن َ ]</font></b> (ع ص ) نعت فاعلی مؤنث از ذقن . <BR><font color=\"Blue\">◄</font> (اِ) آنچه زیر زنخ است یا سر حلقوم یا تندی حلقوم یا چنبر گردن یا فرود شکم متصل ناف . یا چاه سینه یا بالای شکم . ج، ذواقِن .<br /></font></div>'),
(130322, 'ذاقنه', '<span class=\"hlight\">ذاقنه .</span> <font color=\"DarkGreen\"><b>[ ق ِ ن َ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130323, 'ذاقه', '<span class=\"hlight\">ذاقه .</span> (اِخ ) در مراصدالاطلاع چ طهران آمده است : موضع فی الشعر. لکن ظاهراً غلط از کاتب است و اصل آن همچنانکه در معجم البلدان مضبوط است ذاقنه است .<br /></font></div>'),
(130324, 'ذاقی', '<span class=\"hlight\">ذاقی .</span> (اِ) رجوع به ذافنی ... شود.<br /></font></div>'),
(130325, 'ذاقی اسکندری', '<span class=\"hlight\">ذاقی اسکندری .</span> <font color=\"DarkGreen\"><b>[ اِ ک َ دَ ]</font></b> (ع اِ مرکب ) رجوع به ذافنی شود.<br /></font></div>'),
(130326, 'ذاقی الاسکندرانی', '<span class=\"hlight\">ذاقی الاسکندرانی .</span> <font color=\"DarkGreen\"><b>[ قِل ْ اِ ک َ دَ ]</font></b> (ع اِ مرکب ) رجوع به ذافنی ... شود.<br /></font></div>'),
(130327, 'ذاقی الاسکندری', '<span class=\"hlight\">ذاقی الاسکندری .</span> <font color=\"DarkGreen\"><b>[ قِل ْ اِ ک َ دَ ]</font></b> (ع اِ مرکب ) رجوع به ذافنی شود.<br /></font></div>'),
(130328, 'ذال', '<span class=\"hlight\">ذال .</span> (ع اِ) خوج خروه . تاج خروس . خود خروه . عرف الدیک . و آن گوشتپاره ای سرخ است که بر سر خروس بود. فش خروس . (قاض یخان بدر محمد دهار).<br /></font></div>'),
(130329, 'ذال', '<span class=\"hlight\">ذال .</span> (اِ) نام حرف نهم از حروف تهجی عرب و یازدهم از حروف فارسی است میان دال و راء و صورت آن این است (ذ) یعنی دال با نقطه ٔ فوقانیة <span class=\"hlight\">:</span> <br />که دال نیز چو ذال است در کتابت لیک <br />بششصد و نود و شش کم است دال از ذال .<br /> <font color=\"Red\">انوری .</font><br />و ذویلة مصغر آن است .<br /></font></div>'),
(130330, 'ذال', '<span class=\"hlight\">ذال .</span> (ع مص ) سبک رفتن . (تاج المصادر بیهقی ). نرم رفتن . <BR><font color=\"Blue\">◄</font> شتاب رفتن .<br /></font></div>'),
(130331, 'ذالغ', '<span class=\"hlight\">ذالغ.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) مرد بدخنده <BR><font color=\"Blue\">◄</font> امری ذالغ؛ کاری بی فائده، امری مُتذلغ.<br /></font></div>'),
(130332, 'ذام', '<span class=\"hlight\">ذام .</span> (ع اِ) ذان . ذاب . ذین . ذیم . آهو. عیب .<br /></font></div>'),
(130333, 'ذام', '<span class=\"hlight\">ذام .</span> <font color=\"DarkGreen\"><b>[ ذام م ]</font></b> (ع ص ) عیب کننده . نکوهنده .<br /></font></div>'),
(130334, 'ذام والسام', '<span class=\"hlight\">ذام والسام .</span> <font color=\"DarkGreen\"><b>[ م ُ وَس ْ سا ]</font></b> (ع اِمرکب ) (الَ ...) از اتباع است . موت . مرگ، و در حدیث عایشة است که به یهود گفت : علیکم الذام و السام . والدام والسام نیز روایت شده است یعنی با دال مهملة.<br /></font></div>'),
(130335, 'ذاماسکینا', '<span class=\"hlight\">ذاماسکینا.</span> (معرب، اِ) اسم رومی اجاص است . ظاهراً این کلمه همان است که فرانسه ها داماس نامند و آن نوعی اعلا و خوب از آلوست . و شاید منسوب به دمشق .<br /></font></div>'),
(130336, 'ذامط', '<span class=\"hlight\">ذامط.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) نعت فاعلی از ذمط. گلوبرنده . ذابح .<br /></font></div>'),
(130337, 'ذامل', '<span class=\"hlight\">ذامل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع اِ) نامی از نامهای مردان عرب است .<br /></font></div>'),
(130338, 'ذاملة', '<span class=\"hlight\">ذاملة.</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b> (ع ص، اِ) شتر عیبناک . ج، ذَوامل .<br /></font></div>'),
(130339, 'ذامی', '<span class=\"hlight\">ذامی .</span> (ع ص، اِ) شکار به تیر افکنده . مُذماة.<br /></font></div>'),
(130340, 'ذان', '<span class=\"hlight\">ذان .</span> (پسوند) چنانکه دان مزید مؤخر بعض اسماء امکنه است چون ورذان و غیره .<br /></font></div>'),
(130341, 'ذان', '<span class=\"hlight\">ذان .</span> (ع اِ) عیب . ذاب . ذام . ذین . ذیم . آهو.<br /></font></div>'),
(130342, 'ذان', '<span class=\"hlight\">ذان .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع اِ) اسم اشاره ٔ قریب است . این دو مرد.<br /></font></div>'),
(130343, 'ذانب', '<span class=\"hlight\">ذانب .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) نعت فاعلی از ذنب . <BR><font color=\"Blue\">◄</font> سپس رو. پس کس رونده . پی رَو. تابع. تالی .<br /></font></div>'),
(130344, 'ذانک', '<span class=\"hlight\">ذانک .</span> <font color=\"DarkGreen\"><b>[ ن ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ْ ن ِ ک َ ]</font></b> (ع اِ) اسم اشاره ٔ بقریب . این دو مرد. ایشان دو مرد.<br /></font></div>'),
(130345, 'ذاهب', '<span class=\"hlight\">ذاهب .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) نعت فاعلی از ذهاب . رونده . برونده . شونده . بشونده . <BR><font color=\"Blue\">◄</font> درگذرنده . <BR><font color=\"Blue\">◄</font> طویل الذاهب، بسیاردراز. ج، ذاهبون . ذاهبین .<br /></font></div>'),
(130346, 'ذاهبات', '<span class=\"hlight\">ذاهبات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ ذاهبة <span class=\"hlight\">:</span> <br />رکبت مطیةً من قبل زید<br />علاهافی السنین الذاهبات .<br />ابوالحسن محمدبن عمر الانباری (از تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).<br /></font></div>'),
(130347, 'ذاهبة', '<span class=\"hlight\">ذاهبة.</span> <font color=\"DarkGreen\"><b>[ هَِ ب َ ]</font></b> (ع ص ) تأنیث ذاهب . ج، ذاهبات .<br /></font></div>'),
(130348, 'ذاهفة', '<span class=\"hlight\">ذاهفة.</span> <font color=\"DarkGreen\"><b>[ هَِ ف َ ]</font></b> (ع ص ) نعت فاعلی مؤنث از ذهف .اِبل ذاهفة؛ شتران بستوه آمده از بس رفتن . داهفة.<br /></font></div>'),
(130349, 'ذاهل', '<span class=\"hlight\">ذاهل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) نعت فاعلی از ذهول . غافل . بی پروا. فراموش کرده <span class=\"hlight\">:</span> و وقوع حوادث که در زمان متقدم بوده باشد غافل و ذاهل مانند. (جامع التواریخ رشیدی ).<br />یکزمان زین قبله گر ذاهل شوی <br />سخره ٔ هر قبله ٔ باطل شوی .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(130350, 'ذاوالاقیری', '<span class=\"hlight\">ذاوالاقیری .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ذاوالاکیری . یکی از قلل رفیعه ٔ کوه هیمالیا بشمال هند به مرکز نپال . ارتفاع آن <span class=\"hlight\" dir=\"rtl\">٨١٨١</span> گز. و این چهارمین قلّه ازقلل رفیعه ٔ هیمالایاست . <br /></font></div>'),
(130351, 'ذاوی', '<span class=\"hlight\">ذاوی .</span> (ع ص ) نعت فاعلی از ذوی . <BR><font color=\"Blue\">◄</font> پژمریده . پلاسیده، از بقول و مانند آن .<br /></font></div>'),
(130352, 'ذاک', '<span class=\"hlight\">ذاک .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (ع اِ) اسم اشاره ٔ به مذکر بعید است . آن .<br /></font></div>'),
(130353, 'ذاک', '<span class=\"hlight\">ذاک .</span> <font color=\"DarkGreen\"><b>[ کِن ْ ]</font></b> (ع ص ) نعت فاعلی از ذکو. ذاکی . مسک ٌ ذاک، مشکی تیزبوی . مشکی تندبوی .<br /></font></div>'),
(130354, 'ذاکر', '<span class=\"hlight\">ذاکر.</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) ابن محمد جاری . از مردم جار (قریه ای به اصفهان ) و بعضی ذاکربن عمربن سهل الزاهد گفته اند. او از ابومطیع الصحاف سماع دارد.<br /></font></div>'),
(130355, 'ذاکر', '<span class=\"hlight\">ذاکر.</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص ) نعت فاعلی از ذکر. یادکننده . بیان کننده . <BR><font color=\"Blue\">◄</font> شریف . <BR><font color=\"Blue\">◄</font> ثناگوی . ثناگوینده <span class=\"hlight\">:</span> <br />ذاکر فضل تو و مرتهن بِرّ تواند<br />چه طرازی به طراز و چه حجازی بحجاز.<br /> <font color=\"Red\">منوچهری .</font><br />آنکه چون جدّ و پدر در همه ٔ حال مدام <br />ذاکر و شاکر باشد به بَر رب ّ علیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی (از تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٨٩</span>).</font><br /><BR><font color=\"Blue\">◄</font> روضه خوان . ذاکر سیدالشهداء. ج، ذاکرون، ذاکرین .<br /></font></div>'),
(130356, 'ذاکیة', '<span class=\"hlight\">ذاکیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص )تأنیث ذاک . مسک ذاکیة؛ مشک تیزبوی . مشک تندبوی .<br /></font></div>'),
(130357, 'ذاکین', '<span class=\"hlight\">ذاکین .</span> (اِخ ) قریه ای بجنوب اناردرّه از اعمال فراء.<br /></font></div>'),
(130358, 'ذایع', '<span class=\"hlight\">ذایع.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b>(ع ص ) نعت فاعلی مذکر از ذیوع . آشکار. آشکارشده . فاش کرده . فاش شده . شایع. پیدا. ظاهر. مُنتشر. مستفیض .<br /></font></div>'),
(130359, 'ذایع شدن', '<span class=\"hlight\">ذایع شدن .</span> <font color=\"DarkGreen\"><b>[ ی ِ ش ُ دَ ]</font></b> (مص مرکب ) فاشی شدن . فُشُوّ. منتشر شدن .<br /></font></div>'),
(130360, 'ذایعات', '<span class=\"hlight\">ذایعات .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع اِ) خواجه در اساس الاقتباس ضمن صنف نهم از اصناف شانزده گانه ٔ مبادی قیاسات تحت عنوان مشهورات حقیقی مطلق گوید: و بباید دانست که نه هر مشهوری صادق بود، بل مقابل مشهور شنیع بود، و مقابل صادق کاذب، و صادق هر چند بحکم اغلب مشهور بود، امّا گاه بود که به سببی از اسباب چنانکه گفته شود مشهور نبود. و نقیضش مشهور بود و باشد که حکمی بقیدی خاص صادق بود، و بی آن قید مشهور. و مثال مشهور کاذب، قُبح ایذای غیر است بسبب منفعت خود، چه ذبح حیوان که نوعی از آن است بحسب عقل قبیح نیست . و این صنف را ذایعات نیز خوانند. (اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>).<br /></font></div>'),
(130361, 'ذایل', '<span class=\"hlight\">ذایل .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به ذائل شود.<br /></font></div>'),
(130362, 'ذایلة', '<span class=\"hlight\">ذایلة.</span> <font color=\"DarkGreen\"><b>[ ی ِ ل َ ]</font></b> (ع ص ) تأنیث ذایل .<br /></font></div>'),
(130363, 'ذب', '<span class=\"hlight\">ذب .</span> <font color=\"DarkGreen\"><b>[ ذَب ب ]</font></b> (ع مص ) دفع. دفع کردن . منعکردن . بازداشتن . دور کردن . ذب از کسی ؛ راندن و بازداشتن از او <span class=\"hlight\">:</span> اهل مصر در دفع و ذب ّ آن شناعت از حریم خویش به غوغا گرائیدند. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> درآمدن . <BR><font color=\"Blue\">◄</font> آمد و شد کردن ودر جائی قرار نگرفتن . متردّد بودن . <BR><font color=\"Blue\">◄</font> واراندن . (دهار) (تاج المصادر بیهقی ). واراندن و پژمریدن نبات . (تاج المصادر بیهقی ). پژمردن نبات . (دهار). <BR><font color=\"Blue\">◄</font> ذب ّ غدیر؛ خشک شدن غدیر در آخر گرما. <BR><font color=\"Blue\">◄</font> ذب ّ شفه ؛ هواسیدن، یعنی پژمریدن و خشک شدن و خوشیدن لب از تشنگی . <BR><font color=\"Blue\">◄</font> ذب ّ نبت ؛ پژمردن و پلاسیدن گیاه . ذب ّ جسم ؛ لاغر شدن تن . <BR><font color=\"Blue\">◄</font> ذب ّ نهار؛ اندکی باقی ماندن از روز. <BR><font color=\"Blue\">◄</font> ذب ّ لون ؛ بگردیدن و متغیر شدن گونه . <BR><font color=\"Blue\">◄</font> ذُب ّ فلان ؛ بصیغه ٔ مجهول، دیوانه شد او. <BR><font color=\"Blue\">◄</font> رنج کشیدن و مانده شدن در شب و نرسیدن به آب مگر پس از قطع یک شب راه . <BR><font color=\"Blue\">◄</font> ذب از کسی ؛ مدافَعَة. منافَحة. محاماة. مراماة. (تاج المصادر بیهقی ).<br /></font></div>'),
(130364, 'ذب', '<span class=\"hlight\">ذب .</span> <font color=\"DarkGreen\"><b>[ ذَب ب ]</font></b> (ع اِ) گاو دشتی و آن را ذب ّالریاد نیز نامند، از آن روی که پیوسته در پی گاوان ماده رود. و منه رجل ٌ ذب ّالرّیاد؛ مرد بسیارزیارت کننده ٔ زنان و آمد و شد کننده با آنان . و گاو کوهی .<br /></font></div>'),
(130365, 'ذب', '<span class=\"hlight\">ذب .</span> <font color=\"DarkGreen\"><b>[ ذُب ب ]</font></b> (ع اِ) ج ِ ذُباب .<br /></font></div>'),
(130366, 'ذب الریاد', '<span class=\"hlight\">ذب الریاد.</span> <font color=\"DarkGreen\"><b>[ ذَب ْ بُرْ ری ]</font></b> (ع اِ مرکب ) کل . ذَب ّ. گاو دشتی . <BR><font color=\"Blue\">◄</font> مردی که با زنان بسیار مراوده و آمد و شد کند.<br /></font></div>'),
(130367, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) کوهی است به مدینة الرسول . (مراصد الاطلاع ). و نام او در کتب مغازی مکرر آمده است .و ربنجنی در مهذب الاسماء گوید، کوهی است به مکّه .<br /></font></div>'),
(130368, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِخ ) نامی است از نامهای مردان عرب .<br /></font></div>'),
(130369, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) مگس . (دهار) (منتهی الارب ) (زمخشری ) (غیاث ) (مهذب الاسماء) <span class=\"hlight\">:</span> <br />نیستم چون ذباب شوخ چرا<br />دلم از ضعف شد چو پرّ ذباب .<br /> <font color=\"Red\">مسعودسعد.</font><br />مرا از این تن رنجور و دیده ٔ بیخواب <br />جهان چو پر غراب است و دل چو پرّ ذباب .<br /> <font color=\"Red\">مسعودسعد.</font><br />سایه بر دریای چین چون افکند پر ذباب .<br /> <font color=\"Red\">معزّی .</font><br />ذباب وار به هر در نرفتم و نروم <br />وگر روم ز در تو منافقم چو ذباب .<br /> <font color=\"Red\">سوزنی .</font><br />چو مرغ زیرک مانده به هر دو پا دربند<br />کنون دو دست بسر بر همی زنم چو ذباب .<br /> <font color=\"Red\">جمال الدین عبدالرزاق .</font><br />بطبل نافه ٔ مستسقیان بخورد جراد<br />بباد روده ٔ قولنجیان به پشک ذباب .<br /> <font color=\"Red\">خاقانی .</font><br />بناب موش کز او سر فکنده ام چون چنگ <br />بچنگ گربه کزو دست بر سرم چو ذباب .<br /> <font color=\"Red\">خاقانی .</font><br />چون اجل در دامن عمرت زند ناگاه چنگ <br />تو ز چنگ او بمانی دست بر سر چون ذباب .<br /> <font color=\"Red\">عطار.</font><br />فکر زنبور است و آن خواب تو آب <br />چون شدی بیدار باز آید ذباب .<br /> <font color=\"Red\">مولوی .</font><br />عنکبوت دیو بر تو چون ذباب <br />کرو فر دارد نه بر کبک و عقاب .<br /> <font color=\"Red\">مولوی .</font><br />لاف و دعوی باشد این پیش غراب <br />دیگ تی و پُر یکی نزد ذباب .<br /> <font color=\"Red\">مولوی .</font><br />حکیم مؤمن در تحفه گوید: ذباب : به فارسی مگس نامند و تکوّن اواز فضلات و اوّل کرم سفیدی است و کمتر از یک هفته پربهم میرساند و از کافور و زرنیخ و روغن زیتون میگریزد و گویند چون صورت مگسی از کندش و زرنیخ ساخته در محلی بگذارند منع آن مینماید. در اوّل گرم و تر و بهترین او سیاه و بعد از آن ازرق است و زرد او خالی ازسمیت نیست . محلّل و جاذب ضماد او محلّل اورام و رافع گوشت زیاده ٔ جراحات و مانع انتثار موی و داءالثعلب و حکه و قوبا و چون سر او را انداخته بر موضع گزیده ٔ زنبور بمالند رافع الم آن و جاذب سم ّ است و تکرار ضماد او جهت داءالثعلب مجرّب و جهت تحلیل ورم چشم و رفع گوشت زیاده ٔ پلک و شعیره ٔ آن آزموده و نفوخ سوخته ٔ او در مجرای بول جهت رفع احتباس بول مؤثر و آشامیدن او را با شراب جهت عسر ولادت مجرّب دانسته اند و محمدبن احمد گوید که خوردن پخته و خام او را هنود جهت تقویت باصره و منع جمیع آفات چشم مجرّب میدانند و سرگین مگس را چون با آب و عسل بنوشند جهت ازاله ٔ مغص و قولنج و خناق مجرّب یافته اند و چون چند روز بخورندو در آفتاب بنشینند محل ّ برص پوست انداخته زایل میگردد و بهتر از اطریلال است و روغن او که مکرّر مگس رادر روغن کنجد کرده در آفتاب گذاشته صافی کرده باشندجهت رویانیدن موی مجرّب است . و صاحب اختیارات گوید:ابن زهر در خواص آورده است که مگس الوان بود و هر حیوانی را مگس معین بود از شتر و گاو و شیر و سگ و امثال آن و اصل آن کرمی بود و مگس آدمیان از سرگین حاصل میشود و اصل ایشان کرمی کوچک بود که از بدنهای ایشان بیرون آید از هر حیوانی که باشد و آن کرم باز مگس شود و زنبور. همو گوید چون بگیرند مگس بزرگ و سر اوبیندازند و ببدن وی شعیره ای که در مژه باشد حل کنندحلی سخت زایل گرداند و اگر مگس بگیرند و با زرده ٔ تخم مرغ سحق کنند نیک، و ضماد کنند در چشم که گوشت سرخ در اندرون وی چسبیده باشد و به یونانی کرماسیس خوانند در ساعت ساکن گرداند و اگر حل کنند و بر داءالثعلب مالند حلی سخت داءالثعلب را زایل گرداند و اگر برگزیدگی زنبور بمالند سخت، درد ساکن گرداند و دیسقوریدوس گوید: بر گزیدگی عقرب و زنبور و نحل چون بمالند سخت، چند نوبت بر موضع گزیدگی بغایت نافع بود این بخاصیت است و چون ویرا بسوزانند و با عسل بداءالثعلب وداءالحیه طلا کنند موی برویاند و خاکستر وی سرد و خشک بود - انتهی . و در بعض کتب آمده است : ذباب به پارسی مگس . چون بر گزیدگی زنبور مالند سودمند آید و چون سرگینش را به قره قورت و شکر سرخ ساخته بردارند طبیعت را بیارد. و ابن البیطار گوید: ذباب . خواص ابن زهر.قال هو ألوان فللابل ذباب و للبقر ذباب و للاسد ذباب و أصله دود صغار یخرج من ابدانهم و ما یخرج من أبدان غیرذالک یتحول ذبابا و زنابیر و ذباب الناس یتولدمن الزبل قال و ان أخذ الذباب الکبیر فقطعت رؤسه و یحک بجسدها علی الشعیرة التی تکون فی الاجفان حکا شدیدا فانه یبرئه و ان اخذ الذباب و سحق بصفرةالبیض سحقا ناعما و ضمدت به العین التی فیها اللحم الاحمر من داخل الملتصق بها الذی یسمی کر ماشیش فانه یسکن من ساعته و ان مسحت لسعةالزنبور بذباب سکن وجعه و ان حک الذباب علی موضع داءالثعلب حکا شدیدا، فانه یبرئه - انتهی . <BR><font color=\"Blue\">◄</font> زنبور عسل . نحل . ج اَذِبّة. ذِبّان . (منتهی الارب ). زمخشری . ذُب ّ. <BR><font color=\"Blue\">◄</font> دیوانگی . <BR><font color=\"Blue\">◄</font> بدی . <BR><font color=\"Blue\">◄</font> بدی پیوسته با بدی . <BR><font color=\"Blue\">◄</font> بدفالی . <BR><font color=\"Blue\">◄</font> شوم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هزارچشمه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب الاذن </span> ؛ تیزی طرف گوش . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب الاسنان </span> ؛ تیزی دندانها. (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب الحنّاء</span> ؛ اوّل شکوفه ٔ وی . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب السیف </span> ؛ دم شمشیر. تیزی شمشیر یا کرانه ٔ آن که باریک و هر دو طرف تیز باشد. (منتهی الارب ). تیزنای شمشیر. (مهذب الاسماء). کنار شمشیر <span class=\"hlight\">:</span> و سلاطین روزگار در دست شیاطین تاتار گرفتار گشتند و اعیان و اکثر حشم طعمه ٔ ذباب شمشیر آبدار و لقمه ٔ ذآب و کفتار شدند. (جهانگشای جوینی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب العین </span> ؛ نقطه ٔ سیاه میان حدقه . مردمک چشم . (مهذب الاسماء). انسان العین . مردم چشم . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذباب الفرس </span> ؛ مردم چشم اسب . نقطه ٔ سیاه درون حدقه ٔ اسب .<br /></font></div>'),
(130370, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذبابَة.<br /></font></div>'),
(130371, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذَب ْ با ]</font></b> (ع ص ) بسیار دفعکننده از حریم خود.<br /></font></div>'),
(130372, 'ذباب', '<span class=\"hlight\">ذباب .</span><font color=\"DarkGreen\"><b>[ ذَب ْ با ]</font></b> (اِخ ) نامی است از نامهای مردان عرب .<br /></font></div>'),
(130373, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِخ ) ذبابه ٔ هندیة. رجوع به ذبابه ٔ هندیه شود .<br /></font></div>'),
(130374, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ذَب ْ با ]</font></b> (ع اِ) سوسنبر بستانی .<br /></font></div>'),
(130375, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن الحارث . صحابی است . از قبیله ٔ انس اﷲبن سعد العشیرة. وی معبود قبیله ٔ خویش موسوم به قراض را بشکست و نزد رسول اکرم صلوات اﷲ علیه شد و مسلمانی گرفت . و او شاعر بود و این دو بیت او راست :<br />تبعت رسول اﷲ اذ جاء بالهدی <br />و خلفت قراضاً بدار هوان <br />شددت علیه شدة فکسر ته <br />کان لم یکن والدهر ذوحدثان .<br /></font></div>'),
(130376, 'ذباب', '<span class=\"hlight\">ذباب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن محمد. مکنی به ابی العباس مدینی . محدث است .<br /></font></div>'),
(130377, 'ذباب الاذن', '<span class=\"hlight\">ذباب الاذن .</span> <font color=\"DarkGreen\"><b>[ ذُ بُل ْ اُ ذُ ]</font></b> (ع اِ مرکب ) تیزی طرف گوش .<br /></font></div>'),
(130378, 'ذباب الاسنان', '<span class=\"hlight\">ذباب الاسنان .</span> <font color=\"DarkGreen\"><b>[ ذُ بُل ْ اَ ]</font></b> (ع اِ مرکب ) تیزی دندانها.<br /></font></div>'),
(130379, 'ذباب السیف', '<span class=\"hlight\">ذباب السیف .</span> <font color=\"DarkGreen\"><b>[ ذُ بُس ْ س َ ]</font></b> (ع اِ مرکب ) تیزنای شمشیر.<br /></font></div>'),
(130380, 'ذباب العین', '<span class=\"hlight\">ذباب العین .</span> <font color=\"DarkGreen\"><b>[ ذُ بُل ْ ع َ ]</font></b> (ع اِ مرکب ) مردم چشم . مردمک چشم . (مهذب الاسماء) (منتهی الارب ) (دهار).<br /></font></div>'),
(130381, 'ذباب الفرس', '<span class=\"hlight\">ذباب الفرس .</span> <font color=\"DarkGreen\"><b>[ ذُ بُل ْ ف َ رَ ]</font></b> (ع اِمرکب ) نقطه ٔ سیاه درون حدقه ٔ اسب . مردمک چشم اسب .<br /></font></div>'),
(130382, 'ذبابة', '<span class=\"hlight\">ذبابة.</span> <font color=\"DarkGreen\"><b>[ ذُ ب َ ]</font></b> (ع اِ) یکی ذباب . یک مگس . <BR><font color=\"Blue\">◄</font> یک زنبور عسل . ج، ذباب . (دهار). <BR><font color=\"Blue\">◄</font> بقیه ٔ وام و جز آن .<br /></font></div>'),
(130383, 'ذبابة', '<span class=\"hlight\">ذبابة.</span> <font color=\"DarkGreen\"><b>[ ذَب ْ با ب َ ]</font></b> (ع ص ) خوشیده . هواسیده . پژمریده . پژمرده . پلاسیده : شفةٌ ذبّابة؛ لبی پژمریده . لبی خوشیده .<br /></font></div>'),
(130384, 'ذبابة', '<span class=\"hlight\">ذبابة.</span> <font color=\"DarkGreen\"><b>[ ذُ ب َ ]</font></b> (اِخ ) نام موضعی است به عدَن ابین . <BR><font color=\"Blue\">◄</font> نام محلی است به اجاء.<br /></font></div>'),
(130385, 'ذبابی', '<span class=\"hlight\">ذبابی .</span> <font color=\"DarkGreen\"><b>[ ذُ بی ی ]</font></b> (ع ص نسبی ) منسوب به ذُباب . ذبابی، یا زمرد ذبابی ّ؛ زمردی باشد سبز و آبدار و شفّاف و در غایت طراوت و خوشرنگی بی آنکه مایل برنگی دیگر بود. شبیه به رنگ مگس سبز که گاهگاه در میان گیاهان بود. (از جواهرنامه ).<br /></font></div>'),
(130386, 'ذبابی', '<span class=\"hlight\">ذبابی .</span> <font color=\"DarkGreen\"><b>[ ذُ بی ی ]</font></b> (ع اِ) برآمدگی و نُتُوّ طبقه ٔ عنکبوتیه (در چشم ) از جراحت و جز آن .<br /></font></div>'),
(130387, 'ذباح', '<span class=\"hlight\">ذباح .</span> <font color=\"DarkGreen\"><b>[ ذُ <span class=\"hlight\" dir=\"rtl\">/</span> ذِ <span class=\"hlight\" dir=\"rtl\">/</span> ذُب ْ با ]</font></b> (ع اِ) گیاهی است زهردار. <BR><font color=\"Blue\">◄</font> آزاری است در حلق . درد گلو. ذبحة، و آن بیماریی است صعب در گلو و حلق . درد گلو یا خون است که خناق پیدا کند پس میکشد، یا ریشی است که در حلق برآید و در مثل است : رب ّ مطعمة تکون ذباحاً. <BR><font color=\"Blue\">◄</font> شکاف سر انگشتان . (دهار). <BR><font color=\"Blue\">◄</font> داغ که بر حلق اشتر نهند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> موت ذباح ؛ موت سریع. موت زؤآل . موت زُؤاف .<br /></font></div>'),
(130388, 'ذباح', '<span class=\"hlight\">ذباح .</span> <font color=\"DarkGreen\"><b>[ ذُب ْ با ]</font></b> (ع اِ) کفتگی های باطن انگشتان پای .<br /></font></div>'),
(130389, 'ذباح', '<span class=\"hlight\">ذباح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذَبح، در تمام معانی . <BR><font color=\"Blue\">◄</font> شکافتن . پاره کردن . <BR><font color=\"Blue\">◄</font> گلو بریدن . <BR><font color=\"Blue\">◄</font> خبه کردن و هلاک ساختن . <BR><font color=\"Blue\">◄</font> ذباح دَن ؛ سوراخ کردن خم . <BR><font color=\"Blue\">◄</font> ذبحت اللحیة فلاناً؛ دراز گشت و فروهشت لحیه زیر زنخ وی و پیدا آمد پتفوزآن . ذبح الخمر الملح و الشمس و النینان ای طهرها و اباح استعمالها. و نینان، جمع نون بمعنی ماهی است .<br /></font></div>'),
(130390, 'ذباح', '<span class=\"hlight\">ذباح .</span> <font color=\"DarkGreen\"><b>[ ذَب ْ با ]</font></b> (ع ص ) گوسپندکش . (مهذب الاسماء). سلاّخ .<br /></font></div>'),
(130391, 'ذباحة', '<span class=\"hlight\">ذباحة.</span> <font color=\"DarkGreen\"><b>[ ذَ ح َ ]</font></b> (ع مص ) ذَباح . ذَبح . گلو بریدن . سر بریدن . کشتن . بسمل کردن . <BR><font color=\"Blue\">◄</font> در فقه، حیوانی حلال گوشت را بدستور شرع کشتن و در آن شرط است آلت قطع از آهن بودن و مری و حلقوم و اوداج بریده شدن . <BR><font color=\"Blue\">◄</font> کتاب صید و ذباحة، کتابی ازکتب فقه که در آن از قوانین صید و ذباحة بحث کند.<br /></font></div>'),
(130392, 'ذباذب', '<span class=\"hlight\">ذباذب .</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ]</font></b> (ع اِ) نره . شرم مرد. و آن مفردی است بصورت جمع. <BR><font color=\"Blue\">◄</font> ج ِ ذَبذَبة. <BR><font color=\"Blue\">◄</font> ذباذِب ُ الذّنب، شراشر ذنب ؛ یعنی اطراف دنب .<br /></font></div>'),
(130393, 'ذبار', '<span class=\"hlight\">ذبار.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ج ِ ذَبر.<br /></font></div>'),
(130394, 'ذبارت', '<span class=\"hlight\">ذبارت .</span> <font color=\"DarkGreen\"><b>[ ذِ رَ ]</font></b> (ع مص ) ذبارَة. نیکو نگریستن . <BR><font color=\"Blue\">◄</font> خشمناکی . خشمناک شدن . <BR><font color=\"Blue\">◄</font> محکم کردن . <BR><font color=\"Blue\">◄</font> نیکو یاد گرفتن . <BR><font color=\"Blue\">◄</font> روان خواندن . <BR><font color=\"Blue\">◄</font> ذبارت خبر؛ دریافتن آن .<br /></font></div>'),
(130395, 'ذبال', '<span class=\"hlight\">ذبال .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذُبالة. (دهار) <span class=\"hlight\">:</span> <br />عقل گردی، عقل را دانی کمال <br />عشق گردی، عشق را دانی ذبال .<br /> <font color=\"Red\">مولوی .</font><br />با حضور آفتاب با کمال <br />رهنمایی جستن از شمع و ذبال .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> ریشها که بر پهلو برآید و بجانب شکم سوراخ کند.<br /></font></div>'),
(130396, 'ذبالة', '<span class=\"hlight\">ذبالة.</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ ]</font></b> (ع اِ) پلیته . (دهار) (منتهی الارب ). فتیله . فلیته . ذُبّاله َ. پلیته ٔ افروخته . ج، ذبال . (مهذب الاسماء). ذَبائل <span class=\"hlight\">:</span> <br />این همی گفت و ذباله ٔ نور پاک <br />از لبش میشد پیاپی بر سماک .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(130397, 'ذبالة', '<span class=\"hlight\">ذبالة.</span> <font color=\"DarkGreen\"><b>[ ذُب ْ با ل َ ]</font></b> (ع اِ) پلیته . فلیته . فتیله .<br /></font></div>'),
(130398, 'ذباله', '<span class=\"hlight\">ذباله .</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ذَب ْ با ل َ ]</font></b> (ع اِ) .<br /></font></div>'),
(130399, 'ذبان', '<span class=\"hlight\">ذبان .</span> <font color=\"DarkGreen\"><b>[ ذِب ْ با ]</font></b> (ع اِ) ج ِ ذباب . (زمخشری ).<br /></font></div>'),
(130400, 'ذبایح', '<span class=\"hlight\">ذبایح .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع اِ) ذبیحة. (دهار). <BR><font color=\"Blue\">◄</font> ذبایح ِ جن ؛ ذبیحه ها که عرب گاه ساختن خانه یا حفرچاهی میکردند تا بنا یا چاه از ضرر جن ایمن ماند.<br /></font></div>'),
(130401, 'ذبب', '<span class=\"hlight\">ذبب .</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ع مص ) ذَب ّ. ذبوب . ذَبب ِ شفه ؛ هواسیدن و خوشیدن و پژمریدن لب از تشنگی و جز آن . <BR><font color=\"Blue\">◄</font> ذبب جسم ؛ لاغر شدن تن . <BR><font color=\"Blue\">◄</font> ذبب نبت ؛ پژمریدن گیاه . پلاسیدن سبزه . <BR><font color=\"Blue\">◄</font> ذبب نهار؛ اندک باقی ماندن از روز. <BR><font color=\"Blue\">◄</font> ذبب لون ؛ بگردیدن گونه . متغیر شدن رنگ .<br /></font></div>'),
(130402, 'ذبح', '<span class=\"hlight\">ذبح .</span> <font color=\"DarkGreen\"><b>[ ذُ ب َ ]</font></b> (ع اِ) گزر دشتی . زردک صحرائی . جزر برّی . حویج وحشی . <BR><font color=\"Blue\">◄</font> نوعی سماروغ . <BR><font color=\"Blue\">◄</font> گیاهی است خورش نعامه یعنی خوراک اشترمرغ . نباتی است سرخ . (مهذب الاسماء). نباتی است شیرین و خوراکی و آن را گلی سرخ است .<br /></font></div>'),
(130403, 'ذبح', '<span class=\"hlight\">ذبح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذمط. ذَباح . سر بریدن گاو و گوسفند و مانند آنها. سر بریدن . گلو بریدن . گلو وابریدن . (تاج المصادر بیهقی ) (دهار). بسمل کردن . کشتن . نحر. تذکیة.شکستن . هبهبه . <BR><font color=\"Blue\">◄</font> خبه کردن . خَفه کردن . خَوَه کردن . خنق . <BR><font color=\"Blue\">◄</font> پاره کردن . فتق . شق . شکافتن . (زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> هلاک کردن . <BR><font color=\"Blue\">◄</font> ذبح دَن ّ؛ سوراخ کردن خم، بزل آن . ثقب . <BR><font color=\"Blue\">◄</font> گشودن . <BR><font color=\"Blue\">◄</font> ذبح خمر؛ مباح و حلال و طاهر کردن شراب : ذبح الخمر الملح و الشمس و النینان . یعنی این سه چیز شراب را استحاله و حلال سازد. و در فارسی با شدن و کردن صرف شود: ذبح کردن گوسفند از قفا. قفن .<br /></font></div>'),
(130404, 'ذبح', '<span class=\"hlight\">ذبح .</span> <font color=\"DarkGreen\"><b>[ ذِ ب َ ]</font></b> (ع اِ) نوعی از سماروغ . قسمی از کماة.<br /></font></div>'),
(130405, 'ذبح', '<span class=\"hlight\">ذبح .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) زهر.<br /></font></div>'),
(130406, 'ذبح', '<span class=\"hlight\">ذبح .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص، اِ) مذبوح . سربریده . <BR><font color=\"Blue\">◄</font> گوسفندی کشتنی . (مهذب الاسماء). آنچه ذبح کرده شود. چارپائی که ذبح کرده شود. خونریز. کشتار <span class=\"hlight\">:</span> و فدیناه بذبح عظیم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٧/٣٧</span>). من کان له ذبح ٌ.. حدیث . <BR><font color=\"Blue\">◄</font> قتیل . ذبح اکبر و ذبیح اکبر، گوسفند که بفدیة اسماعیل بن ابراهیم از بهشت آمد. <BR><font color=\"Blue\">◄</font> قربانی عید اضحی .<br /></font></div>'),
(130407, 'ذبحان', '<span class=\"hlight\">ذبحان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِخ ) شهری است به یمن .<br /></font></div>'),
(130408, 'ذبحان', '<span class=\"hlight\">ذبحان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) نامی از نامهای مردان عرب، از جمله نام جدّ والِد عبیدبن عمرو صحابی .<br /></font></div>'),
(130409, 'ذبحان', '<span class=\"hlight\">ذبحان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِخ ) بطنی است از رعین .<br /></font></div>'),
(130410, 'ذبحانی', '<span class=\"hlight\">ذبحانی .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b>(ص نسبی ) منسوب به ذبحان بطنی از رعین . (سمعانی ).<br /></font></div>'),
(130411, 'ذبحة', '<span class=\"hlight\">ذبحة.</span> <font color=\"DarkGreen\"><b>[ ذُ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ ب ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span>ذُ ب َ ح َ ]</font></b> (ع اِ) درد گلو. (دهار) (مهذب الاسماء) (زمخشری ). ورمی باشد به هر دو جانب حلقوم . (غیاث ). دردگلو یا خونی است که خناق آرد پس بکشد یا ریشی است که در حلق پدید آید. (منتهی الارب ). دردی است که در گلو از بسیاری خون پیدا میشود و بدترین خناقهاست . و صاحب کشاف اصطلاحات الفنون گوید: ذبحة. بضم ذال معجمه وفتح باء موحدّه که عامه بجای فتح سکون آن را اختیارکرده اند، ورمی است حار که در عضلات جانب حلقوم ایجادمیشود مخصوصاً در مجرای بلع. علامه گوید: و گاه این لفظ درباره ٔ اختناق اطلاق شود. و شیخ بین آنها فرق ننهاده . برخی دیگر این لغت را در مورد ورم لوذتین استعمال کرده اند چنانچه در بحر الجواهر بیان کرده است .<br /></font></div>'),
(130412, 'ذبحة', '<span class=\"hlight\">ذبحة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن عمرو در عقدالفرید چ محمدسعید العریان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> ذیل شرح قبائل طابخةبن الیاس بطون ضبه و جماهیرها مینویسد: و از آنهاست عبدمناف ... و بنوثعلبه .... و بنی کوز و بنی زهیر و میگوید از بنی زهیر است عمروبن مالک بن زیدبن کعب و او سیدی مطاع بود و از فرزندان اوست عبدالحرث و حصین و عمرو و ادهم و ذبحة و...<br /></font></div>'),
(130413, 'ذبذب', '<span class=\"hlight\">ذبذب .</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ]</font></b> (ع اِ) شرم مرد. ذبذبة. نره . عورت مرد. فرج و ذکر. (دهار). <BR><font color=\"Blue\">◄</font> دفع. نگاهداشت .<br /></font></div>'),
(130414, 'ذبذب', '<span class=\"hlight\">ذبذب .</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ]</font></b> (اِخ ) چاهی است به موضعی مسمی به مطلوب از دیار ابی بکربن کلاب .<br /></font></div>'),
(130415, 'ذبذبة', '<span class=\"hlight\">ذبذبة.</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ب َ]</font></b> (ع مص ) تَرَدّد. دودلی . دودلی کردن . تذَبذُب . <BR><font color=\"Blue\">◄</font> دودل کردن کسی را در کاری . <BR><font color=\"Blue\">◄</font> جنبیدن چیزی که آویخته باشد در هوا. ناویدن چیزی درواو آونگان یعنی جنبیدن آن . <BR><font color=\"Blue\">◄</font> جنبش . تحرک . <BR><font color=\"Blue\">◄</font> حمایت همسایه و اهل . <BR><font color=\"Blue\">◄</font> رنجانیدن کسان را. <BR><font color=\"Blue\">◄</font> جنبانیدن . حرکت دادن .<br /></font></div>'),
(130416, 'ذبذبة', '<span class=\"hlight\">ذبذبة.</span> <font color=\"DarkGreen\"><b>[ذَ ذَ ب َ ]</font></b> (ع اِ) نرّه . شرم مرد. ذبذَب . <BR><font color=\"Blue\">◄</font> زبان . <BR><font color=\"Blue\">◄</font> خانه . <BR><font color=\"Blue\">◄</font> چیزی که به هودج آویزند زینت را. منگوله ٔ هودج . ج، ذباذِب .<br /></font></div>'),
(130417, 'ذبذک', '<span class=\"hlight\">ذبذک .</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ]</font></b> (اِخ ) نامی از نامهای مردان ایرانی . و از جمله ٔ جدّ جعفربن احمدبن ذبذک رازی، مُحدث .<br /></font></div>'),
(130418, 'ذبر', '<span class=\"hlight\">ذبر.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) نبشته . نوشته . کتاب . نامه . ج، ذبور.<br /></font></div>'),
(130419, 'ذبر', '<span class=\"hlight\">ذبر.</span> <font color=\"DarkGreen\"><b>[ ذَ ب ِ ]</font></b> (ع ص ) کتابی ذبر؛ کتابی که به آسانی خوانده شود. خوانا. سهل القرائة. مقروّ.<br /></font></div>'),
(130420, 'ذبر', '<span class=\"hlight\">ذبر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) نبشتن . نوشتن . کتابت . <BR><font color=\"Blue\">◄</font> خجک زدن بر نوشته . نقطه نهادن بر کلمات . تنقیط. نقطه کردن بر کتابت . خجک کردن حروف را . <BR><font color=\"Blue\">◄</font> آهسته خواندن . با شتاب خواندن . زود خواندن . <BR><font color=\"Blue\">◄</font> دانست ِ چیزی . دانستن .<br /></font></div>'),
(130421, 'ذبر', '<span class=\"hlight\">ذبر.</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ع مص ) خشم گرفتن . خشمناک شدن .<br /></font></div>'),
(130422, 'ذبر', '<span class=\"hlight\">ذبر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) نامه . صحیفه . کتاب . <BR><font color=\"Blue\">◄</font> کتاب، به لغت حمیر و نامه که بر شاخ خرما که برگ برنیاورده باشد نویسند. ج، ذبار. <BR><font color=\"Blue\">◄</font> سخن . زبان . نطق . <BR><font color=\"Blue\">◄</font> کوه . (به لغت حبشه ) ج، ذِبار.<br /></font></div>'),
(130423, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام کوهی است .<br /></font></div>'),
(130424, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذُ ب ُ ]</font></b> (ع ص، اِ) ج ِ ذابل .<br /></font></div>'),
(130425, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذُب ْ ب َ ]</font></b> (ع ص، اِ) ج ِ ذابل .<br /></font></div>'),
(130426, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) پژمرده شدن . (تاج المصادر بیهقی ) (زوزنی ). پژمردن . پژمریدن . ذبول . پژمریدن نبات . <BR><font color=\"Blue\">◄</font> خوشیده پوست شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باریک میان شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> لاغر شدن اسب . لاغر و باریک شدن اسب . (منتهی الارب ). خشک پوست گردیدن و باریک گردیدن اسب . <BR><font color=\"Blue\">◄</font> پشک افکندن شتر.<br /></font></div>'),
(130427, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) بی فرزندی زن . (آنندراج ) (منتهی الارب ). ذِبل ٌ ذبیل ؛ ای ثکل ثاکل مبالغه است .<br /></font></div>'),
(130428, 'ذبل', '<span class=\"hlight\">ذبل .</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ع اِ) پوست باخه ٔ دریائی یا برّی یا گوش ماهی یا استخوان پشت دابه ٔ دریائی که از آن دست برنجن و شانه ها سازند و خاصیتش آن است که شانه کردن با آن رشگ (یعنی ) بیضه ٔ شبش و سبوسه ٔ سر را زایل گرداند. (منتهی الارب ). و در لغت نامه های مترجم معنی و تفسیر آن به اشکال ذیل آمده است : پوست تمساح . استخوان پشت جانوری آبی که از آن زیور سازند. پوست باخه ٔ دریائی . گوش ماهی . پوست کشف . استخوان ماهی که از آن دست برنجن و شانه سازند. چیزی است چون عاج و آن کاسه ٔ سنگ پشت دریائی است که دست برنجن از آن کنند. پوست سلحفاة بحری یا برّی یا استخوانهای حیوانی بحری که از آن شانه و دست آورنجن کنند. سنگ پشت دریائی و آن چیزی است مانند عاج و آن را باخه و گوش ماهی نیز گویند. کشف که از آن انگشتری سازند. مهذب الاسماء و داود ضریر انطاکی در تذکره گوید: ذَبَل، استخوان سلحفات هندیه باشد نه پوست آن چنانکه بعضی گمان برده اند. و آن بسیار سیاه بود و نوعی از آن به زردی زند. و بهترین ذبل آن است که محکم و سخت براق باشد. و آن خشک است در درجه ٔ دویم . و چون آن را سائیده و بیاشامند بواسیر سست کند و بریزاند و همچنین ضماد آن چون بر آماسها و سرطانات و خنازیر طلی کنند محلل بود. و شرب آن با انگبین ریشها و خستگیهای قصبه را ملتحم کندو نفث الدم و تب ربع را قطع کند. و بخور آن با پاره ٔچوب داری که آدمی را بر آن آویخته باشند یا با مقدارخاک گور کشته برای منع سحر و فتنه مجرب است و نیز دشمنانگی میان دو خصم را بدوستی و آشتی آرد. و از خواص آن آن است که شانه ٔ آن شپش و ریزش موی را منع کند.و چون زن از آن انگشتری کند مانع اسقاط جنین بود و ولادت را آسان کند و ضماد آن از جا دررفتگی استخوان وبروز مقعده (بیرون آمدن نشیمن ) را سود بخشد و فرزجه ٔ آن را چون زن برگیرد منع سیلان رطوبات کند. و آن مضر کبد است و مصلح آن سیب است . و مقدار شربت آن تا نیم درهم باشد و بدل آن استخوان خارپشت است - انتهی .<br />در ترجمه ٔ صیدنه ٔابوریحان بیرونی آمده است : ثعلب از ابن الاعرابی روایت کند که عرب پشت سلحفاة بحری را ذبل گوید و از او دست بندها سازند و زنان در دست کنند و ابن سمبل گوید که ذبل شاخ حیوانی را گویند که از او دست بندها سازند ودر این معنی شعر جریر را آورده در صفت زنی <span class=\"hlight\">:</span> <br />تری العبس الحولی جونا بکوعها<br />لها مسلکا من غیر جاع و لا ذبل .<br />و به هندی او را کجو گویند و به رومی سیلویان گویند - انتهی .<br />ودر اختیارات بدیعی آمده است : ذبل، جلد سلحفات هندی بود و گویند بحری . چون بسوزانند و خاکستر وی به سپیده ٔ تخم مرغ بسرشند و طلی کنند بر شقاق کعبین و انگشتان نافع بود و جهة شقاق که زنان را در نزدیک حیض آمدن پیدا شود بغایت نافع بود - انتهی . و حکیم مؤمن درتحفه گوید: ذبل پوست سنگ پشت هندی است و گویند استخوان اوست . بغایت سیاه و بعضی اجزاء او مایل به زردی وبراق و صلب . در دوّم سرد و خشک و جالی و بغایت قابض و شرب محکوک او مسقط بواسیر و با عسل جهت التحام قرحه ٔ قصبه ٔ ریه و نفث الدم و تب ربع و ضماد او جهت اورام و سرطان و خنازیر و اسقاط بواسیر و طلای سوخته ٔ اوبا سفیدی تخم مرغ جهت شقاق کعب و شق رحم که از ولادت بهم رسد و شقاق مقعد و خروج آن نافع و فرزجه ٔ او مانع سیلان رحم و اسقاط جنین و تسهیل ولادت مفید و مضر جگر و مصلحش سیب و قدر شربتش تا دو درم و بدلش استخوان قنفذ و شانه ٔ او بالخاصیه، جهت رفع نخاله ٔ بن موی و تولد قمل و ریختن موی مؤثر است و چون او را با چوب داری که آدمی را از گلو کشیده باشند و قدری خاک قبرمقتول بخور کنند در منع سحر و فتنه مجرب دانسته اند و بدستور در اصلاح متباغضین مؤثر است - انتهی . و حسین خلف گوید:<br />ذبل . بکسر اول و سکون بای ابجد و لام . پوست لاک پشت هندی باشد و بعضی گویند پوست لاک پشت دریائی است خاکستر آن با سفیده ٔ تخم مرغ شقاق را نافع است - انتهی . ابن البیطار گوید: (قال ) الشریف : هو جلدالسلحفاة الهندیة اذا صنع منه مشط و مشط به الشعر اذهب نخالة الشعرو أخرج الصیبان و اذا أحرق و عجن رماده ببیاض البیض و طلی به علی شقاق الکعبین و الأصابع نفعه و نفع أیضا من شقاق الباطن العارض للنساء عند النفاس و یذهب آثاره و قیل هو جلدالسلحفاة البحریة - انتهی .<br />از مجموع اقوال گوناگون فوق آنچه استنباط میشود این است که ذَبل به معنی لاک و کاسه ٔ انواع سنگ پشتهای بری و بحری است و همچنین جلد شاخی یا استخوانی یا آهکی پاره ای جانوران است و نیز به معنی پوست کرتنکله یعنی تمساح است و با ز به معنی استخوان لسان البحر یعنی ارنب بحری و دمیاست . <BR><font color=\"Blue\">◄</font> اسبی باریک میان . (مهذب الاسماء).<br /></font></div>'),
(130429, 'ذبلة', '<span class=\"hlight\">ذبلة.</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ]</font></b> (ع اِ) پشک . پشکل . بَعرَة. <BR><font color=\"Blue\">◄</font> باد گرم پژمراننده .<br /></font></div>'),
(130430, 'ذبلة', '<span class=\"hlight\">ذبلة.</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ ]</font></b> (ع مص ) ذُبنة. خوشیدن لب از تشنگی . پژمریدن لب از عطش . <BR><font color=\"Blue\">◄</font> خوشیدگی لب و پژمردگی آن از بی آبی .<br /></font></div>'),
(130431, 'ذبنة', '<span class=\"hlight\">ذبنة.</span> <font color=\"DarkGreen\"><b>[ ذُ ن َ]</font></b> (ع مص ) خوشیدن لب از تشنگی . ذبلة. هواسیدگی لب .<br /></font></div>'),
(130432, 'ذبوب', '<span class=\"hlight\">ذبوب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) حصنی است به یمن از عمل علی ّبن امین .<br /></font></div>'),
(130433, 'ذبوب', '<span class=\"hlight\">ذبوب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع مص ) ذَبَب . (در همه ٔ معانی ).خوشیدن و هواسیدن لب از تشنگی و جز آن . <BR><font color=\"Blue\">◄</font> لاغر گردیدن تن . <BR><font color=\"Blue\">◄</font> پژمریدن گیاه . <BR><font color=\"Blue\">◄</font> گردیدن و متغیر شدن گونه ٔ کسی . <BR><font color=\"Blue\">◄</font> دیوانه شدن . <BR><font color=\"Blue\">◄</font> اندک باقی ماندن از روز.<br /></font></div>'),
(130434, 'ذبور', '<span class=\"hlight\">ذبور.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذِبر.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130435, 'ذبول', '<span class=\"hlight\">ذبول .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع مص ) پژمریدن . (منتهی الارب ). ذبل . پژمردن . خوشیدن . پژمرده شدن . (دهار) (تاج المصادر بیهقی ) (زوزنی ). پژمردگی . (دهار). ضمور. کاهیدن . لاغر شدن . لاغری . ضعف . شکستگی . نزاری . مقابل نموّ. و صاحب کشاف اصطلاحات الفنون گوید: بالضم ّ و ضم ّالموحدة المخففة. فی اللغة، پژمردن . کما فی الصّراح . قال الحکماء هو ضدّالنموّ و هما من انواع الحرکة الکمیة. و یفسر بانتقاص حجم اجزاءالجسم الاصلیة بسبب ما ینفصل عنه فی جمیعالاقطار علی نسبة طبیعیة فیقید الانتقاص خرج النمو والسمن و التخلخل و الورم و الازدیاد الصنّاعی . لانّها ازدیاد حجم الاجزاء. و الاصلیة صفةالاجزاء. و خرج بهاالهزال . لانّه انتقاص فی الاجزاء الزائدة. و تفسیرالاجزاء الاصلیة و الزائدة یجی ٔ فی لفظالنمو و بقید بسبب ما ینفصل عنه، یخرج التکاثف الحقیقی لانّه بلا انفصال .و المقصود الانتقاص الدّائمی . لانّه المتبادر بناء علی کونه الفرد الکامل . فلا ینتقض التعریف برفع الوَرَم اذا کان عن الاجزاءالاصلیة فی جمیعالاقطار لانّه لایکون دائماً فی الاجزاء الاصلیة. و لا یظهر فائدة قید علی نسبة طبیعیة. و یجری فی هذا التفسیر بظاهره ما یجیئی فی تعریف النمو. کذا یستفاد من العلمی فی بحث الحرکة. و یطلق الذبول ایضاً علی بعض اقسام البحران و یسمّی بألذّوبان و قد مرّ فی لفظالبحران . و یطلق ایضاً علی اقسام حمّی ّالذّق و قد مرّ فی لفظ الحمی - انتهی .<br />بس عجب نیست که با جنس ذبولی که وراست <br />تره را بر سر خوان تو بگیرد آماه .<br /> <font color=\"Red\">(نجیب جرفادقانی ).</font><br />حرارت سخطت با گران رکابی سنگ <br />ذبول کاه دهد کوههای فربی را.<br /> <font color=\"Red\">انوری .</font><br />چنان فرانمود که حدوث وهن و فترت و ذبول طراوت دولت همه منتج ضعف رأی و سوء تدبیر اسلاف وزراء بوده است . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>). ناصرالدین از این کلمات متأذّی شد و طراوت آن حال به ذبول رسید. (ترجمه ٔ تاریخ یمینی همان نسخه ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>).<br />بارها خوردی تو نان دفع ذبول <br />این همان نان است چون گشتی ملول .<br /> <font color=\"Red\">مولوی .</font><br />الذُبنة؛ ذبوالشفتین من العطش (مجدالدین ) ذُبنة، خوشیدن لب از تشنگی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خوشیده پوست شدن . <BR><font color=\"Blue\">◄</font> لاغر و باریک شدن اسپ . <BR><font color=\"Blue\">◄</font> پشک افکندن مال . پشکل انداختن ابل . <BR><font color=\"Blue\">◄</font> ذبول بشره ؛ خشک پوست گردیدن . <BR><font color=\"Blue\">◄</font> (اِ) نام تب دق در درجه ٔ دوم . <BR><font color=\"Blue\">◄</font> ذبول یا ذبول دقی ؛ رنج باریک . و آن بیماریی است . و مقارنةالقطط و انفاسها یورث الذبول و السل . ابن البیطار. و علت ذبول را به پارسی گدازش گویند و کاهش نیز گویند. (ذخیره ٔ خوارزمشاهی ).و گاهی که <font color=\"DarkGreen\"><b>[ غاذیة ]</font></b> کمتر بازرساند <font color=\"DarkGreen\"><b>[ غذا را ]</font></b> ذبول پدید آید یعنی کاهش . (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> سن ذبول ؛ سن شیخوخت . <BR><font color=\"Blue\">◄</font> نوائی است که مطربان زنند. <BR><font color=\"Blue\">◄</font> ذوبان، و آن بحران ردی باشد در مدّت دراز.<br /></font></div>'),
(130436, 'ذبول', '<span class=\"hlight\">ذبول .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) پژمریده . پژمرده . هواسیده . خوشیده . کاهیده . لاغر شده . لاغر. نزار. <BR><font color=\"Blue\">◄</font> باد سخت که سبزه را خشک کند.<br /></font></div>'),
(130437, 'ذبی', '<span class=\"hlight\">ذبی .</span> <font color=\"DarkGreen\"><b>[ ذِ ب ْ بی ی ]</font></b> (ع اِ) سرهنگ شحنة.<br /></font></div>'),
(130438, 'ذبیان', '<span class=\"hlight\">ذبیان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن بغیض یکی از اجداد حذیفةبن بدربن عمروبن جویة. از اجداد اعصربن سعدبن قیس . رجوع به معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span> س <span class=\"hlight\" dir=\"rtl\">١</span> شود.<br /></font></div>'),
(130439, 'ذبیان', '<span class=\"hlight\">ذبیان .</span><font color=\"DarkGreen\"><b>[ ذِب ْ ]</font></b> (اِخ ) دسته ای از واحه ها بالجزایر در ایالت قسطنطین بدانسوی اورس .<br /></font></div>'),
(130440, 'ذبیان', '<span class=\"hlight\">ذبیان .</span> <font color=\"DarkGreen\"><b>[ ذِ <span class=\"hlight\" dir=\"rtl\">/</span> ذُب ْ ]</font></b>(اِخ ) قبیله ای است از عرب . و سمعانی گوید نام چند بطن از عرب و از آن قبیله است ذبیانی شاعر معروف مادح نعمان بن منذر زیادبن معاویة. و رجوع به الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> و فهارس عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٦</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٢</span> شود.<br /></font></div>'),
(130441, 'ذبیان', '<span class=\"hlight\">ذبیان .</span> <font color=\"DarkGreen\"><b>[ ذِب ْ ]</font></b> (اِخ ) شهری است بدانسوی بلقاء به ودای اردن .<br /></font></div>'),
(130442, 'ذبیان', '<span class=\"hlight\">ذبیان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن ذبیان . در سیرت عمربن عبدالعزیز تصنیف الحافظ جمال الدین ابی الفرج عبدالرحمن بن جوزی در جواب عمربن عبدالعزیز بنامه ٔ عمربن الولیدبن عبدالملک گوید خطاب به او: فامّک بنانة امة السکون کانت تطوف فی سوق حمص و تدخل فی حوانیتها. ثم ّ اﷲ اعلم بها. اشتراها ذبیان بن ذبیان من فئی المسلمین فاهداها لابیک .<br /></font></div>'),
(130443, 'ذبیانی', '<span class=\"hlight\">ذبیانی .</span> <font color=\"DarkGreen\"><b>[ ذُب ْ نی ی ]</font></b> (ص نسبی ) منسوب به ذبیان که نام بطنی چند از اعراب است . (از سمعانی ).<br /></font></div>'),
(130444, 'ذبیانی', '<span class=\"hlight\">ذبیانی .</span> <font color=\"DarkGreen\"><b>[ ذُب ْ ]</font></b> (اِخ ) یا نابغه ٔ ذبیانی . زیادبن معاویةبن ضباب الذبیانی الغطفانی المضری . مکنی به أبی أمامة. شاعری است جاهلی از طبقه ٔ اولی از بطن ذبیان از مردم حجاز. ویرا ببازار عکاظ قبه ای از پوست سرخ می افراشتند و شعراء عصر مانند اعشی و حسان و خفساء و جز آنان بوی گردمی آمدند و شعر خود بر وی عرضه میداشتند. و او بزمان جاهلیت یکی از اشراف بود و نزد نعمان بن منذر مکانت و منزلتی بسزا داشت تا آنگاه که در قصیده ای تشبیب به متجردة زن نعمان کرد و نعمان بر وی بیاشفت و او بگریخت و دیری مخفی بماند تا بار دیگر مورد مهر نعمان شد و بخدمت وی بازگشت . ابوعمروبن العلاء، ذبیانی را بر همه ٔ شعراء تفضیل می نهاد. و شعر او بسیار است لکن بعض آن را در دیوانی کوچک فراهم کرده اند. او نیکوشعرترگویندگان عرب است و در شعر او حشو و تکلف نباشد. گویند عمری طویل یافته است . و وفات وی ظاهراً هیجده سال پیش از هجرت (مطابق <span class=\"hlight\" dir=\"rtl\">٦٠٤</span> م .) بوده است . رجوع به شرح شواهد مغنی سیوطی شود .<br />و صاحب معجم المطبوعات گوید: هو زیادبن معاویة من ذبیان من قیس و یکنی امامة و انما سمی النابغة لقوله :<br />و حلت فی بنی القین بن جسر<br />و قد نبغت لنا منهم شؤون .<br />و النابغة کان خاصاً بالنعمان بن المنذر صاحب الحیرة و من ندمائه و اهل انسه و هو من طبقةالاولی المقدمین علی سائرالشعراء روی عن عمربن الخطاب سأل معشر غطفان من الذی یقول :<br />أتیتک عاریاً خلقاًثیابی <br />علی خرق تظن به الظنون، <br />قالوا النابغة، قال ذاک اشعر شعرائکم کان یضرب له قبة من اَدم بسوق عکاظ فتأتیه الشعراء فتعرض علیه اشعارها و اول من انشده الاعشی ثم حسان بن ثابت ثم انشدته خنساء بنت عمروبن الشرید و وقعت العداوة بینه و بین المنخل الشاعر، فوشی به الی النعمان فهرب النابغه الی بنی غسان و نزل به عمروبن الحارث الاصغر ملک الغساسنة فمدحه و مازال مقیماً عنده حتی مات .<br />دیوان (النابغة الذبیانی ) - عنی بنشره محمد افندی ادهم صاحب مکتبةالرشاد قال فی مقدمته انه مأخوذ عن نسخ مخطوطة قدیمةالعهد و عن نسخ من طبع اوروبا و هو بالشکل الکامل والقصائد المنقولة عن روایةالاصمعی مشروحة کلها شرحاًحسناً مصر <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> م . ص <span class=\"hlight\" dir=\"rtl\">١١٦</span> و طبع فی مجموع مشتمل علی خمسة دواوین من اشعارالعرب . انظر شعراءالعرب - مجموع مشتمل الخ و طبع فی المجلة الاسیویة الفرنسیه سنه <span class=\"hlight\" dir=\"rtl\">١٨٦٨</span> م . و معه ترجمة فرنسیة باعتناء الاستاذ دیر نبرغ . (معجم المطبوعات ).<br /></font></div>'),
(130445, 'ذبیب', '<span class=\"hlight\">ذبیب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) هواسیدن لب از تشنگی، یعنی خوشیدن و پژمریدن آن . (از تاج المصادر بیهقی ).<br /></font></div>'),
(130446, 'ذبیح', '<span class=\"hlight\">ذبیح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص، اِ) ذبح . مذبوح . بسمل . گلوبریده . گوسفند کاردی و آنچه قربان کنند. (مهذب الاسماء). ذبیحة. قربانی . حیوان ذبح شده . حیوان که برای گلو بریدن است . گوسفند کشتنی . چارپا که برای کشتن باشد. ج، ذَبحی ̍، ذَباحی ̍.<br /></font></div>'),
(130447, 'ذبیح', '<span class=\"hlight\">ذبیح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) تخلص یکی از متأخرین شعرای ایران .او مردی درویش مسلک بود و بیشتر عمر خود را بسیاحت گذرانید و نام او اسماعیل است . (قاموس الاعلام ترکی ).<br /></font></div>'),
(130448, 'ذبیح', '<span class=\"hlight\">ذبیح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) ذبیح اﷲ لقب اسماعیل بن ابراهیم علیهماالسلام . و گویند از آن اسحاق بن ابراهیم . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> لقب عبداﷲبن عبدالمطلب . و منه الحدیث : انا ابن الذبیحین . چه جد او صلوات اﷲ علیه اسماعیل و پدرش عبداﷲ هر دو ذبیح باشند.<br /></font></div>'),
(130449, 'ذبیح ا', '<span class=\"hlight\">ذبیح ا.</span> <font color=\"DarkGreen\"><b>[ ذَ حُل ْ لاه ]</font></b> (اِخ ) لقب اسحاق پیغمبر و بقولی لقب اسماعیل پیغامبر دو پسر ابراهیم خلیل اﷲ.<br /></font></div>'),
(130450, 'ذبیحة', '<span class=\"hlight\">ذبیحة.</span> <font color=\"DarkGreen\"><b>[ ذَ ح َ ]</font></b> (ع ص، اِ) تأنیث ذبیح، قربانی . کشتار. بسمل کردنی . (دهار). آنچه به مکه قربان کنند. آنچه قربان کنند در حج . چارپای گلوبریده . چارپا که برای کشتن باشد. حیوان ذبح شده . مذبوح . کشتار. نسیکه . عتیره . و فعیل چون به معنی مفعول آید مؤنث آن نیز فعیل است، و انما جائت بالهاء لغلبة الأسم <span class=\"hlight\">:</span> چون قصابی ذبیحه بکشتی فقرا را بر تقاسیم اجزاء خون مزاحمت رفتی . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی کتابخانه ٔ مؤلف، ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>). ج، ذبایح، اذباح، ذبیحه گرفتن برای خود. و صاحب کشاف اصطلاحات الفنون گوید: ذبیحة. بالفتح کالعقیدة. لغةً ما سیذبح من النعم فانّه منتقل من الوصفیة الی الاسمیة. اذ الذبیح ما ذُبح کما فی الرّضی و غیره . فلیس الذبیحة المزکاة کما طُن ّ و شریعةً قطع الحلقوم من باطن عند المفصل . و هو مفصل ما بین العنق و الرأس . و هو مختار المطرزّی . و المشهور انّه قطع الاوداج . و هو شامل لقطع المری ایضا. و لذا قالوا زکوةالاختیار ذبح ای قطع الاوداج بین الحلق و اللبة ای المنخر و عروقه المری ای مجری الطعام و الشراب و الودجان . و هما عرقان عظیمان فی جانبی قُدام العنق، بینهما الحلقوم و المری . فالذبح شرعاً علی قسمین اختیاری و هو ما مرّ و اضطراری و هو قطع عضو ایّما کان بحیث یسیل منه الدّم المسفوح و ذلک فی الاصطیاد. هکذا فی جامعالرموز.<br /></font></div>'),
(130451, 'ذبیحین', '<span class=\"hlight\">ذبیحین .</span> <font color=\"DarkGreen\"><b>[ ذَ ح َ ]</font></b> (ع اِ) تثنیه ٔ ذبیح . و منه الحدیث : انا ابن الذبیحین ؛ یعنی از نسل اسماعیل ذبیح اﷲ و فرزند بلافصل عبداﷲبن عبدالمطلب . رجوع به عبداﷲبن عبدالمطلب شود.<br /></font></div>'),
(130452, 'ذج', '<span class=\"hlight\">ذج .</span> <font color=\"DarkGreen\"><b>[ ذَج ج ]</font></b> (ع مص ) آشامیدن . نوشیدن . خوردن آب یا مایعی دیگر. ذأج . <BR><font color=\"Blue\">◄</font> بازآمدن از سفر. بازگشت کاروانی و مسافر.<br /></font></div>'),
(130453, 'ذجبل', '<span class=\"hlight\">ذجبل .</span> <font color=\"DarkGreen\"><b>[ ذُ ب ُ ]</font></b> (اِخ ) یوم ذجبل ؛ نام جنگی است میان مردم بصره و خوارج . (میدانی ). شاید این کلمه محرف دُجیل یا چیز دیگر باشد.<br /></font></div>'),
(130454, 'ذجل', '<span class=\"hlight\">ذجل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِمص ) ظلم . جور. ستم . ستم کردن .<br /></font></div>'),
(130455, 'ذح', '<span class=\"hlight\">ذح .</span> <font color=\"DarkGreen\"><b>[ ذَح ح ]</font></b> (ع مص ) سیلی زدن . تپانچه زدن . طپانچه زدن . کشیده زدن . چک زدن . <BR><font color=\"Blue\">◄</font> شکافتن . <BR><font color=\"Blue\">◄</font> کوفتن . <BR><font color=\"Blue\">◄</font> آرمیدن با.<br /></font></div>'),
(130456, 'ذحج', '<span class=\"hlight\">ذحج .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) خراشیدن . <BR><font color=\"Blue\">◄</font> ذحج ریح ؛ کسی یا چیزی را، کشیدن باد او را از جائی بجائی .<br /></font></div>'),
(130457, 'ذحذاح', '<span class=\"hlight\">ذحذاح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) ذُحذح . کوتاه بالای کلان شکم .<br /></font></div>'),
(130458, 'ذحذح', '<span class=\"hlight\">ذحذح .</span> <font color=\"DarkGreen\"><b>[ ذُ ذُ ]</font></b> (ع ص ) ذحذاح .<br /></font></div>'),
(130459, 'ذحذحة', '<span class=\"hlight\">ذحذحة.</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ح َ ]</font></b> (ع مص )گام نزدیک گذاشته شتاب رفتن . <BR><font color=\"Blue\">◄</font> ذحذحه ٔ ریح تراب را؛ بردن باد خاک را.<br /></font></div>'),
(130460, 'ذحل', '<span class=\"hlight\">ذحل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام موضعی است .<br /></font></div>'),
(130461, 'ذحل', '<span class=\"hlight\">ذحل .</span> <font color=\"DarkGreen\"><b>[ ذَ ح ِ ]</font></b> (ع ص ) ذاحل . طلب کننده ٔ خون مقتول .<br /></font></div>'),
(130462, 'ذحل', '<span class=\"hlight\">ذحل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) کشنده را بازکشتن . <BR><font color=\"Blue\">◄</font> کین خواستن : یقال طلب بذحله . <BR><font color=\"Blue\">◄</font> طلب پاداش گناهی که بر او رفته کردن . و یا پاداش دشمنی خواستن .<br /></font></div>'),
(130463, 'ذحل', '<span class=\"hlight\">ذحل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) کینه . (دهار). دشمنی . دشمنانگی . حقد. عداوت . ج، ذُحول . (مهذب الاسماء). اَذحال . (منتهی الارب ).<br /></font></div>'),
(130464, 'ذحلمة', '<span class=\"hlight\">ذحلمة.</span> <font color=\"DarkGreen\"><b>[ ذَ ل َم َ ]</font></b> (ع مص ) ذبح کردن . <BR><font color=\"Blue\">◄</font> فراهم آوردن .<br /></font></div>'),
(130465, 'ذحم', '<span class=\"hlight\">ذحم .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) عیب کردن . <BR><font color=\"Blue\">◄</font> حقیر شمردن . <BR><font color=\"Blue\">◄</font> راندن . <BR><font color=\"Blue\">◄</font> رسوا کردن .<br /></font></div>'),
(130466, 'ذحملة', '<span class=\"hlight\">ذحملة.</span> <font color=\"DarkGreen\"><b>[ ذَ م َل َ ]</font></b> (ع مص ) ذَمْحَلَة. غلطانیدن چیزی را. دحرجة.<br /></font></div>'),
(130467, 'ذحول', '<span class=\"hlight\">ذحول .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذحل . کینه ها. دشمنی ها.<br /></font></div>'),
(130468, 'ذخایر', '<span class=\"hlight\">ذخایر.</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع اِ) ج ِ ذخیرة. ذخیره ها. پستاها. پستائی ها. دست پس ها. پس افکنده ها. پس اوکندها.اندوخته ها. نگاهداشته شده ها برای روزی <span class=\"hlight\">:</span> <br />کلیدهای شهادت نهادی اندر گنج <br />زهی ذخایر گنج تو طاعت جبار.<br /> <font color=\"Red\">فرخی .</font><br />و این قصه دراز است و از خزائن سامانیان مالهای بی اندازه و ذخایر نفیس برداشت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>). و ناگاه بر ذخایر نفیس و گنجهای شایگانی مظفر شوند. (کلیله و دمنه ). و چون آفتاب روشن است که تو آمده ای تا نفایس ذخایر از ولایت ما ببری . (کلیله و دمنه ). از نفایس ذخایر و زواهر جواهر... چیزی یافت که حامل کتاب و اوارج حسّاب از حدّ و عدّ آن قاصر آید. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).خزاین موروث و ذخایر مدفون بر جماعت اتباع تفرقه کرد. (ترجمه ٔ تاریخ یمینی همان نسخه ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>). حکم ذخائر با او انداخت . (ترجمه ٔ تاریخ یمینی همان نسخه ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>). <BR><font color=\"Blue\">◄</font> ذخایر الهیة؛ قومی از اولیأاﷲ باشند که خدای تعالی بوسیله ٔ ایشان رنج و بلا را از بندگان خود دفع فرماید، همچنانکه با ذخایر سیم و زر فقر و نیاز درویشان را میتوان دفع کرد. (کشاف اصطلاحات الفنون، از اصطلاحات الصوفیه ).<br /></font></div>'),
(130469, 'ذخذاخ', '<span class=\"hlight\">ذخذاخ .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مرد گریزان و محترز از هر چیزی .<br /></font></div>'),
(130470, 'ذخذخان', '<span class=\"hlight\">ذخذخان .</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ]</font></b> (ع ص ) مرد گویا و فصیح زبان . زبان آور.<br /></font></div>'),
(130471, 'ذخر', '<span class=\"hlight\">ذخر.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع مص ) یخنی نهادن . (تاج المصادر بیهقی ) (زوزنی ) (مهذب الاسماء) (دهار) (منتهی الارب ). پس انداز کردن . پستائی کردن . نهادن . نگاه داشتن . اندوختن . پس اوکند کردن . پس افکند کردن . ذخیره کردن .<br /></font></div>'),
(130472, 'ذخر', '<span class=\"hlight\">ذخر.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ذخیره . (مهذب الاسماء). چیزی نگاهداشته شده برای وقتی . یخنی . (منتهی الارب ). پس انداز. پس افکند. پس اوکند. چیز پنهان کرده . چیز نهاده . پستائی . اندوخته . ج، اَذخار <span class=\"hlight\">:</span> سایه ٔ کردگار پرتو لطف پروردگار ذخر زمان و کهف امان . (گلستان سعدی ).<br /></font></div>'),
(130473, 'ذخر', '<span class=\"hlight\">ذخر.</span> <font color=\"DarkGreen\"><b>[ ذَ خ ِ ]</font></b> (اِخ ) نام کوهی است به یمن .<br /></font></div>'),
(130474, 'ذخف', '<span class=\"hlight\">ذخف .</span> <font color=\"DarkGreen\"><b>[ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ خ َ ]</font></b>(ع اِ) نام گیاهی است . <br /></font></div>'),
(130475, 'ذخو', '<span class=\"hlight\">ذخو.</span> <font color=\"DarkGreen\"><b>[ ذَخ ْوْ]</font></b> (ع مص ) ذخو ابل ؛ سخت راندن شتران را یا راندن و دور کردن . <BR><font color=\"Blue\">◄</font> ذَخو مراءة؛ آرامیدن با وی .<br /></font></div>'),
(130476, 'ذخکت', '<span class=\"hlight\">ذخکت .</span> <font color=\"DarkGreen\"><b>[ ذَ ک َ ]</font></b> (اِخ ) ذخکث نام قریه ای به رودبار آن سوی سیحون . (سمعانی ). و صاحب حدود العالم گوید: ذَخکث . شهرکی است (به ماوراءالنهر) که از کوه وی داروی موش خیزد. (ظاهراً مراد از داروی موش سم ّالفار است ) (حدود العالم ). و بعضی گفته اند از قراء اسفیجاب است و یا قریه ای است به رودبار پشت سیحون و ساس . و از آنجاست ابونصر احمدبن عثمان بن احمد مستوفی یکی از ائمه ٔ حدیث . وفات <span class=\"hlight\" dir=\"rtl\">٥٠٦</span> استدراک تاج العروس .<br /></font></div>'),
(130477, 'ذخکتی', '<span class=\"hlight\">ذخکتی .</span> <font color=\"DarkGreen\"><b>[ ذَ ک َ تی ی ]</font></b> (ص نسبی ) منسوب به ذخکت شهری به رودبار آنسوی سیحون . (سمعانی ).<br /></font></div>'),
(130478, 'ذخی', '<span class=\"hlight\">ذخی .</span> <font color=\"DarkGreen\"><b>[ ذَخ ْی ْ ]</font></b>(ع مص ) واخیده شدن پشم به کمان ندّافی . (منتهی الارب ). محلوج شدن پشم با کمان حلاّج . <BR><font color=\"Blue\">◄</font> شتابی کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ذَختهم الرّیح ؛ رسید به آنها باد و نیست ایشان را از آن پرده و مانع.<br /></font></div>'),
(130479, 'ذخیر', '<span class=\"hlight\">ذخیر.</span> <font color=\"DarkGreen\"><b>[ ذُ خ َ ]</font></b> (اِخ ) بطنی است از صدف و ابن الکلبی گوید او ذُخیربن غسان بن جذام بن الصدف است . (از انساب سمعانی ). و صاحب تاج العروس بجای ذخیربن غسان ذخیربن شجنان آورده است و ظاهراً غلط است .<br /></font></div>'),
(130480, 'ذخیره خانه', '<span class=\"hlight\">ذخیره خانه .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) خرمنگاه و انبار خانه و مخزن .<br /></font></div>'),
(130481, 'ذخیره نهادن', '<span class=\"hlight\">ذخیره نهادن .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) رجوع به ذخیره کردن شود.<br /></font></div>'),
(130482, 'ذخیره کردن', '<span class=\"hlight\">ذخیره کردن .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ دَ ]</font></b> (مص مرکب ) نهادن . پس انداز کردن . ادّخار. اذّخار. انبار کردن . اندوختن . الفنجیدن . بیلفنجیدن . الفغدن . بیلفغدن . پس دست داشتن .الفختن . بیلفختن . اقتناء. ابتآر. بأر. اعتقاد. پستائی کردن . یخنی . اقماز.<br /></font></div>'),
(130483, 'ذخیری', '<span class=\"hlight\">ذخیری .</span> <font color=\"DarkGreen\"><b>[ ذُ خ َ ری ی ]</font></b> (ص نسبی ) منسوب به ذُخیر، بَطنی از صدف . رجوع به ذُخَیر شود.<br /></font></div>'),
(130484, 'ذخینو', '<span class=\"hlight\">ذخینو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) قریه ای است بسه فرسنگی سمرقند. (الانساب سمعانی ) و یاقوت در معجم البلدان نام این قریه را ذخینوی بفتح اوّله و کسر ثانیه و بعد الیاء المثناه من تحت نون و واو مقصور ضبط کرده است . رجوع به ذخینوی شود.<br /></font></div>'),
(130485, 'ذخینوی', '<span class=\"hlight\">ذخینوی .</span> <font color=\"DarkGreen\"><b>[ ذَن َ ]</font></b> (ص نسبی ) صاحب انساب گوید: الذخینوی بفتح الذال المعجمة و کسر الخاء المعجمة، و سکون الیاء المنقوطة باثنتین من تحتها و فتح النون و فی آخرها الواو هذه النسبة الی قریة ذخینو علی ثلاثة فراسخ من سمرقند.<br /></font></div>'),
(130486, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b> (اِخ ) ابن عبداﷲ، مکنی به ابی عمر. محدث است . و رجوع به عیون الأخبار ابن قتیبه ٔ دینوری ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> شود.<br /></font></div>'),
(130487, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b> (اِخ ) الهمدانی . در عقدالفرید ذیل : «الوقوف علی القبور و ما بین الموتی » آرد: ابوذر الهمدانی بر قبر پسر خود ذرّ بایستاد و گفت : یا ذَرّ، شغلنی الحزن لک عن الحزن علیک، فلیت شعری ما قلت و ما قیل لک ! ثم قال : اللّهم انی قد وهبت لک اسأته فهب له اسأته الیک، فلما انصرف عنه التفت الی قبره فقال : یا ذرّ، قد انصرفنا و ترکناک و لواقمنا ما نفعناک . ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> جزء ثالث و در عیون الاخبار آرد: حدثنی محمدبن احمدبن یونس قال سمعت عمربن جریر المهاجری یقول لما مات ذرّبن عمربن ذرّ قال لاصحابه : الان یضیع الشیخ (لانه کان به بارّاً): فسمعها الشیخ فقال : انّی اضیع واﷲ حی ٌ لایموت . فلما و اراه التراب وقف علی قبره و قال : رحمک اﷲ یا ذرّ ما علینا بعدک من خصاصة و ما بنا الی احد مع اﷲ حاجة و ما یسرّنی انّی کنت المقدّم قبلک و لو لا هول المَطَلع لتمنّیت ُ ان اکون مکانک، لقد شغلنی الحزن لک عن الحزن علیک، فیالیت شعری ماذا قلت و ما قیل لک اثم ّ رفع رأسه الی السماء فقال : اللّهم انّی قد وهبت حقی فیما بینی و بینه له فهب حقک فیما بینک و بینه له . ثم قال عند انصرافه : مضینا و ترکناک، و لو اقمنا ما نفعناک . (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). و در البیان والتبیین آرد: و مات ذربن ابی ذرّ الهمدانی من بنی مرهبة - و هو ذربن عمربن ذر فوقف ابوه علی قبره فقال یاذر، شغلنی الحزن ... ثم قال اللهم انک وعدتنی بالصبر علی ذر صلواتک و رحمتک اللهم و قد وهبت ماجعلت لی من اجر علی ذر لذر فلا تعرفه قبیحا من عمله، اللهم وقد وهبت له اسأته الی ّ فهب لی اسأته الی نفسه فانک اجود و اکرم فلما انصرف عنه التفت الی قبره فقال یا ذر، قد انصرفنا و ترکناک و لو اقمنا مانفعناک . (البیان والتبیین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br /></font></div>'),
(130488, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b> (اِخ ) نامی از نامهای مردان عرب .<br /></font></div>'),
(130489, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع فعل امر) مفرد فعل امر از وذر. مان . بمان . دَع . بگذار. بهل <span class=\"hlight\">:</span> ذرنی و من خلقت وحیدا. (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٧٤</span>). قل اﷲ، ثم ذرهم . (قرآن <span class=\"hlight\" dir=\"rtl\">٩١/٦</span>).<br /></font></div>'),
(130490, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b> (اِخ ) ابن حبیش الشکری العطاردی . وی از تابعین و محدث و مقری است . و قرائت عبداﷲبن مسعود از خود او و عبداﷲ از علی علیه السلام روایت کند و عاصم و ابوبکربن عیاش از ذر روایت کنند. رجوع به معجم الادباء یاقوت، چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> و عیون الأخبار ابن قتیبه ٔ دینوری ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> شود.<br /></font></div>'),
(130491, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b> (ع اِ) ج ِ ذرّة. موران خرد. مورچه و صدمورچه را گویند به وزن یک دانه جو است . و قیل لیس لها وزن ٌ و یحکی ان ّ رجلاً وضع خبزاً حتی علاه الذرّ و ستره ثم وزنه فلم یجد شیئاً. اجزاء غبار <span class=\"hlight\">:</span> <br />خفیف را سپه و پیل و مال چندان بود<br />که بیش از آن نبود در هوا همانا ذر.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عالم ذرّ</span> ؛ آنگاه که ابناء بشر چون ذرّات از ظهر آدم بوالبشر بیرون شده و خدای تعالی آنان را به اقرار و اعتراف وجودخویش داشت . ابوالفتوح رازی در تفسیر آیه ٔ و اذ اخذ ربک من بنی آدم من ظهورهم ذریتهم گوید: جماعتی مفسران سلف و اصحاب حدیث گفتند معنی آیه آن است که خدای پشت آدم بمالید و جمله فرزندان او را برون آورد بر صورت ذره ای اعنی مورچه ٔ خرد و خلاف کردند که این کجا بود. بعضی گفتند به بطن نعمان وادیئی است در پهلوی عرفات و گفته اند به دهناء بوداز زمین هند و آن آنجا بود که آدم فرود آمد از آسمان . کلبی گفت از میان مکه و طایف بود سدی گفت در آسمان بود که خدای تعالی پشت آدم بمالید جانب راست و فرزندان او را از آن جانب بیرون آورد چون مروارید سفید وایشان را گفت برحمت من ببهشت شوید و از جانب چپ پشتش بمالید و فرزندانی از او بیرون آورد سیاه و گفت بدوزخ شوید و لاابالی و باک ندارم و با ایشان خطاب کرد و گفت بدانید که جز من خدائی نیست و من خدای شماام بمن شرک میاورید و من پیغمبرانی خواهم فرستادن بشما تا عهد من یاد شما دهند و من با شما پیمان کنم و بر شما کتابها خواهم فرستاد بگو تا چه میگوئی . ایشان گفتند گواهی میدهیم که تو خدای مائی و آفریدگار مائی و ما را خدائی نیست جز تو. گروهی این روز اقرار کردند بطوع و گروهی بر وجه تقیه خدای تعالی از ایشان بر این عهد بست آنگه آجال و ارزاق و مصائب ایشان بنوشت آدم (ع ) در ایشان نگریست ایشان را دید مختلف اشکال و الوان و متفاوت الصور بعضی نیکو و بعضی زشت و بعضی درازو بعضی کوتاه بعضی توانگر و بعضی درویش گفت بار خدایا چرا ایشان را متساوی نیافریدی گفت خواستم تا اینان شکر من زیادت کنند. سدی گفت در میان ایشان پیغمبران بودند مانند چراغ رخشان آدم از آن میانه نوری دید بلند گفت بار خدایا این کیست گفت این پیغمبری است ازفرزندان تو نام او داود گفت بار خدایا عمر او چند است گفت شصت سال گفت بار خدایا بیفزای گفت قلم برفت، با آجال بندگان گفت بار خدایا از عمر من چهل سال در عمر او افزای و عمر آدم هزار سال بود چهل سال به داود داد تا هزار سال کم چهل سال شد چون عمر او به نهصدو شصت رسید ملک الموت به او آمد آدم گفت چه کار آمدی گفت تا جانت بردارم گفت مرا چهل سال عمر مانده است گفت نه به داود دادی انکار کرد و جحود پیش آورد گفت ندادم لاجرم فرزندانش جاحد باشند و نسیان افتاد و فراموش کرد عهد خدای تا فرزندانش فراموش کار شدند و خطا کرد تا فرزندانش مخطی شدند. نعوذاً باﷲ من مثل هذه المقالات المحالات و الترهات الشنیعة. آنگه ملک الموت باپیش خدا آمد گفت بار خدایا آدم چهل سال دعوی میکند گفت برو بگو او را نه به داود دادی گفت بگفتم جحود می کند گفت برو جانش بردار و بگو آنکه قلم تو بود بدادی و ما در عمر داود بنوشتیم با ما جحود از پیش نشود.حاشا علیه السلام من ذلک . او برفت و آدم را جان برداشت آنگه چون عهد فرزندان آدم بسته بود ایشان را گفت با پشت آدم شوی که من قیامت بر نه انگیزم تا از شما یکی مانده باشد تا در وجود نیاید و عمر و روزی خود مستوفی بنستانید این خبر ذرم (؟) است که مخالفان ما و بعضی موافقان از اهل اخبار گفتند و این درست نیست برای مخالفت او دلیل عقل و ظاهر قرآن را. اما مخالفت او دلیل عقل را از اینجاست که حال این فرزندان که دعوی میکنند که خدای ایشان را بیرون آورد بر صورت ذرّه و به ایشان خطاب کرد و تقریر کرد ایشان را بقوله ؛ الست بربکم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). از دو بیرون نبود یا کامل عقل بودند یا نبودند اگر کامل عقل نبودند از حکیم نیکو نیاید خطاب با ایشان و تقریر با ایشان و اگر کامل عقل بودند لامحاله باید تا آن حال یاد دارند و فراموش نکنند که عاقل مثل آن حال و کمتر از آن در شهره و نادرگی با کمال عقل فراموش نکند چون هر دو قسمت باطل است دلیل کند بر بطلان این قول . اگر گویند طول مدت و تخلل مرگ در میانه از یاد ایشان ببرد گوئیم طول مدت اگرنسیان آرد از تفصیل آن باشد <font color=\"DarkGreen\"><b>[ و ]</font></b> از جمله به یک بارناسی نشود آنگه همه ٔ خلایق به یک بار. حالی چنان غریب و نادره رفته و ایشان کامل عقل با کمال عقل چگونه فراموش کنند آنرا. و اما تخلل مرگ را اگر در این تأثیری بودی بایستی که تخلل نوم و جنون و سکر و اغما و زوال عقل را در این اثری بودی که این جمله مزیل عقل است و ما می دانیم که خفته چون بیدار شود و مغمی علیه چون بهوش آید و مست چون هشیار شود آنچه دانسته باشد یادش آید و علمش به آن حاصل شود نبینی که اصحاب الکهف با آنکه سیصدونه سال خفته بودند چون برخاستند هرچه دانستند همه را یاد آمد و هیچ خلل نبود و اینحال به اوقات و اشخاص مختلف نشود. دیگر آنکه خدای تعالی بیان کرد که غرض من از این آن است تا فردای قیامت نگویند: انا کنا عن هذا غافلین . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). و اگر اینجاندانند یا فراموش کرده باشند اولیتر که در قیامت ندانند. اگر گویند کودکی آنچه کرده باشد درحال طفولیت یاد ندارد گوئیم ما از این احتراز کردیم با آنکه گفتیم عاقل باکمال عقل و طفل عاقل نباشد. اما خلاف او ظاهر قرآن را آن است که خدای تعالی گفت : و اذ اخذ ربک من بنی آدم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). و نگفت من آدم و گفت من ظهورهم و نگفت من ظهره و گفت ذریتهم و نگفت ذریته . دگر آنکه گفت : ان تقولوا یوم القیمة انا کنا عن هذا غافلین (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). و المعنی لئلاتقولوا یوم القیمة. نگویند در روز قیامت که ما از این غافل بودیم . باز نمود که این برای آن کردیم تا روز قیامت دعوی غفلت نکنند تا حجت بر ایشان قایم شود اگر فراموش کنند و غافل شوند حجت ساقط شود از ایشان و این غرض حاصل نباشد. دگرآنکه گفت . او تقولوا انما اشرک آباؤنا من قبل . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٣/٧</span>). تا نگویند که پدران ما مشرک بودند بشرک پدران عذر نیاورند و این در حق کسانی صورت بندد که ایشان را پدران مشرک بوده باشند اما آنانکه از پشت آدم (ع ) بیرون آمده باشند ایشان چگونه گویند، اشرک آباؤنا من قبل و کنا ذریته من بعدهم . اگر گویند چون تأویل مخالفان و اخباریان باطل بکردی تأویل صحیح چیست آیه را بنزدیک شما، گوئیم ما را در تأویل آیه دو وجه است یکی آنکه مراد به این جماعتی اند از فرزندان آدم (ع ) که خدای تعالی ایشان را بیافرید و کمال عقل داد و آلات و تمکین و تکلیف کرد ایشان را و بر زبان پیغمبران به ایشان تقریر کرد که : الست بربکم ؟ (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). ایشان از پس نظر در ادله و تحصیل علم و معرفت به خدای تعالی گفتند بلی . ایشان را بر یکدیگر گواه گرفت تا فردای قیامت نگویند که ما از این غافل بودیم یاتعلیلی کنند بشرک پدران و گویند ما را پدران مشرک بودند ما نیز به آن شرک آوردیم که ما اطفال بودیم و به ایشان اقتدا کردیم . و ایشان را شبهت از آن افتاد که گمان کردند که لفظ ذریه متناول نباشد الا اطفال صغار را و پنداشتند که اشتقاق آن از ذر است و این اندیشه خطاست برای آنکه جمله بشر را ذریّه آدم خوانند از کوچک و بزرگ و بالغ و نابالغ. قال اﷲتعالی ؛ ربنا و ادخلهم جنات عدن التی وعدتهم و من صلح من آبائهم و ازواجهم و ذریاتهم . (قرآن <span class=\"hlight\" dir=\"rtl\">٨/٤٠</span>). و لفظ صالح واقع نباشد الاّ بر بالغان و عاقلان دون اطفال . وجه دویم در تأویل آیه آن است که چون خدای تعالی ایشان را از بدیع فطرت و کمال صنعت چنان آفرید و ترکیب عجیب و آیات و دلائل و عبر در خلق ایشان که دلیل اند بر آنکه ایشان راخالقی است قادر عالم حی ّ موجود حکیم سمیع بصیر مریدکاره مدرک حاصل بر صفات کمال در این خلق بمنزلت کسی بود که گواه بر ایشان گیرد تا انکار نتواند کرد که این جمله را خالقی و آفریدگاری هست و مقدر و مدبّری باید و ایشان را در این باب بمنزلت معترفی باشند و اگرچه آنجا اشهادی و اعتراف حقیقی نباشد چنانکه خدای تعالی گفت . ثم استوی الی السماء و هی دخان فقال لها وللارض ائتیا طوعاً او کرهاً قالتا اتینا طائعین . (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٤١</span>). و برحقیقت نه از خدای تعالی قولی بود و نه از آسمان و زمین . و مثله قوله : شاهدین علی انفسهم بالکفر. (قرآن <span class=\"hlight\" dir=\"rtl\">١٧/٩</span>). و ما دانیم که هیچکس بکفر خود گواهی ندهد و مراد آن است که فعلی کنند که دلیل کفرشان کنند و مانند این قول قایل است . جوارحی تشهد بنعمتک و حالی معترفة باحسانک . و مثله فی التوسع قول الشاعر:<br />فلئن نطقت بشکر برک جاهداً، <br />فلسان حالی بالشکایة ینطق .<br />و آنچه روایت کرده اند از بعضی خطباء مانند این است . سل الأرض من شق انهارک و غرس اشجارک و جنی ثمارک فان لم تجبک حواراً اجابتک اعتباراً. و این بابی واسع است و این را استشهاد بسیار است از نظم و نثر. مردی نظام را پرسید: ما الأمور الصامتة الناطقة قال الدلایل المخبرة و العبر الواعظة. قوله و اذ اخذ ربک من بنی آدم من ظهورهم ذریتهم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٢/٧</span>). گفت یاد کن چون فراگرفت خدای تعالی از بنی آدم از پشتهای ایشان فرزندان ایشان را و این کنایت باشد از خلق ایشان و ایجاد ایشان و اخراج و نقل ایشان از اصلاب آباء و ارحام امهات و اشهدهم علی انفسهم، و گواه کرد ایشان را بر خود بر آن تفسیر که دادیم یا بعضی بر بعضی که ؛ هم کنفس واحدة و قوله . الست بربکم، تقریری است با عقلا و کاملان نه من خدای شماام قالوا بلی . جواب ایشان است که دادند و بلی جواب استفهامی باشد متضمن نفی و نعم جواب کلامی مثبت موجب باشد. شهدنا ما گواه شدیم و گواهی دادیم ان تقولوا تقریر آن است که لئلا تقولوا او حذراً من ان تقولوا و آنجا محذوفی مقدر بود والمعنی انما فعلنا ذلک لئلا تقولوا و کلام بر نظایر این برفته است من قوله ؛ یبین اﷲ لکم ان تضلوا. (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٦/٤</span>). و المعنی لئلا تضلوا و قوله : القی فی الأرض رواسی ان تمید بکم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٥/١٦</span>). و المعنی لئلاّ ان تمید بکم او حذراً من ان تمید بکم . او تقولوا عطفت علی قوله ان تقولوا که گوئی ما برای آن شرک آوردیم که پدران ما مشرک بودند و کنا ذریة من بعدهم، و ما فرزندان بودیم از پس ایشان و اشتقاق ذریه من ذراﷲ الخلق ای خلقهم باشد و وزن او فعلیه باشد و قول آن کس که گفت اصل او ذروه است من الذر درست نیست و بر ایشان گفتند فرزند طفل را ذریه خوانند تشبیهاً بالذر و این قول درست نیست . لقوله و من صلح من آبائهم و ازواجهم وذریاتهم، و اطفال را بصلاح وصف نکنند قوله، افتهلکنابما فعل المبطلون . این نیز دلیل است بر آنکه قول بذر باطل است برای آنکه بیان کرد که این آنان گفتند که ایشان را پدرانی مبطل مشرک بودند و گویندگان بذر نخواهند گفتن که ایشان را بجز آدم پدری بود تا آدم مبطل بود. ابوالهذیل در بعضی کتب خود گفت : حسن بصری بذرگفتی و گفتی خدای تعالی اطفال را که ببهشت برد بثواب ایمانشان برد در ذر. و رمانی حکایت کرد از ابن الرشاد که او بخبر ذر گفتی ولیکن نه از آیت از خبر و از جمله ٔ ادله بر فساد این قول قوله، و اﷲ اخرجکم من بطون امهاتکم لاتعلمون شیئاً. (قرآن <span class=\"hlight\" dir=\"rtl\">٧٨/١٦</span>). گفت شما را از شکم مادر بیرون آوردم چیزی ندانستی اگر آنکه از شکم مادر بیرون آید چیزی نداند آنکه از صلب پدر بیرون آید اولی و احری که چیزی نداند. ابن کثیر و اهل کوفه خواندند، ذریتهم علی التوحید و باقی قراء علی الجمع، ذریاتهم، و ذریت لفظی است صالح واحد را و جمع را و چون واحد باشد اورا دوجمع باشد یکی سلامت و آن ذریات است و یکی تکسیر و آن ذراری است و ابوعمرو خواند یقولوا بالیاء فیها جمیعاً خبراً عن الغایب و باقی قراء بتاء خطاب خواندند.<br /></font></div>'),
(130492, 'ذر', '<span class=\"hlight\">ذر.</span> <font color=\"DarkGreen\"><b>[ ذَرر ]</font></b>(ع مص ) پراکندن . دانه افشاندن بزمین . <BR><font color=\"Blue\">◄</font> ترنجیده شدن . <BR><font color=\"Blue\">◄</font> ذرّ بقل ؛ روئیدن تره . <BR><font color=\"Blue\">◄</font> ذرّ شمس ؛ برآمدن خور. <BR><font color=\"Blue\">◄</font> ذرّ ارض نبت را؛ برآوردن زمین گیاه را. <BR><font color=\"Blue\">◄</font> جدا کردن دانه و نمک و مانند آن . <BR><font color=\"Blue\">◄</font> انداختن داروی پراکندنی . پاشیدن به، چنانکه نمک را بر طعام . <BR><font color=\"Blue\">◄</font> ذرّالرجل ؛ پیر شد مقدم سر او. <BR><font color=\"Blue\">◄</font> نمک سوده و آنچه بدان ماند در نرمی در چیزی پراکندن . (تاج المصادر بیهقی ).<br /></font></div>'),
(130493, 'ذرء', '<span class=\"hlight\">ذرء.</span> <font color=\"DarkGreen\"><b>[ ذَرْءْ ]</font></b> (ع مص ) آفریدن . (صراح ). خلق . <BR><font color=\"Blue\">◄</font> ذرءِفم ؛ سخن بد و بیهوده گفتن . <BR><font color=\"Blue\">◄</font> بسیار کردن چیزی را. <BR><font color=\"Blue\">◄</font> تخم افشاندن . بذر انداختن درزمین . <BR><font color=\"Blue\">◄</font> پیر شدن . سپیدموی شدن . <BR><font color=\"Blue\">◄</font> ذرءِ شعر کسی ؛ سپید شدن موی او. <BR><font color=\"Blue\">◄</font> (اِخ ) ذرءٌ من خیر؛ اندک از نیکی . <BR><font color=\"Blue\">◄</font> در حدیث آمده است : و هم ذرء النّار؛ ای خلقوا لها، یعنی آنان آفریده شده اند آتش را. ذرء النّار؛ گروهی که آفریده شده اند آتش دوزخ را. <BR><font color=\"Blue\">◄</font> حائل . پرده .<br /></font></div>'),
(130494, 'ذرء', '<span class=\"hlight\">ذرء.</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع مص ) سپیدی موی . پیری . سپید شدن موی . سپیدمو شدن . پیر گردیدن .<br /></font></div>'),
(130495, 'ذرآنی', '<span class=\"hlight\">ذرآنی .</span> <font color=\"DarkGreen\"><b>[ ذَ آ نی ی <span class=\"hlight\" dir=\"rtl\">/</span> ذَ رَ آ نی ی ]</font></b> (ع ص ) ملح ذرآنی، نوعی از نمک سخت و سپید است . و ملح انذرانی و اندرانی غلط است .<br /></font></div>'),
(130496, 'ذرا', '<span class=\"hlight\">ذرا.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) پناه . کنف . <BR><font color=\"Blue\">◄</font> جای . <BR><font color=\"Blue\">◄</font> مرتبت . در نامه ٔ القائم بامر اﷲ خلیفه ٔ عباسی خطاب به مسعودبن محمودبن سبکتکین به نقل تاریخ بیهقی آمده است : و قصد <font color=\"DarkGreen\"><b>[ امیرالمؤمنین القائم بامر اﷲ ]</font></b> علی منهاج سلفه الصالح وسلک طریقهم المنیر الواضح و هو فی المنحة علی ما یرطب لسانه من الشکر و یقابل مولم الرزیة بما اسبغ اﷲتعالی علیه من الصبر و یتلقی النازلة برضائه بقضائها علی ما سخر له الذی جل ذراه و یقضی حق الشکر فی الحالین لخالقه و مولاه ... و در ترجمه ای که خود ابوالفضل از این جزء نامه کرده است گوید: و پیروی کرد و بجا آورد به روش سلف صالح خود و پیروی کرد راه روشن ایشان را و امیرالمؤمنین در نعمت و راحت ترزبان است بشکر الهی و برابری میکند با بلیه ٔ الم رسان با صبر بسیاری که خدا به او داده است و روبرو میشود با واقعه به آن طریق که رضا بقضا میدهد بر آنچه که این خلق را خدای بلندرتبه به او ارزانی داشته و در هر دو حال قضاء حق شکر خالقش مینماید و صاحبش - انتهی . <BR><font color=\"Blue\">◄</font> پوشش . ستر. <BR><font color=\"Blue\">◄</font> آنچه بر باد شود. <BR><font color=\"Blue\">◄</font> سرشک ریخته از چشم .<br /></font></div>'),
(130497, 'ذراب', '<span class=\"hlight\">ذراب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) (شاید معرب از زهراب ) زهر. سم ّ.<br /></font></div>'),
(130498, 'ذرابت', '<span class=\"hlight\">ذرابت .</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (ع مص ) ذَرابة. ذَرَب . ذُروبت . تیز شدن . <BR><font color=\"Blue\">◄</font> تباه شدن معده و هضم نشدن طعام در آن . <BR><font color=\"Blue\">◄</font> اصلاح گرفتن معده . (از اضداد است ). <BR><font color=\"Blue\">◄</font> ذرابت جرح ؛ درمان نپذیرفتن خستگی .<br /></font></div>'),
(130499, 'ذرات', '<span class=\"hlight\">ذرات .</span> <font color=\"DarkGreen\"><b>[ ذَرْرا ]</font></b> (ع اِ) ج ِ ذرّة <span class=\"hlight\">:</span> <br />انعامش از شمار گذشته است و چون توان <br />ذرات آفتاب فلک را شمار کرد.<br /> <font color=\"Red\">خاقانی .</font><br />جمله ٔ ذرات عالم گوش گشت <br />تا تو فرمائی هر آن فرمان که هست .<br /> <font color=\"Red\">عطار.</font><br />هست آن ذرات جسمی ای مفید<br />پیش این خورشید جسمانی پدید<br />هست ذرات خواطر وافتکار<br />پیش خورشید حقایق آشکار.<br /> <font color=\"Red\">مولوی .</font><br />ذرات صغار هوائی، آنچه که از اجسام ریز در آفتاب ِ از روزن افتاده دیده شود. . <BR><font color=\"Blue\">◄</font> ذرات صغار صلبه ؛ ذره ها که بعقیده ٔ بعض طبیعیون جسم مرکب از آنهاست . ذرات ناریة؛ ذره های آتشی . <br /></font></div>'),
(130500, 'ذراح', '<span class=\"hlight\">ذراح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) دژی است به صنعاءِ یمن .<br /></font></div>'),
(130501, 'ذراح', '<span class=\"hlight\">ذراح .</span> <font color=\"DarkGreen\"><b>[ ذُ <span class=\"hlight\" dir=\"rtl\">/</span> ذُرْرا ]</font></b> (ع اِ) ذروح . رجوع به ذروح و ذراریح شود.<br /></font></div>'),
(130502, 'ذراح', '<span class=\"hlight\">ذراح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) لبن ذراح ؛ شیر با آب آمیخته .<br /></font></div>'),
(130503, 'ذرار', '<span class=\"hlight\">ذرار.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) دانه های متفرقه .<br /></font></div>'),
(130504, 'ذرار', '<span class=\"hlight\">ذرار.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع مص ) بدخو گردیدن ناقة. <BR><font color=\"Blue\">◄</font> خشم . <BR><font color=\"Blue\">◄</font> اعراض .<br /></font></div>'),
(130505, 'ذرار', '<span class=\"hlight\">ذرار.</span><font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع مص ) مذارة. بدخو شدن ناقة. خشم . اعراض .<br /></font></div>'),
(130506, 'ذرارود', '<span class=\"hlight\">ذرارود.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) محلی است و نام رودی به مراغه رجوع به حبیب السیر جزء <span class=\"hlight\" dir=\"rtl\">٤</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧١</span> دوازده سطر به آخر مانده شود.<br /></font></div>'),
(130507, 'ذراری', '<span class=\"hlight\">ذراری .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذَریرة.<br /></font></div>'),
(130508, 'ذراری', '<span class=\"hlight\">ذراری .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذُریّة. فرزندان . فرزندان جن و انس . <BR><font color=\"Blue\">◄</font> زنان <span class=\"hlight\">:</span> قرب صد هزار برده از ذراری و جواری ایشان ... بدست اهل اسلام افتاد. (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٣٩٤</span>). قرب صد هزار برده از اطفال و ذراری و جواری آن ولایت فایدت یافتند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>). کفار و فجار آن ولایت بقتل می آورد و ذراری و اولاد و اطفال به بردگی می گرفت . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>).<br /></font></div>'),
(130509, 'ذراریح', '<span class=\"hlight\">ذراریح .</span> <font color=\"DarkGreen\"><b>[ذَ ]</font></b> (ع اِ) ج ِ ذُروح و ذرّاح . رجوع به ذروح شود.<br /></font></div>'),
(130510, 'ذراریح', '<span class=\"hlight\">ذراریح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذروح . مشمع ذراریح ؛مشمعی که بر آن کوفته ٔ ذروح طلی کنند. و آن منفط است یعنی ایجاد تاول کند.<br /></font></div>'),
(130511, 'ذراریح', '<span class=\"hlight\">ذراریح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) موضعی است میان کاظمة و بحرین .<br /></font></div>'),
(130512, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ارش . (حبیش تفلیسی ) (مهذب الاسماء). رش دست . (منتهی الارب ). رش . (دهار). از آرنج تا انگشتان .از مرفق تا نوک انگشتان . و آن هفت قبضه باشد. از آرنج تا نوک انگشت میانین . گز. (دهار). ساعد. من طرف المرفق الی طرف الأصبع الوسطی . هشت قبضه است . (دمشقی ). ارج . از آرنج تا نوک میانین، آرش . (ملخص اللغات حسن خطیب ). ج، اَذرُع، ذُرعان . و صاحب یواقیت العلوم گوید؛ شش قبضه ذراعی باشد و نسبت ذراع به او شمار نسبت درم است با دینار. چنانکه ده درم هفت مثقال باشد، همچنین ده ذراع هفت وشمار بود - انتهی . و معادل است با <span class=\"hlight\" dir=\"rtl\">٤٨</span> صد یک گز. (<span class=\"hlight\" dir=\"rtl\">٤٨</span> سانتی مطر). <BR><font color=\"Blue\">◄</font> بازو . <BR><font color=\"Blue\">◄</font> آرنج . قوی بنک . <BR><font color=\"Blue\">◄</font> دست . <BR><font color=\"Blue\">◄</font> یاز . <BR><font color=\"Blue\">◄</font> بن نیزه . صدر نیزه . <BR><font color=\"Blue\">◄</font> نام قبیله ای از عرب . <BR><font color=\"Blue\">◄</font> داغ رش شتر. <BR><font color=\"Blue\">◄</font> علامتی است بنی ثعلبه را به یمن و بعض بنی مالک بن سعد را. <BR><font color=\"Blue\">◄</font> گزی که به او چیزها راپیمایند. هرچه بدان پیمایند جامه و زمین و مانند آن را خواه از چوب باشد و خواه از آهن و جز آن . آنچه از چوب یا آهن که بدان پیمایند طول و عرض زمینی یا جامه ای را. <BR><font color=\"Blue\">◄</font> نام دو پشته است در بلاد عمروبن کلاب . <BR><font color=\"Blue\">◄</font> ج، اذرُع . <BR><font color=\"Blue\">◄</font> آستین : ثوب موشّی الذراع ؛ جامه ٔ آستین ها نگارین . <BR><font color=\"Blue\">◄</font> رحب الذراع ؛ واسع القدرة و البطش و القوة. <BR><font color=\"Blue\">◄</font> واسع الذراع ؛ واسعالخُلق . فراخ خوی . <BR><font color=\"Blue\">◄</font> هو منّی علی حبل الذراع ؛ یعنی مستعد و حاضر است . <BR><font color=\"Blue\">◄</font> اولاد ذارع ؛ کلاب و حمیر. اولاد ذراع . اولاد وازِع . <BR><font color=\"Blue\">◄</font> و در حیوان، از دو دست، گاو و گوسفند آنچه بالای پاچه است، و از دست شتر آنچه بالای ساق باریک است و همچنین از دیگر ستور چون اسپ و استر و خر. و منه قولهم : لاتطعم العبد الکراع فیطمع فی الذراع ؛ روستائی گستاخ شده کفش بالا میکند . <BR><font color=\"Blue\">◄</font> ذراع اسود، مقیاسی که مأمون خلیفه نهاد، پیمودن جامه را. و آن چهارهزار یک میل باشد. <BR><font color=\"Blue\">◄</font> ذراع سلطان، یا ذراع سلطانی <span class=\"hlight\">:</span> آنجا <font color=\"DarkGreen\"><b>[ به اسکندریة ]</font></b> مناره ای ساخت سیصد گز، به ذراع الملک، و به ذراع سلطان چهارصد و پنجاه گز باشد. (مجمل التواریخ والقصص ). هر میلی چهار هزارو پانصد ارش <font color=\"DarkGreen\"><b>[ باشد ]</font></b> به ذراع مرسل و سه هزار ارش بذراع سلطانی . (مجمل التواریخ والقصص ). ذِراع ُ المَلِک . رجوع به ذراع سلطان شود. <BR><font color=\"Blue\">◄</font> ذِراع ِ مُکَسَّرَه شش قبضه است . یک ذراع طول در یک ذراع عرض در یک ذراع عمق . و رجوع به مکسّره شود. <BR><font color=\"Blue\">◄</font> ذراع مُرسل <span class=\"hlight\">:</span> هر میلی چهار هزار و پانصد ارش <font color=\"DarkGreen\"><b>[ باشد ]</font></b> به ذراع مرسل و سه هزار ارش به ذراع سلطانی . (مجمل التواریخ والقصص ). در تاریخ قم آمده است : ابوعلی در کتاب همدان حکایت میکند از ابی جعفر محمدبن عبدوس که او گفت ذراعی که عبداﷲ خرداذبه بدان مساحت کرد آن نه قبضه و دو انگشت بود چنانچه میان آن ذراع و ذراع سابوریه تفاوت و نقصان به ربع و ثلث عشر باشدو آن ذراع که به همدان بوده است و در دیوان آن، هشت قبضه و دو انگشت بوده است . محمدبن الحسن از آن گز هیچ نبرید و کم نکرد الاّ یک انگشت . (ص <span class=\"hlight\" dir=\"rtl\">٢٩</span> تاریخ قم ).<br />صاحب کشاف اصطلاحات الفنون گوید: ذراع بکسر ذال و راء مهمله ٔ مخففة به معنی بازو. و از آرنج تا انگشتان . و در حیوانات از پاچه بالاتر را ذراع گویند. و گزی که باو چیزها پیمایند. و ران شُتر. و بُن نیزه . و قبیله ای است . و نام منزلی است از منازل قمر و آن ستاره ای چند است که بر ذراع برج اسد واقع شده اند. و یقال : رجل ٌ واسعالذراع، خوش خلق . کذا فی المنتخب . و الذراع گز. و آن نزد فقهاء بیست و چهار انگشت بهم آمده باشد سوای انگشت نر بعدد حروف شهادتین یعنی لا اله الاّ اﷲ محمّد رسول اﷲ و هر انگشتی شش دانه جو پهلوی هم نهاده باشد بطریقی که بطون هر یک بیکدیگری نهاده بود. و این به ذراع کرباس مشهور است و آن در شرع در میزان عشر معتبر باشد. و علماء هیئت هم آن را در مساحت قُطر زمین و کواکب و ابعاد ستارگان و ثخن افلاک بکار برده اند و این همان ذراع جدید است . اما ذراع قدیم سی و دو انگشت باشد. و گویند که ذراع هاشمی همین است و بعضی ذراع قدیم را بیست و هفت انگشت تقدیر کرده اند. و برخی ذراع کرباس را هفت قبضه و سه انگشت گفته اند و بازگفته اند که ذراع کرباس هفت قبضه است . ولی درنوبت هفتم انگشت را کمتر از آن گفته اند. و جمعی ذراع مساحت را هفت قبضه با یک انگشت ایستاده گیرند. و ذراع مساحت که به ذارع ملک نیز معروف است هفت قبضه است و بالای هر قبضه یک انگشت ایستاده . و برخی ذراع مساحت را هفت قبضه و ذراع کرباس را یک انگشت ایستاده در قبضه ٔ هفتم دانسته اند. و ذراع عامه را که ذراع مکسر نیز مینامند شش قبضه گفته اند و وجه تسمیه ٔ این ذراع به مکسر آن است که از ذراع ملک یعنی ملوک اکاسره یک قبضه کمتر است . و صاحب مغرب این معنی را ذکر کرده است و ذراع های مذکور همگی طولیه باشند و آنها را ذراع خطیةنیز نامند و اما ذراع های سطحی حاصل ضرب ذراع طولی در نفس خویش باشد. و ذراع جسمی حاصل ضرب ذراع طولی درمعرب اوست . چنانچه از بیرجندی و جامعالرموز و پاره ای از کتب حساب مستفاد میگردد. صاحب قاموس مقدس گوید:ذراع، قصد از فاصله فیمابین بند دست و مرفق یا از مرفق تا انتهای انگشت وسطی میباشد و این مقدار ربع پیمایش قامت انسان است . پیمایشی است که در میان قدما بسیار معمول بوده و فعلا در مشرق زمین مخصوصاً در میان الوار معمول است . بعضی گویند که ذراع عبری <span class=\"hlight\" dir=\"rtl\">٢١</span> بحر وسه ربع بحر است و برخی گویند <span class=\"hlight\" dir=\"rtl\">١٨</span> بحر تمام میباشد. تلمودیان برآنند که ذراع عبری یک ربع از ذراع رومانی بلندتر است و به این تقدیر ذراع <span class=\"hlight\" dir=\"rtl\">٢٢</span> بحر میشود و این فقره تقریباً موافق بذراع مقدس مصری است که <span class=\"hlight\" dir=\"rtl\">٢١</span> بحر وسه ربع است و حال اینکه ذراع عمومی ایشان <span class=\"hlight\" dir=\"rtl\">٢٠</span>بحر و ربع بحر میشود. (قاموس کتاب مقدس ). <BR><font color=\"Blue\">◄</font> تاب .توان . طاقت . ذرع : ضاق بالامر ذراعه ؛ سست و ضعیف شد طاقت او و از آن نجات نیافت . <BR><font color=\"Blue\">◄</font> داغ ران شتر. داغ که بر دست اشتر نهند. ج، اذرع . (مهذب الاسماء). ذرعان .<br /></font></div>'),
(130513, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذَرْ را ]</font></b> (ع ص، اِ) شتری نر که ماده ٔ خویش را به ذراع خود خواباند گشنی را. <BR><font color=\"Blue\">◄</font> مشگیزه یعنی مشکولی و خیکچه که آن را از جانب ذراع باز کرده باشند. <BR><font color=\"Blue\">◄</font> پیماینده .<br /></font></div>'),
(130514, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذِ ]</font></b> (ع ص، اِ) زن چابک در رشتن . زنی که سبک ریسد. زن سبک ریس . زن دوک ریس (؟). (مهذب الاسماء).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130515, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) یا ذراع مبسوطه ٔ اسد. منزل هفتم از منازل قمر؛ ای بازوی شیر، نزدیک تازیان . (التفهیم ابوریحان بیرونی ). و آن رقیب بلده است . واز رباطات سیم است . و آن مجموع دو ستاره است بفاصله نیزه ای از یکدیگر بر دو سر توأمین یعنی بر دو سر دو پیکر که یکی را رأس التوأم الغربی و دیگری را رأس التوأم الشرقی خوانند. ستاره ٔ غربی از قدر اول و شرقی از قدر دوم است . و نیز ابوریحان بیرونی در التفهیم گوید: هر دو سر دو پیکر را ذراع مبسوطه نام کرده اند. و حاصل آنکه اسد یا شیر فلک را دو ذراع یعنی دو رش است، مبسوطة و مقبوضة یعنی رش گشاده و رش فراهم آمده و مجدالدین گوید ذراع مبسوطة منزلی از منازل قمر است و صاحب عباب ذراع مقبوضه را منزل قمر گفته است ومقبوضه آن است که از پی ناحیت شام برآید و ماه در آن منزل کند از تلو ناحیت یمن و میان این دو ذراع مقدار تازیانه ای فاصله است و مبسوطه بالاتر است از مقبوضه و مبسوطه را از آن روی مبسوطه نامند که کشیده تر ازمقبوضه است و گاه باشد که قمر عدول کرده و در وی منزل کند و سجع گوئی از عرب گفته است : اذا طلعت الذراع حسرت الشمس القناع و استعلت فی الاُفق الشعاع و ترقرق السراب فی کل قاع . و طلوع ذراع مبسوطه بشب چهارم تموز و سقوط آن بشب چهارم کانون اول باشد. و باز صاحب عباب گوید سقوط آن بشب ششم از کانون دوم است و این قول ابن قتیبه است و ابراهیم حربی گوید طلوع آن در هفتم تموز و سقوط در ششم کانون آخر باشد. و عرب آن را بر ذراع مبسوط اسد یعنی شیرفلک توهم کند و این منزل پس از هنعه و پیش از نثره باشد. و طلوع آن چهار شب از تموز رفته باشد و سقوط آن چهار شب از کانون اول گذشته و آن از آخر هنعه است تا اول سرطان . و نزد احکامیان منزلی سعد است . و ذراع الاسد المبسوطة را ذراع مطلق و ذراع مبسوطه و ذراع الجوزا نیز نامند. ذراع الاسد المقبوضة یا ذراع مقبوضة: ابوریحان بیرونی در التفهیم گوید هر دو ستاره ٔ سگ پیشین <font color=\"DarkGreen\"><b>[ کلب مقدم ]</font></b> را ذراع مقبوضة خوانند. (التفهیم ). و آن یکی از دو ارش اسد (شیر فلک ) و یکی از منازل قمر است و هی التی تلی الشام والقمر ینزل بها. (تاج العروس ). و آن صورت شعریان است تثنیه ٔ شعری و مرکب است از شعری العبور و شعرای شامیه . و مؤلف جهان دانش گوید: ذراع، دو ستاره است روشن بر دوش توأمین . عرب گوید که آن ذراع است و آن را ذراع مبسوطة خوانند و ذراع مقبوضه شعرای شامی را خوانند و بنزدیک بعضی مقبوضه این است و ماه آن را بپوشاند. و آن منزل هفتم است از منازل قمر و رقیب آن بلده باشد. جهان دانش ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>. و باز بیرونی در آثارالباقیةآرد پس از شرح هنعة: ثم الذراع، و هی کوکبان بینهمامقدار ذراع، و احدهما الشعری الغمیصاء ای الرمصا، وهی الشامیة و هذه الذراع هی ذراع الأسد المبسوطة عندالعبر و المقبوضة التی هی احد کوکبیها الشعری العبورو هی الیمانیة. فامّا المبسوطة عند المنجمین فهی رأس التوأمین و المقبوضة هی من کواکب الکلب المتقدم وفیما بینهم فیها خلافات کثیرة و فی تسمیتها بما سمّوها به احادیث و اخبار خرافات . و طلوع الغمیصاء لسنة الف و ثلثمائة للأسکندر لعشر تخلو من تموز. و العبر الّتی هی الیمانیة لثلث و عشرین لیلة منه - انتهی .<br /></font></div>'),
(130516, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذَرْ را ]</font></b> (اِخ ) احمدبن نصر. محدثی ضعیف است .<br /></font></div>'),
(130517, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذَرْ را ]</font></b> (اِخ ) اسماعیل بن صدیق . (محدث است ).<br /></font></div>'),
(130518, 'ذراع', '<span class=\"hlight\">ذراع .</span> <font color=\"DarkGreen\"><b>[ ذَرْ را ]</font></b> (اِخ ) اسماعیل بن نصر. محدث و ضعیف است . و بعضی احمدبن نصر گفته اند.<br /></font></div>'),
(130519, 'ذراع الجوزا', '<span class=\"hlight\">ذراع الجوزا.</span> <font color=\"DarkGreen\"><b>[ ذِ عُل ْ ج َ ]</font></b> (اِخ ) ذراع الأسد المبسوطة. ذراع مبسوطة.<br /></font></div>'),
(130520, 'ذراع رشیدیه', '<span class=\"hlight\">ذراع رشیدیه .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِرَ دی ی َ ]</font></b> (ترکیب وصفی، اِمرکب ) در تاریخ قم آمده است : و از قومی اهل قم روایت است که ذراع رشیدیه ابراهیم بن شاذو که نام او ملک بن محمّد احوص بود به قم آورد و این غلط است زیرا که ابراهیم روزگار رشید را درنیافت ولیکن ابراهیم بن الیسع بود و او را در آن مساحت اثری محمود بود و سیرت پسندیده از وی باز ماند و حمزةبن معلی اشعری او را و مصقلةبن اسحاق را در شعری که منسوب است بدو مدح کرده است و الیسع را ذم ّ و نکوهش . مگر ابراهیم در این مساحت از عراق ذراعی دیگر به قم آورده است امّا من که مصنف این کتابم این روایت و این خبر ندیده ام و نشنیده ام . واﷲ اعلم . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>). و باز در تاریخ قم آمده است : هارون الرشید التماس حمزه ٔبن یسع مبذول داشت و سؤال او را بنجاح مقرون گردانید... و گزی را بدو داد که آن را ذراع رشیدیّه میخوانند و آن گز درازترین و بزرگترین گزهای دنیا بود. حمزه را گفت این ذراع را بستان و در زیر بغل نه و آنقدر که توانی دست خود را بکش تا آن مقدار که سر انگشت تو بدان رسد از حساب ذراع گیر. حمزه گز رابستد و محکم بزیر بغل خود کوفت تا غایت که بعضی از گز در زیر بغل او رفت و خون ازو روان شد او را گفتنداین چه بود که تو با خود کردی گفت من صلاح قوم خود وآسانی ایشان میخواستم . واﷲ اعلم . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br /></font></div>'),
(130521, 'ذراع سابوری', '<span class=\"hlight\">ذراع سابوری .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) در تاریخ قم آمده است : ابوعلی کاتب در کتاب همدان حکایت میکند از ابی جعفرمحمدبن عبدوس که او میگفت ذراعی که اهل همدان بدان مساحت میکردند پیش از روزگار مأمون او را ذراع سابوری میگفتند و آن ذراع عبارت از دوازده قبضه بود و مثال آن بر ستون مسجد اعظم منقّش کرده اند و نشان و نمودار آن تا الیوم باقی است . تا بدینجا حکایت ابوعلی است . پس این گز که مثال آن مصوّر است در مسجد سهل بن الیسعبن عبداﷲ به میدان الیسع گزی است که حمزةبن الیسع از نزدیک هارون الرشید آورد و آن ذراع به قم به رشیدیّه معروف و مشهور است و به همدان به سابوریّه . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٩</span>).<br /></font></div>'),
(130522, 'ذراع عاصمیه', '<span class=\"hlight\">ذراع عاصمیه .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ ص ِ می ی َ ]</font></b> (ترکیب وصفی، اِمرکب ) عاملی را با وی «حمزه » بفرستاد تا ضیعت های قم را بپیماید و گزی که آن را رشیدیّه خوانند و بدان معروف و مشهور است بدو داد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>). و در ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> آمده است که : و این ذراع رشیدیه که یاد کردیم آن ذراع است که عاصمیه معروف است ... و نیز گفته اندکه این ذراع رشیدیّه که حمزه به قم آورد غیر ذراع عاصمیه است . این جداست و آن تنها. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>).<br /></font></div>'),
(130523, 'ذراع مرسله', '<span class=\"hlight\">ذراع مرسله .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ م ُ س َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) نیم ذرع متعارف ماست . یاقوت در معجم البلدان در شرح کلمه ٔ سواد گوید: و طول الفرسخ اثنا عشر الف ذراع بالذراع المرسلة. پس از این روی ذراع مرسله نیم ذرع متعارف امروزی است و باز گوید: و یکون بذراع المسافة و هی الذراع الهاشمیة تسعة آلاف ذراع .<br /></font></div>'),
(130524, 'ذراع مسافت', '<span class=\"hlight\">ذراع مسافت .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ م َ ف َ ]</font></b> (ترکیب اضافی، اِ مرکب ) ذراع هاشمیة.<br /></font></div>'),
(130525, 'ذراع مکسره', '<span class=\"hlight\">ذراع مکسره .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ م ُ ک َس ْ س َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاحی حفاران را است ) و مثال آن : ده ذراع طول در دو ذراع عرض در پنج ذراع عمق صد ذراع مکسره شود.<br /></font></div>'),
(130526, 'ذراع هاشمیه', '<span class=\"hlight\">ذراع هاشمیه .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِش ِ می ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) یک ذرع و نیم بذرع متعارف ما است و آن را ذراع مسافت نیز نامند.یاقوت در معجم البلدان در شرح کلمه ٔ سواد گوید: و طول الفرسخ اثنا عشر الف ذراع بالذراع المرسلة و یکون بذراع المسافة و هی الذراع الهاشمیة تسعة آلاف ذراع .<br /></font></div>'),
(130527, 'ذراع یمنی', '<span class=\"hlight\">ذراع یمنی .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ ی ُ نا ]</font></b> (اِخ ) ستاره ای است از قدر سیم بر دست راست قیقاوس . (کیکاوس . ملتهب ) .<br /></font></div>'),
(130528, 'ذراعان', '<span class=\"hlight\">ذراعان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) نام دو پشته است . (معجم البلدان یاقوت ).<br /></font></div>'),
(130529, 'ذراعان', '<span class=\"hlight\">ذراعان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) تثنیه ٔ ذراع . و مراد از آن در نزد منجمین ذراع الاسد المبسوطة وذراع الاسد المقبوضة است . رجوع به این دو کلمه شود.<br /></font></div>'),
(130530, 'ذراعة', '<span class=\"hlight\">ذراعة.</span> <font color=\"DarkGreen\"><b>[ ذَرْ را ع َ ]</font></b> (اِخ ) المعدیة: و من المجانین و الموسوسین و النوکی : ابن خنان و صباح الموسوس و... و منهم دُغَة و جهیزة و شولة و ذرّاعةالمعدیة. (ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span> ج <span class=\"hlight\" dir=\"rtl\">٢</span> از البیان والتبیین ).و در عقدالفرید آمده است که : النوکی من نساء الاشراف، ذغة العجیله و جهیزة و شولة و ذراعة. (ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>).<br /></font></div>'),
(130531, 'ذرافن', '<span class=\"hlight\">ذرافن .</span> (اِخ ) ذراقن . نام پسر بقراط حکیم مشهور یونان . (عیون الانباء ابن ابی اصیبعة ص <span class=\"hlight\" dir=\"rtl\">٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br /></font></div>'),
(130532, 'ذراقن', '<span class=\"hlight\">ذراقن .</span> (اِخ ) رجوع به ذرافن شود.<br /></font></div>'),
(130533, 'ذرانح', '<span class=\"hlight\">ذرانح .</span> (اِخ ) موضعی است میان کاظمة و بحرین . یاقوت . و گوید محتمل است ذرایح باشد بصیغه ٔ جمع ذریحه .<br /></font></div>'),
(130534, 'ذرایب', '<span class=\"hlight\">ذرایب .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع ص، اِ) ج ِ ذریبة. و ذریب بمعنی حادّ.<br /></font></div>'),
(130535, 'ذرایب', '<span class=\"hlight\">ذرایب .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (اِخ ) نام موضعی است به بحرین .<br /></font></div>'),
(130536, 'ذرایح', '<span class=\"hlight\">ذرایح .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع ص، اِ) ج ِ ذریحه . و رجوع به ذرانح شود.<br /></font></div>'),
(130537, 'ذرایر', '<span class=\"hlight\">ذرایر.</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع اِ) رجوع به ذرائر شود.<br /></font></div>'),
(130538, 'ذرایع', '<span class=\"hlight\">ذرایع.</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع اِ) ج ِ ذَریعَة. وسایل . وسایط. دست آویزها <span class=\"hlight\">:</span> شوافع و ذرایع که سیمجوریان را بر دولت آل سامان ثابت است مهمل نگذارند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). سلطان آن وسائل و ذرایع بنظر قبول ملاحظه فرمود. (ترجمه ٔ تاریخ یمینی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span>). من نیز بنده ٔ قدیمم و به ذرایع خدمات شایسته، حقوق ثابت گردانیده ام . (جهانگشای جوینی ). در مقدّمه ٔ مشایعت بندگی دولت و متابعت هواداری اخلاص حضرت به ذرایع متین و وسائل مبین اختصاص یافته بود. (جهانگشای جوینی ).<br /></font></div>'),
(130539, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) نشگرده ٔ کفشگران . ازمیل اسکاف . شفرة الحذّاء.<br /></font></div>'),
(130540, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) حدید. تیز.<br /></font></div>'),
(130541, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع مص ) بذائت لسان . زبان درازی . بدزبانی . ج، اَذراب . <BR><font color=\"Blue\">◄</font> تیز شدن شمشیر و زبان و امثال آن . <BR><font color=\"Blue\">◄</font> تباه شدن ریش و فراخ گردیدن آن یا روان گردیدن زرداب از وی . تباه شدن جراحت . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذَرب ُ جرح ؛ دوا نپذیرفتن خستگی . <BR><font color=\"Blue\">◄</font> اسهال پیچ . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> تباه شدن معده . و فی الحدیث، فی البان الابل و ابوالها شفاءُ للذرب . و هو داءٌ یعرض المعدة فلا ینهضم الطعام و یفسد فیها و لا یمسک . <BR><font color=\"Blue\">◄</font> اصلاح گرفتن معده (از اضداد است ). <BR><font color=\"Blue\">◄</font> آزاری که به نشود. <BR><font color=\"Blue\">◄</font> زنگ . صَدَاء. <BR><font color=\"Blue\">◄</font> اسهال . شکم روش . <BR><font color=\"Blue\">◄</font> سخن بد. بیهوده گفتن . ذروبت . ذَرابت .<br /></font></div>'),
(130542, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ]</font></b> (اِخ ) ابن حوط. در البیان والتبیین ذیل (باب من اسماءالکهان و الحکام و الخطباء و العلماء من قحطان ) آرد: از قدمای در حکمت و خطابه و ریاست . عُبَیدبن شرّیةالجرهمی و اسقف نجران و... و ذَرِب بن حوط و علیم بن جناب و... اند.<br /></font></div>'),
(130543, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذَرِب .<br /></font></div>'),
(130544, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذِ رَ ]</font></b> (ع اِ) ج ِ ذِربَة.<br /></font></div>'),
(130545, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ]</font></b> (ع ص ) تیز از هر چیزی : سیف ذَرِب ؛ شمشیری تیز، سیف ٌ حدید. لسان ذَرِب ؛ زبان تند و تیز و بد. <BR><font color=\"Blue\">◄</font> مرد بذی ّاللسان ؛ مرد بدزبان . مرد زبان دراز. <BR><font color=\"Blue\">◄</font> تیز زبان . <BR><font color=\"Blue\">◄</font> (اِ) نشگرده . ازمیل . شفرة. ج، ذُرب .<br /></font></div>'),
(130546, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) سنگریزه مانندی است که در زیر پوست برگردن آدمی یا ستور پیدا آید. <BR><font color=\"Blue\">◄</font> مرضی از امراض جگر و آن سنگ یعنی حصاة پیدا کردن کبد باشد.<br /></font></div>'),
(130547, 'ذرب', '<span class=\"hlight\">ذرب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) تیز کردن چیزی را.<br /></font></div>'),
(130548, 'ذربان', '<span class=\"hlight\">ذربان .</span> (اِخ ) ابن عتیق بن تمیم الکاتب، مکنی به ابی القاسم . حافظ ابوطاهر سلفی در معجم الشعراء از او و وی از ابوحفص الزکرمی العروضی قطعه ای از شعر زکرمی را روایت کرده است . معجم الادباء یاقوت چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٩</span> س <span class=\"hlight\" dir=\"rtl\">٦</span>.<br /></font></div>'),
(130549, 'ذربان', '<span class=\"hlight\">ذربان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) موضعی است در شعر.<br /></font></div>'),
(130550, 'ذربة', '<span class=\"hlight\">ذربة.</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ب َ ]</font></b> (ع ص ) تأنیث ذَرِب .<br /></font></div>'),
(130551, 'ذربة', '<span class=\"hlight\">ذربة.</span> <font color=\"DarkGreen\"><b>[ ذَ ب َ ]</font></b> (اِخ ) آبی است بنوعقیل را به نجد. بروایت یاقوت از ابی زیاد.<br /></font></div>'),
(130552, 'ذربة', '<span class=\"hlight\">ذربة.</span> <font color=\"DarkGreen\"><b>[ ذِ ب َ ]</font></b> (ع اِ) غُدّة. گره گوشت . سنگریزه مانندی که در گردن مردم یا ستور پیدا آید. <BR><font color=\"Blue\">◄</font> (ص ) زن بدزبان . زن زبان دراز. بذیةاللسان و خیانتکار.(منتهی الارب ). بلندآواز. (مهذب الاسماء). ج، ذَرِب .<br /></font></div>'),
(130553, 'ذربی', '<span class=\"hlight\">ذربی .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ با <span class=\"hlight\" dir=\"rtl\">/</span> ذَ رَ بی ی ]</font></b> (ع اِ) سختی و بلا.<br /></font></div>'),
(130554, 'ذربیا', '<span class=\"hlight\">ذربیا.</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ب َی ْ یا ]</font></b> (ع اِ) عیب . آهو. <BR><font color=\"Blue\">◄</font> سختی و بلا. سختی . (مهذب الاسماء). ذَرَیَبّا.<br /></font></div>'),
(130555, 'ذربیات', '<span class=\"hlight\">ذربیات .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ بی یا ]</font></b> (ع اِ) عیب . آهو. <BR><font color=\"Blue\">◄</font> سختی و بلا.<br /></font></div>'),
(130556, 'ذربین', '<span class=\"hlight\">ذربین .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ب َ ]</font></b> (ع اِ) تثنیه ٔ ذَرَب . رماه بِالذَرَبین ؛ متهم کرد او را ببدی و خلاف .<br /></font></div>'),
(130557, 'ذرت', '<span class=\"hlight\">ذرت .</span> <font color=\"DarkGreen\"><b>[ ذُرْ رَ ]</font></b> (ع اِ) گیاهی است چون نی و آن را میوه ای به بزرگی یک و دو خیار بلفافهائی پیچیده و به درون میوه چوبی است که خوردنی نیست و بر آن دانه های بسیار منتظم و پیوسته هست هر یک چند نخودی خرد که تمام سطح را پوشیده است و آن دانه ها خوراکی باشد که برشته کنند و یا در آب پزند خوردن را بلال . گندم ِ مَکه . گَندُمَکَه . مَکَه گندم مصری . گندم مکی .<br /></font></div>'),
(130558, 'ذرت خوشه ای', '<span class=\"hlight\">ذرت خوشه ای .</span> <font color=\"DarkGreen\"><b>[ ذُ رْ رَ ت ِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ترکیب وصفی، اِمرکب ) قسمی از حبوب غذائی بومی افریقا و هند و بالای آن گاه به چهار تا پنج گز رسد.<br /></font></div>'),
(130559, 'ذرح', '<span class=\"hlight\">ذرح .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ ]</font></b> (اِخ ) نام پدر یزید سکونی شاعر.<br /></font></div>'),
(130560, 'ذرح', '<span class=\"hlight\">ذرح .</span> <font color=\"DarkGreen\"><b>[ ذُرْ رَ ]</font></b> (ع اِ) ذروح . رجوع به ذروح و ذراریح شود.<br /></font></div>'),
(130561, 'ذرح', '<span class=\"hlight\">ذرح .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع اِ) درختی است که از چوب آن پالان سازند.<br /></font></div>'),
(130562, 'ذرح', '<span class=\"hlight\">ذرح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذرح طعام ؛ ذراح در وی افکندن . <BR><font color=\"Blue\">◄</font> ذرح شی ٔ در ریح ؛ بباد دادن آن یعنی پرانیدن آن را بباد.<br /></font></div>'),
(130563, 'ذرحرح', '<span class=\"hlight\">ذرحرح .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ رَ ]</font></b> (اِخ ) یوم ذرحرح ؛ نام جنگی است میان بنوسعد و غَسان .<br /></font></div>'),
(130564, 'ذرحرح', '<span class=\"hlight\">ذرحرح .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُرْرَ رَ ]</font></b> (ع اِ) ذروح . رجوع به ذروح و ذراریح شود.<br /></font></div>'),
(130565, 'ذرحوح', '<span class=\"hlight\">ذرحوح .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ذروح . رجوع به ذروح و ذراریح شود.<br /></font></div>'),
(130566, 'ذرخش', '<span class=\"hlight\">ذرخش .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ رُ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ رُ ]</font></b> (اِ) بر وزن و معنی درخش است که برق و تابیدن و روشنی باشد. (برهان قاطع). و در لغت نامه ٔ اسدی آمده است، ذرخش برق است و گویند که در زبان پارسی هیچ کلمه نیست که اوّل او ذال باشد جز این کلمه . ابوشکور گوید <span class=\"hlight\">:</span> <br />ذرخش ار نخندد بگاه بهار<br />همانا نگریدچنین ابر زار.<br />و امروز درخش با دال مهمله و درخشان و درخشیدن به کسر دال و فتح راء متداول است . رجوع به درخش شود.<br /></font></div>'),
(130567, 'ذرذار', '<span class=\"hlight\">ذرذار.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) بسیارگوی . پرگوی . مکثار. <BR><font color=\"Blue\">◄</font> (اِخ ) لقب مردی .<br /></font></div>'),
(130568, 'ذرز', '<span class=\"hlight\">ذرز.</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع مص ) بر لذتهای دنیا قادر گردیدن .<br /></font></div>'),
(130569, 'ذرع', '<span class=\"hlight\">ذرع .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع اِ) طمع. اُمید. <BR><font color=\"Blue\">◄</font> گوساله ٔ دشتی . ج، ذِرعان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ماده شتری که صیاد در پس آن نهان شده بصید تیر افکند.<br /></font></div>'),
(130570, 'ذرع', '<span class=\"hlight\">ذرع .</span><font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) خُلق . سیرت . خو: هو واسعالذرع ؛ ای واسعالخلق . او فراخ خوی است . <BR><font color=\"Blue\">◄</font> دِل . <BR><font color=\"Blue\">◄</font> قوت . <BR><font color=\"Blue\">◄</font> توان . تاب . توانائی . طاقت . ذراع . ضاق بالأمر ذرعه ؛ سست و ضعیف شد طاقت او و بمقصود نرسید یا از مکروهات نجات نیافت . و یقال، ابطرت فلاناً ذرعه ؛ ای کلفته اکثر من طوقه . <BR><font color=\"Blue\">◄</font> دل ؛ کبر فی ذرعی ای فی قلبی، ای عظم وقعه و جل عندی . <BR><font color=\"Blue\">◄</font> تن . نفس : اقصد بذرعک ؛ نرمی و رفق کن با تن خود. <BR><font color=\"Blue\">◄</font> قدر. ذرع کل شی ٔ؛ قدره مما یذرع . <BR><font color=\"Blue\">◄</font> گوشه ٔ کشت . رودکی گوید <span class=\"hlight\">:</span> <br />زرع و ذرع از بهار شد چو بهشت <br />زرع کشت است و ذرع گوشه ٔ کشت . <br /></font></div>'),
(130571, 'ذرع', '<span class=\"hlight\">ذرع .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) گز. ارش . رش . ساق دست . <BR><font color=\"Blue\">◄</font> ذرع، چون مطلق گویند معادل شانزده گز است یعنی یک متر وچهار صدم یک متر و در ذرع شاه یک متر و دوازده صدم یک متر است (و بیشتر در تبریز متداول است ) و ذرع مقصر. مساوی یک متر و چهار صدم یک متر است . (و آن در طهران و فارس معمول است ). <BR><font color=\"Blue\">◄</font> ذرع نیشابوری، دو برابر و نیم ذرع شاهی است . <BR><font color=\"Blue\">◄</font> ذرع مکعب یک ذرع در ابعاد ثلاثة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذرع کردن </span> ؛ به گز پیمودن . به گز کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذرع و پیمان کردن </span> ؛ فعل اتباعی، ذرع کردن (مخصوص زمین است ).<br /></font></div>'),
(130572, 'ذرع', '<span class=\"hlight\">ذرع .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) به گز کردن . گز کردن و پیمودن جامه را به ذراع . به ارش پیمودن . (تاج المصادربیهقی ). <BR><font color=\"Blue\">◄</font> ذرع قیئی کسی را؛ غلبه کردن قیئی بر او و تاب نیاوردن بمنع آن . <BR><font color=\"Blue\">◄</font> غلبه کردن قیئی بر مردم . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذرع بعیر؛ پای بر ذراع اشتر نهادن سوار شدن را. <BR><font color=\"Blue\">◄</font> ذرع کسی ؛ خبه کردن او را به ذراع از پس وی . <BR><font color=\"Blue\">◄</font> آب خوردن از مشک و یا عام است . <BR><font color=\"Blue\">◄</font> ذَرِع َ الیه ؛ شفاعت کرد نزد وی . <BR><font color=\"Blue\">◄</font> ذرع رجلین ؛ مانده گردیدن هر دو پای . <BR><font color=\"Blue\">◄</font> سبقت بردن ؛ ذرعه، سبق الی فیه . (اقرب الموارد).<br /></font></div>'),
(130573, 'ذرع', '<span class=\"hlight\">ذرع .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ]</font></b> (ع ص ) مرد سخت بدگوی . <BR><font color=\"Blue\">◄</font> مرد شباروزرونده . <BR><font color=\"Blue\">◄</font> مرد نیکوصحبت .<br /></font></div>'),
(130574, 'ذرع مقصر', '<span class=\"hlight\">ذرع مقصر.</span> <font color=\"DarkGreen\"><b>[ذَ ع ِ م ُ ق َص ْ ص َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مساوی است با (<span class=\"hlight\" dir=\"rtl\">١/٠٤</span>) متر. و آن در طهران و فارس معمول است .<br /></font></div>'),
(130575, 'ذرعات', '<span class=\"hlight\">ذرعات .</span> <font color=\"DarkGreen\"><b>[ ذَ رِ ]</font></b> (ع اِ) ناقه های تیزرو و فراخ گام و دوردور گام گذارنده بر زمین . <BR><font color=\"Blue\">◄</font> قوائم ذَرِعات ؛ ای سریعات .<br /></font></div>'),
(130576, 'ذرعان', '<span class=\"hlight\">ذرعان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ج ِ ذَرَع . گوساله های دشتی . <BR><font color=\"Blue\">◄</font> (اِخ ) نام دو ستاره است . (مهذب الاسماء).<br /></font></div>'),
(130577, 'ذرعان', '<span class=\"hlight\">ذرعان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ ذِراع .<br /></font></div>'),
(130578, 'ذرعان', '<span class=\"hlight\">ذرعان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ج ِ ذَرَع .<br /></font></div>'),
(130579, 'ذرعة', '<span class=\"hlight\">ذرعة.</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (اِخ ) ابن کعب (<span class=\"hlight\" dir=\"rtl\">٤٤٢</span> - <span class=\"hlight\" dir=\"rtl\">٥١٠</span> م .).ملقب به ذونواس الحمیری از ملوک یمن در جاهلیت . گویند او همان صاحب الأخدود قرآن کریم است، وی دین یهودداشت و بدو برداشتند که مردم نجران به دین ترسائی گرائیده اند او بجانب ایشان شد و اخادید را حفر کرد و از آتش بینباشت و سران ترسا را بدانجا گرد کرد و در آتش افکند و مرتدین از دین یهود بسوختند و آنانکه به یهودیت بازگشتند نجات یافتند و نجاشی پادشاه حبشه از این امر آگاهی یافت و وی دین نصرانی داشت، با سپاه بسیار به صنعا حمله برد و ذونواس در ساحل بحر احمر نزدیک عدن بمقابله ٔ وی شتافت و نجاشی پیروزی یافت . ذونواس از ترس اسارت اسب به دریا راند و غرقه گشت . (الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٢</span> و <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). و رجوع به ذونواس شود.<br /></font></div>'),
(130580, 'ذرعة', '<span class=\"hlight\">ذرعة.</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (اِخ ) ابن شریک . نام یکی از قتله ٔ حسین بن علی، سیدالشهداء علیهماالسلام است . رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> شود.<br /></font></div>'),
(130581, 'ذرعة', '<span class=\"hlight\">ذرعة.</span> <font color=\"DarkGreen\"><b>[ ذُ ع َ ]</font></b> (ع اِ) ذریعة. وسیله ٔ دست آویز و آنچه بدو بدیگری پیوندند. سبب .<br /></font></div>'),
(130582, 'ذرعم', '<span class=\"hlight\">ذرعم .</span> <font color=\"DarkGreen\"><b>[ ذِ ع ِ ]</font></b> (ع ص ) هیچکاره ٔ پلیدزبان . (منتهی الارب ).<br /></font></div>'),
(130583, 'ذرعمط', '<span class=\"hlight\">ذرعمط.</span> <font color=\"DarkGreen\"><b>[ ذُ رَ م ِ ]</font></b> (ع ص ) شیر سطبر. شیرغلیظ. <BR><font color=\"Blue\">◄</font> مرد آزمند و خواهنده ٔ هر چیز.<br /></font></div>'),
(130584, 'ذرعی', '<span class=\"hlight\">ذرعی .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ص نسبی ) منسوب بذَرع . مال ذرعی، جامه . پارچه . قماش . نسیج . منسوج .<br /></font></div>'),
(130585, 'ذرعینة', '<span class=\"hlight\">ذرعینة.</span> <font color=\"DarkGreen\"><b>[ ذَ ن َ ]</font></b> (اِخ ) نام قریه ای است به بخارا.<br /></font></div>'),
(130586, 'ذرعینی', '<span class=\"hlight\">ذرعینی .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ص نسبی ) منسوب به ذرعینه، قریه ای از قراء بخارا. (سمعانی ).<br /></font></div>'),
(130587, 'ذرف', '<span class=\"hlight\">ذرف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذُرفان . ذُروفان . ذروف . ذَریف . تِذراف . روان گردیدن سرشک . بردویدن اشک . رفتن اشک از چشم . رفتن اشک و جز آن . (زوزنی ). ذرفت عینیه ؛ روان شد اشک چشم او. <BR><font color=\"Blue\">◄</font> روان کردن : ذرفت العین دمعها؛ روان کرد چشم اشک خود را. <BR><font color=\"Blue\">◄</font> جاری و روان شدن و دویدن و جاری و روان کردن آب و هر مایعی دیگر.<br /></font></div>'),
(130588, 'ذرفان', '<span class=\"hlight\">ذرفان .</span> <font color=\"DarkGreen\"><b>[ ذَ رَ ]</font></b> (ع مص ) روان گردیدن سرشک . <BR><font color=\"Blue\">◄</font> ذرف . روان کردن سرشک . <BR><font color=\"Blue\">◄</font> (اِ) رفتار سست و نرم .<br /></font></div>'),
(130589, 'ذرفان', '<span class=\"hlight\">ذرفان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذرف . رفتن اشک و جز آن . (زوزنی ).<br /></font></div>'),
(130590, 'ذرق', '<span class=\"hlight\">ذرق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) پیخال . سرگین مرغ . (مهذب الاسماء). ریخ . (زمخشری ). فضله ٔ طیر. چلغوز مرغ . روث طیور. (داود ضریر انطاکی ).<br /></font></div>'),
(130591, 'ذرق', '<span class=\"hlight\">ذرق .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ ]</font></b> (ع اِ) حندقوقا. حندقوقی . حباقی . سپست دشتی . آسپست دشتی . حندقوق . حندقوقی بری . حندقوقای بستانی (؟) دیوسپست . دیوآسپست . عرقضان . عرقصا. عرقصان . عریقصاء. عریقصان . عریقصانة و در ترجمه ٔ صیدنه ٔ ابوریحان آمده است : ذُرَق، ابوحنیفه گوید، نباتی است که به هیئت به گندناء کوهی مشابهت دارد بر سر نبات او وعائی بود که تخم اودر آنجا بود و دانه ٔ او گردفام بود و در وقت تری اورا بخورند و چون خشک شود بیش نخورند و بیخ او بشکل پیاز بود و رنگ او سیاه بود و چون پوست سیاه از او جدا کنند از میان او بشبه پیاز سفید چیزی بیرون آید وشیرینی در طعم او بود و آب در او بسیار بود و آدمیان پیاز او را بخورند و لیث گوید ذرق نباتی است که به سپست ماند و در شهر او را حندقوقا گویند. و ابن البیطار گوید: ذرق هو الحندقوقی . قال ابوحنیفه قال ابوزیاد من العشب الذرق و یسمی العرقصان و فیه شبه من القت یطول فی السماء و ینبت کما ینبت القت و هو ینبت فی القیعان و منافع المیاه و قد رأیته بالعراق و یبیعه الانباط و یسمونه الحندقوقی و قد ذکرته فی الحاء.<br /></font></div>'),
(130592, 'ذرق', '<span class=\"hlight\">ذرق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) سرگین افکندن مرغ . (تاج المصادر بیهقی ). فضله افکندن طیور. سرگین اوکندن مرغ . (زوزنی ). پیخال افکندن . ریخ زدن مرغ . اِذراق . <BR><font color=\"Blue\">◄</font> (اِ) بلغنی ذرق من قول ؛ ای طرف . (مهذب الاسماء) (لغت نامه ٔ اسدی ).<br /></font></div>'),
(130593, 'ذرق الخطاطیف', '<span class=\"hlight\">ذرق الخطاطیف .</span> <font color=\"DarkGreen\"><b>[ ذَ قُل ْ خ َ ]</font></b> (ع اِ مرکب ) سرگین پرستوک .صاحب اختیارات گوید: به پارسی سرگین پرستوک خوانند چون در چشم کشند سپیدی که در چشم بود زایل گرداند.<br /></font></div>'),
(130594, 'ذرق الطیر', '<span class=\"hlight\">ذرق الطیر.</span> <font color=\"DarkGreen\"><b>[ ذَ قُطْ طَ ]</font></b> (ع اِ مرکب ) فضله ٔ پرندگان . <BR><font color=\"Blue\">◄</font> خرفطان . بنتومة. رقعةالفارسیة. عنم . داود ضریر انطاکی در تذکره گوید: ذرق، یطلق علی روث الطیور و کل ّ مع اصله . و اذا قید بذرق الطیور فالبنتومة . و ابن البیطار در مفردات آرد: هو النبات المعروف بالیونانیة بالبنتومة.<br /></font></div>'),
(130595, 'ذرق الطیور', '<span class=\"hlight\">ذرق الطیور.</span> <font color=\"DarkGreen\"><b>[ ذَ قُطْ طُ ]</font></b> (ع اِ مرکب ) رجوع به ذرق الطیر شود.<br /></font></div>'),
(130596, 'ذرم', '<span class=\"hlight\">ذرم .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) سقط جنین . افکندن زن بچه ٔ خود را. فکانه کردن جنین .<br /></font></div>'),
(130597, 'ذرمازی', '<span class=\"hlight\">ذرمازی .</span> <font color=\"DarkGreen\"><b>[ ذَ زی ی ]</font></b> (اِخ ) محمدبن فضل . محدث است و ابوحفص شاهین از او روایت کند.<br /></font></div>'),
(130598, 'ذرملة', '<span class=\"hlight\">ذرملة.</span> <font color=\"DarkGreen\"><b>[ ذَ م َ ل َ ]</font></b> (ع مص ) ریخ زدن . سلح . <BR><font color=\"Blue\">◄</font> نان خاکسترآلود از تنور بیرون کردن تا زود پیش مهمان نهند.<br /></font></div>'),
(130599, 'ذرنوح', '<span class=\"hlight\">ذرنوح .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ذروح . ذرّاح . رجوع به ذروح و ذراریح شود.<br /></font></div>'),
(130600, 'ذره', '<span class=\"hlight\">ذره .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) هر جزء غبار منتشر در هوا و جز آن . چیزهای نهایت خرد که از روزن پیدا آید چون آفتاب یا روشنی بر وی تابد. صاحب کشاف اصطلاحات الفنون گوید: نصف از سدس قطمیر است (یعنی دوازده یک ) و بعضی گفته اند که ذرّه را وزنی نباشد چنانچه در بحر الجواهر گفته - انتهی . <BR><font color=\"Blue\">◄</font> و صد ذره مقدار یک جو باشد. یعنی ذره صدیک، یعنی یک حصه از صد حصه جو بود. ج، ذرّ، ذرّات <span class=\"hlight\">:</span> <br />صورت خشمت ار ز هیبت خویش <br />ذره ای را بخاک بنماید<br />خاک دریا شود بسوزد آب <br />بفسرد آفتاب و بشجاید.<br /> <font color=\"Red\">دقیقی .</font><br />هر قطره ای ز جودت رودیست همچو جیحون <br />هر ذره ای ز حلمت کوهی است چون بذیل .<br />رفیعی (از حاشیه ٔ لغت نامه ٔ خطی اسدی متعلق به نخجوانی ).<br />بافسون همان سنگ بر جای خویش <br />ببست و نغلطید یک ذرّه پیش .<br /> <font color=\"Red\">فردوسی .</font><br />ای بر سر خوبان جهان بر سر جیک <br />پیش دهنت ذره نماید خرجیک .<br /> <font color=\"Red\">عنصری .</font><br />ور بدرّی شکم و بندم از بندم <br />نرسد ذره ای آزار بفرزندم .<br /> <font color=\"Red\">منوچهری .</font><br />مدان مرخصم را خرد ای برادر<br />که سوزد عالمی یک ذرّه آذر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />غلط گفتم ز ذره کمتر است این <br />که زی خورشیدانور میفرستم .<br /> <font color=\"Red\">ابوالفرج رونی .</font><br />آن از کوه ... ذره ای بود. (کلیله و دمنه ).<br />ماندبعنکبوت سطرلاب آفتاب <br />زو ذرّه های لایتجزا برافکند.<br /><font color=\"Red\">خاقانی .</font><br />نیست یکی ذرّه جهان نازکش <br />پای ز انبازی او باز کش .<br /> <font color=\"Red\">نظامی .</font><br />خورشید رخ ترا کند ذکر<br />هر ذرّه اگر شودزبانی .<br /> <font color=\"Red\">عطار.</font><br />ذره ذره کاندرین ارض و سماست <br />جنس خود را همچو کاه و کهرباست .<br /> <font color=\"Red\">مولوی .</font><br />قدر آن ذره ترا افزون دهد<br />ذرّه چون کوهی قدم بیرون نهد.<br /> <font color=\"Red\">مولوی .</font><br />آنکه رای خرده دانش گر نماید اهتمام <br />ذره ٔ خرد از بزرگی آفتاب آسا شود.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> ذرّه ای، یا یک ذرّه . مقداری نهایت قلیل <span class=\"hlight\">:</span> <br />ایا کرده در بینی ات حرص و رس <br />از ایزد نیایدت یکذرّه ترس .<br /> <font color=\"Red\">لبیبی .</font><br />در آفتاب اگر ذره قدرتی بودی <br />سیاه روی نگشتی ز جرم قرص قمر.<br /> <font color=\"Red\">مسعودسعد.</font><br />از جمالش ذره ای باقی نماند<br />آن قدح بشکست و آن ساقی نماند.<br /> <font color=\"Red\">عطار.</font><br />ذره ای خود نیستی از انقلاب <br />تو چه میدانی حدوث آفتاب .<br /> <font color=\"Red\">مولوی .</font><br />هزار ذره اگر کم شود ز روی هوا<br />بذره ای نرسد آفتابرا نقصان .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />ذره ای کز عراق برخیزد<br />رشک خورشید خاوران باشد.<br /> <font color=\"Red\">سلمان ساوجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذره ای یا یک ذره یا ذرةمثقالی انصاف، محبت، نان، و غیره نداشتن </span> ؛ هیچ از آن نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">آن ذره که در حساب ناید مائیم </span> ؛<br />ما نزد او یا در آنجا بچیزی نیستیم، ما را بدانجا ارج و بها و محلی نیست . و رجوع به جزء لایتجزی و جوهر فرد و نقطه شود.<br /> <span class=\"hlight\">پیش آفتاب ذره کجا در حساب آید</span> . (تاریخ بیهقی ).<br /> <span class=\"hlight\">ذره به خورشید بردن </span>، تعبیری مثلی است مانند زیره به کرمان یا قطره به عمان بردن و نظایر آن .<br /> <span class=\"hlight\">ذره ذره پشم قالی میشود</span> .<br /> <span class=\"hlight\">ذره را به آفتاب چه نسبت </span> .<br /><span class=\"hlight\">مثل ذره </span>، سرگردان .<br /></font></div>'),
(130601, 'ذره ای', '<span class=\"hlight\">ذره ای .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص نسبی ) منسوب بِذرَة . <BR><font color=\"Blue\">◄</font> (اِ) یک ذرّه .<br /></font></div>'),
(130602, 'ذره بین', '<span class=\"hlight\">ذره بین .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) عدسی از شیشه یا بلور محدّب السطحین که برای بزرگ نمودن اشیاء خرد و ریزه بکار میرود و تصویر حاصله بزرگتر از خود شی ٔ است . و پیش از داگر و فوکو علمای مشرق به این خاصیت آشنا بوده و عملاً بکار می برده اند. ابوریحان بیرونی در کتاب الجماهر فی معرفةالجواهر گوید: و حدّث السلامی عن اللّحام ان ّ ابابشر السیرافی کان عند خاله بسرندیب ذات لیلة فاحضر فص ّ یاقوت احمر و کان یضعه علی احرف الکتاب حتی یقرأه و تعجّب الحاکی منه ... فالحروف الدّقاق تقرء بمثلها من البلور لان ّ الخط یغلظ من ورائها فی المنظر، و السطورتتسع. و علل ذلک موکلة الی صناعةالمناظر - انتهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذرّه بین گذاشتن </span> ؛ سخت دقیق شدن . نهایت کنجکاوی کردن .<br /></font></div>'),
(130603, 'ذره بینی', '<span class=\"hlight\">ذره بینی .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص نسبی ) آنچه که جز با ذرّه بین نتوان دیدن از غایت صغر. حیوانات ذرّه بینی . گیاهان ذره بینی .<br /></font></div>'),
(130604, 'ذره پرور', '<span class=\"hlight\">ذره پرور.</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ پ َرْ وَ ]</font></b> (نف مرکب ) تربیت کننده ٔ ذرّه . مجازاً، مربّی زیردستان و برکشنده ٔ آنان .<br /></font></div>'),
(130605, 'ذره پروری', '<span class=\"hlight\">ذره پروری .</span> <font color=\"DarkGreen\"><b>[ ذَرْ رَ <span class=\"hlight\" dir=\"rtl\">/</span>رِ پ َرْ وَ ]</font></b> (حامص مرکب ) چگونگی و عمل ذرّه پرور.<br /></font></div>'),
(130606, 'ذرهم', '<span class=\"hlight\">ذرهم .</span> <font color=\"DarkGreen\"><b>[ ذُ هَُ ]</font></b> (اِ)جوالیقی در المعرب بنقل از ابن الکلبی گوید: جُرهُم معرّب است و اصل آن ذُرهُم است . رجوع به جرهم شود.<br /></font></div>'),
(130607, 'ذرو', '<span class=\"hlight\">ذرو.</span> <font color=\"DarkGreen\"><b>[ ذَرْوْ ]</font></b> (ع اِ) پاره ای ناتمام از کلام .<br /></font></div>'),
(130608, 'ذرو', '<span class=\"hlight\">ذرو.</span> <font color=\"DarkGreen\"><b>[ ذَرْوْ ]</font></b> (ع مص ) پرانیدن . <BR><font color=\"Blue\">◄</font> بردن . <BR><font color=\"Blue\">◄</font> ذرو ریح شی ٔ را؛ برداشتن باد آنرا. دامیدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> پریدن . <BR><font color=\"Blue\">◄</font> رفتن . پریدن و رفتن چیزی خود بخود. <BR><font color=\"Blue\">◄</font> برباد کردن خرمن گندم و جز آن تا از کاه پاک شود. دامیدن . (زوزنی ). <BR><font color=\"Blue\">◄</font> ذروشی ٔ؛ شکستن آنرا. <BR><font color=\"Blue\">◄</font> بشتاب رفتن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذرو ظبی ؛ بشتاب رفتن آهو. <BR><font color=\"Blue\">◄</font> ذرو دهان ؛ خطا کردن در سخن و ناتمام گفتن . <BR><font color=\"Blue\">◄</font> بیفتادن . (تاج المصادر بیهقی ). ذَرو شی ٔ؛ افتادن آن . (منتهی الارب ). ذروضرس ؛ بیفتادن دندان . <BR><font color=\"Blue\">◄</font> بر باد داده شدن . دامیده شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> وعید کردن . (زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> آفریدن . (تاج المصادر بیهقی ) (زوزنی ). <BR><font color=\"Blue\">◄</font> ستاره از جای خویش برفتن . (زوزنی ).<br /></font></div>'),
(130609, 'ذرو', '<span class=\"hlight\">ذرو.</span><font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) و یا بقول ابن الفقیه، ذات ذرو؛ یکی ازوادیهای علاة به یمامة. صمةبن عبداﷲ القشیری گوید:<br />نظرت و اصحابی بذروة نظرة<br />فلو لم تفض عینای ابصرتا نجدا.<br /></font></div>'),
(130610, 'ذروان', '<span class=\"hlight\">ذروان .</span> <font color=\"DarkGreen\"><b>[ ذَرْ ]</font></b> (اِخ ) نام جایگاهی در شعر کثیر. <BR><font color=\"Blue\">◄</font> نام حصنی به یمن نزدیک صنعاء. <BR><font color=\"Blue\">◄</font> نام چاهی بنی زریق را بمدینه .<br /></font></div>'),
(130611, 'ذروبت', '<span class=\"hlight\">ذروبت .</span> <font color=\"DarkGreen\"><b>[ ذُ ب َ ]</font></b> (ع مص ) ذروبة. ذَرَب َ. ذرابة. ذروبت معده ؛ تباه شدن معده و هضم نکردن طعام . <BR><font color=\"Blue\">◄</font> اصلاح گرفتن معده . (از اضداد است ).<br /></font></div>'),
(130612, 'ذروبیذس', '<span class=\"hlight\">ذروبیذس .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) قفطی گوید و کان لسولون اخ ٌ یقال له ذرونیدس، یذکره افلاطون فی کتاب طیماؤس ... و ظاهراً ذرونیدوس غلط و ذروبیدس صحیح باشد.<br /></font></div>'),
(130613, 'ذروت', '<span class=\"hlight\">ذروت .</span> <font color=\"DarkGreen\"><b>[ ذَرْ وَ ]</font></b> (ع اِ) ثروت .<br /></font></div>'),
(130614, 'ذروتین', '<span class=\"hlight\">ذروتین .</span> <font color=\"DarkGreen\"><b>[ ذَرْ وَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ وَ ت َ ]</font></b> (ع اِ) تثنیه ٔ ذروة. در اصطلاح علمای هیأت، مراد ذروه ٔ تدویر و ذروه ٔ اوج است .<br /></font></div>'),
(130615, 'ذروثیوس', '<span class=\"hlight\">ذروثیوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن القفطی گوید عالمی ریاضی از مردم روم و مشهور است و او را در علم فلک و احکام نجومیه ید طولی و تصانیفی است که نزد اهل این دانش شهرت دارد. و از جمله ٔ تصانیف او کتاب الخمسة است که محتوی چند کتاب است، کتاب اول در موالید و کتاب دویم در تواریخ و ادوار و کتاب سیم در هیلاج و کدخداه و کتاب چهارم در تحویل سالهای موالید و کتاب پنجم در ابتداء اعمال و کتاب ششم (کذا) و کتاب هفتم در مسائل و موالید و هم او راست کتاب شانزدهم در تحویل سالهای موالید، و این کتب را عمربن فرخان طبری تفسیر کرده است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130616, 'ذروح', '<span class=\"hlight\">ذروح .</span> <font color=\"DarkGreen\"><b>[ ذُرْ رو <span class=\"hlight\" dir=\"rtl\">/</span> ذُ ]</font></b> (ع اِ) باغوجه . (زمخشری ). کوژخار. (مهذب الاسماء). کاغنه . (زمخشری ). آله <br />کلو. (ریاض الأدویة). دکلوک . باغوچه . عروسک . (دهار) (زمخشری ). الاکلنگ . کاوِنه . دارساس، مگسک . (حبیش تفلیسی ) ذُرّوح . ذُرَّح . ذَروح . ذُرّاح . ذِرّیح . ذَرّوح . ذُرحوح . ذَرنوح . ذُرَّحرَح . ذُراح . ذَریحَه . ذُرنوح . ذُرَّح . ذُرَحرَحه . ذِرّیحة. ج، ذراریح .<br />آنچه در لغت نامه های مترجم آمده است : کرمی است پرنده سرخ با خالهای سیاه بغایت زهرناک . جانوری است سرخ رنگ با خجکهای سیاه که می پرد. جنبنده ای خرد است سرخ با خالهای سیاه و می پرد و از ذوات السموم باشد و گویند در گزیدگی سگ هار سودمند بود. حیوانی است مقدارزنبوری و رنگ زرد می باشد ونقطه های سرخ دارد و چون او را بگیرند بی توقف بول کند و زهر وی آن است . حیوانی است از مگس بزرگتر بقدر زنبور سرخ لکن باریکتر و نقطه های سیاه بر آن و آن سم قاتل است و باید که آنها را در کوزه ٔ نو کنند و سر کوزه به لته ٔ کتان بسته سرنگون بر بخار سرکه ٔ جوشان گذارند تا مخنوق شده بمیرند. و بدل آن طینوث باشد یا کرم سبز که بر درخت صنوبر می یابند. و در اختیارات بدیعی آمده است : ذراریح، حیوانی است از مگس بزرگتر بقدر زنبور سرخ اما باریکتر بود و بغایت سرخ رنگ و نقط سیاه بر آن و آن سم ّ مهلک بود. مؤلف گوید: یعنی صاحب اختیارات در حوالی همدان و کوهرود و آن حوالی بسیار باشد هر یک بمقدار زنبوری بزرگ و بر نبات شبرم نشسته باشد و بی حد باشند در آن صحراها چون خواهند که استعمال کنند در کوزه نو کنندو سر آن با کتان پاره ای بگیرند و واژگونه بر سر دیگی که سرکه در آن جوشد نهند تا بخار سرکه به ایشان رسد و خناقشان گیرد بعد از آن استعمال کنند بهترین وی ذهبی رنگ بود. طبیعت وی بغایت گرم بود و خشک و گویندگرم و خشک بود در دویم . چون بر ثآلیل طلا کنند قلع کند و اگر در موم روغن کنند برص ناخن را زایل گرداند و ناخن تباه شده بیندازد بزودی و بر برص و بهق با سرکه طلا کنند نافع بود و با خردل سحق کرده طلا کنند موی برویاند و ورم سرطانی بگدازاند چون با زیت بپزند تاغلیظ شود و برآن طلا کنند و بر جرب و قوبا طلا کردن نافع بود و اندکی از وی چون با ادویه ای بود که دفع مضرت وی بکند مدرّ بول بود و گویند اگر در زیت بجوشانند موی بر داءالثعلب برویاند و اگر گزندگی عقرب بوی حک کنند نافع بود و اگر در روغن حل کنند و یک هفته درآفتاب نهند و بعد از آن قطره ای در گوش چکانند درد گوش زایل گرداند و کری ببرد و روغن وی محلل ورمهای بلغمی صلب بود و هر کس که یک درم ذراریح بخورد گویند کشنده بود و علامت وی آن بود که ورم زهار و قضیب و نواحی آن پیدا کند و قرحه ٔ مثانه آورد و بول ببندد و بعد از آن خون و گوشت پاره ای به عوض بول بیرون آید و سوزش سخت و اسهال سحجی و غثیان و اختلال عقل و سوزش حلق و افتادن در وقت برخاستن و غشی و تاریکی چشمها و طعم دهان مانند طعم قطران یافتن و سه تسوج از وی قرحه ٔ مثانه پیدا کند بخاصیت با وجود اینکه سنگ مثانه بریزاند و اگر خواهند که در دوائی مستعمل کنند یک تسوج با ادویه ای که مصلح وی بود مانند کتیرا. و مداوای کسی که آن خورده باشد بقی و حقنه و شیر تازه آشامیدن و لعاب و روغن بادام شیرین و جلاب و مرقهای چرب و بیض نیم برشت کنند صاحب تقویم گوید مصلح وی حب کاکنج و طین مختوم بود و بدل وی گویند طینوث است و گویند کرم درخت صنوبر. داود انطاکی در تذکره گوید: طیری باشد و بزرگ تر آن به اندازه ٔ زنبوری باشد و گیاهان تازه وتر را دوست گیرد و بیشتر در اوایل تابستان بر گیاه ارزن گرد آید و بهترین قسم آن است که بسیاهی و سرخی زند و برآن خطوط زرد پهن بود و پست تر و زبون تر سیاه و سبز و سپس سرخ باشد. و آن گرم و خشک است در دویم یا سیم یا چهارم . و مقطع و محلل است و به تجربة تفتیح سدد و تفتیت حصی کند و مدر طمث و بول بود و شرب آن درد طحال را سود بخشد و در گزیدگی سگ هار شرب آن با شوربای گوشت گاو بی عدیل است . و مصریان آن را با روغن زیتون بسایند و بکسی که از سگ ترسد (مراد سگ هار گزیده است ) دهند و در حقیقت ذروح دوای مخصوص این بیماری باشد. و طلاء آن در داءالثعلب و حکة و جرب و ریشها و نمش و بقیه ٔ آبله گاوی و بهق و برص نافع است . و اکتحال بدو سفیدی و ناخنه و بیخ سبَل َ را مفید است و مسقط جنین باشد و سبب خناق و کرب و مغص گردد و پوست را ریش کند و از این رو با آنکه وی بزرگترین داروی روئیدن مو است از استعمال آن بپرهیزند. و مصلح آن روغنها باشد و نیز در کوزه نهادن و سوختن یا در لته ای پیچیده و در سرکه ای جوشان آویختن و این عمل در تلطیف هر حیوان سمّی بکار است . و صواب استعمال تمام ذروح است و بعضی اطراف آن را دور افکنند و برخی برخلاف تنها اطراف را بکار برند و بدل آن دودالصنوبر است - انتهی . و حکیم مؤمن در تحفه گوید: ذراریح بحای مهمله حیوانی است بقدر زنبور و عفن و بدبو و با نباتات تازه می باشد و به ترکی الاکلنگ و به دیلمی دارساس نامند و به لغت اصفهان قسمی از سین است و بهترین او موجود در گندم زار است که مایل بسیاهی و سرخی و با خطوط زرد باشد و سبز و سرخ و زرد و منقط بسیاهی و سایر اقسام غیر مستعمل است در آخر سیم گرم و خشک و بسیار تند و مقرح جلد و از سموم قتاله و مقطع و مفتح و مفتت حصاة ومدرّ بول و حیض و رافع <font color=\"DarkGreen\"><b>[ ورم ]</font></b> سپرز و محرّق او شربا مستعمل است و خوردن محرق او با مرق گوشت گاو و بدستور با روغن زیتون جهت رفع خوف سگ دیوانه گزیده بهترین ادویه است و قطعهای خون منجمد با بول شارب او دفعمی شود و عوام را اعتقاد آنکه سگهای کوچک بسبب گزیدن سگ دیوانه متکون شده و این دوا اخراج آن سگ بچه ها میکند و در اخراج سنگ گرده و مثانه بغایت مؤثر است و بجای احراق هرگاه بپارچه پیچیده به بخار سرکه ٔ جوشان بدارند باعث تلطیف او می شود و استعمال آن جایز است و ضماد او جهت داءالثعلب و برص ناخن و با قیروطی جهت قلع ناخن فاسد و رویانیدن ناخن صحیح و با سرکه جهت جرب و تقشر جلد و بهق و برص و قوبا و گزیدن عقرب و ثالیل و رفع قمل و بقایای جدری و نمش و اکتحال او جهت ناخنه . و روغن زیتون که در او جوشانیده باشند جهت رویانیدن موی ابرو در داءالثعلب و گرانی سامعه و درد گوش نافع و قدر شربتش یک عدد سوخته ٔ آن و زیاده کشنده است بدرد مثانه و مغص و بول الدم و غشی و تب بسیار تند و اختلال عقل و چون قسم سیاه منقط بسرخی را در روغن کنجد شش ماه در آفتاب گذارند تدهین او جهت منع ابتداء کچلی و قلع مزمن آن مجرّب است . و در ترجمه ٔ صیدنه ٔ ابوریحان آمده است : حیوانی است بقدر زنبور و لون او زرد بود و بر جرم او نقطه های سرخ بود و چون آدمی او را بگیرد بی توقف بول کند و آن کشنده بود و ابن المظفر گوید: به هیئت از مگس بزرگتر است و بر جرم او الوان مختلف بود زرد و سرخ و سیاه و او را دو بال بود و آن زهر قاتل است و دفع مضرت او را چنان کنند که باعدس بیامیزند و علاج سگ دیوانه بدان کنند و جراحت گزیدگی او را بدان دوا نمایند و رازی در کتاب حاوی می آورد که پایها و بالهای او دافع مضرّت هم اوست . دیسقوریدوس گوید: نیکترین وی آن بود که در گندم یافت شود و هرچه در لون بالهای او اختلاف بیش باشد و به هیئت وبه مقدار بنات وردان بود در بزرگی و فربهی قوت او بیش بود و بنات وردان حیوانی است که در مواضع آبناک بود چون چشمه ها و طریق اصلاح او آن است که او را در کوزه ای کنند و سر آن را محکم کنند و به آتش نزدیک دارند تا در او بمیرد. پس در ریسمان کشند و نگاه دارند. <font color=\"DarkGreen\"><b>[ بیاض ]</font></b> گوید گرم و خشک است در سیم درجه . جرب را نافع بود چون از او زیاده بخورند مثانه ریش کند و بکشدو اگر اندک خورند بول براند و برص را سودمند بود چون با سرکه در موضع آن طلا کنند. و اگر با قیروطی بر برص ناخن طلا کنند زایل کند - انتهی .<br />ذراریح حشره ٔ کوچک سبزرنگی است بطول <span class=\"hlight\" dir=\"rtl\">٤</span> سانتی متر که از آن بوی زننده و عفنی متصاعد میشود این حشره دارای <span class=\"hlight\" dir=\"rtl\">٣</span> - <span class=\"hlight\" dir=\"rtl\">٥</span> درصد کانتاریدین است ذراریح سمی است قوی و <span class=\"hlight\" dir=\"rtl\">١/٥</span> گرم آن از راه معده باعث مرگ میشود. مشمع ذراریح از قدیم الایام مرسوم بود آرشیژن پزشک نرون آن را بکار برده و تا اواخر قرن <span class=\"hlight\" dir=\"rtl\">١٩</span> نیز استعمال آن بسیار متداول بوده است بطوری که در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٥</span> م . در بیمارستانهای پاریس متجاوز از <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> کیلوگرم کانتارید مصرف شده بوده است لیکن این اواخر از استعمال آن بسیار کاسته شده است سابق براین مشمع ذراریح را در اغلب بیماریهای دردناک بکار می برده اند ولی در این اواخر تنها در پلورزی های مزمن و طولانی و حملات احتقانی سل ریوی مورد استفاده است . برای ساختن مشمع ذراریح مقداری از گرد ذراریح را با دو برابر وزن آن موم و روغن باسلیقون و روغن زیتون مخلوط کرده و ورقه نازکی ازآن را روی پارچه میکشند و معمولا این مشمع را شب روی ناحیه ٔ دردناک گذارده و صبح برمیدارند. مشمع ذراریح پس از چند ساعت تولید درد و سوزش موضعی کرده جلد رابشدت سرخ کرده و پس از <span class=\"hlight\" dir=\"rtl\">٦</span> - <span class=\"hlight\" dir=\"rtl\">٨</span> ساعت در تمام سطح پوست تاولهای کوچکی تولید کرده و اگر مشمع را از روی جلدبرندارند و اثر آن ادامه پیدا کند پوست ناسور میشود. ذراریح علاوه بر آن که درد و سوزش موضعی شدیدی تولید میکند، در سلسله ٔ اعصاب اثر مضعف داشته سبب احتقان و التهاب شدید کلیوی شده درجه ٔ حرارت را بالا برده واز راه تاولهای جلدی بروز عوارض عفونی را در روی پوست تسهیل میکند و بدینجهت بکار بردن آن در مبتلایان بدولاب (نفریت البومینوری ) و فلج و در نزد اطفال بی مورد است اثر مصرف آن نیز امتیاز واضحی بر آثار سایر مصرفات ندارد و بهمین جهت است که امروزه استعمال آن تقریباً متروک مانده است (از کتاب درمانشناسی ج اول ). جالینوس فی الحادیة عشرة. قد جربناها تجربة لیست بالبسیرة فی علاج الاظفار البرصة فوجدناها اذا وضعت علیهامع قیروطی کانت نافعة لها أو مع مرهم قلعتها حتی یسقط الظفر کله و قد یخلط من الذراریح مرارا کثیرة معالادویة النافعة للجرب و العلة التی یتقشر معها الجلد و مع أدویة أخر شأنها التغییر و مع أدویة أخرتقلع الثآلیل المنکوسة المعروفة بالمسامیر و قد کان رجل یلقی شیئاً منها یسیرا فی الدواء المدرّللبول وبعض الناس یلقی اجنحتها و أرجلها فقط و یزعمون ان الاجنحة و الا رجل تنفع من شرب ابدان الذراریح و قوم آخرون یقولون خلاف ذلک ان ابدانها تنفع من اجنحتها و أرجلها و طلب به ما یطلب بسم الموت و أما انا فأنی اذا خلطتها الفیتها کما هی باجنحتها و أرجلها. و مما ینفع من جمیعالوجوه التی جربت فیها الذراریح تلک الذراریح الاخر التی تکون علی الحنطة و فی اجنحتها خطوط بالعرض صفر و خاصة ان القیت منها فی کوز فخار جدیدو صیرت علی فم الکوز خرقة کتان نظیفة و أمسکت الکوزو الخرقة مشدودة علی فمه و هو مکبوب علی قدر فیها خل حتی یتصاعد منها بخارالخل فیختنق و علی هذا المثال ینبغی أن یعمل بالحیوان المسمی ببوپرسطس و هو جنس من الحیوان یشبه الذراریح فی منظره و قوته و الدود الاخضر الذی یوجد علی شجرالصنوبر قوته هذا القوة بعینها. دیسقوریدیوس فی الثانیة قیماریدس و هو نوع من الذراریح ماکان منه یتولد بین الحنطة فانه یصلح للجرب فینبغی ان یصیر فی اناء غیر مقیر و یسد فمه بخرقة سخیفة نقیة و تقلب و تصیر الفم علی اناء فخار فیه خل ثقیف مغلی و لا یزال الاناء ممسکا علی الفخار حتی یمیت الذراریح و من بعد ذلک تشدفی خیط کتان و تخزن و اقواها فعلا ماکان منها مختلف اللون فی اجنحتها خطوط صفر بالعرض و أجسامها کبار طوال ممتلئة شبیهة فی العظم ببنات وردان و ماکان منها فی لون واحد لایختلف فیه فان فعله ضعیف و کذا یحرق الصنف من الذراریح الذی یقال له بوپرسطس و تفسیره نافخ النار و الصنف من الذراریح الذی یقال له فنطیون و هو دودالصنوبر یصیر علی منخل و یعلق المنخل علی رماد حار و یقلی علی المنخل قلیا یسیرا ثم یخزن و قوّةالذراریح بالجملة مسخنة معفنة مقرحة و لذلک یقع فی اخلاط الادویة الموافقة للاورام السرطانیة و یبری ٔ الجرب المتقرح و القوابی الردئیة اذا خلطت بالفرزجات الملینة ادرت البول و الطمث و قد زعم قوم ان الذراریح اذا خلطت بالادویة المعجونة نفعت المحقونین بادرارها البول و من الناس من زعم ان اجنحة الذراریح و أرجلها بادزهر لها اذا شربت . ابن ماسویه : ان اکتحلت نفعت الظفرة. الخوز: بالغة النفع للسعفة لطوخابخل . ابن سینا: قلیله یعین الادویة المدرة من غیر مضرة و قال بعضهم و یسقی واحد منها لمن یشکو مثانته و لاینجع فیه العلاج و هو نافع و شرب ثلث طساسیج منه مقرح للمثانة. جالینوس : تقریحه هو لامالة المادة الحادة الیها التی لایخلو عنها بدن مع خاصیة فیها. الغافقی : اذا طلی بمسحوقها مع خل قتلت القمل و کانت صالحة للبرص و للزیت الذی تطبخ فیه قوة ینبت بها الشعر فی داءالثعلب و ان حک ّ به علی لسع العقرب نفع نفعا بینا. سفین الاندلسی : اذا أضیف من جرمها المجفف المسحوق مقدار حبتّین فی شربةالحصا وصلتها و نفع من ذلک نفعا بلیغا و دهنها یحل الاورام البلغمیة الصلبة منها و الرخوة جدا. الشریف : اذا اغرقت فی دهن و شمست فیه اسبوعا و قطر من ذلک الدهن علی الاذن الوجعة شفا المهل و ینفع من الصمم الحادث و النوع الطیار منها ذوالاجنحة یسمی بالبربریة ارغلال اذا درست و رمیت فی مرقة لحم بقری و تحساه المعضوض من کلب نفعه نفعا بینا عجیبا لا یعدله فی ذلک شی ٔ و علامة شفائه ان المعضوض یبول دودا ذوات رؤس سود و اذا أخذ منه النوع الاسود المطرف بالحمرة و غمر فی الدهن العتیق و شمس ستة اشهرثم من بعد ذلک دهن بالدهن الفرطسة بعد الحلق و الانقاء بالدواء کان ذلک دواء عجیبا لانه یخرج الفرطسة باصولها و یجفف الرطوبة الفاسدة منها. المنصوری : من سقی من الذراریح أخذه وجع فی العانة و مغص و تقطیع و حرقةالبول و بال دمامع وجع شدید و ربما احتبس بوله ثم اندفع مع الدم بلذع و حرقة شدیدة و ربما یورم القضیب و العانة و نواحیها و یعرض له حرقة فی الفم و الحلق و التهاب شدید و حمی و اختلاط. الطبری : سم الذراریح حار جدا یقصد المثانة و یحرقها حرقا و یخرج منها الدم و اللحم بالبول و یأخذ منها الغشاء و تظلم منه العینان و علاجه أن یتقیا بماءالشبت المطبوخ و السمن البقری و یستنقع فی ماء حار و یتمرخ بدهن الحل و یحقن بماء کشک الشعیر المطبوخ مع دهن الورد و بزرالکتان . مگسک . ج، ذراریح به پارسی اله کلو گویند و آن حیوانی است مشابه زنبور سرخ الا آنکه از او باریکتر است و نقطه های سیاه دارد بهترینش آن است که ذهبی رنگ بود طبیعتش گرم و خشک است در دوم و از جمله ٔ سمومات قتاله است . چون خواهند که بجهت بعضی از منافع که دارد بکار برند وجهی که ضرر نکند اول آنها را در کوزه ٔ نو اندازند و سر کوزه را به لته ٔ کتان بسته کوزه را سرنگون بر سر دیگی دارند که سرکه در او جوشد تا مخنوق شده بمیرند پس بکار برند چون برثآلیل طلا کنند قلع کند و چون کوفته و پخته به موم روغن آمیزند برص ناخن را زایل گرداند و ناخن تباه شده را بزودی بریزد و بهق را نفع دهد و جرب و قوبا را دفع کند و چون یک طسو از او با دو طسو از کتیره ٔ کوفته و پخته بهم آمیزند و به ناشتا میل کنند ادرار بول و حیض کند و سنگ گرده و مثانه بریزاند و گزیدگی سگ دیوانه را سودمند بود و یک طسو از او کشنده بود و مداوای آن به شیر تازه و قیی ٔ کنند.<br /></font></div>'),
(130617, 'ذرود', '<span class=\"hlight\">ذرود.</span> <font color=\"DarkGreen\"><b>[ ذِرْ وَ ]</font></b> (اِخ ) نام کوهی است .<br /></font></div>'),
(130618, 'ذرور', '<span class=\"hlight\">ذرور.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع مص ) برآمدن آفتاب . دمیدن خورشید. دمیدن صبح . طالع شدن روز. طلوع . برآمدن آفتاب وماه و ستاره . (زوزنی ). <BR><font color=\"Blue\">◄</font> ذرور لحم ؛ نزاری و لاغری گوشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لرزانی گوشت از لاغری . تشنّج لحم . تَخدَّدُ لحم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاشیدن داروهای پراکندنی و پاشیدنی بر جراحت و قرحه : ینفع <font color=\"DarkGreen\"><b>[ الاَّبنوس ]</font></b> حرق النار ذروراً. (ابن البیطار). <BR><font color=\"Blue\">◄</font> دمیدن گیاه .<br /></font></div>'),
(130619, 'ذرور', '<span class=\"hlight\">ذرور.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (معرب، اِ) معرّب از داروی فارسی . دوای خشک سوده یا کوفته پراکندنی و پاشیدنی در چشم و قروح و جراحات . سوده های خشک ادویه که برای قطع رطوبات بر ریش و خستگی پراکنند یا در چشم کنند. ذریرة. ج، ذرورات . <BR><font color=\"Blue\">◄</font> نوعی بوی خوش یعنی عطر. ذریرة. ج، اَذِرّة. داود انطاکی در تذکره گوید: هر دارو که سحق کنند برای قطع رطوبات و خون و اصلاح خستگیها بشرط آنکه با مایع و روانی نیامیزد. و در داروهای چشم علاوه بر شروط مذکوره، باید مبرّد باشد تا اکثار آن زیان نکند - انتهی . <span class=\"hlight\">:</span> و غبار مواکب او را ذرور دیده های خود ساختند. (جهانگشای جوینی ).<br />گهی که اطلس رای تو روی بنماید<br />چو گرد پنبه بود مهر و بر مثال ذرور.<br /> <font color=\"Red\">نظام قاری .</font><br />و داود انطاکی ساختن اقسامی از ذرور را ذکر کند از جمله ذرور ابیض وذرور اصفر و ذرور یلصق الجراح و یجفف الرطوبات و یلحم و یأکل اللحم الزائد. و ذرور سریعالفعل و ذرور یقطع الدم حیث کان و یجفف کل قرح کالجدری و غیره . و در تحفه ٔ حکیم مؤمن، چند قسم ذرور را نام برد و طریقه ٔ ساختن آن بنماید. از جمله : ذرور اصفر صغیر وردینج و درد چشم اطفال را عجیب النفع بود. صفت آن : انذروت پرورده پنج مثقال، مامیثا دو مثقال کوفته و پخته صلایه کنند تا هم چون غبار شود. ذرور اصفر کبیر وردینج ورمد قدیمی را نفع دهد. صفت آن : انذروت مربی پنج درم، مامیثا دو درم، صبر و بذرالورد و زعفران از هر یک نیم درم، افیون چهاردانگ، همه را کوفته و پخته صلایه کنند تا همچو غبار شود. ذروری که بیاض را قلع کند و صفت آن : کف دریا و پوست تخم مرغ از هر یک پنج درم، نبات و انذروت و اسفیداج از هر یک چهار درم، نوشادر درمی، همه را کوفته و پخته صلایه کنند تا هم چو غبار شود. ذروری که خارش چشم را مفید بود وصفت آن : صبر و حضض و پوست هلیله ٔ زرد و مامیثا از هر یک ده درم . همه را کوفته و پخته صلایه کنند تا هم چو غبار شود. ذروری که قروح را دفع کند و صفت آن : شنج محرق و شادنج مغسول از هر یک ده مثقال، کوفته و پخته صلایه کنند تا همچو غبار شود. ذرور شادنج سبل و غلظ اجفان را نفع دهندصفت آن : شادنج ده درم انذروت و صبر سقوطری و حضض یکی و هلیله سیاه و پوست هلیله کابلی از هر یک پنج درم . زعفران نیم درم . همه را کوفته و پخته صلایه کنند تاهم چو غبار شود. ذروری که موسرج و قروح العین را سودمند آید و صفت آن : اثمد و شادنج از هر یک سی درم کوفته و پخته صلایه کنند تا هم چو غبار شود.<br /></font></div>'),
(130620, 'ذرورات', '<span class=\"hlight\">ذرورات .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذَرور. داروهای خشک سوده ٔ پراکندنی بر قروح و جراحات و چشم .<br /></font></div>'),
(130621, 'ذروردان', '<span class=\"hlight\">ذروردان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ مرکب ) حنجور. ظرفی که درآن ذرور نگاه دارند. دارودان . (یادداشت لغت نامه ).<br /></font></div>'),
(130622, 'ذرورملکانا', '<span class=\"hlight\">ذرورملکانا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ مرکب ) ترکیبی از انذروت مدبر و نشاسته و شکر تبرزد.<br /></font></div>'),
(130623, 'ذروع', '<span class=\"hlight\">ذروع .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) ذریع. سبک سیر فراخ گام از اسپ و اشتر. اسپ و اشتر سبک سیر فراخ گام .<br /></font></div>'),
(130624, 'ذروف', '<span class=\"hlight\">ذروف .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع مص ) ذرف . ذَرفان ذریف . تذراف . اشک ازچشم رفتن . روان گردیدن سرشک . رفتن اشک و جز آن . (زوزنی ). دویدن و بردویدن چیزی روان چون اشک و جز آن .<br /></font></div>'),
(130625, 'ذرونیذس', '<span class=\"hlight\">ذرونیذس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) قفطی در ترجمه ٔ افلاطون گوید: سولون را برادری است بنام ذرونیذس که افلاطون در شعر خود بسیار ذکر او آرد ذرونیذس را پسری بود بنام اقریطس که باز افلاطون در کتاب طیماؤس ازاو نام برده است . و ظاهراً این کلمه ذروبیدس با باءموحده ٔ تحتانیه است نه نون . رجوع به ذروبیدس شود.<br /></font></div>'),
(130626, 'ذری', '<span class=\"hlight\">ذری .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) زرع ذری ؛ کشت تخم انداخته . یعنی زمین بذرافشانده .<br /></font></div>'),
(130627, 'ذری', '<span class=\"hlight\">ذری .</span> <font color=\"DarkGreen\"><b>[ ذُ را ]</font></b> (ع اِ) ج ِ ذِروَة و ذُروَة.<br /></font></div>'),
(130628, 'ذری', '<span class=\"hlight\">ذری .</span> <font color=\"DarkGreen\"><b>[ ذُ را ]</font></b> (ع اِ) آنچه برافتد از چیزی .<br /></font></div>'),
(130629, 'ذری', '<span class=\"hlight\">ذری .</span> <font color=\"DarkGreen\"><b>[ ذَرْی ْ ]</font></b> (ع مص ) ذری ریح تراب را؛ بردن باد خاک را. دامیدن . (تاج المصادر بیهقی ) (زوزنی ) (مجمل اللغة). <BR><font color=\"Blue\">◄</font> ذری خرمن ؛ برباد کردن آنرا. و همچنین است ذری حنطة و امثال آن : ذری الناس الحنطة؛ مردمان گندم را باد دادند.<br /></font></div>'),
(130630, 'ذری', '<span class=\"hlight\">ذری .</span> <font color=\"DarkGreen\"><b>[ ذَ ری ی <span class=\"hlight\" dir=\"rtl\">/</span> ذِرْ ری ی ]</font></b> (ع ص ) شمشیر بسیارآب . <BR><font color=\"Blue\">◄</font> (اِ) آب و جوهر شمشیر.<br /></font></div>'),
(130631, 'ذریات', '<span class=\"hlight\">ذریات .</span> <font color=\"DarkGreen\"><b>[ ذُرْ ری یا ]</font></b> (ع اِ) ج ِ ذریّة <span class=\"hlight\">:</span> <br />دیگر روز ابلیس بصحرا بیرون رفت و تختی از آهن بنهاد و از ذریات خود یکی را بنشاند. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br />همچو آن ابلیس و ذریّات او<br />با خدا در جنگ واندر گفتگو.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(130632, 'ذریاس', '<span class=\"hlight\">ذریاس .</span> <font color=\"DarkGreen\"><b>[ ذِرْ ]</font></b> (ع ص ) ثافسیا. رجوع به ثافسیا شود.<br /></font></div>'),
(130633, 'ذریب', '<span class=\"hlight\">ذریب .</span> <font color=\"DarkGreen\"><b>[ ذِرْ ی َ ]</font></b> (ع اِ) زهر اصفر. گل زرد. (و کلمه معرب مینماید). رجوع به زریاب شود.<br /></font></div>'),
(130634, 'ذریبا', '<span class=\"hlight\">ذریبا.</span> <font color=\"DarkGreen\"><b>[ ذَ رَی ْی َ ]</font></b> (ع اِ) بتقدیم مثناة بر موحدة. قاله فی الشرح .(منتهی الارب ). عیب . <BR><font color=\"Blue\">◄</font> داهیة. سختی . بلا.<br /></font></div>'),
(130635, 'ذریة', '<span class=\"hlight\">ذریة.</span> <font color=\"DarkGreen\"><b>[ ذُ رْ ری ی َ ]</font></b> (ع اِ) نسل . پشت . فرزندان . پدران و فرزندان .نسل آدمی و پری . نسل مردمان و جِن ّ. فرزند. فرزندان و فرزندزادگان، یستوی فیه الواحد و الجمع. ج، ذُرّیّات . ذَراری <span class=\"hlight\">:</span> <br />طعنه چه زنی مرمرا بدان کم <br />از خانه براندند اهل عصیان <br />زیرا که براندند مصطفی را<br />ذریه ٔ شیطان از اهل و اوطان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و صاحب معالم التنزیل گوید یقع الذریة علی الاَّباء کما یقع علی الأولاد. <BR><font color=\"Blue\">◄</font> زنان . رجوع به ذریت شود.<br /></font></div>'),
(130636, 'ذریت', '<span class=\"hlight\">ذریت .</span> <font color=\"DarkGreen\"><b>[ ذُرْ ری ی َ ]</font></b> (ع اِ) پشت فرزندان .<br />نسل <span class=\"hlight\">:</span> <br />ای بار خدای همه ذریت آدم <br />با ملک سلیمانی و با حکمت لقمان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ابلیس لعین بدین زمین اندر<br />ذریّت خویش دید بسیاری .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(130637, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذِرْ ر ]</font></b> (ع اِ) ذروح . رجوع به ذراح و ذروح و ذراریح شود.<br /></font></div>'),
(130638, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ ]</font></b> (اِخ ) حمیری . محدث است . <BR><font color=\"Blue\">◄</font> نام پسر محمدبن مناذر شاعر. (معجم الادباء، چ مارگلیوث ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span> س <span class=\"hlight\" dir=\"rtl\">١٢</span> و بعد آن ).<br /></font></div>'),
(130639, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) پدر قبیله ای است از عرب .<br /></font></div>'),
(130640, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) پشته ها. هضاب . مفرد آن ذریحه است .<br /></font></div>'),
(130641, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام گشنی یعنی فحلی معروف است از شتران که اشتران نژاده را بوی نسبت کنند.<br /></font></div>'),
(130642, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> رجوع به معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span> س <span class=\"hlight\" dir=\"rtl\">١٢</span> - <span class=\"hlight\" dir=\"rtl\">١٤</span> شود.<br /></font></div>'),
(130643, 'ذریح', '<span class=\"hlight\">ذریح .</span> <font color=\"DarkGreen\"><b>[ ذِرْ ری ]</font></b> (اِخ ) نام بتی بود به نجیر از ناحیه ٔ یمن، نزدیک حضرموت . (معجم البلدان ).<br /></font></div>'),
(130644, 'ذریحة', '<span class=\"hlight\">ذریحة.</span> <font color=\"DarkGreen\"><b>[ ذَ ح َ ]</font></b>(ع اِ) ذَروح . رجوع به ذراح و ذروح و ذراریح شود.<br /></font></div>'),
(130645, 'ذریحة', '<span class=\"hlight\">ذریحة.</span> <font color=\"DarkGreen\"><b>[ ذَ ح َ ]</font></b> (ع اِ) پشته . هضبة. ج، ذرایح .<br /></font></div>'),
(130646, 'ذریحی', '<span class=\"hlight\">ذریحی .</span> <font color=\"DarkGreen\"><b>[ ذَ حی ی ی ]</font></b> (ع ص ) احمر ذریحی ؛ سرخی سرخ . سرخ سیر. احمر قانی . <BR><font color=\"Blue\">◄</font> ارغوانی . ارجوانی : احمرٌ ذریحی . <BR><font color=\"Blue\">◄</font> منسوب به ذرّیح، فحل معروف از شتران که اشتران نجیب را بدو نسبت کنند.<br /></font></div>'),
(130647, 'ذریحی', '<span class=\"hlight\">ذریحی .</span> <font color=\"DarkGreen\"><b>[ ذَ حی ی ]</font></b> (ع اِ) مادّه ٔ عامله ٔ قوی که از حشره ٔ ذروح (ذراریح ) گیرند و از آن مشمع سازند. و این ماده را در طب نیز بکار برندلکن باید در استعمال آن نهایت احتیاط مرعی داشت چه ماده ای سخت خطرناک است . <br /></font></div>'),
(130648, 'ذریحیات', '<span class=\"hlight\">ذریحیات .</span> <font color=\"DarkGreen\"><b>[ذَ حی یا ]</font></b> (ع اِ) شتران از نسل ذریح، فحل معروف .<br /></font></div>'),
(130649, 'ذریرح', '<span class=\"hlight\">ذریرح .</span> <font color=\"DarkGreen\"><b>[ ذُ رَ رِ ]</font></b> (ع اِ مصغر) مصغّر ذُرّاح .<br /></font></div>'),
(130650, 'ذریس', '<span class=\"hlight\">ذریس .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ)به لغت اندلس طیهوج است . تیهو و آن پرنده ای است از بلدرچین بزرگتر. و از کبک خردتر برنگ سنجاب و گوشت آن از همه ٔ انواع طیر حتی تذرو لطیف تر است . و اینکه صاحب برهان میگوید که از کبک بزرگتر است درست نیست .<br /></font></div>'),
(130651, 'ذریع', '<span class=\"hlight\">ذریع.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) تیزرو. شتاب رو. سبک سیر. ذروع . فرس ذریع، اسب سبک سیر و تیزرو و فراخ گام و همچنین است بعیر ذریع. <BR><font color=\"Blue\">◄</font> فراخ گام . واسعالخطو. و در صفت رسول صلوات اﷲعلیه آمده است ؛ کان ذریعالمشی ؛ ای واسعالخطو. <BR><font color=\"Blue\">◄</font> امر فراخ و وسیع. <BR><font color=\"Blue\">◄</font> مرگی . مرگامرگی . وبا. موت فاشی . <BR><font color=\"Blue\">◄</font> تند. سریع. بشتاب . تیز. زود. ناگهانی . قتل ذریع؛ قتل سریع. اکل ذریع، خوردنی بشتاب و بسیار. و فی الحدیث : فأکل اکلاً ذریعاً؛ ای سریعاً و کثیراً. <BR><font color=\"Blue\">◄</font> شفیع. خواهشگر. <BR><font color=\"Blue\">◄</font> وسیله . (مهذب الاسماء). دست آویز. ذریعة. <BR><font color=\"Blue\">◄</font> موت ذریع؛ مرگی فاش . (مهذب الاسماء).<br /></font></div>'),
(130652, 'ذریف', '<span class=\"hlight\">ذریف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذرف . ذروف . ذرفان . تذراف . رجوع به ذروف شود. <BR><font color=\"Blue\">◄</font> (اِ) اشک روان .<br /></font></div>'),
(130653, 'ذسقیروطوس', '<span class=\"hlight\">ذسقیروطوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) رجوع به ذیاسقوریذس شود.<br /></font></div>'),
(130654, 'ذش', '<span class=\"hlight\">ذش .</span> <font color=\"DarkGreen\"><b>[ ذَش ش ]</font></b> (ع مص ) سیر کردن و رفتن . دَش ّ.<br /></font></div>'),
(130655, 'ذعاذع', '<span class=\"hlight\">ذعاذع .</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ]</font></b> (ع اِ) ذعاذِع نخل ؛ بلایه ها از خرمابن و ردی ّ آن . <BR><font color=\"Blue\">◄</font> تفرّقوا ذعاذِع ؛ پراکنده شدند اینجا آنجا.<br /></font></div>'),
(130656, 'ذعاذع', '<span class=\"hlight\">ذعاذع .</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ]</font></b> (ع اِ) ج ِ ذعاذِعَة. (مهذب الاسماء).<br /></font></div>'),
(130657, 'ذعاذعة', '<span class=\"hlight\">ذعاذعة.</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ع َ ]</font></b> (ع اِ) گروه . فرقة. ج، ذعاذِع . (مهذب الاسماء).<br /></font></div>'),
(130658, 'ذعاریر', '<span class=\"hlight\">ذعاریر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ذعاریر انف ؛ آب سبزگونه که از بینی فرودآید. و تفرقوا ذعاریر بقذان ؛ ای تفرقوا شعاریر بُقذّان او بقندحرة ای متفرقین مثل الذباب .<br /></font></div>'),
(130659, 'ذعاط', '<span class=\"hlight\">ذعاط.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِخ ) موضعی است .<br /></font></div>'),
(130660, 'ذعاع', '<span class=\"hlight\">ذعاع .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذعاعة. گروه ها. فرقه ها. <BR><font color=\"Blue\">◄</font> خرمابنان بلایه و ردی ّ. <BR><font color=\"Blue\">◄</font> فاصله های میان خرمابنان . مسافت بین خرمابنی با دیگری در رَسته .<br /></font></div>'),
(130661, 'ذعاعة', '<span class=\"hlight\">ذعاعة.</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (ع اِ) خرمابن بلایة و ردی ّ. <BR><font color=\"Blue\">◄</font> مسافت از خرمابنی تا خرمابنی در رَسته ٔ خرمابنان . ج، ذَعاع . <BR><font color=\"Blue\">◄</font> یک گروه . یکی فرقة.<br /></font></div>'),
(130662, 'ذعاف', '<span class=\"hlight\">ذعاف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذَعف . بمردن . هلاک شدن .<br /></font></div>'),
(130663, 'ذعاف', '<span class=\"hlight\">ذعاف .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص، اِ) ذَعف . سم ّ ساعة؛ زهر که در ساعت بکشد یا عام است یعنی زهر مطلق . زهر قاتل . زهر کشنده . (مهذب الاسماء). ج، ذُعُف . <BR><font color=\"Blue\">◄</font> موت ذعاف ؛ مرگ شتاب . مرگ سریع. موت مُذعِف ؛ مرگ ناگهانی .<br /></font></div>'),
(130664, 'ذعاق', '<span class=\"hlight\">ذعاق .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص ) ماءٌذعاق ؛ آب سطبر تلخ که خوردن نتوان . <BR><font color=\"Blue\">◄</font> داءٌ ذعاق ؛ بیماری کشنده .<br /></font></div>'),
(130665, 'ذعالب', '<span class=\"hlight\">ذعالب .</span> <font color=\"DarkGreen\"><b>[ ذَ ل ِ ]</font></b> (ع اِ) ج ِ ذِعلِب .<br /></font></div>'),
(130666, 'ذعالیب', '<span class=\"hlight\">ذعالیب .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) جمع ذُعلوب . کناره جامه های پاره و خرقه ها یا آنچه از جامه های پاره شده بدان آویزان باشد. جامه های کهنه . جامه های خَلَق <span class=\"hlight\">:</span> <br />لقد اکون علی الحاجات ذا لبث <br />و احوذیّاً اذا انضم ّ الذعالیب .<br />و سیوطی در المزهر گوید. ذعالیب جمعی است بی واحد.<br /></font></div>'),
(130667, 'ذعبان', '<span class=\"hlight\">ذعبان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) گرگ جوان .<br /></font></div>'),
(130668, 'ذعت', '<span class=\"hlight\">ذعت .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) خَوَه کردن . (تاج المصادر بیهقی ). خفه کردن . خَبَه کردن . سخت خبه کردن کسی را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مالیدن در خاک کسی را. <BR><font color=\"Blue\">◄</font> راندن . سخت راندن .<br /></font></div>'),
(130669, 'ذعج', '<span class=\"hlight\">ذعج .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) سخت راندن کسی را یاستوری را. <BR><font color=\"Blue\">◄</font> ذعج جاریة؛ آرمیدن با وی .<br /></font></div>'),
(130670, 'ذعذاع', '<span class=\"hlight\">ذعذاع .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مذیاع . دهن لَغ. آنکه راز نگاه نتواند داشت . فاش کننده ٔ اسرار. سخن چین .خبرکش .<br /></font></div>'),
(130671, 'ذعذعة', '<span class=\"hlight\">ذعذعة.</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ع َ ]</font></b>(ع مص ) تفرقه . تبدید. پراکندن . پریشان کردن . <BR><font color=\"Blue\">◄</font> ذعذعه ٔ مال ؛ پراکنده و جدا کردن اشتران را. <BR><font color=\"Blue\">◄</font> ذعذعه ٔ سرّ فاشی و منتشر و ظاهر و آشکارکردن راز را. <BR><font color=\"Blue\">◄</font> ذعذغه ٔ خبر؛ پراکندن و فاشی کردن آنرا. <BR><font color=\"Blue\">◄</font> ذعذعه ٔ ریح شجر را؛ سخت جنبانیدن باد درخت را. <BR><font color=\"Blue\">◄</font> ترسانیده شدن .<br /></font></div>'),
(130672, 'ذعر', '<span class=\"hlight\">ذعر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ترسانیدن . (تاج المصادر بیهقی ). تخویف . تهدید. بیم دادن .<br /></font></div>'),
(130673, 'ذعر', '<span class=\"hlight\">ذعر.</span> <font color=\"DarkGreen\"><b>[ ذُ ع َ ]</font></b> (ع ص ) امر مخوف . چیزی که از آن ترسیده شود.<br /></font></div>'),
(130674, 'ذعر', '<span class=\"hlight\">ذعر.</span> <font color=\"DarkGreen\"><b>[ذُ ]</font></b> (ع اِ) ترس . خوف . بیم . خشیت . رعب . رهب . فزع . فرق . هراس . دهشت . وحشت <span class=\"hlight\">:</span> سبب ذعری که در صمیم دل او متمکن گشته و خیالی که بحواشی خاطر او متطرق شده . (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>).<br /></font></div>'),
(130675, 'ذعر', '<span class=\"hlight\">ذعر.</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (ع اِمص ) سرگشتگی . تحیّر.<br /></font></div>'),
(130676, 'ذعره', '<span class=\"hlight\">ذعره .</span> <font color=\"DarkGreen\"><b>[ ذُ ع َ رَ ]</font></b> (ع اِ) مرغکی است که بر درخت آشیانه دارد و پیوسته دم خودمی جنباند. صاحب اقرب الموارد گوید و این آن مرغ است که عامّه در بلاد ما بدان اُم ّ صُفَیدَه نام دهند.<br /></font></div>'),
(130677, 'ذعریة', '<span class=\"hlight\">ذعریة.</span> <font color=\"DarkGreen\"><b>[ ذُ ع َ ری ی َ ]</font></b> (ع ص ) سنه ٔ ذعریّة؛ سال سخت .<br /></font></div>'),
(130678, 'ذعط', '<span class=\"hlight\">ذعط.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص )سبک گلو بریدن کسی را یا عام ّ است . (منتهی الارب ).<br /></font></div>'),
(130679, 'ذعف', '<span class=\"hlight\">ذعف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص، اِ) ذعاف . سم ّساعت . زهر که در ساعت کشد. زهر مطلق . <BR><font color=\"Blue\">◄</font> حیةٌ ذعف اللّعاب ؛ مار در جای کش . مار جابجا کشنده .<br /></font></div>'),
(130680, 'ذعف', '<span class=\"hlight\">ذعف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) زهر دادن . کسی را زهر خورانیدن . زهر در طعام کردن . سم دادن . مسموم کردن . دواخور کردن . چیزخور کردن .<br /></font></div>'),
(130681, 'ذعف', '<span class=\"hlight\">ذعف .</span> <font color=\"DarkGreen\"><b>[ ذُ ع ُ ]</font></b> (ع اِ) ج ِ ذُعاف .<br /></font></div>'),
(130682, 'ذعف', '<span class=\"hlight\">ذعف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذَعاف . بمردن . هلاک شدن .<br /></font></div>'),
(130683, 'ذعفان', '<span class=\"hlight\">ذعفان .</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (ع اِ) مرگ . موت .<br /></font></div>'),
(130684, 'ذعق', '<span class=\"hlight\">ذعق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) فریاد کردن . <BR><font color=\"Blue\">◄</font> بانگ زدن بر کسی و ترسانیدن او را.<br /></font></div>'),
(130685, 'ذعل', '<span class=\"hlight\">ذعل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) اقرار کردن پس از انکار.<br /></font></div>'),
(130686, 'ذعلب', '<span class=\"hlight\">ذعلب .</span> <font color=\"DarkGreen\"><b>[ ذِ ل ِ ]</font></b> (ع ص، اِ) شتر ماده ٔ شتاب رو. مایه ٔ تیزرو. ناقه ٔ سبک رو. ذعلبة. ج، ذعالِب .<br /></font></div>'),
(130687, 'ذعلبة', '<span class=\"hlight\">ذعلبة.</span> <font color=\"DarkGreen\"><b>[ ذِ ل ِ ب َ ]</font></b> (ع ص، اِ) شتر ماده ٔ شتاب رو. مایه ٔتیزرو. ناقه ٔ سبک رو. ذِعلِب . شترمرغ . نعامة. <BR><font color=\"Blue\">◄</font> حاجت اندک . <BR><font color=\"Blue\">◄</font> کناره ٔ جامه یا آنچه از جامه پاره شده و آویخته باشد.<br /></font></div>'),
(130688, 'ذعلفة', '<span class=\"hlight\">ذعلفة.</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ف َ ]</font></b> (ع مص ) سرگشته کردن . هلاک کردن .<br /></font></div>'),
(130689, 'ذعلوب', '<span class=\"hlight\">ذعلوب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) کناره ٔ جامه و پاره ٔ خرقه یا آنچه از جامه پاره شده و بدان آویزان باشد. <BR><font color=\"Blue\">◄</font> (ص ) جامه ٔ کهنه . کهن جامه . ج، ذعالیب .<br /></font></div>'),
(130690, 'ذعلوق', '<span class=\"hlight\">ذعلوق .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) تره ای است تیزبوی همچون گندنا. و محمودبن عمر ربنجنی گوید طرخون . <BR><font color=\"Blue\">◄</font> مرغکی است . <BR><font color=\"Blue\">◄</font> نوعی از سماروغ . یعنی قسمی از کماة. <BR><font color=\"Blue\">◄</font> (ص ) کودک چالاک تیزفهم سبک روح . <BR><font color=\"Blue\">◄</font> (صوت ) ذعلوق دهلوق، کلمه ای است که میش را به دوشیدن خوانند. <BR><font color=\"Blue\">◄</font> گوسفند سبک جثه ٔ تنگ دهان (؟). <BR><font color=\"Blue\">◄</font> (اِخ ) نام شمشیر خالدبن سعیدبن عاص .<br /></font></div>'),
(130691, 'ذعن', '<span class=\"hlight\">ذعن .</span> <font color=\"DarkGreen\"><b>[ ذَ ع َ ]</font></b> (ع مص ) گردن دادن و گردن نهادن کسی را. رام گردیدن کسی را.<br /></font></div>'),
(130692, 'ذعور', '<span class=\"hlight\">ذعور.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مُتَذعر. ترسنده . <BR><font color=\"Blue\">◄</font> زن ترسنده از ریبه و تهمت . زن ترسان از بدنامی . زنی ترسنده . (مهذب الاسماء). زن ترسنده از بهتان و سخن بد. <BR><font color=\"Blue\">◄</font> ناقه ٔ ذعور؛ ماده شتری که چون دست بر پستان وی نهند خویشتن را درکشد.<br /></font></div>'),
(130693, 'ذعوط', '<span class=\"hlight\">ذعوط.</span> <font color=\"DarkGreen\"><b>[ ذَع ْ وَ ]</font></b> (ع ص ) (شاید معرب از زود فارسی چنانکه ذَوَط) مرگ شتاب . موت ذَعْوَط، موت ذاعط؛ مرگ ناگهان .<br /></font></div>'),
(130694, 'ذغ', '<span class=\"hlight\">ذغ .</span> <font color=\"DarkGreen\"><b>[ ذَغ غ ]</font></b> (ع مص ) آرمیدن با.<br /></font></div>'),
(130695, 'ذغال', '<span class=\"hlight\">ذغال .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِ) چوب سوخته ٔ آتش نشانده و کشته که برای بار دیگر سوختن را آماده کنند. فحم . انگشت .زگال . زغال . زوال و برخی آن را با زاء اخت راء نویسند و ظاهراً چنانکه معمول نیز همان است با ذال صحیح باشد چه دغل با دال مهملةنیز به معنی خس و خاشاکی است که در حمامها سوزند.<br /></font></div>'),
(130696, 'ذغال اخته', '<span class=\"hlight\">ذغال اخته .</span> <font color=\"DarkGreen\"><b>[ ذُ اَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ مرکب ) اخته ذغال . درختی است میوه دار و میوه ٔ آن بطعم ترش و رنگ آلبالوی سیاه و رسیده و بشکل سنجد باریک .<br /></font></div>'),
(130697, 'ذغال حیوانی', '<span class=\"hlight\">ذغال حیوانی .</span> <font color=\"DarkGreen\"><b>[ ذُ ل ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> ح ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) سوخته ٔ استخوان بطرزی خاص .<br /></font></div>'),
(130698, 'ذغال سنگ', '<span class=\"hlight\">ذغال سنگ .</span> <font color=\"DarkGreen\"><b>[ ذُ ل ِ س َ ]</font></b> (ترکیب اضافی، اِ مرکب ) ذغال معدنی . حجر موسی . حجاره ٔ قبر موسی . احجارالسود. (الجماهر بیرونی ). و آن چوبهای متحجر تحت الارضی است . رجوع به احجارالسود شود. و جمیع اهل الصین و الخطا انّما فحمهم تراب عندهم منعقد کالطفل عندنا و لونه لون الطفل تأتی الفیلة بالأحمال فیقطعونه قطعا علی قدر قطع الفحم عندنا و یشعلون النار فیه فیقد کالفحم و هو اشد حرارة من الفحم و اذا صار رماداً عجنوه بالماء و یبسوه و طبخوا به ثانیة و لایزالون یفعلون به کذلک الی ان یتلاشی . (ابن بطوطه ).<br /></font></div>'),
(130699, 'ذغال گرفتگی', '<span class=\"hlight\">ذغال گرفتگی .</span> <font color=\"DarkGreen\"><b>[ ذُ گ ِ رِ ت َ<span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) مسمومیت از دَم <font color=\"DarkGreen\"><b>[ گاز ]</font></b> ذغال .<br /></font></div>'),
(130700, 'ذغالاب', '<span class=\"hlight\">ذغالاب .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِ مرکب ) زکالاباب . مرکب . سیاهی . مداد. نقس . حبر. دوده . دوده ٔ مُرَکّب .<br /></font></div>'),
(130701, 'ذغالدان', '<span class=\"hlight\">ذغالدان .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِ مرکب ) ظرفی غالباً از تُنُکه آهن که بدان از انبار ذغال برای منقل و اجاق و بخاری آرند. <BR><font color=\"Blue\">◄</font> انبار ذغال . <BR><font color=\"Blue\">◄</font> جائی کوچک و تنگ .<br /></font></div>'),
(130702, 'ذغالدانی', '<span class=\"hlight\">ذغالدانی .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (اِ مرکب ) ذغالدان .<br /></font></div>'),
(130703, 'ذغالفروش', '<span class=\"hlight\">ذغالفروش .</span> <font color=\"DarkGreen\"><b>[ ذُ ف ُ ]</font></b> (نف مرکب ) آنکه ذغال فروشد.<br /></font></div>'),
(130704, 'ذغالفروشی', '<span class=\"hlight\">ذغالفروشی .</span> <font color=\"DarkGreen\"><b>[ ذُ ف ُ ]</font></b> (حامص مرکب ) عمل فروختن ذغال . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) جای فروختن ذغال .<br /></font></div>'),
(130705, 'ذغالی', '<span class=\"hlight\">ذغالی .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ص نسبی ) آلوده به ذغال . منسوب به ذغال . ذغال فروش .<br /></font></div>'),
(130706, 'ذغمری', '<span class=\"hlight\">ذغمری .</span> <font color=\"DarkGreen\"><b>[ ذَ م َ ری ی ]</font></b> (ع ص ) بدخو. سیّی ءالخلق .<br /></font></div>'),
(130707, 'ذغمور', '<span class=\"hlight\">ذغمور.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص ) مرد کینه ور که کینه اش از دل نرود. بدکینه .<br /></font></div>'),
(130708, 'ذف', '<span class=\"hlight\">ذف .</span> <font color=\"DarkGreen\"><b>[ ذُف ف ]</font></b> (ع اِ) آب اندک .<br /></font></div>'),
(130709, 'ذف', '<span class=\"hlight\">ذف .</span> <font color=\"DarkGreen\"><b>[ ذَف ف ]</font></b> (ع مص ) قتل مجروح . کشتن خسته . ذفاف . مذافّة. تذفیف . اذفاف . الاجهاز علی الجریح . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذف در امری ؛ سرعت کردن در آن . شتافتن در او. شتاب کردن در وی . <BR><font color=\"Blue\">◄</font> خذ ما ذف ّ لک (بصیغه ٔ مجهول )؛ بگیر آنچه را که مهیا و موجود است و زود بدست آید.<br /></font></div>'),
(130710, 'ذف', '<span class=\"hlight\">ذف .</span> <font color=\"DarkGreen\"><b>[ذَف ف ]</font></b> (ع اِ) گوسفندان . <BR><font color=\"Blue\">◄</font> آواز کفش گاه راه رفتن . ذفَة، یکی . و بدال مهمله نیز آمده است .<br /></font></div>'),
(130711, 'ذفاری', '<span class=\"hlight\">ذفاری .</span> <font color=\"DarkGreen\"><b>[ ذَ را ]</font></b> (ع اِ) ج ِ ذِفری <font color=\"DarkGreen\"><b>[ ذِ را ]</font></b> .<br /></font></div>'),
(130712, 'ذفاریق', '<span class=\"hlight\">ذفاریق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ج ِ ذفروق .<br /></font></div>'),
(130713, 'ذفاف', '<span class=\"hlight\">ذفاف .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص ) زود. سبک . بشتاب . <BR><font color=\"Blue\">◄</font> زهر کشنده . <BR><font color=\"Blue\">◄</font> خفاف ٌ ذفاف ؛ سبک، زود، یا از اتباع است .<br /></font></div>'),
(130714, 'ذفاف', '<span class=\"hlight\">ذفاف .</span> <font color=\"DarkGreen\"><b>[ ذِ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ ]</font></b> (ع اِ) آب اندک . ج، اَذِفه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> زهر قاتل .<br /></font></div>'),
(130715, 'ذفاف', '<span class=\"hlight\">ذفاف .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) زهر کشنده . سم قاتل . <BR><font color=\"Blue\">◄</font> آب اندک یا نم و تری . ج، ذُفُف . ما فیه ذفاف ؛ نیست در آن چیزی که تعلق گرفته شود بدان . <BR><font color=\"Blue\">◄</font> ما ذف َّ ذفافاً؛ آماده نکرد چیزی را، یا چیزی نکرد.<br /></font></div>'),
(130716, 'ذفاف', '<span class=\"hlight\">ذفاف .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع مص ) ذف .مذافّة. اِذْفاف . تذفیف . کشتن خسته را. قتل مجروح . الاجهاز علی الجریح . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذفاف در امری ؛ شتافتن، شتاب کردن، تسریع در آن .<br /></font></div>'),
(130717, 'ذفافة', '<span class=\"hlight\">ذفافة.</span> <font color=\"DarkGreen\"><b>[ ذُ ف َ ]</font></b> (اِخ ) (ابو... المصری ) در متن تاریخ جهانگشای جوینی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span> شعر ذیل آمده است :<br />و ما السّحاب ُ اذا ما انجاب ُ عن بَلَد<br />و لا یلم ّ به یوماً بمذموم <br />و در حاشیه گوید: لابی ذُفافةالمصری ّ فی بعض الرؤساء و بعده :<br />اِن جدت فالجودُ شی ٔ قد عُرفت َ به <br />و ان تجافیت لم تنسب الی اللّوم .<br /><font color=\"Red\">(تتمةالیتیمة نسخه ٔ پاریس ورق <span class=\"hlight\" dir=\"rtl\">٥٠٩</span>).</font><br /></font></div>'),
(130718, 'ذفافة', '<span class=\"hlight\">ذفافة.</span> <font color=\"DarkGreen\"><b>[ ذُ ف َ ]</font></b> (اِخ ) العبسی . محمدبن موسی بن حماد گوید: من و عمراوی نزد دعبل بن علی بودیم در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> هَ . ق . پس از آمدن وی از شام . و از ابوتمام یاد کردیم، دعبل به عیب جوئی وی پرداخت و چنین می پنداشت که او دزد شعر است آنگاه بغلام خود گفت : ای نَفنف : آن خریطه بیار، غلام خریطه بیاورد که دفاتری در میان داشت دعبل دست بدان فروبرد و دفتری از آن برآورد آنگاه گفت : این را بخوانید، و ما در دفتر بدینسان خواندیم : مکنف گوید ابوسلمی از خاندان زهیربن ابن ابی سلمی است و منزلش قنسرین بود و ذفافةالعبسی را هجا گفته و از ابیات آن هجاست :<br />ان الضراط به تعاظم جدکم <br />فتعاظموا ضِرطاً بنی القعقاع .<br />ولیکن پس از این وی را بدین ابیات رثا گفته است :<br />ابعد ابی العباس یستعتب الدهرُ<br />و ما بعده للدهر عُتبی و لا عذرُ<br />و لو عوتب المقدار و الدهر بعده <br />لما أعتبا ما اورق السلم النضر<br />الا ایها الناعی ذفافة ذا الندی <br />تعست و شلت من انا ملک العشر<br />اتنعی فتی ً من قیس عیلان صخرةً<br />تفلق عنها من جبال العدی الصخر<br />اذا ما ابوالعباس خلّی مکانه <br />فلا حملت انثی و لا مسّها طهر<br />ولا امطرت ارضاً سماء و لا جرت <br />نجوم، و لا لذّت لشاربها الخمر<br />کأن بنی القعقاع یوم وفاته <br />نجوم سماء خرمن بینها البدر<br />تُوفّیت الامال بعد ذُفافة<br />و اصبح فی شغل عن السَفر السَفر<br />یُعَّزون عن ثاو تُعزی به العُلا<br />و یبکی علیه المجد و البأس و الشعر<br />و ما کان الاّ مال َ من قل ّ ماله <br />و ذخراً لمن أمسی و لیس له ذخر<br /> <font color=\"Red\">(الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>).</font><br />و سپس گفت ابوتمام، همه ٔ این قصیده بدزدیده و در شعر خود درآورده است . و مراد از قصیده ٔابی تمام قصیده ای است بمطلع:<br />کذا فلیجل الخطب و لیفدح الأمر.<br />ذفافة کثمامة نام مردی است .<br /><font color=\"Red\">؟</font><br /></font></div>'),
(130719, 'ذفة', '<span class=\"hlight\">ذفة.</span> <font color=\"DarkGreen\"><b>[ ذَف ْ ف َ ]</font></b> (ع اِ) یکی گوسفند. واحد ذَف ّ.<br /></font></div>'),
(130720, 'ذفذفة', '<span class=\"hlight\">ذفذفة.</span> <font color=\"DarkGreen\"><b>[ ذَ ذَ ف َ ]</font></b> (ع مص ) کشتن خسته را. الاجهاز علی الجریح . <BR><font color=\"Blue\">◄</font> خرامیدن .<br /></font></div>'),
(130721, 'ذفر', '<span class=\"hlight\">ذفر.</span><font color=\"DarkGreen\"><b>[ ذَ ف َ ]</font></b> (ع مص ) بوی آمدن . بوی برخاستن . <BR><font color=\"Blue\">◄</font> تیزی و تندی بوی خواه خوش و خواه ناخوش . یا خاص است به گند بَغَل صنان .<br /></font></div>'),
(130722, 'ذفر', '<span class=\"hlight\">ذفر.</span> <font color=\"DarkGreen\"><b>[ ذِ ف ِ <span class=\"hlight\" dir=\"rtl\">/</span> ف َرر ]</font></b> (ع ص، اِ) شتر بزرگ ذفری و سخت شدید. <BR><font color=\"Blue\">◄</font> بزرگ خلقت . <BR><font color=\"Blue\">◄</font> چابک . <BR><font color=\"Blue\">◄</font> درازبالا. <BR><font color=\"Blue\">◄</font> تمام بدن . یا جوان چابک درازبالا و تمام بدن .<br /></font></div>'),
(130723, 'ذفر', '<span class=\"hlight\">ذفر.</span> <font color=\"DarkGreen\"><b>[ ذَ ف ِ ]</font></b> (ع ص ) مرد گنده بَغَل . <BR><font color=\"Blue\">◄</font> تیز. تند. (در بوی ): مسک ذفر؛ مشک تیزبوی و له <font color=\"DarkGreen\"><b>[ لأذخِر ]</font></b> اصل مندفن و قضبان دقاق ذفرالریح . (ابن البیطار). ذفرالمَشم ّ؛ تیزبوی .<br /></font></div>'),
(130724, 'ذفر', '<span class=\"hlight\">ذفر.</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص، اِ) ج ِ اَذفَر و ذفراء.<br /></font></div>'),
(130725, 'ذفرا', '<span class=\"hlight\">ذفرا.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) ذفراء. عطرالأمَة. سذاب البر. تره ای است ربعیة، بدبوی که شتر آن را نخورد. <BR><font color=\"Blue\">◄</font> (ص ) کتیبة ذفراء؛ لشکر که بوی زنگ آهن دارد.<br /></font></div>'),
(130726, 'ذفران', '<span class=\"hlight\">ذفران .</span> <font color=\"DarkGreen\"><b>[ ذَ ف ِ ]</font></b> (اِخ ) نام وادیئی است نزدیک وادی صفراء به راه بدر یا تصحیف دقران است .<br /></font></div>'),
(130727, 'ذفروق', '<span class=\"hlight\">ذفروق .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) قمع خرما. کون خرما. ج، ذفاریق .<br /></font></div>'),
(130728, 'ذفری', '<span class=\"hlight\">ذفری .</span> <font color=\"DarkGreen\"><b>[ ذِ را ]</font></b> (ع اِ) پس سر و گردن . یا پس گوش شتر که خوی کند یا عام است . آنجا که زیر گوش بدانجارسد از گردن . (مهذب الاسماء). پس گردن اشتر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> بناگوش . (دهار). زیر گوش . ج، ذِفرَیات، ذُفاری ̍. و صاحب کشاف اصطلاحات الفنون گوید:بکسر ذال بعضی گویند آنجا که گوش بوی رسید از گردن .و در خلاص گفته که : ذِفریان هر دو کنار گوش است . و علاّمه ٔ تفتازانی گوید که ذفری بیخ گوش است . و موضعی که عرق کند در پس گوش . کذا فی بحر الجواهر. و در صراح آمده است : هذه ذفری بدون تنوین، چه الف آن برای تأنیث است . و برخی از علماء عربیت این کلمه را در حال نکره بودن منون خوانند و یجعل الفها للالحاق بدرهم .<br /></font></div>'),
(130729, 'ذفری', '<span class=\"hlight\">ذفری .</span> <font color=\"DarkGreen\"><b>[ ذُ را ]</font></b> (ع اِ) اسم عربی سداب بری است و هرچه کریه الرائحة باشد و صاحب اختیارات بدیعی گوید: نوعی از سداب بری است و بوی بد دارد و گل وی زرد و خوشرنگ بود و چون ورق آن را بکوبند <font color=\"DarkGreen\"><b>[ و آب آن ]</font></b> بیاشامند جهت درد اندرون و تب ربع و درد جگر سودمند بود.<br /></font></div>'),
(130730, 'ذفریات', '<span class=\"hlight\">ذفریات .</span> <font color=\"DarkGreen\"><b>[ ذِ رَ ]</font></b> (ع اِ) ج ِ ذِفری ̍.<br /></font></div>'),
(130731, 'ذفط', '<span class=\"hlight\">ذفط.</span><font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذفط طائر؛ برجستن آن بر ماده و همچنین است ذفط تیس . <BR><font color=\"Blue\">◄</font> ذفط ذباب ؛ فضله افکندن مگس . و گفته اند که صواب در هر دو معنی با قاف است .<br /></font></div>'),
(130732, 'ذفطسة', '<span class=\"hlight\">ذفطسة.</span> <font color=\"DarkGreen\"><b>[ ذَ طَ س َ ]</font></b> (ع مص ) تباه کردن کسی مال خود را. ضایع کردن مال خویش را. دفطسة با دال مهمله نیز بهمین معنی است .<br /></font></div>'),
(130733, 'ذفف', '<span class=\"hlight\">ذفف .</span> <font color=\"DarkGreen\"><b>[ ذَ ف َ ]</font></b> (ع مص ) خسته را کشتن . مجروح را بقتل رسانیدن . <BR><font color=\"Blue\">◄</font> سرعت و شتاب کردن در کاری .<br /></font></div>'),
(130734, 'ذفف', '<span class=\"hlight\">ذفف .</span> <font color=\"DarkGreen\"><b>[ ذُ ف ُ ]</font></b> (ع اِ) ج ِ ذِفاف .<br /></font></div>'),
(130735, 'ذفل', '<span class=\"hlight\">ذفل .</span> <font color=\"DarkGreen\"><b>[ ذِ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ ]</font></b> (ع اِ) قطران تُنُک و رقیق .<br /></font></div>'),
(130736, 'ذفوط', '<span class=\"hlight\">ذفوط.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) سُست . ناتوان .<br /></font></div>'),
(130737, 'ذفوف', '<span class=\"hlight\">ذفوف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) تیز. سبک . تند. <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسب نعمان بن منذر.<br /></font></div>'),
(130738, 'ذفکر', '<span class=\"hlight\">ذفکر.</span> <font color=\"DarkGreen\"><b>[ ذَ ک َ ]</font></b> (ع اِ) تخم کرفس کوهی است و آن را به یونانی فطراسالیون نامند.<br /></font></div>'),
(130739, 'ذفیف', '<span class=\"hlight\">ذفیف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) سبک شدن . سبک سبک شدن . زود رفتن . (تاج المصادر بیهقی ). تیز بشدن .<br /></font></div>'),
(130740, 'ذفیف', '<span class=\"hlight\">ذفیف .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) سبک . (مهذب الاسماء). تیز. زود. سریع. سبک بر روی زمین . طاعون ذفیف ؛ مرگامرگی ناگهان کش . وبای در جای کشنده . مرگی جابجای کشنده . <BR><font color=\"Blue\">◄</font> خفیف ذفیف ؛ از اتباع است به معنی سریع و زود. تند و فرز. تر و چسبان . چست و چابک .<br /></font></div>'),
(130741, 'ذفیفة', '<span class=\"hlight\">ذفیفة.</span> <font color=\"DarkGreen\"><b>[ ذَ ف َ ]</font></b> (ع ص ) تأنیث ذفیف .<br /></font></div>'),
(130742, 'ذقاحة', '<span class=\"hlight\">ذقاحة.</span> <font color=\"DarkGreen\"><b>[ ذُق ْ قا ح َ ]</font></b> (ع ص ) متهم کننده کسی را بگناهی که نکرده است .<br /></font></div>'),
(130743, 'ذقاق', '<span class=\"hlight\">ذقاق .</span> <font color=\"DarkGreen\"><b>[ ذُق ْ قا ]</font></b> (ع اِ) کویچه . کوچه . ج، اَذِقَّة.<br /></font></div>'),
(130744, 'ذقان', '<span class=\"hlight\">ذقان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) نام کوهی است و گویند موضعی است .<br /></font></div>'),
(130745, 'ذقانان', '<span class=\"hlight\">ذقانان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (اِخ ) نام دو کوه است در بلاد بنی کعب .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(130746, 'ذقذاق', '<span class=\"hlight\">ذقذاق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) تیززبان زودگوی که در آن شتاب زدگی باشد. و بعضی گویند ذفذاف بدو فاء موحده باشد.<br /></font></div>'),
(130747, 'ذقط', '<span class=\"hlight\">ذقط.</span> <font color=\"DarkGreen\"><b>[ ذَ ق ِ ]</font></b> (ع ص ) مرد خشمناک .<br /></font></div>'),
(130748, 'ذقط', '<span class=\"hlight\">ذقط.</span> <font color=\"DarkGreen\"><b>[ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ ]</font></b> (ع مص ) برجستن طیر بر ماده . <BR><font color=\"Blue\">◄</font> فضله افکندن مگس .<br /></font></div>'),
(130749, 'ذقط', '<span class=\"hlight\">ذقط.</span> <font color=\"DarkGreen\"><b>[ ذُ ق َ ]</font></b> (ع اِ) مگس ریز. ج، ذِقطان .<br /></font></div>'),
(130750, 'ذقطان', '<span class=\"hlight\">ذقطان .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ج ِ ذُقط.<br /></font></div>'),
(130751, 'ذقطان', '<span class=\"hlight\">ذقطان .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مرد خشمناک .<br /></font></div>'),
(130752, 'ذقن', '<span class=\"hlight\">ذقن .</span> <font color=\"DarkGreen\"><b>[ ذَ ق َ ]</font></b> (ع اِ) (ظاهراً معرب زنخ ) زنخ . (دهار) (مهذب الاسماء). چانه . زنخدان <span class=\"hlight\">:</span> <br />گفتم گل است یا سمن است آن رخ و ذقن <br />گفتا یکی شکفته گل است و یکی سمن .<br /> <font color=\"Red\">فرخی .</font><br />دی بسلام آمد نزدیک من <br />ماه من آن لعبت سیمین ذقن .<br /><font color=\"Red\">فرخی .</font><br />نرگس تازه چو چاه ذقنی شد بمثل <br />گر بود چاه ز دینار و ز نقره ذقنا.<br /> <font color=\"Red\">منوچهری .</font><br />بر سپهر لاجوردی صورت سعدالسعود<br />چون یکی چاه عقیقین در یکی نیلی ذقن .<br /> <font color=\"Red\">منوچهری .</font><br />من بگشته ز حال صورت خویش <br />در غم آن نگار سیم ذقن .<br /> <font color=\"Red\">مسعودسعد.</font><br />نشسته بودم کامد خیال او ناگاه <br />چو ماه روی و چو گل عارض و چو سیم ذقن .<br /> <font color=\"Red\">مسعودسعد.</font><br />فرقکی هست از چه بالوعه تا چاه ذقن .<br /> <font color=\"Red\">اخسیکتی .</font><br />چیست نامش گفت نامش بوالحسن <br />حلیه اش را گفت ز ابرو و ذقن .<br /> <font color=\"Red\">مولوی .</font><br />ببوسه (؟) سیب ذقن گفتمش ز گلشن کیست <br />کمال گفت تو انگور خور ز باغ مپرس .<br /> <font color=\"Red\">کمال .</font><br /> <BR><font color=\"Blue\">◄</font> در مثل است : مثقل ٌ استعان بذقنه ؛ در حق کسی گویند که از خوارتر از خود یاری جوید و اصل آن از شتر گرانبار است که چون برخاستن نتواند زنخ خویش را چون تکیه گاهی بر زمین نهد. ج، اَذقان . (مهذب الاسماء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاه ذقن </span> ؛ چاه زنخ . چاه زنخدان . گوی که در بعض چانه ها باشد و در خوبرویان بر خوبی آنان افزاید.<br /></font></div>'),
(130753, 'ذقن', '<span class=\"hlight\">ذقن .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) زدن بر گردن کسی . یا زدن بر زنخ کسی . بر زنخدان زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ذقن علی یده و ذقن علی عصاه ؛ نهاد زنخ خویش را بر دست خود.نهاد زنخ خود را بر چوبدست . <BR><font color=\"Blue\">◄</font> به عصا زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بر حلق زدن .<br /></font></div>'),
(130754, 'ذقن', '<span class=\"hlight\">ذقن .</span> <font color=\"DarkGreen\"><b>[ ذَ ق َ ]</font></b> (ع مص )ذقنت الدلو؛ کژلب گردید دلو آنگاه که دوختی آنرا.<br /></font></div>'),
(130755, 'ذقن', '<span class=\"hlight\">ذقن .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) شیخ الهم ّ. پیر فانی . پیر سالخورده .<br /></font></div>'),
(130756, 'ذقن', '<span class=\"hlight\">ذقن .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع اِ) ج ِ اَذقن و ذقناء.<br /></font></div>'),
(130757, 'ذقن الباشا', '<span class=\"hlight\">ذقن الباشا.</span> <font color=\"DarkGreen\"><b>[ ذَ ق َ نُل ْ ]</font></b> (ع اِ مرکب ) نامی است که عربهای معاصر به ابریشم دهند. و باشا معرّب پاشاست .<br /></font></div>'),
(130758, 'ذقن الشیخ', '<span class=\"hlight\">ذقن الشیخ .</span> <font color=\"DarkGreen\"><b>[ ذَ ق َ نُش ْ ش َ ]</font></b> (ع اِ) افسنطین . رجوع به افسنطین شود.<br /></font></div>'),
(130759, 'ذقون', '<span class=\"hlight\">ذقون .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص، اِ) شتر ماده ٔ سست زنخ که در رفتن زنخ خود را فروهشته دارد. اشتر سرجنبان . اشتری که سر خود را می جنباند در رفتن . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دلوی ذقون ؛ دلوی کژلب .<br /></font></div>'),
(130760, 'ذقیط', '<span class=\"hlight\">ذقیط.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) مرد خبیث . مرد پلید.<br /></font></div>'),
(130761, 'ذل', '<span class=\"hlight\">ذل .</span> <font color=\"DarkGreen\"><b>[ ذِل ل ]</font></b> (ع اِ) روش . طور. طریقه . مجری . عادت . ج، اذلال : امور اﷲ جاریة اذلالها (یا) علی اذلالها؛ ای مجاریها. و جاء علی اذلاله ؛ به روش و طور خویش آمد. دعه علی اذلاله ؛ او را بر حال خود بمان . <BR><font color=\"Blue\">◄</font> (ص ) اذلال ناس ؛ مردم کم پایه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) ذِل ّ طریق ؛ میانه ٔ راه . <BR><font color=\"Blue\">◄</font> (اِمص ) نرمی . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مهربانی . <BR><font color=\"Blue\">◄</font> (مص ) نرم و رام گردیدن . رام شدن . (زوزنی ) (دهار) (تاج المصادر بیهقی ). نرم شدن . <BR><font color=\"Blue\">◄</font> آسان شدن .<br /></font></div>'),
(130762, 'ذل', '<span class=\"hlight\">ذل .</span> <font color=\"DarkGreen\"><b>[ ذُل ل ]</font></b> (ع اِمص ) خواری .(مهذب الاسماء). هوان . هون . ذلت . مذلت . خوار گردیدن .خوار شدن . (تاج المصادر بیهقی ). ذُلالت . ذَلالت . قوله تعالی <span class=\"hlight\">:</span> و لم یکن له ولی من الذل . (قرآن <span class=\"hlight\" dir=\"rtl\">١١١/١٧</span>)؛ و نمی باشد مر او را دوستاری از مذلت . (تفسیر ابوالفتوح رازی ). مقابل عزّ و عزّت . ارج . ارجمندی .<br />آنچه با رنج یافتی و بذل <br />تو بآسانی از گزافه مدیش .<br /> <font color=\"Red\">رودکی .</font><br />خردک نگرش نیست که خردک نگرش کس <br />در کار بزرگان همه ذل است و هوان است .<br /> <font color=\"Red\">منوچهری .</font><br />گر فکنده ست او مرا در ذل غربت گو فکن <br />غربت اندر خدمت خواجه مرا والا کند.<br /> <font color=\"Red\">منوچهری .</font><br />به گورستان بگذشتم، دو گور دیدم پاکیزه، به گچ کرده و ساعتی تمنا کردم که کاشکی من چون ایشان بودمی در عزّ تا ذل نباید دید که طاقت ندارم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٠٤</span>).<br />چه نیکو سخن گفت یاری بیاری <br />که تا کی کشم از خسر ذل و خواری .<br /> <font color=\"Red\">؟ (از لغت نامه ٔ اسدی نخجوانی ).</font><br />زین اسب آز ذل است ای پسر<br />نعل او خواری عنان او سؤال .<br /> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span>).</font><br />عزّ من بی تو بود خواهد، ذل <br />نفع من بی تو گشت خواهد ضرّ.<br /> <font color=\"Red\">مسعودسعد.</font><br />بی نیازی سپاه ذل شه است .<br /> <font color=\"Red\">سنائی .</font><br />مرا عز و ذلی است در راه همت <br />که پروای موسی و بلعم ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />پس لباس کبر بیرون کن ز تن <br />ملبس ذل پوش در آموختن .<br /> <font color=\"Red\">مولوی .</font><br />گفت خدمت آنکه بهر ذل نفس <br />خویش را سازی تو چون عباس دبس .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> مهربانی . رحمت . رأفت . <BR><font color=\"Blue\">◄</font> نرمی . رفق . <BR><font color=\"Blue\">◄</font> رام شدن .رامی، خلاف صعوبت . و سرکشی . <BR><font color=\"Blue\">◄</font> فروتنی . خضوع . مقابل برتنی : و منه قوله تعالی : و اخفض لهما جناح الذّل . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤/١٧</span>). <BR><font color=\"Blue\">◄</font> ذل ّ ذَلیل ؛ خواری خوارکننده یا بسیارخواری .<br /></font></div>'),
(130763, 'ذلاح', '<span class=\"hlight\">ذلاح .</span> <font color=\"DarkGreen\"><b>[ ذُل ْ لا ]</font></b> (ع ص، اِ) شیر به آب آمیخته .<br /></font></div>'),
(130764, 'ذلاذل', '<span class=\"hlight\">ذلاذل .</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ]</font></b> (ع ص، اِ) ج ِ ذلذل . ذلاذل الناس ؛ مردم کم پایه . پست مرتبگان از مردم . <BR><font color=\"Blue\">◄</font> ذلاذل ثوب، ذناذن ثوب ؛ اسافل جامه . <BR><font color=\"Blue\">◄</font> ذلاذل القمیص ؛ عطف دامن یا عطف دامن دراز. ذَلَذِل . و واحد آن ذُلذُل . ذِلذِل . ذِلذَلَة. ذُلَذِل . ذُلَذِلَه است .<br /></font></div>'),
(130765, 'ذلاقت', '<span class=\"hlight\">ذلاقت .</span> <font color=\"DarkGreen\"><b>[ ذَ ق َ ]</font></b> (ع اِمص ) ذَلَق . تیززبانی . فصاحت . زبان آوری . طلاقت . گشاده زبانی . گشادگی زبان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (مص ) ذلاقت لسان ؛ تیز و فصیح شدن زبان . <BR><font color=\"Blue\">◄</font> تیززبان شدن . فصیح شدن : جماعتی که مجتمعآن مقام و مستمع آن کلام بودند از فصاحت آن سباقت و ملاحت آن ذلاقت تعجبها نمودند. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی مؤلف ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>). حال ذلاقت و لیاقت و ظرافت و لطافت او بر رای سلطان عرض کردند. (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٤٣٥</span>). بلادت حیاء او به ذلاقت فصاحت متحلی شده . (ترجمه ٔ تاریخ یمینی چ تهران ص <span class=\"hlight\" dir=\"rtl\">٣٦٢</span>). در جمع میان درایت شمشیر و ذلاقت قلم منفرد. (ترجمه ٔ تاریخ یمینی نسخه ٔ خطی کتابخانه ٔ مؤلف ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>). تیغ ذلاقت زبان او نیام نشناختی . (ترجمه ٔ تاریخ یمینی همان نسخه ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>). <BR><font color=\"Blue\">◄</font> گشاده روی شدن . (تاج المصادر بیهقی ).خوش و آرمیده شدن شب و روز. (تاج المصادر بیهقی ).<br /></font></div>'),
(130766, 'ذلال', '<span class=\"hlight\">ذلال .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) ج ِ ذلیل . چنانکه اذلة. و اذلاّء.<br /></font></div>'),
(130767, 'ذلالت', '<span class=\"hlight\">ذلالت .</span> <font color=\"DarkGreen\"><b>[ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ ل َ ]</font></b> (ع مص ) خوار شدن . ذلیل گردیدن . ذُل ّ. ذلت . مذلت .<br /></font></div>'),
(130768, 'ذلان', '<span class=\"hlight\">ذلان .</span> <font color=\"DarkGreen\"><b>[ ذُل ْ لا ]</font></b> (ع ص ) خوار. ذلیل . موهون . <BR><font color=\"Blue\">◄</font> ج ِ ذلیل . (دهار). و این صورت اخیر را جز در دستور الاخوان دهار جای دیگر نیافتم .<br /></font></div>'),
(130769, 'ذلة', '<span class=\"hlight\">ذلة.</span> <font color=\"DarkGreen\"><b>[ ذِل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ذُل ْ ل َ ]</font></b> (ع مص ) رجوع به ذلت شود.<br /></font></div>'),
(130770, 'ذلت', '<span class=\"hlight\">ذلت .</span> <font color=\"DarkGreen\"><b>[ ذِل ْ ل َ ]</font></b> (ع مص ) ذُل ّ. ذُلالَة. مذلت . ذَلالَت . خوار شدن . (تاج المصادر بیهقی ). موهون گردیدن . خواری . (نطنزی ). هوان . حقارت . مهانت . زبونی . مقابل، عزّت . ارج، ارجمندی : تعزّ من تشاء و تذل ّ من تشاء. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٦/٢</span>).<br /></font></div>'),
(130771, 'ذلج', '<span class=\"hlight\">ذلج .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) تَجَرﱡع . جرعه جرعه آشامیدن . هفت هفت نوشیدن آب را دم بدم درکشیدن مایعی را.<br /></font></div>'),
(130772, 'ذلذل', '<span class=\"hlight\">ذلذل .</span> <font color=\"DarkGreen\"><b>[ ذِ ذِ ]</font></b> (ع اِمص ) خواری .<br /></font></div>'),
(130773, 'ذلذل', '<span class=\"hlight\">ذلذل .</span> <font color=\"DarkGreen\"><b>[ ذَ ذِ ]</font></b> (ع اِ) ذلاذل .<br /></font></div>'),
(130774, 'ذلذل', '<span class=\"hlight\">ذلذل .</span> <font color=\"DarkGreen\"><b>[ ذُ ذُ ]</font></b> (ع اِ)واحد ذَلذِل و واحد ذَلاذِل است . یعنی اسافل جامه .<br /></font></div>'),
(130775, 'ذلذل', '<span class=\"hlight\">ذلذل .</span> <font color=\"DarkGreen\"><b>[ ذُ ذُ ]</font></b> (ع اِ) یکی عطف دامن یا یکی عطف دامن دراز. نورد و چین دامن .بن دامن . (مهذب الاسماء). پایان پیراهن . ج، ذلاذِل .<br /></font></div>'),
(130776, 'ذلذل', '<span class=\"hlight\">ذلذل .</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ ذِ ]</font></b> (ع اِمص ) خواری .<br /></font></div>'),
(130777, 'ذلذلات', '<span class=\"hlight\">ذلذلات .</span> <font color=\"DarkGreen\"><b>[ ذُ ذِ ]</font></b> (ع ص، اِ) ذلذات ناس ؛ کم پایگان از مردم . (منتهی الارب ).<br /></font></div>'),
(130778, 'ذلذلة', '<span class=\"hlight\">ذلذلة.</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ ذِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ذِ ذِ ل َ ]</font></b> (ع اِمص ) خواری . <BR><font color=\"Blue\">◄</font> (اِ) عطف دامن یا عطف دامن دراز.<br /></font></div>'),
(130779, 'ذلغ', '<span class=\"hlight\">ذلغ.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع مص ) ذلغ شفة؛ برگشتن لب .انقلاب شفة؛ یا ترکیدن لب، تشقق شفه . <BR><font color=\"Blue\">◄</font> ذلغ جاریة؛ آرمیدن با وی . <BR><font color=\"Blue\">◄</font> ذلغ طعام ؛ ولغطعام، لغف طعام، اکل طعام یا سغسعه ٔ طعام . یا خوردن طعام نرم را. <BR><font color=\"Blue\">◄</font> نیک چرب کردن طعام را.<br /></font></div>'),
(130780, 'ذلف', '<span class=\"hlight\">ذلف .</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ]</font></b> (ع اِمص ) خردی بینی و راستی تیغ آن، یعنی راستی قصبه ٔآن یا باریکی یا اندک سطبری بینی و راستی طرف آن .<br /></font></div>'),
(130781, 'ذلف', '<span class=\"hlight\">ذلف .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص، اِ) ج ِ اَذلف و ذَلفاء.<br /></font></div>'),
(130782, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ذَ ]</font></b> (ع مص ) ذلاقت . تیز شدن سنان یا کارد و مانند آن . تیززبانی . تیز شدن زفان و سنان . (تاج المصادر بیهقی ). ذَلق لسان و ذَلَق لسان تیز و فصیح گردیدن زبان . تیززبان شدن . (زوزنی ). <BR><font color=\"Blue\">◄</font> بی آرامی . بی آرام شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> روشن شدن، چنانکه چراغ . <BR><font color=\"Blue\">◄</font> ذلق ضَب ّ؛ برآمدن سوسمار از ریگ درشت بسوی نرمتر. <BR><font color=\"Blue\">◄</font> ذلق کسی از عطش ؛ نزدیک مرگ شدن او از تشنگی . بر مرگ بودن از تشنگی . <BR><font color=\"Blue\">◄</font> پیخال افکندن مرغ . فضله انداختن طیر. <BR><font color=\"Blue\">◄</font> سست کردن باد گرم کسی را. <BR><font color=\"Blue\">◄</font> سست وناتوان گردانیدن روزه کسی را. <BR><font color=\"Blue\">◄</font> ذلق الأمعاء؛ سستی و ضعف ماسکه . <br /></font></div>'),
(130783, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذَ ل ِ ]</font></b> (ع ص ) تیز. (زبان و سنان و مانند آن ). حاد. <BR><font color=\"Blue\">◄</font> زبانی گشاده . طَلِق . <BR><font color=\"Blue\">◄</font> نَسو. <BR><font color=\"Blue\">◄</font> خطیب ذَلِق ؛ فصیح .زبان آور. تیززبان . گشاده زبان . هویداسخن . سبک زبان .<br /></font></div>'),
(130784, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذُ ]</font></b> (ع ص، اِ) ج ِ اذلق و ذلقاء.<br /></font></div>'),
(130785, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) شمشیرگونه ای که دو حدّ و نوکی تیز دارد و میان عصا پنهان کنند.<br /></font></div>'),
(130786, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع اِ) مجرای محور در بکرة. گذرگاه محور میان بکرة. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> تیزی زبان . (دهار). <BR><font color=\"Blue\">◄</font> تیزی سنان . <BR><font color=\"Blue\">◄</font> تیزنای زفان . (مهذب الاسماء). تیزنای زبان . <BR><font color=\"Blue\">◄</font> تیزی هر چیزی . ذلاقت . <BR><font color=\"Blue\">◄</font> (ص ) لسان ذلق ؛ زبان تیز و فصیح . لسان طلق ذلق ؛ زبانی تیز و فصیح .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">حروف ذلق </span> ؛ شش حرف باشد: ب . ر. ف . ل . م . ن . و آن حرفها باشند که از کرانه ٔ زبان و لب برآید و هر اسم رباعی و خماسی غیر ذی زوائد در عربی یک یا دو یا سه حرف از حروف ذلق را دارد و اگر نداشته باشد دخیل است . و سه حرف از این حروف شش گانه ذولقیة است و آن : ل . ر.ن است و سه حرف شفهیة، و آن : ب . ف . م . باشد.<br /></font></div>'),
(130787, 'ذلق', '<span class=\"hlight\">ذلق .</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ ل ُ ]</font></b> (ع ص ) تیز. <BR><font color=\"Blue\">◄</font> فصیح : لسان ُ ذلق ؛ زبانی تیز و فصیح .<br /></font></div>'),
(130788, 'ذلقامان', '<span class=\"hlight\">ذلقامان .</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ]</font></b> (اِخ ) نام مجموع دو وادی به یمامه و آنگاه که سیل آندو تلاقی کند و یکی شوند آن را ریب نامند. (از معجم البلدان ).<br /></font></div>'),
(130789, 'ذلل', '<span class=\"hlight\">ذلل .</span> <font color=\"DarkGreen\"><b>[ ذُ ل ُ ]</font></b> (ع ص، اِ) ج ِ ذَلول .<br /></font></div>'),
(130790, 'ذلم', '<span class=\"hlight\">ذلم .</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ]</font></b> (ع اِ) جای فرورفتن آب رودبار.<br /></font></div>'),
(130791, 'ذلو', '<span class=\"hlight\">ذلو.</span> <font color=\"DarkGreen\"><b>[ ذَل ْوْ ]</font></b> (ع مص ) چیدن خرمای تر را. باز کردن خرمای تر.<br /></font></div>'),
(130792, 'ذلول', '<span class=\"hlight\">ذلول .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) رام . (مهذب الاسماء)(دهار). منقاد. نرم . مطیع. مُذلَّلَة در عمل . کارکشته . کارشکسته . (ابوالفتوح رازی ). آسان . آهسته . آرام . فرهخته . (مهذب الاسماء). مقابل صعب . سرکش . تور: القران ذلول ذو وجوه فاحملوه علی احسن الوجوه . <BR><font color=\"Blue\">◄</font> سحاب ذلول ؛ ابر بی برق و رعد. ج، ذُلُل، اَذِلَّة.<br /></font></div>'),
(130793, 'ذلولی', '<span class=\"hlight\">ذلولی .</span> <font color=\"DarkGreen\"><b>[ ذَ لی ی ]</font></b> (ع ص ) نیکوخوی . نرم خوی . خوار. نرم . رام . ج، ذلولیون .<br /></font></div>'),
(130794, 'ذلک', '<span class=\"hlight\">ذلک .</span> <font color=\"DarkGreen\"><b>[ ذا ل ِ <span class=\"hlight\" dir=\"rtl\">/</span> ذا ل ِ ک َ ]</font></b> (ع اِ، ضمیر) آن . برای اشاره بعید است : و ما ذلک علی اﷲ بعزیز. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٠/١٤</span>). <BR><font color=\"Blue\">◄</font> این است : ذلک فضل اﷲ یؤتیه من یشاء. (قرآن <span class=\"hlight\" dir=\"rtl\">٥٤/٥</span> و <span class=\"hlight\" dir=\"rtl\">٢١/٥٧</span> و <span class=\"hlight\" dir=\"rtl\">٤/٦٢</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بناءً علی ذلک </span> ؛ بنابراین . از اینرو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مع ذلک </span> ؛ و با این . با این همه . با وصف این .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">و غیر ذلک </span> ؛و جز این .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">و نحو ذلک </span> ؛ و مانند این .<br /></font></div>'),
(130795, 'ذلی', '<span class=\"hlight\">ذلی .</span> <font color=\"DarkGreen\"><b>[ ذَل ْی ْ ]</font></b> (ع مص ) چیدن خرمای تر را. باز کردن خرمای تر از نخل .<br /></font></div>'),
(130796, 'ذلیذلات', '<span class=\"hlight\">ذلیذلات .</span> <font color=\"DarkGreen\"><b>[ ذُ ل َ ذِ ]</font></b> (ع ص، اِ) ذلیذلات ناس ؛ مردم کم پایه . فرومایگان مردم .<br /></font></div>'),
(130797, 'ذلیق', '<span class=\"hlight\">ذلیق .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) طلیق . طلق . ذلق . گشاده زبان . زبان آور. تیززبان . زبان تیز. (دهار). قوی سخن، خطیب ُ ذلیق . لسان ُ ذلیق . <BR><font color=\"Blue\">◄</font> سنان ذلیق ؛ نیزه ٔ تیز.<br /></font></div>'),
(130798, 'ذلیل', '<span class=\"hlight\">ذلیل .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (ع ص ) خوار. (دهار). مهین . زبون . حقیر.داخِر . مقابل عزیز، ارجمند، باارج . ج، اَذِلَّة، ذِلال، اَذِلاّء <span class=\"hlight\">:</span> <br />بی دل شود عزیز، که گردد ذلیل و خوار.<br /> <font color=\"Red\">فرخی .</font><br />آلتونتاشیان همه ذلیل شدند و برافتادند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٠٦</span>).<br />خوکی زدر درآمد در پوست میش پنهان <br />بگریخته ز شیران مانده ذلیل و مسکین .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مر دانش را ذلیل چو گرشاسب و روستم <br />راعیش را رهی چو بلیناس و دانیال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />با سبکسار کس، مکن صحبت <br />تا نمانی حقیر و خوار و ذلیل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />امروز من چو خار و گیاام ذلیل و پست <br />از باغ بخت چون کندم هر زمان بلا.<br /> <font color=\"Red\">مسعودسعد.</font><br />رأی او را ذلیل گشته قدر<br />عزم او را مطیع گشته قضا.<br /> <font color=\"Red\">معزی .</font><br />اقوال پسندیده مدروس گشته ... و مظلوم محق ّ ذلیل و ظالم مبطل عزیز. (کلیله و دمنه ). وجود مبارک خود را ذلیل عزت و اسیر شوکت و رهین منّت بیگانه نساخت . (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br />بر من از صد هزار عزت بیش <br />آنکه باشم ذلیل و خوارتو من .<br /> <font color=\"Red\">عطار.</font><br /><BR><font color=\"Blue\">◄</font> گنه کار. <BR><font color=\"Blue\">◄</font> رام . مطیع. نرم . (دهار). آسان . ذُل ُّ ذلیل ؛ خوارکننده یا بسیار خوارکننده . <BR><font color=\"Blue\">◄</font> ذلیل گردیدن . اعتراف . لشو. انقماع . <BR><font color=\"Blue\">◄</font> اقهار. <BR><font color=\"Blue\">◄</font> ذلیل گردانیدن . تذلیل . اضراع . کأص . اعیاء. اقماع .<br /></font></div>'),
(130799, 'ذلیل', '<span class=\"hlight\">ذلیل .</span> <font color=\"DarkGreen\"><b>[ ذِل ْ لی ]</font></b> (ع ص ) ذلیل کننده . مُذِل ّ.<br /></font></div>'),
(130800, 'ذلیلة', '<span class=\"hlight\">ذلیلة.</span> <font color=\"DarkGreen\"><b>[ ذَ ل َ ]</font></b> (ع ص ) تأنیث ذلیل .<br /></font></div>'),
(130801, 'ذلیلی', '<span class=\"hlight\">ذلیلی .</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (حامص ) ذِلّت . مذلَّت <span class=\"hlight\">:</span> <br />ذلیلی در طمع میدان به تحقیق <br />چو عزت در قناعت دان و توفیق .<br /><font color=\"Red\">(منسوب به ناصرخسرو).</font><br /></font></div>'),
(130802, 'ذم', '<span class=\"hlight\">ذم .</span> <font color=\"DarkGreen\"><b>[ ذِم م ]</font></b> (ع ص ) بسیار لاغر. <BR><font color=\"Blue\">◄</font> هالک . <BR><font color=\"Blue\">◄</font> مرد نکوهیده . <BR><font color=\"Blue\">◄</font> (اِ) امان . <BR><font color=\"Blue\">◄</font> عهد. پذرفتاری .<br /></font></div>'),
(130803, 'ذم', '<span class=\"hlight\">ذم .</span> <font color=\"DarkGreen\"><b>[ ذَم م ]</font></b> (ع مص ) نکوهیدن . (دهار) (زوزنی ) (تاج المصادر بیهقی ). مذمَت . نکوهش . بدگوئی . بدگفتن . هجو گفتن کسی را.... قدح . تعییب . مقابل مَدح، ستودن، و آن گفتار یا کردار یا ترک هر دو باشد بنحوی که حاکی از پست ساختن مقام غیر یا انحطاط شأن و حیثیت دیگری شود. (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> کسی که مدح تو کند بچیزی که در تو نباشد از او احتراز کن . که نیز ذم ّ تو کند بچیزی که در تو نباشد.<br />چون بگیتی نه وفا ماند و نه اهل <br />ذم ّ اهلیت اخوان چه کنم .<br /> <font color=\"Red\">خاقانی .</font><br />خلق تو اکسیر عدل نطق تو تفسیر عقل <br />مدح تو توحید محض خصم تو مخصوص ذم .<br /> <font color=\"Red\">خاقانی .</font><br />اگر چه به انصاف با دشمن و دوست <br />دم مدح رانم سر ذم ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />جهان عشق تو نادر جهانیست <br />که در وی رسم مدح و ذم نماند.<br /><font color=\"Red\">عطار.</font><br /></font></div>'),
(130804, 'ذمار', '<span class=\"hlight\">ذمار.</span><font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) زنهار. زینهار. عهد. آنچه سزاوار بودنگاهداشت آن بر مرد. یقال : فلان حامی الذمار؛ ای اذا ذمر و غضب حمی . و نیز گویند، ذمار! ای احفظ ذمارک !<br /></font></div>'),
(130805, 'ذمار', '<span class=\"hlight\">ذمار.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام یکی از ملوک یمن . و ذمار مخلاف صنعاء به اسم او نامیده شده است .<br /></font></div>'),
(130806, 'ذمار', '<span class=\"hlight\">ذمار.</span> <font color=\"DarkGreen\"><b>[ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُ ]</font></b> (اِخ ) نام قریه ای بدو منزلی صنعاء در یمن . و گویند ذمار نام صنعاء باشد. (نهایة). نام مخلافی از مخالیف یمن . (ابن الندیم ). نام بطنی از حمیر که در مخلاف ذمار سکونت دارند. اسم قریه ای است به یمن بدو منزلی صنعاء.و عده ای از علماء بدانجا منسوبند: از جمله : ابوهشام عبدالملک بن عبدالرحمن الذماری و بعضی نام او را عبدالملک بن محمد گفته اند. او از ثوری و غیر او سماع دارد و ابوالقاسم مروان دمشقی گوید: ابوعبدالملک ذماری قاری ملقب به مزنة زاهد دمشق، قران را نزد علی بن زیدبن واقد و یحیی بن الحارث درست کرد و از آن دو روایت کند. و او متولی قضاء دمشق بود، و محمدبن حسان اسدی و سلیمان بن عبدالرحمن و نمران بن عتبه ٔ ذماری از او روایت کنند. ابن منده گوید: وی از مردم دمشق است و ازام ّالدرداء روایت کند و از او برادرزاده ٔ وی ریاح بن الولید الذماری و بقولی رباح روایت کند. و گروهی گفته اند که ذمار نام صنعاء باشد. و صنعاء کلمه ای حبشیةاست بمعنی حصین و استوار و وثیق و این نام را حبشیان که با ابرهة و اریاط به یمن آمدند بدانجا دادند و بعضی گفته اند، میان آن و صنعاء شانزده فرسنگ است . و اصحاب حدیث غالباً آن را به کسر ذال تلفظ کنند لیکن ابن درید گوید بفتح است و گوید بدانگاه که در جاهلیت قریش کعبه را خراب کردند در پایه سنگی یافتند که بخط مسند بر آن نوشته بود: که راست ملک ذمار؟ حمیران برگزیده را، کراست ملک ذمار؟ حبشه اشرار را، کراست ملک ذمار؟ ایرانیان آزاده را. کراست ملک ذمار؟ قریشیان سوداگر را و پس از آن حارمحار، ای رجع مرجعاً. (معجم البلدان یاقوت ). و صاحب قاموس الاعلام گوید: ذمار قصبه ای است به پانزده ساعتی جهت جنوبی صنعاء یمن . و تابعسنجاق صنعا و مرکز قضاست . و آن شهری باستانی است و به زمان حمیریان صاحب اهمیت بود و در اوائل دور اسلام علما و محدثین بسیار از آنجا نشأت کرده اند. قضای ذمار محدود است از شمال به صنعا و از جنوب به قضای پریم و از غرب به سنجاق حدیده و قضای ریمه و از شرق به اراضی غیر مضبوطة. و این ناحیت کوهستانی و در اراضی مرتفعه است . و آبهای آن قسمتی از جانب حدیده به بحراحمر و قسمتی از طریق حضرموت به بحر عمان ریزد. و بدانجا گوسفندان بسیار از نژادی نیکو هست . (از قاموس الاعلام ترکی ). و رجوع به حلل السندسیة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span> شود.<br />در رساله ٔ معادن مستخرجه از کتاب الاکلیل حسن الهمدانی (چ حیدرآباد در دنبال کتاب الجماهر بیرونی ) آمده است که : و فی جبل حرّان قبلی مدینة ذمار معادن الحجارة النفیسة الیمانیة من العقیق الاحمر و الابیض و الاصفر و المورونی .<br /></font></div>'),
(130807, 'ذمارالقرن', '<span class=\"hlight\">ذمارالقرن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) در رساله ٔ معادن مستخرج از کتاب الاکلیل حسن الهمدانی (چ حیدرآباد در دنبال کتاب الجماهر بیرونی ) آمده است که : و فی مسار من بلد حرّان معدن ذهب و فی ذمارالقرن معدن نحاس احمر جید.<br /></font></div>'),
(130808, 'ذماری', '<span class=\"hlight\">ذماری .</span> <font color=\"DarkGreen\"><b>[ ذِ ری ی ]</font></b> (ص نسبی ) سمعانی گوید نسبت است به قریه ای به یمن به شانزده فرسنگی صنعاء موسوم به ذمار. و حکی ان ّ الأسود العبسی کان معه شیطانان یقال لأحدهما سحیق و للاخر شقیق، کانا یخبرانه بکل ّ شی ٔ یحدث من امرالنّاس فسار الأسود حتّی اخذ ذمار و کان باذان اذ ذاک مریضاً بصنعاء فجاء الرسول فقال : «خدایگان باذان ! <font color=\"DarkGreen\"><b>[ اسود ]</font></b> ذمار گرفت » قال باذان و هو فی <font color=\"DarkGreen\"><b>[ بیاض «]</font></b>اسب زین و اشتر پالان و اشتاب بی درنگ » فکان ذلک آخر کلام تکلم به حتّی مات . فجاء الأسود شیطانه فی اعصار من الریح فاخبره بموت باذان و هو فی قصر ذمار فنادی الاسود فی قومه یا آل عامر و حاسر <font color=\"DarkGreen\"><b>[ حمیر؟ ]</font></b> فخذوا من مراد ان ّ سحیقا قد ادارذمار و اباح لکم صنعاء فارکبوا و عجلّوا فسار الأسود و من معه من عبس و بنی عامر و حمیر حتّی نزل بهم .<br /></font></div>'),
(130809, 'ذمام', '<span class=\"hlight\">ذمام .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص، اِ) ج ِ ذمیم . و ذِمَّة.<br /></font></div>'),
(130810, 'ذمام', '<span class=\"hlight\">ذمام .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع اِ) حق . واجب . <BR><font color=\"Blue\">◄</font> حرمت . آب رو. <BR><font color=\"Blue\">◄</font> زینهار. (دهار) (نطنزی ). ایلاف . ج، اَذِمّة. <BR><font color=\"Blue\">◄</font> چاههای اندک آب . <BR><font color=\"Blue\">◄</font> دیوان ذمام، ظاهراً دیوان رسیدگی به دعاوی بوده است .<br /></font></div>'),
(130811, 'ذمامة', '<span class=\"hlight\">ذمامة.</span> <font color=\"DarkGreen\"><b>[ ذِ م َ ]</font></b> (ع اِ) امان . <BR><font color=\"Blue\">◄</font> عهد. ضمانت . کفالت . ذمّة. <BR><font color=\"Blue\">◄</font> حیا.<br /></font></div>'),
(130812, 'ذمامة', '<span class=\"hlight\">ذمامة.</span> <font color=\"DarkGreen\"><b>[ ذُ م َ ]</font></b> (ع اِ) باقی مانده ٔ چیزی .<br /></font></div>'),
(130813, 'ذمایم', '<span class=\"hlight\">ذمایم .</span> <font color=\"DarkGreen\"><b>[ ذَ ی ِ ]</font></b> (ع ص، اِ) ج ِ ذمیمة.<br /></font></div>'),
(130814, 'ذمة', '<span class=\"hlight\">ذمة.</span> <font color=\"DarkGreen\"><b>[ ذِم ْ م َ ]</font></b> (ع اِ) کفالت . ذِمامَت . دَمامَت . <BR><font color=\"Blue\">◄</font> عهد. پیمان . (ادیب نطنزی ). اِل . امان <span class=\"hlight\">:</span> به امان پناهید و زنهار طلبید و در ذمت عنایت و رعایت حاجب آلتونتاش گریخت . (ترجمه ٔ تاریخ یمینی چ طهران ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>). <BR><font color=\"Blue\">◄</font> حرمت . (مهذب الاسماء). ملحة. <BR><font color=\"Blue\">◄</font> زینهار. (ادیب نطنزی ). زنهار. (مهذب الاسماء). ذمَّةالمسلمین واحدة؛ یعنی مسلمانان در کار ذمه چون یک تن باشند، که هرگاه یکی از آنان کسی را امان داد هرچند فرومایه تر کس از مسلمانان باشد همه ٔ مسلمانان او را امان داده باشند. <BR><font color=\"Blue\">◄</font> پذرفتاری .ضمان . <BR><font color=\"Blue\">◄</font> زنهاری . (دستوراللغة نطنزی ). زینهاری . (دهار). مردم با عهد و پیمان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عُهْده َ. <BR><font color=\"Blue\">◄</font> عُنُق . گردن . امانةاﷲ فی عنقک ؛ ای ذمتک . (از منتهی الارب ). به گردن تست . و از این معنی است مشغول الذِمّة و بری ءالذمّة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اهل ذِمَّة</span> ؛ اهل کتاب از زرتشتیان و جهودان و ترسایان که در زمین مسلمانی با شروط ذِمَة زیست دارند. لدخولهم فی عهدالمسلمین و امانهم . و آنان را ذمیان یعنی زنهاریان گویند و آنان ملتزم به ادای جزیه باشند. <BR><font color=\"Blue\">◄</font> قضی بذمّته ؛ احسان کرد در حق وی تا نکوهیده نگردد. <BR><font color=\"Blue\">◄</font> طعام مهمانی . طعام عروسی . ج، ذِمَم، ذِمام . و سید در تعریفات گوید: لغةَ، العهد، لأن ّ نقضه یوجب الذم . و منهم من جعلها و صفاً، فعرّفها بأنّها وصف یصیرالشخص به اهلاً للأیجاب له و علیه . و منهم من جعلها ذاتاً، فعرّفها، بأنّها نفس، لها عهدٌ، فأن ّ الانسان یولد و له ذِمّةُ صالحة للوجوب، له و علیه، (عند جمیعالفقهاء) بخلاف سائر الحیوانات . (تعریفات جرجانی ).<br />و صاحب کشاف اصطلاحات الفنون گوید: الذمّة بالکسر، قال بعض الفقهاء ان ّ الذمة امر لا معنی له بل هی من مخترعات الفقهاء یعبرون عن وجوب الحکم علی المکلف بثبوته فی ذمته و هذا القول لیس بصحیح اذ فی المغرب ان الذمة فی اللغة العهد و یعبّر بالأمان و الضمان و یسمّی محل التزام الذمة بها فی قولهم ثبت فی ذمّتی کذا ای علی نفسی . فالذمة فی قول الفقهاء یراد به نفس المکلف . و ذکر القاضی الأمام ابوزید: ان ّ الذمة شرعا وصف یصیر به الأنسان اهلاً لما له و لما علیه فان ّ اﷲتعالی لما خلق الأنسان محلاً للأمانة اکرمه بالعقل و الذمة حتی صار اهلاً لوجوب الحقوق له و علیه و ثبت له حقوق العصمة و الحریةو المالکیة کما اذا عاهدنا الکفار و اعطیناهم الذمّة ثبت لهم و علیهم حقوق المسلمین فی الدنیا. و هذا هوالعهد الّذی جری بین اﷲتعالی و عباده یوم المیثاق . ثم هذا الوصف غیرالعقل اذا العقل لمجرد فهم الخطاب، فاَن اﷲتعالی عند اخراج الذریة یوم المیثاق جعلهم عقلاءو الاّ لم یجز الخطاب و السؤال و لا الاشهاد علیهم بالجواب و لو کان العقل کافیا للأیجاب لم یحتج الی الأشهاد و السؤال و الجواب فعلم ان ّ الایجاب لامر ثبت بالسؤال و الجواب و الاشهاد. و هو العهد المعبر عنه بالذمة فلو فرض ثبوت العقل بدون الذمة لم یثبت الوجوب له وعلیه، و الحاصل ان ّ هذا الوصف بمنزلة السّبب لکون الأنسان اهلاً للوجوب له و علیه و العقل بمنزلة الشرط و معنی قولهم وجب ذلک فی ذمته، الوجوب علی نفسه بأعتبار ذلک الوصف . فلما کان الوجوب متعلّقا به جعلوه بمنزلة ظرف یستقر فیه الوجوب دلالة علی کمال التعلق و اشارة الی ان ّ هذا الوجوب انّما هو باعتبار العهد و المیثاق الماضی، کما یقال وجب فی العهد و المروة ان یکون کذا و کذا. و امّا علی ما ذکره فخرالاسلام من ان المراد بالذمة فی الشرع نفس و رقبة لها ذمة و عهد فمعنی هذا القول انّه ٔ وجب علی نفسه باعتبار کونها محلا لذلک العهد. فالرقبة تفسیر للنفس و العهد تفسیر للذمة. و هذا فی التحقیق من تسمیة المحل باسم الحال ّ. و المقصود واضح . هذا کله خلاصة ما فی التلویح و حاشیته للفاضل الچلپی و البیرجندی فی باب الکفالة - انتهی .<br /></font></div>'),
(130815, 'ذمة', '<span class=\"hlight\">ذمة.</span> <font color=\"DarkGreen\"><b>[ ذَم ْ م َ ]</font></b> (ع ص، اِ) بئرٌ ذَمَّة؛ چاه اندک آب . (مهذب الاسماء). چاه کم آب . <BR><font color=\"Blue\">◄</font> چاه بسیارآب . چاه پرآب . (از اضداد است ). ج، ذِمام .<br /></font></div>'),
